COLLDATA("sh14538","ar",[[10140,"انظر: الضعفاء والمتروكين (٢/ ١٤٨)، الكامل لابن عدى (٦/ ٥٢٩)، الضعفاء الكبير (٣/ ٣٨)، التاريخ الكبير (٥/ ٤٣٦)، ميزان الاعتدال (٢/ ٦٦٦)، المجروحين (٢/ ١٣٣)، المغنى (٢/ ٣٨٥١)."],[10141,"(٣) هو: عيسى بن قرطاس الكوفى."],[10142,"قال النسائى: متروك الحديث، قال الآجرى عن أبى داود: شيخ ضعيف، قال أبو حاتم: يروى الموضوعات عن الثقات لا يحل الاحتجاج به."],[10143,"انظر: تهذيب الكمال (٢٣ / ت ٤٦٥١)، التاريخ الكبير (٦ / ت ٢٧٧٨)، الجرح والتعديل (٦ / ت ١٥٨٠)، تهذيب التهذيب (٨/ ٢٢٧)، الكامل لابن عدى (٦/ ٤٤١)، المغنى (٢ / ت ٤٨٢٣)، الضعفاء والمتروكين للدارقطنى (٤١٥)، لسان الميزان (٧/ ٣٣٢)، تاريخ ابن معين (٣/ ٤٦٤)."],[10144,"(٤) هو: عبد الرحمن بن إسحاق بن سعد بن الحارث أبو شيبة الواسطى الأنصارى، ويقال: الكوفى ابن أخت النعمان بن سعد. قلت: قد سبق."],[10145,"(٥) هو: عبيد بن إسحاق العطار الكوفى، يقال له: عطار المطلقات، قال البخارى: منكر الحديث.="],[10146,"عطار المطلقات، قلت له: هذه الأحاديث التى تحدث بها باطل، فقال: اتق الله ويحك، فقلت: هى باطل، فسكت."],[10147,"٥٤٢ - وعبيد بن القاسم"],[10148,"(١)"],[10149,"قريب سفيان الثورى ليس بثقة."],[10150,"٥٤٣ - وعثمان بن عمير أبو اليقظان"],[10151,"(٢)"],[10152,"كوفى ليس بشئ."],[10153,"٥٤٤ - وعلى بن نزار"],[10154,"(٣)"],[10155,"ليس حديثه بشئ."],[10156,"٥٤٥ - والعباس بن الفضل"],[10157,"(٤)"],[10158,"= انظر: الجرح والتعديل (٥/ ٤٠١)، الضعفاء الكبير (٣/ ١١٥)، الكامل لابن عدى (٧/ ٥٢)، المغنى (٢/ ٣٩٥٣)، ميزان الاعتدال (٣/ ١٨)، لسان الميزان (٤/ ١١٧)، المجروحين (٢/ ١٧٦)."],[10159,"(١) هو: عبيد بن القاسم الأسدى التميمى الكوفى، يقال: إنه ابن أخت سفيان الثورى."],[10160,"انظر: تهذيب الكمال (١٩ / ت ٣٧٣٣)، الجرح والتعديل (٥ / ت ١٩١٤)، الكاشف (٢ / ت ٣٦٧٩)، الميزان (٣ / ت ٥٤٣٦)، تهذيب التهذيب (٧/ ٧٢)، لسان الميزان (٧/ ٢٩٩)، الكامل لابن عدى (٧/ ٥٤)."],[10161,"(٢) هو: عثمان بن عمير البجلى أبو اليقظان الكوفى الأعمى، ويقال: ابن قيس، ويقال: ابن حميد."],[10162,"انظر: تهذيب الكمال (١٩/ ٣٨٥١)، تهذيب التهذيب (٧/ ١٤٥)، الجرح والتعديل (٦ / ت ٨٨٤)، الكاشف (٢ / ت ٣٧٨١)، ميزان الاعتدال (٣ / ت ٥٥٥٠)، لسان الميزان (٧/ ٣٠٢)، تاريخ ابن معين رواية الدورى (٢/ ٣٩٥)، علل أحمد (١/ ١٩، ١٦٧)، أبو زرعة الرازى (٤٣٠)، المعرفة والتاريخ (٢/ ٧٨١)، تاريخ أبى زرعة الدمشقى (٦٤٧)، المجروحين (٢/ ٩٥)، علل الدارقطنى (ت ٤٠٦)، سؤالات البرقانى (ت ٣٥٦)، تاريخ الإسلام (٦/ ١٠٠)، المغنى (٢ / ت ٤٠٠٥١)، ديوان الضعفاء (ت ٢٧٨٠)، الكامل لابن عدى (٦/ ٢٨٢)."],[10163,"(٣) على بن نزار بن حيان الأسدى الكوفى مولى بنى هاشم."],[10164,"انظر: تهذيب الكمال (٢١/ ت ٤١٤٣)، تهذيب التهذيب (٧/ ٣٨٩)، الجرح والتعديل (٦ / ت ١١٣٢)، ميزان الاعتدال (٣/ ت ٥٩٥٧)، الكاشف (٢/ ت ٤٠٣٢)، لسان الميزان (٧/ ٣١٣)، ضعفاء ابن الجوزى (٢/ ٢٠٠)، تاريخ ابن معين (٢/ ٤٢٣)، المعرفة والتاريخ (٣/ ٤٠)، المجروحين (٢/ ١١٢)، ديوان الضعفاء (ت ٢٩٧١)، الكامل لابن عدى (٦/ ٣٣١)."],[10165,"(٤) هو: العباس بن الفضل، هو ابن عمرو بن عبيد الأنصارى الأزرق. ="],[10166,"ليس بشئ."],[10167,"٥٤٦ - وعقبة الأصم"],[10168,"(١)"],[10169,"ليس بشئ."],[10170,"٥٤٧ - وعبد الواحد بن زيد"],[10171,"(٢)"],[10172,"ليس بشئ."],[10173,"٥٤٨ - وعباد بن [منصور]"],[10174,"(٣)"],[10175,"ليس بشئ."],[10176,"= قال النسائى: متروك الحديث، قال البخارى: ذهب حديثه."],[10177,"انظر: الضعفاء والمتروكين (٢/ ٧٩)، الضعفاء الكبير (٣/ ٣٦١)، المجروحين (٢/ ١٨٩)، الجرح والتعديل (٦/ ٢١٢)، الكامل لابن عدى (٣١٦)، ميزان الاعتدال (٢/ ٣٨٥)، ديوان الضعفاء (ت ٢١٠١)، الكاشف (٢/ ٦٨)."],[10178,"(١) هو: عقبة بن عبد الله الأصم الرفاعى العبدى البصرى."],[10179,"انظر: تهذيب الكمال (٢٠/ ت ٣٩٧٩)، تهذيب التهذيب (٧/ ٢٤٤)، ميزان الاعتدال (٣ / ت ٥٦٨٩)، المجروحين (٢/ ١٩٩)، التاريخ الكبير (٦ /ت ٢١٣٠)، المغنى (٢ /ت ٤١٥٠)، الإكمال (٤/ ١٣٦)، علل أحمد (١/ ٢٢٧)، تاريخ ابن معين (٢/ ٤٠٩)، المعرفة والتاريخ (٢/ ١٢٢)، الضعفاء والمتروكين للدارقطنى (ت ٤٢٢)، ديوان الضعفاء (ت ٢٨٥٣)، الأنساب (٦/ ١٤٧)، الثقات (٥/ ٢٢٩)."],[10180,"(٢) هو: عبد الواحد بن زيد الزاهد القدوة، شيخ العباد، أبو عبيدة البصرى. قال البخارى: تركوه."],[10181,"انظر: تعجيل المنفعة (٦٧٤)، الجرح والتعديل (٦/ ٢٠)، المجروحين (٢/ ١٥٤)، التاريخ الكبير (٦/ ٦٢)، المعرفة والتاريخ (٢/ ١٢١، ٣/ ١)، حلية الأولياء (٦/ ١٥٥)، الثقات (٧/ ١٢٤)، تاريخ الإسلام (٦/ ٢٤٣)، المغنى (٢ / ت ٣٨٦٩)، سير أعلام النبلاء (٧/ ١٧٨)، الكامل لابن عدى (٦/ ٥١٩)."],[10182,"(٣) ما بين المعقوفين طُمس بالمخطوط وأظنه كذلك."],[10183,"وهو: عباد بن منصور الناجى أبو سلمة البصرى القاضى، قال ابن معين: كان يرمى بالقدر."],[10184,"انظر: تهذيب الكمال (١٤ / ت ٣٠٩٣)، تهذيب التهذيب (٥/ ١٠٣)، الجرح والتعديل (٦/ ٤٣٨)، الكاشف (٢ /ت ٢٥٩٧)، ميزان الاعتدال (٢ /ت ١٤١)، تاريخ ابن معين (٢/ ٢٩٣)، المغنى (١/ ت ٣٠٥٤)، الضعفاء الكبير (٣/ ١٣٣)، البداية والنهاية (١٠/ ١٠٩)، الوافى بالوفيات (١٦/ ٦١٢)، طبقات ابن سعد (٧/ ٢٧٠)، تاريخ ابن معين رواية الدورى (٢/ ٢٩٣)، تاريخ خليفة (٤٠٣)، علل أحمد (١/ ٣١٠)، المجروحين (٢/ ١٦٥)، ديوان الضعفاء (ت ٣٠٥٤)، العبر (١/ ٢١٨)، المراسيل للعلائى (ت ٣٣٢)، الكامل لابن عدى (٥/ ٥٤٤)."],[10185,"٥٤٩ - عبد الرحمن بن إبراهيم الكرمانى"],[10186,"(١)"],[10187,"ليس بشئ."],[10188,"٥٥٠ - وعكرمة بن إبراهيم"],[10189,"(٢)"],[10190,"ليس بشئ."],[10191,"٥٥١ - وعبد الله بن واقد"],[10192,"(٣)"],[10193,"يحدث عن قتادة وليس بشئ."],[10194,"٥٥٢ - وعباد بن ميسرة المنقرى"],[10195,"(٤)"],[10196,"(١) هو: عبد الرحمن بن إبراهيم الكرمانى."],[10197,"وقد جمع الذهبى بينه وبين عبد الرحمن بن إبراهيم القاص فى \"الميزان\"، وفرق بينهما فى \"المغنى\" وجع بينهما ابن أبى حاتم فجعلهما واحدًا، ولم يجمع ابن معين بين الاثنين بل جعل لكل واحد منهما ترجمة، فهذا ضعيف والقاص ثقة. والله أعلم."],[10198,"انظر: ميزان الاعتدال (٢/ ت ٤٨٠٣)، تاريخ ابن معين (٢/ ٣٤٣)، لسان الميزان (٣/ ٤٠١)، المجروحين (٢/ ٦٠)، الضعفاء الكبير (٢/ ٣٢٠)، الجرح والتعديل (٥/ ت ٩٩٧)، تراجم الأحبار (٢/ ٤٣٨)، ذيل الكاشف (٨٦٥)، الأنساب (١٠/ ٣٢٠)."],[10199,"(٢) هو: عكرمة بن إبراهيم الباهلى البصرى الأزدى، يكنى أبا عبد الله، سكن الموصل وولى قضاء الرى. قال النسائى: ضعيف، وقال: ليس بثقة، قال أبو أحمد الحاكم: ليس بالقوى عندهم."],[10200,"انظر: تعجيل المنفعة (ت ٧٤٩)، الجرح والتعديل (٧/ ١١)، التاريخ لابن معين (٣/ ٤١١)، التاريخ الكبير (٧/ ٥٠)، ذيل الكاشف (١٠٥٨)، الكامل لابن عدى (٦/ ٤٨٧)، سؤالات البرقاني (٤٠٤)، ميزان الاعتدال (٣/ ٨٩)، لسان الميزان (٤/ ٨١)، تاريخ بغداد (١٢/ ٢٦٢)، تنقيح المقال (٨٠٢٠)، المجروحين (٢/ ١٨٨)، ديوان الضعفاء (ت ٢٨٦٦)، المغنى (٢/ ت ٤١٦٤)."],[10201,"(٣) هو: عبد الله بن واقد، أبو قتادة الحرانى، مولى بنى حمان، ويقال: مولى بنى تميم، توفى سنة سبع ومائتين. قال البخارى: سكتوا عنه، وقال: منكر الحديث تركوه، قال النسائى: ليس بثقة."],[10202,"انظر: تهذيب الكمال (١٦/ ٣٦٣٨)، تهذيب التهذيب (٦/ ٦٦)، ميزان الاعتدال (٢ / ت ٤٦٧٢)، الجرح والتعديل (٥/ ٨٨٣)، التاريخ الكبير (٥/ ت ٧١٣)، الذيل على الكاشف (٧٣٨)، طبقات ابن سعد (٧/ ١٨٣)، الكامل لابن عدى (٥/ ٣٢٠)، تاريخ ابن معين (٢/ ٣٣٦)."],[10203,"(٤) هو: عباد بن ميسرة المنقرى البصرى المعلم."],[10204,"انظر: تهذيب الكمال (١٤/ ت ٣١٠٠)، تهذيب التهذيب (٥/ ١٠٧)، الجرح والتعديل ="],[10205,"٥٥٣ - وعباد بن راشد"],[10206,"(١)"],[10207,"٥٥٤ - وعباد بن كثير"],[10208,"(٢)"],[10209,"٥٥٥ - وعباد بن منصور"],[10210,"(٣)"],[10211,"كلهم (٤) ليس حديثهم بالقوى ولكنه يكتب."],[10212,"٥٥٦ - عبد الوهاب الثقفى"],[10213,"(٥)"],[10214,"قال: وكان عبد الوهاب الثقفى قد اختلط بآخره."],[10215,"= (٦ /ت ٤٣٩)، الكاشف (٢ /ت ٢٥٩٩)، ميزان الاعتدال (٢ /ت ٤١٤٧)، التاريخ الكبير (٦/ ١٦١٨)، الضعفاء والمتروكين (٤١٠)، تاريخ ابن معين (٢/ ٢٩٣)، المغنى (١ /ت ٣٠٥٥)، تاريخ الإسلام (٦/ ٢٠٨)، الكامل لابن عدى (٥/ ٥٥٠)، ديوان الضعفاء (ت ٢٠٨٦)."],[10216,"(١) عباد بن راشد التميمى مولاهم البصرى البزار ابن أخت داود بن أبى هند، ويقال: ابن خالته."],[10217,"انظر: تهذيب الكمال (١٤/ ت ٣٠٧٧)، تهذيب التهذيب (٥/ ٩٢)، الجرح والتعديل (٦ /ت ٤٠٦)، الكاشف (٢ /ت ٢٥٨٤)، ميزان الاعتدال (٢ /ت ٤١٠٣)، التاريخ الكبير (٦ /ت ١٦٠٨)، ديوان الضعفاء (ت ٢٠٧٠)، المغنى (١ /ت ٢٠٣٢)، غاية النهاية لابن الجزرى (١/ ٣٥٢)، الكشف الحثيث (٣٦٩)، المجروحين (٢/ ١٦٣)، المعرفة والتاريخ (٢/ ١٢٦)، تاريخ ابن معين (٢/ ٢٩١)، علل أحمد (١/ ٣٠٩)، تاريخ الإسلام (٦/ ٢٠٦)، الكامل لابن عدى (٥/ ٥٤٩)."],[10218,"(٢) هو: عباد بن كثير بن قيس الرملى الفلسطينى ويقال: عباد بن قيس التميمى."],[10219,"انظر: تهذيب الكمال (١٤ / ت ٣٠٩١)، التاريخ الكبير (٦/ ٢٦٤١)، الجرح والتعديل (٦ /ت ٤٣٤)، الكاشف (٢ /ت ٢٥٩٥)، ميزان الاعتدال (٢/ ٤١٣٣)، تهذيب التهذيب (٥/ ١٠٢)، الكامل لابن عدى (٥/ ٥٤٣)، تاريخ ابن معين (٢/ ٢٩١)."],[10220,"(٣) سبق."],[10221,"(٤) قلت هم: عباد بن ميسرة، وعباد بن راشد، عباد بن كثير، وعباد بن منصور."],[10222,"وقد ذكر الدورى كل واحد منهم بلفظ: حديثه ليس بالقوى ولكنه يكتب."],[10223,"(٥) عبد الوهاب بن عبد المجيد بن الصلت بن عبيد الله بن الحكم بن أبى العاص الثقفى أبو محمد البصرى، توفى سنة أربع وثمانين، وقيل: أربع وتسعين ومائة."],[10224,"انظر: تهذيب الكمال (١٨ /ت ٣٦٠٤)، التاريخ الكبير (٦ /ت ١٨٢٨)، تهذيب التهذيب (٦/ ٤٤٩)، الجرح والتعديل (٦ /ت ٣٦٩)، الكاشف (٢ /ت ٣٥٦٤)، ميزان الاعتدال (٢ /ت ٥٣٢١)، المغنى (٢ /ت ٣٨٩٤)، لسان الميزان (٤/ ٨٨)، تاريخ بغداد (١١/ ١٨)، الأنساب (٣/ ١٤٠)."],[10225,"٥٥٧ - وعثمان البرى"],[10226,"(١)"],[10227,"ضعيف."],[10228,"٥٥٨ - وعيسى بن الفضل"],[10229,"(٢)"],[10230,"ضعيف."],[10231,"٥٥٩ - عمر بن راشد"],[10232,"(٣)"],[10233,"ضعيف."],[10234,"٥٦٠ - والعلاء بن هلال"],[10235,"(٤)"],[10236,"كذاب."],[10237,"٥٦١ - وعمر بن حبيب"],[10238,"(٥)"],[10239,"(١) هو: عثمان بن مقسم أبو سلمة البرى بصرى."],[10240,"قال البخارى: لم يكن فيه خير، وقال ابن معين: من المعروفين بالكذب ووضع الحديث عثمان البرى."],[10241,"انظر: ميزان الاعتدال (٣/ ٥٦)، لسان الميزان (٤/ ١٥٥)، المجروحين (٢/ ١٠١)، الجرح والتعديل (٦/ ٩١٨)، التاريخ الكبير (٦/ ٢٥٢)، الضعفاء الكبير (٣/ ٢١٧)، الضعفاء والمتروكين (٢/ ١٧٢)، الغنى (٢ / ت ٤٠٦٦)، الكامل لابن عدى (٦/ ٢٦٤)."],[10242,"(٢) لم أقف عليه."],[10243,"(٣) هو: عمر بن راشد الكوفى. قلت: وقد سبق."],[10244,"(٤) هو: العلاء بن هلال بن عمر الباهلى الرقى والد هلال بن العلاء."],[10245,"قال البخارى وغيره: منكر الحديث."],[10246,"انظر: تهذيب الكمال (٢٢ / ت ٤٥٨٩)، تهذيب التهذيب (٨/ ١٩٣)، التاريخ الكبير (٦ / ت ٣١٥٠)، الكاشف (٢ / ت ٤٤٠٨)، ميزان الاعتدال (٣ / ت ٥٧٤٨)، لسان الميزان (٧/ ٣٠٩)، الأنساب (٢/ ٧١)، الثقات (٧/ ٢٦٦)، ديوان الضعفاء (ت ٢٨٩٣)، (٢ / ت ٤١٩٤)، ضعفاء ابن الجوزى (٢/ ١٨٩)، المجروحين (٢/ ١٨٤)، تراجم الأحبار (٣/ ٢١١)، الكامل لابن عدى (٦/ ٣٨٣)."],[10247,"(٥) هو: عمر بن حبيب بن محمد بن مجالد بن سبيع بن الحارث بن عبد الحارث بن أسد بن كعب ابن جندل بن عامر بن مالك بن غنم بن الدول بن حسل بن عدى بن عبد مناة البصرى العدوى توفى سنة (٢٠٦) أو (٢٠٧)."],[10248,"انظر: تهذيب الكمال (٢١ / ت ٤٢١١)، الجرح والتعديل (٦ / ت ٥٥٣)، الكاشف = ضعيف."],[10249,"٥٦٢ - عبد الله بن شقيق"],[10250,"(١)"],[10251,"على بن المدينى قال: سمعت يحيى قال: كان التيمى سيئ الرأى فى عبد الله بن شقيق، قال على: قلت ليحيى: سمعته منه؟، قال: نعم."],[10252,"٥٦٣ - عبد الواحد بن قيس"],[10253,"(٢)"],[10254,"على قال: سمعت يحيى وذكر عنده عبد الواحد بن قيس الذى روى عنه الأوزاعى فقال: كان شبه لا شئ، وقال: وقد روى عنه الحسن بن ذكوان (٣)."],[10255,"٥٦٤ - عثمان الشحام"],[10256,"(٤)"],[10257,"على قال: سمعت يحيى وذكر عثمان الشحام فقال: يعرف وينكر ولم يكن بذاك."],[10258,"٥٦٥ - عمرو بن مرزوق"],[10259,"(٥)"],[10260,"= (٢ /ت ٤٩١)، تهذيب التهذيب (٧/ ٤٣١)، ميزان الاعتدال (٣ /ت ٦٠٦٧)، لسان الميزان (٧/ ٣١٦)، تاريخ ابن معين (٢/ ٤٢٦)، الأنساب (٨/ ٤١٠)، الكامل لابن عدى (٦/ ٧١)، الكامل فى التاريخ (٦/ ٣٨٥)، تاريخ بغداد (١١/ ١٩٦)، المجروحين (٢/ ٨١)، العبر (١/ ٣٥٢)، المعرفة والتاريخ (١/ ٤٣٥)، أعلام النبلاء (٩/ ٤٩٠)."],[10261,"قلت: وجاء بالمخطوط عمرو بن حبيب وهو تصحيف."],[10262,"(١) هو: عبد الله بن شقيق العقيلى أبو عبد الرحمن، ويقال: أبو محمد البصرى توفى سنة (١٠٨)."],[10263,"قلت: قد سبق."],[10264,"(٢) هو: عبد الواحد بن قيس السلمى، أبو حمزة الدمشقى الأفطس، النحوى، مولى عروة، ويقال: مولى عمرو بن عتبة."],[10265,"انظر: تهذيب التهذيب (٦/ ٤٣٩)، تهذيب الكمال (١٨ / ت ٣٥٩٢)، التاريخ الكبير (٦ / ت ١٦٩٤)، الجرح والتعديل (٦ / ت ١٢٠)، الكاشف (٢ /ت ٣٥٥٢)، ميزان الاعتدال (٢ / ت ٥٢٩٩)، لسان الميزان (٧/ ٢٩٤)، الثقات (٧/ ١٢٣)، الكامل لابن عدى (٦/ ٥١٨)."],[10266,"(٣) وبقية القول، كان الحسن بن ذكوان يحدث عنه بعجائب."],[10267,"(٤) هو: عثمان الشحام العدوى أبو سلمة البصرى، يقال: اسم أبيه عبد الله، وقيل: ميمون."],[10268,"انظر: تهذيب التهذيب (٧/ ١٦٠)، تهذيب الكمال (١٩/ ت ٣٨٧٥)، الجرح والتعديل (٦/ ت ٩٥١)، الكاشف (٢ /ت ٣٨٠٤)، المغنى (٢ /ت ٤٠٧٥)، الضعفاء الكبير (٣/ ٢٠٨)، الكامل لابن عدى (٦/ ٢٩٣)، تاريخ ابن معين (٢/ ٣٩٦)."],[10269,"(٥) هو: عمرو بن مرزوق أبو عثمان الباهلى يقال: مولاهم، توفى سنة أربع وعشرين ومائتين ="],[10270,"ابن أبى خيثمة: حدثنا عبد الله بن ميسرة قال: كان يحيى بن سعيد القطان لا يرضى عمرو بن مرزوق."],[10271,"٥٦٦ - عبد الله بن جعفر"],[10272,"(١)"],[10273,"قال: وسمعت يحيى بن معين يقول: عبد الله بن جعفر المدينى أبو على ليس بشئ، وسئل عنه مرة أخرى فقال: كذاب."],[10274,"٥٦٧ - عامر بن صالح"],[10275,"(٢)"],[10276,"قال: وسمعته يقول: عامر بن صالح المدينى من آل الزبير كان كذابًا، يروى عن هشام بن عروة كل حديث يسمعه، قال: وقد لقيته وكتبت عامة هذه الأحاديث، وهو عامر بن صالح بن عبد الله بن عروة بن الزبير."],[10277,"= قال أحمد بن حنبل: عمرو رجل صالح لا أدرى ما يقول على، قال أبو حاتم: كان ثقة من العباد لم نجد من أصحاب شعبة ممن كتبنا عنه أحسن حديثًا منه، قال أبو زرعة: سمعت سليمان بن حرب يقول وذكر عمرو بن مرزوق: فقال: جاء. بما ليس عندهم فحسدوه."],[10278,"انظر: تهذيب الكمال (٢٢ / ت ٤٤٤١)، تهذيب التهذيب (٨/ ٩٩)، الجرح والتعديل (٦ / ت ١٤٥٦)، ميزان الاعتدال (٣ / ت ٦٤٥٤)، الكاشف (٢ / ت ٤٢٩٣)، التاريخ الكبير (٦ / ت ٢٦٧٧)، تاريخ الثقات (٣٧٠)، السابق واللاحق (٢٠٥)."],[10279,"(١) هو: عبد الله بن جعفر بن نجيح السعدى مولاهم، أبو جعفر المدينى، والد على بن المدينى، توفى سنة (١٧٨)."],[10280,"انظر: تهذيب الكمال (١٤ / ت ٣٢٠٦)، تهذيب التهذيب (٥/ ١٧٤)، التاريخ الكبير (٥ / ت ١٤٨)، الجرح والتعديل (٥ / ت ١٠٢)، الكاشف (٢ /ت ٢٦٩٢)، ميزان الاعتدال (٢ / ت ٤٢٤٧)، الوافى بالوفيات (١٧/ ١٠٤)، الكامل لابن عدى (٥/ ٢٨٩)، المغنى (١/ ٣١٢٧)، المجروحين (٢/ ١٤)، الضعفاء الكبير (٢/ ٢٣٩)، ديوان الضعفاء (ت ٢١٤٠)، لسان الميزان (٧/ ٢٥٩)."],[10281,"(٢) هو: عامر بن صالح بن عبد الله بن عروة بن الزبير بن العوام الزبيرى، أبو الحارث المدنى، توفى سنة اثنتين وثمانين ومائة."],[10282,"قال أبو حاتم: صالح الحديث ما أرى به بأسًا، كان ابن معين يحمل عليه، وأحمد يروى عنه، قال الدارقطنى: أساء ابن معين القول فيه، ولم يتبين أمره عند أحمد، وهو مدنى يترك عندى."],[10283,"انظر: تهذيب الكمال (١٤ / ت ٣٠٤٦)، تهذيب التهذيب (٥/ ٧١)، الكامل لابن عدى (٦/ ١٥٥)، الجرح والتعديل (٦/ ١٨٠٥)، ميزان الاعتدال (٢ /ت ٤٠٨١)، الكاشف (٢ / ت ٢٥٥٧)."],[10284,"٥٦٨ - عبد الوهاب بن مجاهد"],[10285,"(١)"],[10286,"قال: حدثنا محمد بن عباد بن موسى، حدثنا وكيع قال: كنا عند عبد الوهاب بن مجاهد قال: فقلنا: حمدًا لله بلغنا أن أباك مات وأنت صغير، فغضب فقام، قال: وسمعته يقول: عبد الوهاب بن مجاهد ضعيف."],[10287,"٥٦٩ - عبد الملك بن الربيع بن سبرة"],[10288,"(٢)"],[10289,"قال: وسئل يحيى بن معين عن أحاديث عبد الملك بن الربيع بن سبرة، عن أبيه، عن جده فقال: ضعاف."],[10290,"٥٧٠ - عبد العزيز بن أبان"],[10291,"(٣)"],[10292,"عمرو بن الحسن قال: حدثنى محمد بن بندار قال: سمعت محمد بن سعيد القارى قال: شهدت وكيعًا سئل عن عبد العزيز بن أبان، فقال: له لحية له هيئة."],[10293,"٥٧١ - عزرة بن قيس"],[10294,"(٤)"],[10295,"(١) هو: عبد الوهاب بن مجاهد بن جبير الكى، مولى عبد الوهاب بن السائب المخزومى."],[10296,"انظر: تهذيب الكمال (١٨ / ت ٣٦٠٦)، تهذيب التهذيب (٦/ ٤٥٣)، الجرح والتعديل (٦ / ت ٣٦٢)، ميزان الاعتدال (٢ / ت ٥٠٢٤)، لسان الميزان (٧/ ٢٩٥)، المغنى (٢ / ت ٣٨٩٧)، الكامل لابن عدى (٦/ ٥١٣)."],[10297,"(٢) هو: عبد الملك بن الربيع بن سبرة بن معبد الجهنى."],[10298,"وثقة العجلى، وضعفه ابن معين وأبو خيثمة وغيرهما، وأخرج له مسلم حديثًا واحدًا فى المتعة متابعة."],[10299,"انظر: تهذيب الكمال (١٨ / ت ٣٥٢٦)، تهذيب التهذيب (٦/ ٣٩٣)، التاريخ الكبير (٦ / ت ١٣٤٤)، الكاشف (٢ /ت ٣٤٩٤)، ميزان الاعتدال (٢ / ت ٥٢٠٥)."],[10300,"(٣) عبد العزيز بن أبان بن محمد بن عبد الله بن سعيد بن العاص بن أمية الأموى السعيدى، أبو خالد الكوفى نزيل بغداد."],[10301,"انظر: تهذيب الكمال (١٨ / ت ٣٤٣٤)، تهذيب التهذيب (٦/ ٣٢٩)، التاريخ الكبير (٦ / ت ١٥٨٧)، الجرح والتعديل (٥ / ت ١٧٦٧)، ميزان الاعتدال (٢ / ت ٥٠٨٢)، طبقات ابن سعد (٦/ ٤٠٤)، تاريخ البخارى (٦/ ٣٠)، لسان الميزان (٧/ ٢٨٨)، الكامل لابن عدى (٦/ ٥٠٣)."],[10302,"(٤) جاء بالمخطوط \"عروة بن قيس\" وهو تصحيف، والصواب ما أثبت، وهو عزرة بن قيس اليحمدى البصرى، روى عن أم الفيض مولاة عبد الملك بن مروان."],[10303,"انظر: الجرح والتعديل (٧ / ت ١١٠)، المغنى (٢ / ت ٤١٠٤)، ميزان الاعتدال (٣/ ٦٥)، = ابن أبى خيثمة قال: سئل يحيى بن معين عن عروة بن قيس، فقال: لا شئ."],[10304,"٥٧٢ - العباس بن الفضل الأنصارى"],[10305,"(١)"],[10306,"ثقة، ولكنه حدث بحديث أنكروه عليه، قال: وسمعته مرة أخرى يقول: العباس بن الفضل الأنصارى ليس بشئ."],[10307,"٥٧٣ - عيسى بن ميمون"],[10308,"(٢)"],[10309,"قال: وسمعته يقول: عيسى بن ميمون ليس بشئ."],[10310,"٥٧٤ - عبد الله بن المثنى"],[10311,"(٣)"],[10312,"قال: وسمعته يقول: عبد الله بن المثنى أبو محمد بن عبد الله الأنصارى ليس بشئ."],[10313,"٥٧٥ - عزرة (*) بن قيس"],[10314,"(٤)"],[10315,"قال: وسئل عن عزرة بن قيس روى عنه أحمد بن إسحاق الحضرمى حديث أم الفيض؟ فقال: لا شئ."],[10316,"٥٧٦ - عبد الله بن جعفر الأرطباى"],[10317,"(٥)"],[10318,"= لسان الميزان (٤/ ١٦٦)، التاريخ الكبير (٧/ ٦٥)، المجروحين (٢/ ١٩٧)، تاريخ الإسلام (٦/ ١٠٠)، الكامل لابن عدى (٧/ ٩٥)."],[10319,"(١) هو: عباس بن الفضل، هو ابن عمرو بن عبيد الأنصارى. قلت: قد سبق."],[10320,"(٢) هو: عيسى بن ميمون الجرشى المدينى يكنى أبا يحيى مولى القاسم بن محمد القرشى."],[10321,"قال البخارى: منكر الحديث، قال النسائى: متروك الحديث."],[10322,"انظر: تقريب التهذيب (ت ٥٣٣٥)، الذيل على الكاشف (١٢٠٨)، الجرح والتعديل (٦ / ت ١٥٩٦)، تاريخ أسماء التقات (١٠٦٥)، لسان الميزان (٧/ ٣٣٣)، الكامل لابن عدى (٦/ ٤١٨)."],[10323,"(٣) هو: عبد الله بن المثنى بن عبد الله بن أنس بن مالك الأنصارى، وكنيته أبو المثنى، والد محمد ابن عبد الله الأنصارى."],[10324,"انظر: الجرح والتعديل (٥ / ت ٨٣٠)، ميزان الاعتدال (٢/ ٤٩٩)، لسان الميزان (٧/ ٢٦٩)، الضعفاء الكبير (٢/ ٣٠٤)، ديوان الضعفاء (ت ٢٣٠٤)، التاريخ الكبير (٥/ ٢٠٨)، معرفة الثقات (ت ٢٩٦٠)، الوافى بالوفيات (١٧/ ٤٢١)، تراجم الأحبار (٢/ ٣٤١)، المغنى (١ / ت ٣٣٢٠)."],[10325,"(*) جاء بالمخطوط عروة بن قيس وهو تصحيف."],[10326,"(٤) سبق."],[10327,"(٥) لم أقف عليه."],[10328,"قال: ورجعت إلى أبى يوما وقد كتبت عن الحسن المروروذى، عن عبد الله بن جعفر الأرطبانى، فقال: آيش الأرطبانى أأحد يسمع حديث الأرطبانى؟ ! ."],[10329,"٥٧٧ - عبد الواحد بن زيد"],[10330,"(١)"],[10331,"قال: وسمعت يحيى بن معين يقول: عبد الواحد بن زيد ليس حديثه بشئ ضعيف."],[10332,"٥٧٨ - عاصم بن هلال"],[10333,"(٢)"],[10334,"قال: وسثل عن عاصم بن هلال؟، فقال: ضعيف."],[10335,"٥٧٩ - عبد الله بن بسر"],[10336,"(٣)"],[10337,"قال: قال يحيى: رأيت عبد الله بن بسر كان هاهنا، قلت ليحيى: كيف كان؟، قال: لا شئ."],[10338,"٥٨٠ - عبد الله بن رجاء البصرى"],[10339,"(٤)"],[10340,"(١) هو: عبد الواحد بن زيد القاص أبو عبيدة البصرى."],[10341,"انظر: تعجيل المنفعة (٦٧٤)، التاريخ الكبير (٦/ ٦٢)، الجرح والتعديل (٦/ ١٠٧)، الثقات (٧/ ١٢٤)، المغنى (٣٨٦٩)، سير الأعلام (٧/ ١٨٧)."],[10342,"قلت: وأظنه قد سبق والله أعلم."],[10343,"(٢) هو: عاصم بن هلال البارقى ويقال: العنبرى، أبو النضر البصرى، إمام مسجد أيوب السختيانى."],[10344,"انظر: تهذيب الكمال (١٣/ ٣٠٣٠)، تهذيب التهذيب (٥/ ٥٨)، التاريخ الكبير (٦ / ت ٣٠٧٦)، الجرح والتعديل (٦ / ت ١٩٣٨)، الكاشف (٢ / ت ٢٥٤٣)، ميزان الاعتدال (٢ / ت ٤٠٧٠)، المغنى (١ / ت ٢٩٩٦)، ديوان الضعفاء (ت ٢٠٤٣)، المجروحين (٢/ ١٢٩)، علل أحمد (١/ ١٤٢)، سؤالات البرقانى (٣٤٠)، تاريخ ابن معين (٢/ ٢٨٤)."],[10345,"(٣) هو: عبد الله بن بسر السكسكى الحبرانى أبو سعيد الحمصى، سكن البصرة."],[10346,"انظر: تهذيب الكمال (١٤ / ت ٣١٨١)، تهذيب التهذيب (٥/ ١٥٩)، الجرح والتعديل (٥ / ت ٥٧)، الكاشف (٢ / ت ٢٦٧٠)، ميزان الاعتدال (٢/ ٤٢٢٥)، ديوان الضعفاء (ت ٢١٢٧)، المغنى (١ / ت ٣١١٣)، تاريخ الإسلام (٥/ ٢٦٤)، ضعفاء الدارقطنى (٣١٧)، الثقات (٥/ ١٥)، ضعفاء النسائى (ت ٣٤٥)، الكامل لابن عدى (٥/ ٢٨٤)."],[10347,"(٤) هو: عبد الله بن رجاء بن عمر، ويقال: ابن المثنى، أبو عمر، ويقال: أبو عمرو الغدانى البصرى. ="],[10348,"ابن أبى خيثمة قال: سمعت ابن معين يقول: عبد الله بن رجاء البصرى ليس من أصحاب الحديث."],[10349,"٥٨١ - عامر الأحول"],[10350,"(١)"],[10351,"العباس الدورى قال: سمعت أبا بكر بن أبى الأسود قال: سألت إسماعيل عن عامر الأحول؟، فقال: سل جدك أبا الأسود؛ فإنه أعلم به، فسألته فقال: كان ضعيفًا فى الحديث."],[10352,"٥٨٢ - عبد الكريم"],[10353,"(٢)"],[10354,"قال: حدثنا أبو بكر، أخبرنا إسماعيل قال: خرج عبد الكريم مرة من البصرة فقال أبو العالية: اللهم لا ترد صاحب الأكسية."],[10355,"٥٨٣ - عمران القطان"],[10356,"(٣)"],[10357,"= انظر: تهذيب الكمال (١٤ / ت ٣٢٦٢)، تهذيب التهذيب (٥/ ٢٠٩)، الجرح والتعديل (٥ / ت ٢٥٥)، الكاشف (٢٧٤١)، ميزان الاعتدال (٢ / ت ٤٣٠٩)."],[10358,"(١) هو: عامر بن عبد الواحد الأحول البصرى."],[10359,"قال أحمد: ليس هو بالقوى فى الحديث؛ ضعيف."],[10360,"انظر: تهذيب الكمال (١٤ / ت ٣٠٥٤)، التاريخ الكبير (٦ / ت ٢٩٧٧)، الجرح والتعديل (٦ / ت ١٨١٧)، الكاشف (ت ٢٥٦٤)، ميزان الاعتدال (٢ / ت ٤٠٨٩)، تعجيل المنفعة (٥٠٥)، طبقات خليفة (٢١٦)، علل أحمد (١٥٣)، سوالات الآجرى لأبى داود (٣ / ت ٣١٤)، المعرفة والتاريخ (٢/ ٦٦٦)، ثقات ابن شاهين (ت ٢٠٥٤)، الغنى (ت ٣٠١٥)، تاريخ الإسلام (٥/ ٩٢)، ديوان الضعفاء (ت ٢٠٥٤)، الأنساب (١/ ١٤٨)، تاريخ ابن معين (٢/ ٢٨٨)."],[10361,"(٢) هو: عبد الكريم بن أبى المخارق، واسمه قيس، ويقال: طارق أبو أمية المعلم البصرى."],[10362,"انظر: تهذيب الكمال (١٨ / ت ٣٥٠٦)، تهذيب التهذيب (٦/ ٣٧٦)، الجرح والتعديل (٦ / ت ٣١١)، الكاشف (٢ / ت ٣٤٧٦)، ميزان الاعتدال (٢ / ت ٥١٧٢)، سير أعلام النبلاء (٦/ ٨٣)، لسان الميزان (٧/ ٢٩١)، الكامل لابن عدى (٧/ ٣٧)."],[10363,"(٣) هو: عمران بن داور العمى أبو العوام القطان البصرى."],[10364,"انظر: تهذيب التهذيب (٨/ ١٣٠)، تهذيب الكمال (٢٢ / ت ٤٤٨٩)، التاريخ الكبير (٦ / ت ٢٨٦٨)، الجرح والتعديل (٦ / ت ١٦٤٩)، ميزان الاعتدال (٣ / ت ٦٢٨٢)، الكامل لابن عدى (٦/ ١٦٢)، سير أعلام النبلاء (٧/ ٢٨٠)، تاريخ الإسلام (٦/ ٥٩)، الكنى للدولابى (٢/ ٤٧)، علل أحمد (١/ ٢٤٣)، تراجم الأحبار (٣/ ٢٣٣)."],[10365,"ابن أبى خيثمة قال: قال يحيى بن معين: عمران بن القطان ضعيف، قال ابن أبى"],[10366,"خيثمة: وهو عمران الداور أبو العوام القطان، أخبرنا بذلك عمرو بن مرزوق."],[10367,"يتلوه فى الجزء السادس إن شاء الله"],[10368,"على بن المدينى قال: سمعت يحيى يقول: لم يكن عمر بن سعد ممن يعتمد عليه."],[10369,"الحمد لله رب رب العالمين وصلواته على سيدنا محمد النبى وآله وسلامه."],[10370,"وهو حسبنا ونعم الوكيل."],[10371,"الجزء السادس من كتاب"],[10372,"قبول الأخبار ومعرفة الرجال"],[10373,"تأليف أبى القاسم عبد الله بن أحمد بن محمود البلخى (١)"],[10374,"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ"],[10375,"الحمد لله رب العالمين، وصلى الله على سيدنا محمد النبى، وآله الطيبين وسلم تسليمًا وحسبنا الله ونعم الوكيل (٢)."],[10376,"٥٨٤ - عمر بن سعد"],[10377,"(٣)"],[10378,"على بن المدينى قال: سمعت يحيى بن معين يقول: لم يكن عمر بن سعد ممن يعتمد عليه."],[10379,"٥٨٥ - وعثمان بن سعد الكاتب"],[10380,"(٤)"],[10381,"بصرى ليس بشئ."],[10382,"٥٨٦ - عبد الأعلى بن أبى المساور"],[10383,"(٥)"],[10384,"(١) هذا العنوان بداية كل جزء جديد منفصل عن الذى قبله، كذا فعل المصنف فى الأجزاء السابقة وهذا آخر الأجزاء، والله الموفق."],[10385,"(٢) هذه العبارة يقدم بها المصنف لجميع الأجزاء."],[10386,"(٣) قال ابن عدى: عمر بن سعد، عن عمر بن عبد الله الثقفى، عن أبيه لم يصح حديثه سمعت ابن حماد يذكره عن البخارى."],[10387,"انظر: الكامل لابن عدى (٦/ ١٠٨)، المغنى (٢ / ت ٤٤٧١)، لسان الميزان (٤/ ٣٠٧)، التاريخ الكبير (٦/ ١٥٨)، ميزان الإعتدال (٣/ ١٩٩)."],[10388,"(٤) هو عثمان بن سعد التميمى، أبو بكر البصرى الكاتب المعلم. انظر: تهذيب الكمال (١٩/ ت ٣٨١٤)، تهذيب التهذيب (٧/ ١١٧)، الجرح والتعديل (٦ / ت ٨٣٨)، الكاشف (٢ / ت ٣٧٤٩)، ميزان الاعتدال (٣ / ت ٥٥١١)، الغنى (٢ / ت ٤٠٢٣)، المجروحين (٢/ ٩٦)، ديوان الضعفاء (٢٧٦٣)، تاريخ الإسلام (٦/ ٢٤٧)، تاريخ ابن معين (٢٣٩٣)، طبقات ابن سعد (٥/ ٣١٦)، ضعفاء النسائى (٤٢١)، لسان الميزان (٧/ ٣٠١)، الكامل لابن عدى (٦/ ٢٨٧)."],[10389,"(٥) هو: عبد الأعلى بن أبى المساور، أبو مسعود الجرار الكوفى، الزهرى مولاهم، نزيل المدائن."],[10390,"قال البخارى: كوفى منكر الحديث."],[10391,"انظر: تهذيب التهذيب (٦/ ٩٨)، تهذيب الكمال (١٦/ ٣٦٦)، التاريخ الكبير = واسطى وليس حديثه بشئ."],[10392,"٥٨٧ - عتبة بن أبى حكيم"],[10393,"(١)"],[10394,"قال: وسمعته يقول: عتبة بن أبى حكيم ضعيف."],[10395,"٥٨٨ - عبد الرزاق بن عمر"],[10396,"(٢)"],[10397,"وسمعته يقول: عبد الرزاق بن عمر الذى يروى عنه الحكم بن موسى ليس بشئ، وكان شاميًّا."],[10398,"٥٨٩ - عتاب بن بشير"],[10399,"(٣)"],[10400,"= (٦ /ت ١٧٥٣)، الجرح والتعديل (٦ /ت ١٣٥)، ميزان الاعتدال (٢ /ت ٤٧٣١)، الكاشف (٢ /ت ٣١١٨)، لسان الميزان (٧/ ٢٧٤)، الكامل لابن عدى (٦/ ٥٤٧)، الأنساب (٣/ ٢٣٢)، التاريخ الصغير (٢/ ١٧١)، الضعفاء الكبير (٣/ ٦١)، المجروحين (٢/ ١٥٦)، المغنى (١ /ت ٣٤٤٩)."],[10401,"(١) هو: عتبة بن أبى حكيم الهمدانى، ثم الشعبانى، أبو العباس الأردنى، قال ابن عدى شامى."],[10402,"والقول الأول لابن حجر فى تهذيب التهذيب. قال ابن معين: ثقة، كذا قاله الدورى والغلابى عنه."],[10403,"انظر: تهذيب الكمال (١٩/ ت ٣٧٧٢)، التاريخ الكبير (٦ /ت ٣٢١٨)، الجرح والتعديل (٦ /ت ٢٠٤٣)، الكاشف (٢ /ت ٣٧١٢)، تهذيب التهذيب (٧/ ٩٤)، الكامل لابن عدى (٧/ ٦٦)، ثقات ابن حبان (٧/ ٢٧١)، ثقات ابن شاهين (١١٠٣)، المعرفة والتاريخ ليعقوب (٢/ ٤٥٦، ٨١٣)، تاريخ ابن معين رواية الدورى (٢/ ٣٨٩)، أحوال الرجال (٣٠٩)، تاريخ واسط (٧١)، ضعفاء النسائى (٤١٥)، لسان الميزان (٧/ ٣٠٠)، تاريخ الإسلام (٦/ ٩٩)، معجم البلدان (١/ ٢٠٣)."],[10404,"(٢) هو: عبد الرزاق بن عمر الثقفى، أبو بكر الدمشقى الكبير."],[10405,"انظر: تهذيب الكمال (١٨ /ت ٣٤١٣)، التاريخ الكبير (٦ /ت ١٩٣٤)، الجرح والتعديل (٦ /ت ٢٠٥)، ميزان الاعتدال (٢ /ت ٥٠٤١)، تهذيب التهذيب (٦/ ٣٠٩)، الكامل لابن عدى (٦/ ٥٣٧)، تاريخ البخارى الصغير (٢/ ١٨٠)، لسان الميزان (٧/ ٢٨٧)، الثقات (٨/ ٢ / ٤)، المغنى (١ /ت ٣٦٨٥)، المجروحين (٢/ ١٥٩)، المعرفة والتاريخ (٣/ ٤١)، تاريخ ابن معين رواية الدورى (٣/ ٣٦٢)، دائرة معارف الأعلمى (٢١/ ١١٦)."],[10406,"(٣) هو: عتاب بن بشير الجزرى أبو الحسن، ويقال: أبو سهل الحرانى مولى بنى أمية."],[10407,"قال أحمد: أرجو أن لا يكون به بأس، روى بآخره أحاديث منكرة، وما أرى أنها إلا من قبل خصيف."],[10408,"انظر: تهذيب الكمال (١٩/ ت ٣٧٦٣)، تهذيب التهذيب (٧/ ٩١)، التاريخ الكبير (٧ /ت ٢٥٥)، الجرح والتعديل (٧ /ت ٥٦)، الكاشف (٢ /ت ٣٧٠٤)، ميزان الاعتدال (٣ /ت ٥٤٦٥)، الكامل لابن عدى (٧/ ٦٤)، الكنى لمسلم (٢٣)، طبقات خليفة (٣٢١)، علل أحمد = قال: وسمعت هارون بن معروف يقول: اختلط على عتاب بن بشير العرض والسماع فكان يتكلم فيه."],[10409,"٥٩٠ - عبد الرحمن بن زياد بن أنعم الأفريقى"],[10410,"(١)"],[10411,"قال: وسئل يحيى بن معين، عن عبد الرحمن بن زياد بن أنعم الأفريقى، فقال: ضعيف."],[10412,"٥٩١ - عامر بن شقيق بن جمرة"],[10413,"(٢)"],[10414,"قال: وقال: عامر بن شقيق بن حمزة، ضعيف الحديث وهو أسدى."],[10415,"٥٩٢ - عمرو بن قيس"],[10416,"قال: وسئل عن حديث عمرو بن قيس، عن عاصم بن أبى النجود، عن شقيق، عن عبد الله قال: قال رسول الله - صلى الله عليه وآله وسلم -: \"تابعوا بين الحج والعمرة فإنهما ينفيان الفقر والذنوب كما ينفى الكير خبث الحديد والفضة، وليس للحج المبرور ثواب إلا الجنة\" (٣)."],[10417,"فقال: عمرو ثقة وهو حديث منكر."],[10418,"٥٩٣ - عبيد الله بن الوليد الوصافى"],[10419,"(٤)"],[10420,"= (١/ ٥٦)، ثقات ابن حبان (٨/ ٥٢٢)، طبقات ابن سعد (٧/ ٤٨٥)، تاريخ الدارمى (٥٣٩، ٥٤٠)."],[10421,"(١) هو: عبد الرحمن بن زياد بن أنعم بن ذرى بن يحمد بن معد يكرب بن أسلم بن منبه بن النمادة ابن حيويل الشعبانى أبو أيوب، ويقال: أبو خالد الأفريقى القاضى، قال ابن عدى: أبو خلف."],[10422,"انظر: تهذب الكمال (١٧/ ٣٨١٧)، تهذيب التهذيب (٦/ ١٧٣)، الكاشف (٢ / ت ٣٢٣٢)، ميزان الاعتدال (٢ / ت ٤٨٦٦)، الجرح والتعديل (٥ / ت ١١١١)، التاريخ الكبير (٥ / ت ٩١٦)، الكامل لابن عدى (٥/ ٤٥٧)، لسان الميزان (٧/ ٢٧٩)، خلاصة تذهيب الكمال (٢٢٧)، طبقات خليفة (٢٩٦)، سير أعلام النبلاء (٦/ ٤١١)."],[10423,"(٢) هو: عامر بن شقيق بن جمرة الأسدى الكوفى، قال ابن معين: هذا ليس هو ابن شقيق بن سلمة."],[10424,"انظر: تهذيب الكمال (١٤/ ٣٠٤٣)، تهذيب التهذيب (٥/ ٩٦)، الجرح والتعديل (٦ / ت / ١٨٠)، الكاشف (٢ / ت ٢٥٥٤)، ميزان الاعتدال (٢ / ت ٤٠٨٠)، ديوان الضعفاء (٢٠٥٠)، الثقات (٧/ ٢٤٩)، المغنى (١ / ت ٣٠٠٦)، تاريخ ابن معين (٢/ ٢٨٧)."],[10425,"(٣) ذكره الهيثمى فى مجمع الزوائد (٣/ ٢٧٧)، من طريق ابن عباس، وابن عمر، وعامر بن ربيعة وجابر، وعزاه لأحمد والطبرانى والبزار، وجميع طرقه فيها من فيه ضعف. وقد تقدم تخريجه."],[10426,"(٤) هو: عبيد الله بن الوليد الوصافى، أبو إسماعيل الكوفى، قال البخارى: هو من ولد الوصاف ابن عامر العجلى."],[10427,"قال: وسئل عن عبيد الله بن الوليد الوصافى، فقال: ضعيف الحديث."],[10428,"٥٩٤ - عمرو بن خالد"],[10429,"(١)"],[10430,"قال: وسمعته يقول: عمرو بن خالد يحدث عنه الحسن بن ذكوان، كوفى ليس بشئ."],[10431,"٥٩٥ - عمران"],[10432,"(٢)"],[10433,"قال: وسئل عن عمران الذى روى عن عكرمة قال: كان طالوت سقاء فلم يدمن عمران، قال: وحدثنا هو قال: حدثنا أبو أحمد الزبيرى، عن شريك، عن عمران، عن عكرمة قال: كان طالوت سقاء يبيع الماء."],[10434,"٥٩٦ - عمرو بن ثابت الحداد"],[10435,"(٣)"],[10436,"قال: وسمعته يقول: عمرو بن ثابت الحداد لا يكتب حديثه."],[10437,"٥٩٧ - عمرو بن ثابت"],[10438,"(٤)"],[10439,"انظر: تهذيب الكمال (١٩ / ت ٣٦٩٤)، تهذيب التهذيب (٧/ ٥٥)، التاريخ الكبير (٥ / ت ١٢٩٨)، الجرح والتعديل (٥ / ت ١٥٩٠)، الكاشف (٢ / ت ٣٦٤٩)، ميزان الاعتدال (٣ /ت ٥٤٠٥)، الثقات (٧/ ١٥٠)، لسان الميزان (٧/ ٢٩٨)، الكامل لابن عدى (٥/ ٥٢٠)، الضعفاء الكبير (٣/ ١٢٨)، المغنى (٢ /ت ٣٩٥٣)."],[10440,"(١) هو: عمرو بن خالد أبو خالد، الكوفى، انتقل إلى واسط، قال ابن حجر: أبو خالد القرشى، مولى بنى هاشم."],[10441,"انظر: تهذيب الكمال (٢١ / ت ٤٣٥٧)، تهذيب التهذيب (٨/ ٢٦)، التاريخ الكبير (٦ / ت ١٢٧٧)، الكاشف (٢ / ت ٤٢١٣)، الكامل لابن عدى (٦/ ٢١٧)، المعرفة والتاريخ (٣/ ٣٩٥)، المجروحين (٢/ ٧٦)، ضعفاء الدارقطنى (٤٠٣)، ضعفاء أبى نعيم (ت ١٦٦)، ديوان الضعفاء (ت ٣٠٧٣)، تاريخ الإسلام (٦/ ٢٥٩)، تاريخ الدورى (٢/ ٤٤٢)، نسيم الرياض (٣/ ٤٧٢)، تنقيح المقال (٢ /ت ٨٦٩١)."],[10442,"(٢) أظنه عمران بن ظبيان، وقد سبق، والله أعلم."],[10443,"(٣) هو: عمرو بن ثابت بن هرمز، وهو عمرو بن أبى المقدام العجلى، الكوفى البكرى، ويقال: أبو محمد، مولى بكر بن وائل."],[10444,"انظر: تهذيب الكمال (٢١/ ت ٤٣٣٣)، تهذيب التهذيب (٨/ ٩)، ميزان الاعتدال (٣ /ت ٦٣٤٠)، الكامل لابن عدى (٦/ ٢/٢)، طبقات ابن سعد (٦/ ٣٨٣)، تاريخ ابن معين رواية الدورى (٢/ ٤٤٠)، رواية الدارمى (ت ٥٢٠)، المعرفة والتاريخ (٢/ ٦٥١)، ضعفاء الدارقطنى (٤٠٢)، موضح أوهام الجمع والتفريق (٢/ ٢٩٤)، ديوان الضعفاء (ت ٣١٦٣)، معرفة ليعقوب، الثقات (١٣٦٩)، معجم الثقات (١٧٧)، المغنى (٤٦٣٦)، المجروحين (٢/ ٧٦)، لسان الميزان (٧/ ٣٢٣)."],[10445,"(٤) هو الذى سبق، والله أعلم."],[10446,"قال: وحدثنا الوليد بن شجاع، حدثنا على بن الحسن بن شقيق قال: سمعت عبد الله بن المبارك يقول: دعوا حديث عمرو بن ثابت، فإنه كان يسب السلف (١)."],[10447,"٥٩٨ - عمار بن سيف"],[10448,"(٢)"],[10449,"قال: وسمعت يحيى. يقول: عمار بن سيف ليس حديثه بشئ."],[10450,"٥٩٩ - عبد الله بن جابر بن ربيعة الضبى"],[10451,"قال: وسمعته يقول: عبد الله بن جابر بن ربيعة الضبى، روى عنه أبو نعيم قال: ضعيف (٣)."],[10452,"٦٠٠ - عبد الرحمن بن مسهر"],[10453,"(٤)"],[10454,"قال: وسمعته يقول: عبد الرحمن بن مسهر ليس بشئ، وهو قاضى جبل (٥)، الذى مدح نفسه عند هارون (٦)."],[10455,"٦٠١ - عزرة"],[10456,"(٧)"],[10457,"(١) ذكر ابن عدى فى الوضع السابق، أن ابن المبارك تركه."],[10458,"(٢) هو: عمار بن سيف الضبى، أبو عبد الرحمن الكوفى. انظر: تهذيب الكمال (٢١ / ت ٤١٦٤)، تهذيب التهذيب (٧/ ٤٠٢)، التاريخ الكبير (٧ / ت ١٣١)، الجرح والتعديل (٦ / ت ٢١٩١)، ميزان الاعتدال (٣ / ت ٥٩٨٩)، ديوان الضعفاء (ت / ٢٩٨٥)، طبقات ابن سعد (٦/ ٣٨٨)، تاريخ الثقات (٣٥٢٢)، تاريخ ابن معين رواية الدورى (٢/ ٤٢٣)، رواية الدارمى (ت ٦٧٥)، المشتبه (٥٩٩)، المجروحين (٢/ ١٩٥)، لسان الميزان (٧/ ٣١٤)، الكامل لابن عدى (٦/ ١٣٥)."],[10459,"(٣) انظر: الجرح والتعديل (٥ / ت ١١٧)، ميزان الاعتدال (٢/ ٤٠٠)، ديوان الضعفاء (٢١٣٦)، دائرة معارف الأعلمى (٢١/ ١٧٦)، لسان الميزان (٣/ ٢٦٥)، المغنى (١ / ت ٣١٢٢)."],[10460,"(٤) هو: عبد الرحمن بن مسهر، الكوفى، أخو على بن مسهر وقد سبق."],[10461,"(٥) هى بليدة بين النعمانية وواسط فى الجانب الشرقى، ينسب إليها جماعة من أهل العلم، هامش سير أعلام النبلاء."],[10462,"(٦) ذكر الذهبى أنه مدح نفسه عند المأمون عندما كان يمر على ناحية جُبَّل على جانب دجلة، سير أعلام النبلاء (٨/ ٤٨٤)."],[10463,"(٧) هو: عزرة بن عبد الرحمن الخزاعى الكوفى الأعور."],[10464,"انظر: تهذيب الكمال (٢٠/ ت ٣٩٢٠)، الجرح والتعديل (٧ / ت ١١٢)، الكاشف (٢ /ت ٣٨٤١)، تهذيب التهذيب (٧/ ١٩٢)."],[10465,"على قال: قلت ليحيى تعرف عزرة صاحب قتادة؟، قال: بلى، والله إنى لأعرفه وأكره أن أقول (١)."],[10466,"٦٠٢ - عمرو بن سمرة"],[10467,"(٢)"],[10468,"قال أبو حاتم الرازى: عمرو بن سمرة ضعيف الحديث."],[10469,"٦٠٣ - وعطاء بن مسلم الحفاف"],[10470,"(٣)"],[10471,"دفن كتبه وخلط فى حديثه."],[10472,"٦٠٤ - وعلى بن قردين"],[10473,"(٤)"],[10474,"ذاهب الحديث."],[10475,"٦٠٥ - عمرو بن محمد العنقزى"],[10476,"(٥)"],[10477,"ليس بذاك المتين."],[10478,"(١) ذكره ابن أبى حاتم فى \"الجرح والتعديل\"، وفى آخره بلى، والله والله إنى لأعرفه، وليس فيه وأكره أن أقول. قال ابن المدينى: ثقة. قلت: والقول الذى ذكره ابن أبى حاتم قول يحيى بن سعيد القطان."],[10479,"(٢) كذا بالمخطوط، وأظنه: عمر بن شمر الجعفى، أبو عبد الله، روى عن عمران بن مسلم، والسدى وجابر الجعفى، روى عنه أحمد بن يونس، كذا فى الجرح والتعديل (٣ /ت ١٣٢٤)."],[10480,"(٣) هو: عطاء بن مسلم الخفاف أبو مخلد الكوفى، نزيل حلب."],[10481,"انظر: تهذيب الكمال (٢٠ /ت ٣٩٤٠)، تهذيب التهذيب (٧/ ٢١١)، التاريخ الكبير (٦ /ت ٣٠٣٣)، الجرح والتعديل (٦ /ت ١٨٥٩)، الكاشف (٢ /ت ٣٨٥٦)، ميزان الاعتدال (٣ /ت ٥٦٤٨)، الكامل لابن عدى (٨٠١٧)، لسمان الميزان (٧/ ٣٠٥)، الأنساب (٥/ ١٥٥)، المغنى (٢ /ت ٤١٢٨)، ديوان الضعفاء (ت ٢٨٣١)، المجروحين (٢/ ١٣١)، تاريخ بغداد (١٢/ ٢٩٤)، معجم البلدان (٣/ ١٢٤)، الثقات (٧/ ٢٥٣)."],[10482,"(٤) كذا بالمخطوط، وأظنه على بن قرين بن بهيس بغدادى بصرى، قال ابن عدى: بصرى يسرق الحديث."],[10483,"إنظر: الكامل لابن عدى (٦/ ٣٦٦)، المغنى (٢/ ٤٣١٩)، لسان الميزان (٤/ ٢٥١)، ميزان الاعتدال (٣/ ٥٩١٣)، الضعفاء والمتروكين (٢/ ١٩٨)، الضعفاء الكبير (٣/ ٢٤٩)، الكشف الحثيث (٥١٩)."],[10484,"(٥) هو: عمرو بن محمد العنقزى القرشى مولاهم، أبو سعيد الكوفى، قال ابن حبان: كان يبيع العنقز فنسب إليه والعنقز المرزنجوش. قال أحمد والنسائى: ثقة، وكذا قال العجلى."],[10485,"انظر: تهذيب الكمال (٢٢ /ت ٤٤٤٤)، تهذيب التهذيب (٨/ ٩٨)، الجرح والتعديل (٦ /ت ١٤٥٠)، الكاشف (٢ /ت ٤٢٩١). قلت: أخطأ المصنف فى إيراده هنا تحت عنوان هذا الباب."],[10486,"٦٠٦ - عطية العوفى"],[10487,"(١)"],[10488,"لين الحديث."],[10489,"٦٠٧ - عمرو بن قيس سندل المكى"],[10490,"(٢)"],[10491,"ضعيف الحديث."],[10492,"٦٠٨ - وعلى بن على اللهبى"],[10493,"(٣)"],[10494,"ضعيف الحديث."],[10495,"٦٠٩ - على بن عابس"],[10496,"(٤)"],[10497,"ليس بالقوى يكتب حديثه."],[10498,"٦١٠ - عطاء بن خالد"],[10499,"(٥)"],[10500,"يكتب حديثه ولا يحتج به."],[10501,"٦١١ - وعلى بن الحسين بن واقد"],[10502,"(٦)"],[10503,"ليس بالمتين."],[10504,"(١) هو: عطية بن سعد العوفى الكوفى، يكنى أبا الحسن، وقد سبق."],[10505,"(٢) سبق."],[10506,"(٣) هو: على بن أبى على اللهبى المدينى. قال أحمد: يروى أحاديث مناكير عن جابر. وقال البخارى: لم يرضه أحمد منكر الحديث."],[10507,"انظر: الكامل لابن عدى (٦/ ٣١٤)، الضعفاء والمتروكين (٢/ ١٩٦)، الجرح والتعديل (٦ / ت ١٩٧)، الضعفاء الكبير (٣/ ٢٤٠)، المغنى (٢ / ت ٤٣٠٧)، ميزان الاعتدال (٣/ ١٤٧)، الضعفاء والمتروكين للدارقطنى (ت ٤٠٨)، ديوان الضعفاء (ت ٢٩٤٨)، الأنساب (١١/ ٢٣٦)، لسان الميزان (٤/ ٢٤٥)."],[10508,"(٤) هو: على بن عابس السدى، وقد سبق."],[10509,"(٥) كذا بالمخطوط، وقال ابن حجر: صوابه: عطاف. هو: عطاف بن خالد بن عبد الله بن صفوان المخزومى. قال البخارى: لم يحمده مالك بن أنس. وقال أحمد: ثقه صحيح الحديث روى نحو مائة حديث."],[10510,"انظر: الكامل لابن عدى (٧/ ٩٥)، الجرح والتعديل (٧/ ٢١)، ميزان الاعتدال (٣ / ت ٥٦٣١)، الكاشف (٢ / ت ٣٧٧٠)، تهذيب الكمال (٢٠/ ت ٣٩٣٥)، التاريخ الكبير (٧ / ت ٢٣٢)."],[10511,"(٦) هو: على بن الحسين بن واقد المروزى، كان جده واقد، مولى عبد الله بن عامر بن كريز، توفى سنة (٢١١)، أو (٢١٢)."],[10512,"انظر: تهذيب الكمال (٢٠ / ت ٤٠٥٢)، تهذيب التهذيب (٧/ ٣٠٨)، التاريخ الكبير (٦ / ت ٢٣٦٥)، الجرح والتعديل (٦ / ت ٩٧٨)، الكاشف (٢ / ت ٣٩٥٧)، ميزان الاعتدال (٣ / ت ٥٨٢٤)."],[10513,"٦١٢ - وعيسى بن ميمون"],[10514,"(١)"],[10515,"صاحب القاسم، عن عائشة، ضعيف الحديث، منكر الحديث، لا ينبغى أن يحدث عنه."],[10516,"٦١٣ - وعيسى بن أبى عيسى الحناط"],[10517,"(٢)"],[10518,"ضعيف الحديث."],[10519,"٦١٤ - وعبد الرحمن بن إسحاق"],[10520,"(٣)"],[10521,"يكتب حديثه ولا يحتج به، روى عنه البصريون بشر بن المفضل، ويزيد بن زريع."],[10522,"٦١٥ - وعباد بن كثير الرملى"],[10523,"(٤)"],[10524,"قال: ضعيف الحديث."],[10525,"٦١٦ - وعبد العزيز بن محمد الدراوردى"],[10526,"(٥)"],[10527,"يكتب حديثه ولا يحتج به."],[10528,"٦١٧ - عمرو بن إبراهيم"],[10529,"(٦)"],[10530,"صاحب قتادة ليس بالمتين، يكتب حديثه ولا يحتج به."],[10531,"٦١٨ - وعبد الرحمن بن سليمان [بن] (٧) الغسيل (٨)"],[10532,"(١) هو: عيسى بن ميمون الجرشى المدينى، يكنى أبا يحيى، وقد سبق."],[10533,"(٢) هو: عيسى بن أبى عيسى الحناط الغفارى أبو موسى، ويقال: أبو محمد المدنى، مولى قريش. وهو: عيسى بن ميسرة الكوفى، كان بالمدينة."],[10534,"انظر: تهذيب الكمال (٢٣ / ت ٤٦٤٨)، تهذيب التهذيب (٨/ ٢٢٤)، الجرح والتعديل (٦ /ت ١٦٠٥)، الكاشف (٢ /ت ٤٤٥٨)، ميزان الاعتدال (٣ /ت ٦٥٩٦)، التاريخ الكبير (٦ /ت ٢٧٩٤)، تاريخ الثقات (٣٨٠)، تراجم الأحبار (٣/ ٢٤٣١)، معرفة الثقات (١٤٦٦)، لسان الميزان (٧/ ٣٣٢)، المجروحين (٢/ ١١٧)، الكامل لابن عدى (٦/ ٤٣١)."],[10535,"(٣) هو: عبد الرحمن بن إسحاق، وهو عباد بن إسحاق، وعباد لقب مدينى، كذا قال ابن عدى."],[10536,"قال يحيى بن سعيد: لم أرهم يحمدونه، أي أهل المدينة، قال ابن معين: ثقة، وقال: صالح الحديث. قال أحمد: عبد الرحمن بن إسحاق المدينى الذى روى عنه ابن علية، وبشر بن المفضل، ويزيد بن زريع، وخالد الطحان، هو صالح الحديث، قال: وربما، قال إسماعيل: حدثنا عباد بن إسحاق، وعبد الرحمن بن إسحاق، وهو واحد كان له اسمان، عباد، وعبد الرحمن."],[10537,"انظر: الكامل لابن عدى (٥/ ٤٨٩، ٤٩٠)."],[10538,"(٤) هو عباد بن كثير بن قيس الرملى من أهل فلسطين. وقد سبق."],[10539,"(٥) سبق، وصوابه: عمر بن إبراهيم، والله أعلم."],[10540,"(٦) سبق."],[10541,"(٧) ما بين المعقوفين ساقط من المخطوط."],[10542,"(٨) هو: عبد الرحمن بن سليمان بن عبد الله بن حنظلة الأنصارى الأوسى المدنى، يكنى أبا سليمان الأنصارى. ابن الغسيل"],[10543,"يكتب حديثه ولا يحتج به."],[10544,"٦١٩ - وعنبسة بن سعيد"],[10545,"(١)"],[10546,"أخو أبى الربيع السمان، ضعيف الحديث، يروى عنه يزيد بن هارون."],[10547,"٦٢٠ - وعمر بن عبد الله بن يعلى بن مرة الثقفى"],[10548,"(٢)"],[10549,"ضعيف الحديث."],[10550,"٦٢١ - وعثمان بن عمير"],[10551,"(٣)"],[10552,"أبو يقظان ليس بالقوى، كان شعبة يتكلم فيه."],[10553,"انظر: تهذيب الكمال (١٧ / ت ٣٨٤٠) تهذيب التهذيب (٦/ ١٨٩) ميزان الاعتدال (٢ / ت ٤٨٨٣) الجرح والتعديل (٥ / ت ١١٣٤) الكاشف (٢ / ت ٣٢٥١) التاريخ الكبير (٥ / ت ٩٣٩) الكامل لابن عدى (٥/ ٤٦٣) الجمع لابن القيسرانى (١/ ٢٨١) العبر (١/ ٢٦٠) ديوان الضعفاء (ت ٢٤٥٤) المغنى (٢ / ت ٣٥٧٧) تاريخ ابن معين (٢/ ٣٤٩) ورواية الدارمى (٤٥٠)"],[10554,"(١) جاء بالمخطوط \"عنيبسة\" وهو تصحيف عن عنبسة بن سعيد القطان الواسطى ويقال: البصرى."],[10555,"انظر: تهذيب الكمال (٢٢ / ت ٤٥٣٤) تهذيب التهذيب (٨/ ١٥٧) الجرح والتعديل (٦ / ت ٢٢٣١) الكاشف (٢ / ت ٤٣٦٧) ميزان الاعتدال (٣ / ت ٦٥٠٣) المغنى (٢ / ت ٤٧٤٨) لسان الميزان (٧/ ٣٢٩). الكامل لابن عدى (٦/ ٤٦٥)."],[10556,"(٢) هو: عمر بن عبد الله بن يعلى بن منية الثقفى الكوفى."],[10557,"انظر: تهذيب الكمال (٢١ / ت ٤٢٧٠) تهذيب التهذيب (٧/ ٤٧٠) ميزان الاعتدال (٣ / ت ٦١٥٦) الجرح والتعديل (٦ / ت ٦٣٨) التاريخ الكبير (٦ / ت ١٨٧٥) معرفة الثقات (١٣٥٤) معجم الثقات (٢٢١) لسان الميزان (٧/ ٣١٩) المغنى (٢ / ت ٤٥٠٠) المعرفة والتاريخ (٣/ ١١١) تاريخ الإسلام (٥/ ٢٨٦) ديوان الضعفاء (ت ٣٠٧٦) تاريخ ابن معين رواية الدارمى (ت ٤٦٢) علل أحمد (١/ ١٨١) تاريخ ابن معين رواية الدورى (٢/ ٤٣١) الكامل لابن عدى (٦/ ٦٥)."],[10558,"(٣) هو: عثمان بن عمير البجلى أبو اليقظان الكوفى الأعمى، ويقال: ابن قيس، ويقال ابن حميد."],[10559,"انظر: تهذيب الكمال (١٩ / ت ٣٨٥١) تهذيب التهذيب (٧/ ١٤٥) التاريخ الكبير (٢ / ت ٢٠٥٥) الجرح والتعديل (٦ / ت ٨٨٤) الكاشف (٢ / ت ٣٧٨١) ميزان الاعتدال (٣ / ت ٥٥٥٠) تاريخ ابن معين رواية الدورى (٢/ ٣٩٥) رواية الدارمى (ت ٥٥٨) رواية ابن الجنيد (٣٦، ٥٥) علل أحمد (١/ ١٩، ١٦٧) تاريخ أبى زرعة الرازى (٤٣٠) المعرفة والتاريخ (٢/ ٧٨١) المجروحين (٢/ ٩٥) علل الدارقطنى (ت ٤٠٦) ديوان الضعفاء (ت ٢٧٨٠) لسان الميزان (٧/ ٣٠٢) المغنى (٢ / ت ٤٠٥١). تاريخ أبى زرعة الدمشقى (٦٤٧) سؤالات البرقانى (ت ٣٥٦)."],[10560,"٦٢٢ - وعبد الله بن محمد بن يحيى بن عروة"],[10561,"(١)"],[10562,"صاحب الحرامى، كان يفتعل الحديث."],[10563,"٦٢٣ - وعمرو بن دينار فهرمان آل الزبير"],[10564,"(٢)"],[10565,"ضعيف الحديث."],[10566,"٦٢٤ - وعبد الحميد بن جعفر"],[10567,"(٣)"],[10568,"يكتب حديثه ولا يحتج به."],[10569,"٦٢٥ - عبد الله بن محمد بن عجلان"],[10570,"(٤)"],[10571,"وسئل عن عبد الله بن محمد بن عجلان مولى فاطمة بنت عتبة، عن أبيه، عن جده، عن أبى هريرة، فقال: أبوه ثقة."],[10572,"٦٢٦ - وعبد الوهاب بن عطاء الخفاف"],[10573,"(٥)"],[10574,"(١) هو: عبد الله بن محمد بن يحيى بن عروة بن الزبير."],[10575,"انظر: الكامل لابن عدى (٥/ ٣٠٣) الجرح والتعديل (٥/ ١٥٨) الضعفاء والمتروكين (٢/ ١٤١). المغنى (١/ ت ٣٣٤٧) ديوان الضعفاء (٢٢٨٦) الضعفاء الكبير (٢/ ٣٠٠) الكشف الحثيث (٢٤٧) ضعفاء ابن الجوزى (٢/ ١٤١) تلخيص المستدرك (٣/ ٥٤٨) لسان الميزان (٣/ ٣٣١)."],[10576,"(٢) هو: عمرو بن دينار البصرى، أبو يحيى الأعور، قهرمان آل الزبير بن شعيب البصرى."],[10577,"انظر: تهذيب الكمال (٢٢ / ت ٤٣٦١) التاريخ الكبير (٦ /ت ٢٥٤٥) الجرح والتعديل (١ / ت ١٢٨١) الكاشف (٢ / ت ٤٢١٦) ميزان الاعتدال (٣ / ت ٦٣٦٦) تهذيب التهذيب (٨/ ٣٠) تاريخ ابن معين رواية الدارمى (ت ٤٤٩) أحوال الرجال (١٧١) كشف الأستار (١١٨٧) علل الدارقطنى (٢/ ٤٩) موضح أوهام الجمع والتفريق (٢/ ٢٨٦) ديوان الضعفاء (ت ٣١٧٧) تاريخ الإسلام (٥/ ٢٨٦) معرفة الثقات (١٣٧٨) المغنى (٢ / ت ٤٦٥٥)."],[10578,"(٣) هو: عبد الحميد بن جعفر بن عبد الله بن الحكم بن رافع بن سنان الأنصارى الأوسى أبو الفضل، ويقال: أبو حفص، ويقال: إن رافع بن سنان جده لأمه. توفى سنة ثلاث وخمسين ومائة."],[10579,"انظر: تهذيب الكمال (١٦/ ت ٣٧٠٩) تهذيب التهذيب (٦/ ١١١) الكاشف (٢ /ت ٣١٣٥) الجرح والتعديل (٦ / ت ٤٦) ميزان الاعتدال (٢ / ت ٤٧٦٧) تاريخ ابن معين رواية الدورى (٢/ ٣٤١) رواية الدارمى (ت ٢٦٣) تاريخ واسط ٢١٧، الجمع لابن القيسرانى (١/ ٣١٩) الثقات (٧/ ٢٢٢) سير أعلام النبلاء (٧/ ٢٠) الكامل لابن عدى (٧/ ٣)."],[10580,"(٤) هو: عبد الله بن محمد بن عجلان، روى عن أبيه، وعنه إبراهيم بن حمزة الزبيرى."],[10581,"انظر: الجرح والتعديل (٥ / ت ٧١٩) ديوان الضعفاء (ت ٢٢٨٨) الضعفاء الكبير (٣/ ٢٩٦) المجروحين (٢/ ١٩) التاريخ الكبير (٥/ ١٨٨) التحفة اللطيفة (٢/ ٣٩٨) المغنى (١ / ت ٣٣٣٦)."],[10582,"(٥) هو: عبد الوهاب بن عطاء الخفاف أبو نصر العجلى مولاهم البصرى. سكن بغداد."],[10583,"انظر: تهذيب الكمال (١٨ /ت ٣٦٠٥) التاريخ الكبير (٦ /ت ١٨٢٤) الجرح والتعديل (٦ /ت يكتب حديثه ولا يحتج به."],[10584,"٦٢٧ - وعباد بن راشد"],[10585,"(١)"],[10586,"عن الحسن ليس بالقوى، يكتب حديثه."],[10587,"٦٢٨ - وعاصم بن عمرو البجلى"],[10588,"(٢)"],[10589,"عن أبى أمامة، روى عنه فرقد السبخى والكوفيون، أبو إسحاق، وطارق، والحجاج ابن أرطاة، يكتب حديثه ولا يحتج به."],[10590,"٦٢٩ - والعباس بن الفضل الأنصارى الموصلى"],[10591,"(٣)"],[10592,"ضعيف الحديث، يروى عن القاسم بن عبد الرحمن."],[10593,"٦٣٠ - عبد الأعلى بن أبى المساور الكوفى"],[10594,"(٤)"],[10595,"٣٧٢) الكاشف (٢ / ت ٣٥٦٥) ميزان الاعتدال (٢ / ت ٥٣٢٢) تهذيب التهذيب (٦/ ٤٥٠) الكامل لابن عدى (٦/ ٥١٧) الثقات (٧/ ١٣٣) لسان الميزان (٧/ ٢٩٥) سير أعلام النبلاء (٩/ ٤٥١)."],[10596,"(١) هو: عباد بن راشد التميمى مولاهم البصرى البزار، ابن أخت داود بن أبى هند، ويقال: ابن خالته."],[10597,"انظر: تهذيب الكمال (١٤/ ١١٦) تهذيب التهذيب (٥/ ٩٢) ميزان الاعتدال (٢ / ت ٤١٠٣) الجرح والتعديل (٦ / ت ٤٠٦) الكاشف (٢ /ت ٢٥٨٤) التاريخ الكبير (٦ / ت ١٦٠٨) تاريخ الإسلام (٦/ ٢٠٦) ديوان الضعفاء (ت ٢٠٧٠) المغنى (١ /ت ٢٠٣٢) غاية النهاية لابن الجزرى (١/ ٣٥٢) الكشف الحثيث (٣٦٩) ثقات ابن شاهين (ت ١٠١٦) الجمع لابن القيسرانى (١/ ٣٣٣) تاريخ ابن معين رواية الدورى (٢/ ٢٩١) العلل لأحمد (١/ ٣٠٩) المعرفة والتاريخ (٢/ ١٢٦) ضعفاء النسائى (ت ٤٠٩) المجروحين (٢/ ١٦٣) الكامل لابن عدى (٥/ ٥٤٩)."],[10598,"(٢) (هو: عاصم بن عمرو، ويقال: ابن عوف البجلى الكوفى، قال أبو حاتم: صدوق يحول من كتاب \"الضعفاء\" يعنى الذى للبخارى."],[10599,"انظر: تهذيب الكمال (١٣/ ٣٠٢٢) تهذيب التهذيب (٥/ ٥٤) ميزان الاعتدال (٢ /ت ٤٠٦٣) الكاشف (٢ /ت ٢٥٣٥) التاريخ الكبير (٦ / ت ٣٠٧٨)."],[10600,"(٣) هو عباس بن الفضل بن عمرو بن عبيد الأنصارى الموصلى المقرى."],[10601,"انظر: الكامل لابن عدى (٦/ ٣) الضعفاء والمتروكين (٢/ ٧٩) الضعفاء الكبير (٣/ ٣٦١) المجروحين (٢/ ١٨٩) الجرح والتعديل (٦/ ٢١٢) المغنى (١ / ت ٣٠٨٠) ميزان الاعتدال (٢/ ٣٨٥) تهذيب الكمال (١٤ / ت ٣١٣٥) التاريخ الكبير (٧ / ت ١٢) الكاشف (٢ / ت ٢٦٣٠) تهذيب التهذيب (٥/ ١٢٦)."],[10602,"(٤) هو عبد الأعلى بن أبى المساور الزهرى مولاهم، أبو مسعود الجرار الكوفى، نزيل المدائن."],[10603,"قال: حدثنا إبراهيم بن موسى الفراء قال: أخبرنا [١٠٠/ أ] ابن أبى زائدة قال: نهيت أنا خالد أن يحدث عن عبد الأعلى بن أبى المساور الكوفي."],[10604,"٦٣١ - عمر بن يزيد الرفاء"],[10605,"(١)"],[10606,"وعمر بن يزيد الرفاء أبو حفص كذاب."],[10607,"٦٣٢ - عمران بن عُيَيْنَة (٢) وأخوته."],[10608,"٦٣٣ - محمد"],[10609,"(٣)."],[10610,"٦٣٤ - وإبراهيم"],[10611,"(٤)."],[10612,"٦٣٥ - وآدم"],[10613,"(٥)."],[10614,"ليسوا بالأقوياء."],[10615,"٦٣٦ - عمرو بن أبى عمر"],[10616,"(٦)"],[10617,"انظر: تهذيب الكمال (١٦ / ت ٣٦٩٠) تهذيب التهذيب (٦/ ٩٨) التاريخ الكبير (٦ / ت ١٧٥٣) الجرح والتعديل (٦ / ت ١٣٥) ميزان الاعتدال (٢ / ت ٤٧٣١) الكاشف (٢ / ت ٣١١٨)."],[10618,"(١) انظر: الكامل لابن عدى (٦/ ١١٢) الضعفاء والمتروكين (٢/ ٢١٩) الضعفاء الكبير (٣/ ١٩٥) الجرح والتعديل (٦/ ١٤٢)."],[10619,"(٢) هو: عمران بن عيينة بن أبى عمران الهلالى، أبو الحسن الكوفي، أخو سفيان."],[10620,"قال الآجرى: سئل أبو داود، عن إبراهيم، وعمران، ومحمد بن عيينة، فقال: كلهم صالح وحديثهم قريب."],[10621,"إنظر: تهذيب الكمال (٢٢ / ت ٤٤٩٨)، تهذيب التهذيب (٨/ ١٣٦)، ميزان الاعتدال (٣ / ت ٦٣٠١)، التاريخ الكبير (٦ / ت ٢٨٧٤)، الجرح والتعديل (٣ / ت ١٦٨٠)، الكاشف (٢ / ت ٤٣٣٧)."],[10622,"(٣) تهذيب التهذيب (٩/ ٣٩٥)، ميزان الاعتدال (٣/ ٦٨٠)، الجرح والتعديل (٦/ ١٩٢)، لسان الميزان (٥/ ٣٣٧)، معرفة الثقات (١٦٣٢)، الإكمال (٦/ ١٢٦)، التاريخ الكبير (١/ ٢٠٤)، تاريخ الثقات (٤١٠)."],[10623,"(٤) المغنى (١/ ت ١٤١)، تهذيب التهذيب (١/ ١٤٩)، الجرح والتعديل (٢/ ٣٦٢)، الكاشف (١/ ٨٩)، التاريخ الكبير (١/ ٣١٠)."],[10624,"(٥) المغنى (١/ ت ٥٠٦)، ميزان الاعتدال (١/ ١٧٠)، جامع الرواة (١/ ٨)، رجال الطوسى (١٤٣)، اللسان (١/ ٣٣٦)، الجامع في الرجال (ص ٩)."],[10625,"(٦) هو: عمرو بن أبى عمر، واسمه: ميسرة، مولى الطلب بن عبد الله بن حنطب المخزومى، أبو عثمان المدنى، قلت: وقد سبق."],[10626,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن عمرو بن أبى عمر؟، قال: ضعيف الحديث، هو الذى روى عنه ابن الهاد."],[10627,"٦٣٧ - عبيد الله بن عبد الرحمن بن موهب"],[10628,"(١)"],[10629,"قال: وسئل عن عبيد الله بن عبد الرحمن بن موهب روى عنه الحنفى (٢)؟، قال: ليس بشئ."],[10630,"٦٣٨ - عبد الله بن جعفر"],[10631,"(٣)"],[10632,"قال: وسمعت يحيى يقول: عبد الله بن جعفر ابن أخى إسماعيل بن جعفر، شيخ كان يجالسنا فى المسجد، صاحب مغنيات، لم يكن بشئ."],[10633,"٦٣٩ - عيسى بن إبراهيم"],[10634,"(٤)"],[10635,"الدورى، حدثنا يحيى بن معين قال: عيسى بن إبراهيم ليس بشئ، روى عنه بقية وكثير بن هشام."],[10636,"٦٤٠ - وعيسى بن ميمون"],[10637,"(٥)"],[10638,"صاحب القاسم، عن عائشة، ليس بشئ."],[10639,"(١) هو: عبيد الله بن عبد الرحمن بن عبد الله بن موهب المدنى."],[10640,"انظرة ميزان الاعتدال (٣ / ت ٥٣٧٨)، الكامل لابن عدى (٥/ ٥٢٩)."],[10641,"(٢) الحنفى: هو أبو على الحنفى، والحديث هو ما ذكره ابن عدى فى الكامل فى عتق غلام وجارية كانوا عند السيدة عائشة، رضي الله عنها، وكذا ذكره الذهبى فى الميزان، والحديث، أخرجه ابن ماجه وغيره."],[10642,"(٣) لم أقف عليه."],[10643,"(٤) هو: عيسى بن إبراهيم بن طهمان الهاشمى، قال البخارى: منكر الحديث، قال النسائى متروك الحديث."],[10644,"انظر: الكامل لابن عدى (٦/ ٤٣٩)، الضعفاء والمتروكين (٢/ ٢٣٨)، الجرح والتعديل (٦/ ٢٧١)، المجروحين (٢/ ١٢١)، المغنى (٢ / ت ٤٧٨٦)، ضعفاء ابن الجوزى (٢/ ٢٣٨)، التاريخ الكبير (٦/ ٤٠٧)."],[10645,"(٥) هو: عيسى بن ميمون القرشى المدينى، مولى القاسم بن محمد، جمع بعضهم بينه وبين عيسى بن ميمون الجرشى، وفرق آخرون بينهم، وهو الصواب، والله أعلم."],[10646,"انظر: تقريب التهذيب (ت ٥٣٥٢)، تهذيب الكمال (٢٣ / ت ٤٦٦٧)، التاريخ الكبير (٦ / ت ٢٧٨١)، الجرح والتعديل (٦ / ت ١٥٩٥)، ميزان الاعتدال (٣ / ت ٦٦١٧)، الذيل على الكاشف (ت ١٢٠٨)، لسان الميزان (٧/ ٣٣٣)، تاريخ أسماء الثقات (١٠٦٥)، الثقات (٨/ ٤٨٩)، الكامل لابن عدى (٦/ ٤١٨)."],[10647,"٦٤١ - وعدى بن الفضل"],[10648,"(١)"],[10649,"لا يكتب حديثه."],[10650,"٦٤٢ - عبد الحميد بن جعفر"],[10651,"(٢)"],[10652,"قال: عبد الحميد بن جعفر كان يحيى بن سعيد يضعفه."],[10653,"٦٤٣ - وعمرو بن على بن مقدم"],[10654,"(٣)"],[10655,"لم أكتب عنه شيئًا، وكان واسطًا نزل البصرة."],[10656,"٦٤٤ - وعطاء بن طلق"],[10657,"(٤)"],[10658,"ليس بشئ."],[10659,"٦٤٥ - وعنبسة بن سعيد"],[10660,"(٥)"],[10661,"ضعيف، بصرى، وهو أخو أبى الربيع السمان."],[10662,"(١) هو: عدى بن الفضل التيمى، أبو حاتم البصرى، مولى بنى تيم بن مرة."],[10663,"انظر: تهذيب التهذيب (٧/ ١٦٩)، تهذيب الكمال (١٩/ ت ٣٨٨٩)، التاريخ الكبير (٧ / ت ٢٠٣)، الجرح والتعديل (٧ / ت ١١)، الكاشف (٢ / ت ٣٨١٦)، لسان الميزان (٧/ ٣٠٣)، معرفة الثقات (ت ١٢٢٥)، الثقات (٨/ ٥١٩)، المعرفة والتاريخ (٣/ ٦١)، تاريخ ابن معين رواية الدورى (٢/ ٣٩٨)، رواية الدارمى (ت ٥٧٨)، أحوال الرجال (ت ١٧٢)، السابق واللاحق (٣٣٧)، سؤالات البرقانى (ت ٥١٨)، الضعفاء الكبير (ت ٢٧٩٧)، الكامل لابن عدى (٧/ ٩٢)."],[10664,"(٢) تقدم برقم (٦٢٤)."],[10665,"(٣) هو: عمر بن على بن عطاء بن مقدم المقدمى، أبو جعفر البصرى، مولى ثقيف، قال ابن حجر: ثقة كان يدلس شديدًا."],[10666,"انظر: تهذيب الكمال (٢١/ ٤٢٩٠)، تهذيب التهذيب (٧/ ٤٨٥)، الجرح والتعديل (٦ / ت ٦٧٨)، الكاشف (٢ / ت ٤١٦٠)، ميزان الاعتدال (٣ / ت ٦١٧٢)، المغنى (٢ / ت ٤٥١٥)، ديوان الضعفاء (ت ٣٠٨٤)، لسان الميزان (٧/ ٣٢٠)."],[10667,"(٤) لم أقف عليه، ولعله: \"عصام بن طليق\"، وهذا أغلب الظن عندى، وأظنه هو الصواب."],[10668,"وهو عصام بن طليق الطفاوى البصرى."],[10669,"انظر: تهذيب الكمال (٢٠/ ٣٩٢٥)، ميزان الاعتدال (٣ / ت ٥٦٢٣)، تهذيب التهذيب (٧/ ١٩٥)، تاريخ ابن معين رواية الدورى (٢/ ٤٠٢)، الذيل على الكاشف (ت ١٠٤٧)، الجرح والتعديل (٧/ ١٤٠)، لسان الميزان (٧/ ٣٠٥)، تاريخ أبى رزعة الرازى (٥٣٩)، المجروحين (٢/ ١٧٤)، تاريخ الإسلام (٦/ ٢٥٠)، ديوان الضعفاء (ت ٢٨١٤)."],[10670,"(٥) هو: عنبسة بن سعيد القطان الواسطى، ويقال: البصرى. قلت: وقد سبق."],[10671,"٦٤٦ - وعبد الرحيم بن زيد العمى"],[10672,"(١)"],[10673,"ليس بشئ."],[10674,"٦٤٧ - عبد الكريم أبو أمية"],[10675,"(٢)"],[10676,"قال: حدثنا هشام بن يوسف، عن معمر قال: قال لى أيوب: عبد الكريم أبو أمية غير ثقة فلا يحمل عنه."],[10677,"٦٤٨ - العوام بن حمزة"],[10678,"(٣)"],[10679,"قال يحيى: والعوام بن حمزة ليس حديثه بشئ يروى عنه يحيى القطان."],[10680,"٦٤٩ - والعوام بن مراجم"],[10681,"(٤)"],[10682,"لم أسمع أحدًا يحدث عنه إلا شعبة."],[10683,"٦٥٠ - وعمران بن يزيد"],[10684,"(٥)"],[10685,"(١) هو: عبد الرحيم بن زيد الحوارى العمى البصرى أبو زيد."],[10686,"انظر: تهذيب الكمال (١٨ / ت ٣٤٠٧)، تهذيب التهذيب (٦/ ٣٠٥)، الجرح والتعديل (٥ / ت ١٦٠٢)، الكاشف (٢ / ت ٣٤٠١)، التاريخ الكبير (٥ / ت ١٨٣٨)، لسان الميزان (٧/ ٢٨٦)، سير أعلام النبلاء (٨/ ٣٥١)، الكامل لابن عدى (٦/ ٤٩٣)."],[10687,"(٢) هو: عبد الكريم بن أبى المخارق، واسمه قيس، ويقال: طارق أبو أمية المعلم البصرى، نزل مكة."],[10688,"انظر: تهذيب الكمال (١٨ / ت ٣٥٠٦)، التاريخ الكبير (٦ / ت ١٧٩٧)، الجرح والتعديل (٦/ ت ٣١١)، الكاشف (٢ / ت ٣٤٧٦)، ميزان الاعتدال (٢ / ت ٥١٧٢)، تهذيب التهذيب (٦/ ٣٧٦)، سير أعلام النبلاء (٦/ ٨٣)، لسان الميزان (٧/ ٢٩١)، الكامل لابن عدى (٧/ ٣٧)."],[10689,"(٣) هو: العوام بن حمزة المازنى البصرى."],[10690,"انظر: تهذيب الكمال (٢٢ / ت ٤٥٤٠)، التاربخ الكبير (٦ / ت ٣٠٩)، الجرح والتعديل (٧ / ت ١١٨)، لسان الميزان (٧/ ٣٣٠)، تاريخ أسماء الثقات (١٠٨٧)، سير أعلام النبلاء (٦/ ٣٥٥)، الثقات (٧/ ٢٩٩)، الذيل على الكاشف (ت ١١٧٩)، الكامل لابن عدى (٧/ ١٠٢)."],[10691,"(٤) هو: العوام بن مراجم، وليس مزاحم كما جاء بالمخطوط، وهو تصحيف، والصواب ما أثبت براء وجيم، كما ذكر ابن حجر فى تعجيل المنفعة، وهو عوام بن مراجم القيسى عن أبى عثمان النهدى، وعنه شعبة، وخالد بن إسحاق، قال أبو حاتم: صالح، وقال ابن معين: ثقة."],[10692,"انظر: الجرح والتعديل (٧/ ١١٦)، تعحيل المنفعة (ت ٨٢٣)، تاريخ ابن معين رواية الدورى (٢/ ٤٦٠)."],[10693,"(٥) هو: عمران بن يزيد الرفاء البصرى، أحاديثه تشبه الموضوع، كذا قال ابن عدى."],[10694,"قلت: وقد سبق."],[10695,"ليس يحتج بحديثه، روى عنه أبو النصر."],[10696,"٦٥١ - عمران العمى"],[10697,"(١)"],[10698,"قال ابن المدينى: سألت عن عمران العمّى؟ فقال: لم يكن به بأس، ولكنه لم يكن من أهل الحديث، وقد كتبت عنه أشياء فرميت بها."],[10699,"٦٥٢ - عبد الواحد بن صفوان"],[10700,"(٢)"],[10701,"قال العباس: قال ابن معين: عبد الواحد بن صفوان بصرى وليس هو بشئ."],[10702,"٦٥٣ - وعبد الله بن عرادة"],[10703,"(٣)"],[10704,"ضعيف."],[10705,"٦٥٤ - وعلي بن زيد"],[10706,"(٤)"],[10707,"ليس بحجة."],[10708,"٦٥٥ - وعمر بن راشد"],[10709,"(٥)"],[10710,"ليس بشئ."],[10711,"(١) انظر: الكامل لابن عدى (٦/ ١٦٦)، الضعفاء الصغير (٢٧٢)، المغنى (٢ / ت ٤٦١٤)، لسان الميزان (٤/ ٣٤٩)، معارف الأعلمى (١٥/ ٢٣)، ميزان الاعندال (٣/ ٢٤١)."],[10712,"قلت: وهو عمران بن قدامة العمى."],[10713,"(٢) هو: عبد الواحد بن صفوان بن أبى عياش الأموى، مولى عثمان مدنى، سكن البصرة."],[10714,"انظر: تهذيب الكمال (١٨ / ت ٣٥٨٨)، تهذيب التهذيب (٦/ ٤٣٦)، التاريخ الكبير (٦ / ت ١٧٠٤)، الجرح والتعديل (٦ / ت ١١٣)، ميزان الاعتدال (٢ / ت ٥٢٩٣)، الذيل على الكاشف (٩٦٢)، لسان الميزان (٧/ ٢٩٤)، الثقات (٧/ ١٢٤)، الكامل لابن عدى (٦/ ٥٢٠)."],[10715,"(٣) هو: عبد الله بن عرادة بن شيبان السدوسى، أبو شيبان البصرى."],[10716,"انظر: تهذيب الكمال (١٥ / ت ٣٤٢٤)، تهذيب التهذيب (٥/ ٣١٩)، التاريخ الكبير (٥ / ت ٥٢٥)، الجرح والتعديل (٥ / ت ٦١٩)، الكاشف (٢ / ت ٢٨٨٤)، ميزان الاعتدال (٢ / ت ٤٤٤٦)، تاريخ الدورى (٢/ ٣١٩)، ضعفاء النسائى (ت ٣٢٧)، المجروحين (٢/ ٨)، ديوان الضعفاء (ت ٢٣٨)، المغنى (٢ / ت ٣٢٦٢)."],[10717,"(٤) هو: على بن زيد بن عبد الله بن أبى مليكة زهير بن عبد الله بن جدعان بن عمرو بن كعب بن تيم بن مرة التميمى، أبو الحسن البصرى، أصله من مكة. قلت: وقد سبق."],[10718,"(٥) هو: عمر بن راشد بن شجرة أبو حفص اليمامى."],[10719,"انظر: تهذيب الكمال (٢١ / ت ٤٢٣١)، تهذيب التهذيب (٧/ ٤٤٦)، الميزان (٣ / ت ٦١٠١)، أبو زرعة الرازى (٥١٣)، المعرفة والتاريخ (٣/ ١٥٣)، المجروحين (٢/ ٨٣)، الكشف الحثيث (ت ٥٤٦)، المغنى (٢ / ت ٤٤٥٦)، موضح أوهام الجمع والتفريق (٢٥٨)، تاريخ الإسلام (٦/ ٢٥٥)، ديوان الضعفاء (ت ٣٠٣٩)، تاريخ ابن معين (٢/ ٤٢٩)، أحوال الرجال (ت ١٩٩)، الكامل لابن عدى (٦/ ٢٧)."],[10720,"٦٥٦ - وعمر بن هارون"],[10721,"(١)"],[10722,"ليس بشئ."],[10723,"٦٥٧ - وعبد العزيز بن حصين بن الترجمان خراسانى"],[10724,"(٢)"],[10725,"[ضعيف الحديث] (٣)."],[10726,"٦٥٨ - وعبد الأعلى بن أبى عبد الله"],[10727,"(٤)"],[10728,"ليس بشئ."],[10729,"٦٥٩ - عبد الأعلى الثعلبى"],[10730,"(٥)"],[10731,"قال ابن المدينى: سألت يحيى عن عبد [١٠٠ /ب] الأعلى الثعلبى، فقال: تعرف وتنكر."],[10732,"(١) هو: عمر بن هارون بن يزيد بن جابر بن سلمة الثقفى، مولاهم أبو حفص البلخى."],[10733,"انظر: تهذيب الكمال (٢١ / ت ٤٣١٧)، الجرح والتعديل (٦ / ت ٤٧٥)، ميزان الاعتدال (٣ / ت ٦٢٣٧)، تهذيب التهذيب (٧/ ٥٠١)، تاريخ بغداد (١١/ ١٧٨)، المجروحين (٢/ ٩٠)، المغنى (٢ / ت ٤٥٦٧)، ضعفاء ابن الجوزى (٢/ ٢١٨)، تاريخ الثقات (٣٦١)، ضعفاء الدارقطنى (٣٦٨)، تذكرة الحفاظ (١/ ٣٤٠)، ديوان الضعفاء (ت ٣١١٨)، غاية النهاية (١/ ٥٩٨)، علل أحمد (١/ ٣٦٨)، تاريخ ابن معين رواية الدورى (٢/ ٤٣٥)، الكامل لابن عدى (٦/ ٥٨)."],[10734,"(٢) كنيته: أبو سهل مروزى الأصل."],[10735,"انظر: ميزان الاعتدال (٢/ ت ٥٠٩٥)، لسان الميزان (٤/ ٢٨)، الضعفاء الكبير (٣/ ١٥)، الصغير (٢٢٥)، الكامل لابن عدى (٦/ ٥٠٠)، تاريخ ابن معين (٢/ ٢٦٥)، تلخيص المستدرك (١/ ١٦)، المغنى (١/ ت ٣٧٢٨)، الجرح والتعديل (٥ / ت ١٧٧٧)."],[10736,"(٣) ما بين المعقوفين من تاريخ ابن معين رواية الدورى."],[10737,"(٤) لعله: عبد الأعلى بن عبد الله، شيخ لموسى بن يعقوب الزمعى، قال الذهبى: لا يعرف من هو، وقال فى المغنى: وهو ابن أبى فروة، وقال العقيلى: لا يتابع على حديثه، وشيخه إسماعيل مولى مزينة نحوه، يعنى لا يعرف."],[10738,"انظر: ميزان الاعتدال (٢ / ت ٤٧٢٧)، المغنى (١/ ت ٣٤٤٦)، ديوان الضعفاء (ت ٢٣٦٣)، مجمع الزوائد (٦/ ١٢٣)."],[10739,"(٥) هو: عبد الأعلى بن عامر الثعلبى الكوفى."],[10740,"انظر: تهذيب الكمال (١٦ / ت ٣٦٨٤)، تهذيب التهذيب (٦/ ٩٤)، التاريخ الكبير (٦ / ت ١٧٤٣)، الجرح والتعديل (٦ / ت ١٣٤)، الكاشف (٢ / ت ٣١١٤)، ميزان الاعتدال (٢ / ت ٤٧٢٦)، الكامل لابن عدى (٦/ ٥٤٦)، تاريخ ابن معين رواية الدورى (٢/ ٣٣٩)، طبقات خليفة (١٥٩)، ديوان الضعفاء (ت ٢٣٦٢)، المغنى (١/ ت ٣٤٤٤)، تاريخ أبى زرعة الرازى (٦٣٦)، تاريخ الإسلام (٥/ ١٠١)، طبقات ابن سعد (٦/ ٣٣٤)، لسان الميزان (٧/ ٢٧٤)."],[10741,"٦٦٠ - عبد الله بن سمه"],[10742,"(١)"],[10743,"قال: وقلت ليحيى: إن عبد الله بن سمه يزعم أنه كان يسأل المحدثين، فقال: ما سأل عبد الله أحدًا قط، وأنا معه أنا كنت أسال وأكتب ثم ينسخها منى."],[10744,"٦٦١ - عمرو بن الأزهر"],[10745,"(٢)"],[10746,"قال العباس: قال ابن معين: عمرو بن الأزهر كان بواسط، وهو بصرى ضعيف."],[10747,"٦٦٢ - وعبد الحكيم"],[10748,"(٣)"],[10749,"واسطى كذاب."],[10750,"٦٦٣ - وعبيد بن القاسم"],[10751,"(٤)"],[10752,"كان يكون فى مسجد الجامع، وكانت له هيئة وكان كذابًا."],[10753,"٦٦٤ - وعامر بن صالح"],[10754,"(٥)"],[10755,"كان يكون عند مسجد حصن، وكان ضعيف الحديث."],[10756,"٦٦٥ - وعبد القدوس الشامى"],[10757,"(٦)"],[10758,"(١) لم أقف عليه."],[10759,"(٢) هو: عمرو بن الأزهر العتكى البصرى، كان بواسط."],[10760,"انظر: ميزان الاعتدال (٣/ ٢٤٥)، ديوان الضعفاء (ت ٣١٥٧)، اللآلئ المصنوعة (١/ ٣١٨، ٢/ ١١٥)، التاريخ الصغير (٢/ ٢٦٢)، الكشف الحثيث (٣٢١)، الجرح والتعديل (٦/ ١٢٢٦)، الموضوعات (١/ ٣٣٦)، المجروحين (٢/ ٧٨)، تنزيه الشريعة (١/ ٩٢)، المغنى (٢/ ت ٤٦٣٠)."],[10761,"(٣) هو: عبد الحكيم بن منصور الخزاعى، أبو سهل، يقال: أبو سفيان الواسطى."],[10762,"انظر: تهذيب الكمال (١٦/ ت ٣٧٠٣)، تهذيب التهذيب (٦/ ١٠٨)، التاريخ الكبير (٦ / ت ١٩١٥)، الجرح والتعديل (٦ / ت ١٨٨)، الكاشف (٢ / ت ٣١٣٠)، المجروحين (٢/ ١٤٤)، ديوان الضعفاء (ت ٢٣٨٤)، المغنى (٢ / ت ٣٤٧٨)، تاريخ ابن معين رواية الدورى (٢/ ٣٤١)، رواية الدارمى (ت ٦٣٧)، ابن محرز (١٢٨)، الكامل لابن عدى (٧/ ٣٠)."],[10763,"(٤) هو: عبيد بن القاسم الأسدى، التيمى الكوفى، يقال: إنه ابن أخت سفيان الثورى."],[10764,"قلت: وقد سبق."],[10765,"(٥) عامر بن صالح بن عبد الله بن عروة بن الزبير بن العوام الزبيرى، أبو الحارث المدنى."],[10766,"قلت: وقد سبق."],[10767,"(٦) هو: عبد القدوس بن حبيب، أبو سعيد الكلاعى الدمشقى الشامى الوحاظى. انظر: الكامل لابن عدى (٧/ ٤٥)، الضعفاء والمتروكين (٢/ ١١٣)، الجرح والتعديل (٦/ ٥٥)، ="],[10768,"ضعيف."],[10769,"٦٦٦ - عنبسة بن عبد الرحمن"],[10770,"(١)"],[10771,"الذى يروى عنه الوليد بن مسلم، ليس حديثه بشئ."],[10772,"٦٦٧ - وعبد الله بن زحر"],[10773,"(٢)"],[10774,"ليس بشئ."],[10775,"٦٦٨ - وعبد العزيز بن عبد الله بن حمزة بن صهيب"],[10776,"(٣)"],[10777,"٦٦٩ - وعطاء بن عجلان"],[10778,"(٤)"],[10779,"= الكشف الحثيث (٤٥٤)، المجروحين (٢/ ١٣١)، ميزان الاعتدال (٢/ ٦٤٣)، الضعفاء للعقيلى (٢/ ٢٥٦)، التاريخ الكبير (٦/ ١١٩)، سير أعلام النبلاء (٨/ ١٣٥)، الأنساب (١٣/ ٢٧٨)، المعرفة والتاريخ (٣/ ٤٥)، المغنى (٢ / ت ٣٧٧٣)."],[10780,"(١) هو: عنبسة بن عبد الرحمن بن عنبسة بن سعيد بن العاص بن سعيد بن العاص بن أمية."],[10781,"وقال بعضهم: عنبسة بن أبى عبد الرحمن الأموى."],[10782,"انظر: تهذيب الكمال (٢٢ / ت ٤٥٣٦)، تهذيب التهذيب (٨/ ١٦٠)، التاريخ الكبير (٧ / ت ١٦٩)، الكاشف (٢ / ت ٤٣٦٩)، الجرح والتعديل (٦ / ت ٢٢٤٧)، ميزان الاعتدال (٣ / ت ٦٥١٢)، الكامل لابن عدى (٦/ ٤٥٩)، المعرفة والتاريخ (٢/ ٤٤٨)، تاريخ ابن معين رواية الدورى (٢/ ٤٥٨)، رواية الدارمى (ت ٦٦٩)، المجروحين (٢/ ١٨٧)، لسان الميزان (٧/ ٣٢٩)، ضعفاء ابن الجوزى (٢/ ٢٣٥)."],[10783,"(٢) لعله عبيد الله بن زحر بالتصغير؛ لأن هذا لا يعرف، كذا قال ابن حجر فى التعجيل، وقال: روى عن أبى هريرة، وعنه يحيى بن أبى كثير، وليس هو عبيد الله بن زحر بالتصغير."],[10784,"قلت: والذي رجح عندى أنه عبد الله بالتصغير، قوله ليس بشئ، فهذا قول ابن معين فى عبيد الله. وهو: عبيد الله بن زحر الضمرى، مولاهم الإفريقى، ولد بأفريقية، ودخل العراق فى طلب العلم."],[10785,"انظر: تهذيب التهذيب (٧/ ١٢)، تهذيب الكمال (١٩/ ت ٣٦٣٣)، التاريخ الكبير (٥ / ت ١٢٢٣)، الجرح والتعديل (٥ / ت ١٤٩٩)، الكاشف (٢ / ت ٣٥٩٠)، ميزان الاعتدال (٣ / ت ٥٣٥٩)، لسان الميزان (٧/ ٢٩٦)، تعجيل المنفعة (٦٨٥)، الكامل لابن عدى (٥/ ٥٢٢)."],[10786,"(٣) هو: عبد العزيز بن عبيد الله بن حمزة بن صهيب بن سنان الحمصى."],[10787,"انظر: تهذيب الكمال (١٨ / ت ٣٤٦٢)، تهذيب التهذيب (٦/ ٣٤٩)، الجرح والتعديل (٥ / ت ١٨٠٥)، الكاشف (٢ / ت ٣٤٤٦)، ميزان الاعتدال (٢ / ت ٥١١٥، ٥١١٦)، لسان الميزان (٤/ ٣٦)."],[10788,"(٤) هو: عطاء بن عجلان الحنفى، أبو محمد البصرى العطار.="],[10789,"ضعيف."],[10790,"٦٧٠ - وعبد الله بن أبى مريم"],[10791,"(١)"],[10792,"ليس حديثه بشئ."],[10793,"٦٧١ - وعثمان بن أبى العاتكة"],[10794,"(٢)"],[10795,"هو أبو حفص القاص، ليس بشئ."],[10796,"٦٧٢ - وعبد الحميد بن [سليمان أخو] (٣) فليح (٤)"],[10797,"ليس بشئ."],[10798,"=انظر: تهذيب الكمال (٢ / ت ٣٩٣٦)، تهذيب التهذيب (٢٠٨١٧)، ميزان الاعتدال (٣ / ت ٥٦٤٤)، التاريخ الكبير (٦ ات ٣٠٣٤)، المغنى (٢ ات ٤١٢٤)، موضح أوهام الجمع والتفريق (٢/ ٣١٣)، الكشف الحثيث (ت ٤٩٠)، تاريخ واسط (١٤٥)، المعرفة والتاريخ (٢/ ١٢٦)، ديوان الضعفاء (ت ٢٨٢٧)، تاريخ الدورى (٢/ ٤٠٤)، أبو زرعة الرازى (٦٤٥)، ابن محرز (٢٥)، علل أحمد (١/ ١٢٧)، لسان الميزان (٧/ ٣٠٥)، الكامل لابن عدى (٧/ ٧٨)."],[10799,"(١) هو: عبد الله بن أبى مريم الغسانى الحمصى، والد أبى بكر، لا يكاد يعرف، وخبره منكر، كذا قال الذهبى."],[10800,"انظر: ميزان الاعتدال (٢ / ت ٤٥٩٧)، الثقات (٧/ ٥٥)، لسان الميزان (٣/ ٣٥٧)، تاريخ حمص (٢/ ١٦٠)، الجرح والتعديل (٥ / ت ٨٤٦)، التاريخ الكبير (٥/ ٢١٠)، المغنى (١/ ٣٣٦٤)."],[10801,"(٢) هو: عثمان بن أبى العاتكة سليمان الأزدى، أبو حفص الدمشقى القاص."],[10802,"انظر: تهذيب الكمال (١٩ / ت ٣٨٢٧)، ميزان الاعتدال (٣ / ت ٥٥٢٢)، الكاشف (٢ / ت ٣٧٥٨)، تهذيب التهذيب (٧/ ١٢٤)، الجرح والتعديل (٦ / ت ٨٦٦)، تاريخ الإسلام (٦/ ٢٤٨)، شذرات الذهب (١/ ٢٣٩)، أحوال الرجال (ت ٢٧٩)، المغنى (٢ / ت ٤٠٣)، الكنى للدولابى (١/ ١٥٣)، التاريخ الكبير (٦/ ٢٤٣)، تاريخ ابن معين: رواية الدارمى (٢/ ٦٢٧)، رواية الدورى (٢/ ٣٩٣)، المعرفة والتاريخ (١/ ١٣١)، الكامل لابن عدى (٦/ ٢٧٠)."],[10803,"(٣) ما بين المعقوفين ساقط من المخطوط."],[10804,"(٤) هو: عبد الحميد بن سليمان الخزاعى، أبو عمر المدنى الضرير، نزيل بغداد، أخو فليح."],[10805,"انظر. تهذيب الكمال (١٦/ ت ٣٧١٧)، تهذيب التهذيب (٦/ ١١٦)، الكاشف (٢ / ت ٣١٤٣)، ميزان الاعتدال (٢ / ت ٤٧٧٧)، الجرح والتعديل (٦ / ت ٦٥)، الكامل لابن عدى (٧/ ٥)، مجمع الزوائد (١/ ١٥٥)، (٤/ ٤٩)، المجروحين (٢/ ١٤١)، الضعفاء الكبير (٣/ ٤٦)، لسان الميزان (٧/ ٢٧٦)، المغنى (١ / ت ٣٤٩٥)."],[10806,"٦٧٣ - وعبد الله بن جعفر"],[10807,"(١)"],[10808,"أبو على المدينى: ليس بشئ."],[10809,"٦٧٤ - وعبيد الله بن عامر الأسلمى"],[10810,"(٢)"],[10811,"ليس بشئ."],[10812,"٦٧٥ - عطاء بن عجلان"],[10813,"(٣)"],[10814,"كوفى ليس حديثه بشئ."],[10815,"٦٧٦ - وعبد الغفور هو أبو الصباح"],[10816,"(٤)"],[10817,"ليس حديثه بشئ."],[10818,"٦٧٧ - وعبد الرحمن بن سليمان الأصبهانى"],[10819,"(٥)"],[10820,"ليس بشئ."],[10821,"٦٧٨ - عبد الله بن سنان"],[10822,"(٦)"],[10823,"كوفى كان ينزل القطيعة، وليس حديثه بشئ."],[10824,"(١) سبق."],[10825,"(٢) هو: عبد الله بن عامر النسلمى، أبو عامر المدنى، كان يصلى فى رمضان فى مسجد الرسول - صلى الله عليه وآله وسلم - وكان من حفاظ القرآن."],[10826,"انظر: تهذيب الكمال (١٥ / ت ٣٣٥٥)، تهذيب التهذيب (٥/ ٢٧٥)، الجرح والتعديل (٥ / ت ٥٦٣)، الكاشف (٢ / ت ٢٨٢٦)، ميزان الاعتدال (٢ / ت ٤٣٩٤)، التاريخ الكبير (٥ / ت ٤٨٢)، الكامل فى التاريخ (٥/ ٥٥٤)، ديوان الضعفاء (ت ٢٢١٣)، المغنى (١/ ت ٣٢٢٦)، تاريخ الإسلام (٦/ ٢١٠)، الكامل لابن عدى (٥/ ٢٥٣)، ضعفاء الدارقطنى (ت ٣١٦)، المجروحين (٢/ ٦)."],[10827,"(٣) سبق برقم (٦٦٩)."],[10828,"(٤) هو: عبد الغفور بن عبد العزيز أبو الصباح الواسطى."],[10829,"انظر: الكامل لابن عدى (٧/ ٢١)، الجرح والتعديل (٦/ ٥٥)، الكشف الحثيث (٤٥٣)، الضعفاء والمتروكين (٢/ ١١١)، الضعفاء الكبير (٣/ ١١٣)، اللآلئ المصنوعة (٢/ ١٢٩)، التاريخ الكبير (٦/ ١٣٧)، تنزيه الشريعة (١/ ٨١)، تاريخ بغداد (١١/ ١٣٠)، المغنى (٢ / ت ٣٧٧١)."],[10830,"(٥) انظر: ميزان الاعتدال (٢/ ٥٦٨)، لسان الميزان (٣/ ٤١٨)، ديوان الضعفاء (ت ٢٤٥٢)، الجرح والتعديل (٥ / ت ١١٣٥)، الضعفاء الكبير (٢/ ٣٣٤)، المغنى (٢ / ت ٣٥٧٨)."],[10831,"(٦) انظر: الجرح والتعديل (٥/ ٦٨)، الضعفاء والمتروكين (٢/ ١٢٦)، الضعفاء الكبير (٢/ ٢٦٣)."],[10832,"٦٧٩ - عبد الملك بن أبى سليمان"],[10833,"(١)"],[10834,"وقال: صدقة بن الفضل: كان يحيى يضعف حديث عبد الملك بن أبى سليمان."],[10835,"٦٨٠ - وعمار بن أبى عمار"],[10836,"(٢)"],[10837,"قال: وعمار بن أبى عمار مدنى يخالف فى أحاديث، وفى قلبى منه شئ."],[10838,"وروى عن ابن عباس أنه توضأ لكل صلاة."],[10839,"٦٨١ - عامر الأحول"],[10840,"(٣)"],[10841,"وسئل عن عامر الأحول، فقال: شيخ، وحرّك يده."],[10842,"٦٨٢ - عيسى الحناط"],[10843,"(٤)"],[10844,"قال ابن المدينى: ذكروا ليحيى بن سعيد حديث عيسى الحناط عن الشعبى، عن ثلاثة"],[10845,"(١) هو: عبد الملك بن أبى سليمان، واسمه ميسرة، أبو محمد، ويقال: أبو سليمان، وقيل: أبو عبد الله العرزمى، أحد الأئمة."],[10846,"انظر: تهذيب الكمال (١٨ / ت ٣٥٣٢)، التاريخ الكبير (٥ / ت ١٣٥٣)، الجرح والتعديل (٥ / ت ١٧١٩)، الكاشف (٢ / ت ٣٤٩٩)، ميزان الاعتدال (٢ / ت ٥٢١٢)، لسان الميزان (٢٩١١٧)، الكامل لابن عدى (٥٢٥١٦)."],[10847,"(٢) هو: عمار بن أبى عمار مولى بنى هاشم، ويقال: مولى بنى الحارث بن نوفل أبو عمرو، ويقال: أبو عبد الله المكى."],[10848,"انظر: تهذيب الكمال (٢١/ ت ٤١٦٧)، تهذيب التهذيب (٧/ ٤٠٤)، التاريخ الكبير (٧ / ت ١٠٨)، الجرح والتعديل (٦ / ت ٢١٦٧)، الكاشف (٢ / ت ٤٠٥٣)، تاريخ ابن معين رواية الدورى (٢/ ٤٢٣)."],[10849,"(٣) هو: عامر بن عبد الواحد الأحول البصرى."],[10850,"انظر: تهذيب الكمال (١٤/ ٣٠٥٤)، تهذيب التهذيب (٥/ ٧٧)، التاريخ الكبير (٦ / ت ٢٩٧٧)، الجرح والتعديل (٦ / ت ١٨١٧)، الكاشف (٢ / ت ٢٥٦٤)، ميزان الاعتدال (٢ / ت ٤٠٨٩)، الثقات (٥/ ١٩٣)، تاريخ الدورى (٢/ ٢٨٨)، رواية الدارمى (ت ٥٧٣)، طبقات خليفة (٢١٦)، الأنساب للسمعانى (١/ ١٤٨)، ديوان الضعفاء (ت ٢٠٥٤)، المغنى (ت ٣٠١٥)، تاريخ الإسلام (٥/ ٩٢)، الكامل لابن عدى (٦/ ١٥٣)، المعرفة والتاريخ (٢/ ٦٦٦)."],[10851,"(٤) هو: عيسى بن أبى عيسى الحناط الغفارى أبو موسى ويقال: أبو محمد المدنى مولى قريش، قال ابن معين: عيسى الحناط، ويقال: الخباط، ويقال: الخياط، كان كوفيًا انتقل إلى المدينة، وكان خياطًا ثم ترك ذلك وصار حناطًا، ثم ترك ذلك وصار يبيع الخيط."],[10852,"من أصحاب النبى - صلى الله عليه وآله وسلم -: \"هو أحق بها ما لم تغتسل\" (١)."],[10853,"فقال: والله ما يسرنى أنى حدثت بهذا الحديث وأنى تصدقت بمالى كله."],[10854,"٦٨٣ - عبد العزيز بن أبان"],[10855,"(٢)"],[10856,"محمد بن سعيد القارى الترمذى، قال: شهدت وكيعًا وسئل عن عبد العزيز بن أبان فقال: له لحية له هيئة."],[10857,"[١٠١/ أ] إسحاق بن راهويه، قال: شهدت جريرًا، أو قال له يحيى بن آدم، يا أبا عبد الله إنّ عبد العزيز بن أبان، قال: إنك قرأت على منصور، فقال: إن كان يكذب يكذب فسود الله وجهه، ما كنا نسمع من منصور إلا خمسة خمسة إلا يومًا واحدًا حفظت منه أربعين حديثًا."],[10858,"٦٨٤ - عمرو بن مسلم"],[10859,"(٣)"],[10860,"قال ابن المدينى: ذكرت لعمر بن مسلم صاحب طاوس، فحرّك يده، وقال: ما أرى هشام بن حجر (٤) إلَّا أمثل منه."],[10861,"٦٨٥ - عمرو بن شعيب"],[10862,"(٥)"],[10863,"قال ابن (٦) المدينى: سمعت يحيى، يقول: حديث عمرو بن شعيب عندنا واهى."],[10864,"٦٨٦ - عمر بن قيس"],[10865,"(٧)"],[10866,"(١) كذا بالمخطوط، وجاء فى الكامل لابن عدى \"ثلاثة عشر\"، وجاء فيه: \"هو أحق بها ما لم تغتسل من الحيضة الثالثة\"، أبو بكر وعمر وجعل يعد."],[10867,"(٢) سبق."],[10868,"(٣) هو: عمرو بن مسلم الجندى اليمانى."],[10869,"انظر: تهذيب الكمال (٢٢ / ت ٤٤٥١)، تهذيب التهذيب (٨/ ١٠٤)، ميزان الاعتدال (٣ / ت ٦٤٥٠)، الجرح والتعديل (٦ / ت ١٤٣١) الكاشف (٢ / ت ٤٢٩٧)، التاريخ الكبير (٦ / ت ٢٦٦٥)، لسان الميزان (٧/ ٣٢٧)، تراجم الأحبار (٢/ ٥٩٤)، المغنى (٢ / ت ٤٧١٠)، الكامل لابن عدى (٦/ ٢١٠)."],[10870,"(٤) كذا بالمخطوط: وجاء فى المصادر بالتصغير \"حجيرًا\"."],[10871,"(٥) هو: عمرو بن شعيب بن محمد بن عبد الله بن عمرو بن العاص يكنى أبا إبراهيم. قلت: وأظنه سبق."],[10872,"(٦) جاء بالمخطوط \"أبو\"، قال ابن عدى: حدثنا ابن حماد، ثنا صالح، قال: ثنا على، سمعت يحيى ابن سعيد يقول، فذكره."],[10873,"(٧) هو: عمر بن قيس المكى أبو حفص، المعروف بسندل، مولى آل بنى أسد، وقيل: مولى آل منظور ابن سيار.="],[10874,"قال: وقال يحيى: سمعت عمر بن قيس يحدث عن عطاء، عن عبيد بن عمير فى دية اليهودى والنصرانى عجائب."],[10875,"٦٨٧ - عمر بن سعد"],[10876,"(١)"],[10877,"قال: وسمعته يقول: لم يكن عمر بن سعد ممن يعتمد عليه."],[10878,"٦٨٨ - عمر بن أبى سلمة"],[10879,"(٢)"],[10880,"قال: وقال يحيى: كان شعبة يضعف عمر بن أبى سلمة."],[10881,"٦٨٩ - عيسى الخياط"],[10882,"(٣)"],[10883,"قال: وقال يحيى: حدثنا عيسى الخياط بحديث الشعبى فى الرجل يتصدق بالصدقة ثم يرثها؟ فقال: عن ابن مسعود، قال يحيى: فقلت له: إنهم يروونه عن مسروق."],[10884,"فقال ابن مسعود: فقمت وتركته (٤)."],[10885,"٦٩٠ - عثمان بن سعد الكاتب"],[10886,"(٥)"],[10887,"قال: وذكر ليحيى عثمان بن سعد (*) الكاتب فجعل يعجب من الرواية (٦)."],[10888,"= انظر: تهذيب الكمال (٢١ / ت ٤٢٩٧)، التاريخ الكبير (٦ / ت ٢١٢٢)، الجرح والتعديل (٦ / ت ٧٠٣)، الكاشف (٢ / ت ٤١٦٥)، تهذيب التهذيب (٧/ ٤٩٠)."],[10889,"(١) لعله: عمر بن سعيد بن سليمان الدمشقى أبو حفص، والله أعلم ولعله غيره."],[10890,"انظر: الكامل لابن عدى (٦/ ١١٥)، الجرح والتعديل (٦/ ٩٩)، الضعفاء الكبير (٣/ ١٤٧)، تهذيب التهذيب (٦/ ٣٨٤)، ميزان الاعتدال (٣ / ت ٦١٢٠)، المغنى (٢/ ٤٦٢)."],[10891,"(٢) هو: عمر بن أبى سلمة بن عبد الرحمن بن عون الزهرى المدنى."],[10892,"انظر: تهذيب التهذيب (٧/ ٤٥٦)، تهذيب الكمال (٢١ / ت ٤٢٤٧)، التاريخ الكبير (٦ / ت ٢٠٥٤)، الكاشف (٢ / ت ٤١٢٦)، ميزان الاعتدال (٣ / ت ٦١٢٧)، لسان الميزان (٧/ ٣١٨)، الثقات (٧/ ١٦٤)، علل أحمد (١/ ١٣٦)، التاريخ الكبير (٦/ ١٦٦)، طبقات خليفة (٢٦٢)، أحوال الرجال (ت ٢٤٨)، تاريخ الإسلام (٢٨٦١٥)، المغنى (٢ / ت ٤٤٧٦)، ديوان الضعفاء (ت ٣٠٥٥)، ثقات ابن شاهين (ت ٧١١)، سير أعلام النبلاء (٦/ ١٣٣)، الكامل لابن عدى (٦/ ٧٨)."],[10893,"(٣) سبق، وهو: الحناط، والخياط، وكان يبيع الخيط."],[10894,"(٤) لم أقف عليه، والله أعلم."],[10895,"(٥) هو: عثمان بن سعد التميمى، أبو بكر البصرى الكاتب المعلم. وقد سبق برقم (٥٨٥)."],[10896,"(*) جاءت بالمخطوط \"سعيد\" وهو تصحيف."],[10897,"(٦) سبق."],[10898,"٦٩١ - عبد الله بن سعيد بن أبى سعيد المقبرى"],[10899,"(١)"],[10900,"قال السباك: سمعت عبيد الله يقول: ترك يحيى بن سعيد حديث عبد الله بن سعيد"],[10901,"ابن أبى سعيد المقبرى."],[10902,"٦٩٢ - عبد الله بن سعيد بن أبى هند"],[10903,"(٢)"],[10904,"قال: وقال: عبد الله بن سعيد بن أبى هند: نعرف وننكر (٣)."],[10905,"٦٩٣ - عسل بن سفيان"],[10906,"(٤)"],[10907,"قال: وسمعت يحيى بن معين، يقول: عسل بن سفيان بصرى كانوا يروون عنه، ثم ضعف حديثه فى حديث رواه عن آخر، عن أبى هريرة، فى السدل، كذا قال يحيى عن آخر، عن أبى هريرة وإنما هو عسل، عن عطاء، عن أبى هريرة (٥)."],[10908,"(١) سبق، برقم (١٢٥)."],[10909,"(٢) هو: عبد الله بن سعيد بن أبى هند الفزارى، مولاهم أبو بكر المدنى، توفى سنة (١٤٦)، وقيل: (١٤٧)."],[10910,"انظر: تهذيب التهذيب (٥/ ٢٤٠)، تهذيب الكمال (١٥ / ت ٣٣٠٩)، التاريخ الكبير (٥ / ت ٢٨٩)، الجرح والتعديل (٥ / ت ٣١٣)، الكاشف (٢ / ن ٢٧٨٢)، ميزان الاعتدال (٢ / ت ٤٣٥٥)."],[10911,"(٣) قلت: هذا قول سعيد بن يحيى القطان، وأما غيره فوثقوه، ولم يضعفه إلا أبو حاتم وأبو زرعة، والباقى على توثيقه، والله أعلم."],[10912,"(٤) هو: عسل بن سفيان التميمى اليربرعى، أبو قرة البصرى."],[10913,"انظر: تهذيب الكمال (٢٠/ ت ٣٩٢١)، التاريخ الكبير (٧ / ت ٤١٦)، الجرح والتعديل (٧ / ت ٢٤٢)، الكاشف (٢ / ت ٣٨٤٢)، ميزان الاعتدال (٣ / ت ٥٦٢٠)، تهذيب التهذيب (٧/ ١٣٩)."],[10914,"(٥) أخرج الترمذي حديث عسل، عن عطاء، عن أبى هريرة \"أبواب الصلاة\" باب ما جاء فى كراهية السدل فى الصلاة، برقم (٣٧٨)."],[10915,"وقال: حديث أبى هريرة لا نعرفه فى حديث عطاء، عن أبى هريرة مرفوعًا، إلا من حديث عسل بن سفيان، وقال الشيخ شاكر فى تحقيق الحديث: رواه أحمد (رقم ٧٩٢١، ٨٤٧٧، ج ٢، ص ٢٩٥، ٣٤١)، من طريق: عسل، عن عطاء، رواه أبو داود (١/ ٢٤٥)، من طريق: الحسن بن ذكوان، عن سليمان الأحول، عن عطاء، عن أبى هريرة، ثم قال أبو داود: رواة عسل، عن عطاء، عن أبى هريرة، عن النبى - صلى الله عليه وآله وسلم -، ورواه الحاكم فى \"المستدرك\" (١/ ٢٥٣)، من طريق ="],[10916,"حرف غ"],[10917,"٦٩٤ - غالب أبو الهذيل"],[10918,"(١)"],[10919,"ابن أبى خيثمة، حدثنا عبد الله بن سعيد الكندى، حدثنا ابن إدريس، حدثنا أبى، عن غالب أبى الهذيل قال: وما كان غالب أبو الهذيل؟ قال: كان رافضيًا."],[10920,"٦٩٥ - غالب بن عبيد الله العقيلى"],[10921,"(٢)"],[10922,"يحيى بن معين قال: غالب بن عبيد الله العقيلى ضعيف."],[10923,"٦٩٦ - غالب بن عبد الله القرقسانى"],[10924,"(٣)"],[10925,"ابن إسماعيل قال: سمعت ابن عمار يقول: كتب المعافى بن عمران إلى وكيع ينهاه أن يحدث عن غالب بن عبد الله القرقسانى، وألقاه من رجاله."],[10926,"= الحسين بن ذكوان عن الأحول، وصححه على شرطهما ووافقه الذهبى، فالحسين بن ذكوان هو المعلم، وهو ثقة معروف، والحسن بن ذكوان، هو: أبو سلمة، ضعفه ابن معين وغيره، وذكر ابن حبان فى الثقات، فإن كان ما فى المستدرك ليس خطأ من الناسخ، كان الحديث عنهما جميعًا، وهو الظاهر؛ لأن الذهبى فى تلخيصه قال: \"حسين المعلم\"، ووافق على تصحيح الحاكم، وإن كان ما فى المستدرك خطأ من الناسخ كان فى إسناده شئ من الضعف، وفى إسناد الترمذي \"عسل بن سفيان\"، وفيه ضعف من قبل حفظه، ولكن متابعته للحسن بن ذكوان ترفع الحديث إلى درجة الصحة أو الحسن على الأقل، وبذلك لا يسلم للترمذى تعليله إياه بانفراد \"عسل\" به، والظاهر أنه لم يطلع على الإسناد الآخر، وليس لعسل بن سفيان عند الترمذي إلا هذا الحديث، انتهى كلام الشيخ شاكر."],[10927,"(١) هو: غالب بن الهذيل الأودى، أبو الهذيل الكوفى."],[10928,"انظر: تهذيب الكمال (٢٣ / ت ٤٦٨٢)، تهذيب التهذيب (٢٤٤١٨)، التاريخ الكبير (٧ / ت ٤٤١)، الجرح والتعديل (٧ / ت ٢٦٩)، الكاشف (٢ / ت ٤٤٨٣)."],[10929,"(٢) هو: غالب بن عبيد الله الجزرى العقيلى، روى عن عطاء، روى عنه عبيد الله بن عمر."],[10930,"قال أبو حاتم: متروك الحديث، منكر الحديث."],[10931,"انظر: الجرح والتعديل (٧ / ت ٢٧٢)، الكامل لابن عدى (٧/ ١٠٩)، الضعفاء والمتروكين (٢/ ٢٤٥)، المغنى (٢ / ت ٤٨٥٥)، المجروحين (٢/ ٢٠١)، أحوال الرجال (٣٢٢)، الضعفاء والمتروكين للدارقطنى (ت ٤٢٩)، تنقيح المقال (٩٣٥٣)، تاريخ ابن معين رواية الدروى (٢/ ٤٦٨)، ميزان الاعتدال (٣/ ٣٣١)، لسان الميزان (٤/ ٤١٤)، دائرة معارف الأعلمى (٢٣/ ١٢٩)."],[10932,"(٣) لم أقف عليه."],[10933,"٦٩٧ - غياث"],[10934,"(١)"],[10935,"قال يحيى: وغياث كذاب [١٠١/ ب]، ليس بثقة ولا مأمون."],[10936,"حرف ف"],[10937,"٦٩٨ - فليح"],[10938,"(٢)"],[10939,"ابن أبى خيثمة قال: سمعت يحيى بن معين يقول: سمعت والله أبا كامل مظفر يقول: فليح كنا نتهمه؛ لأنه يتناول أصحاب الزهرى."],[10940,"٦٩٩ - الفضل بن دلهم"],[10941,"(٣)"],[10942,"قال: وسئل عن الفضل بن دلهم، عن الحسن، فقال: ضعيف."],[10943,"٧٠٠ - فضل أو فضيل بن سليمان النميرى"],[10944,"(٤)"],[10945,"(١) هو: غياث بن إبراهيم الكوفى، يكنى أبا عبد الرحمن، وهو ابن إبراهيم النخعى."],[10946,"انظر: الكامل لابن عدى (٧/ ١١٣)، الإكمال (٦/ ٦٣١)، ميزان الاعتدال (٣/ ٣٣٧)، لسان الميزان (٤/ ٤٢٢)، دائرة معارف الأعلمى (٢٣/ ١٥٧)، تصحيفات المحدثين (٨٧٨)، الضعفاء والمتروكين للدارقطنى (ت ٤٢٧)، تاريخ بغداد (١٢/ ٣٢٣)، الضعفاء الصغير (٢٩٤)، أحوال الرجال (٣٧٠)، المجروحين (٢/ ٢٠٠)، ضعفاء ابن الجوزى (٢/ ٢٤٧)، المغنى (٢ / ت ٤٨٨١)، تاريخ ابن معين رواية الدورى (٢/ ٤٧٠)."],[10947,"(٢) هو: فليح بن سليمان بن أبى المغيرة، واسمه: رافع، ويقال: نافع بن جبير الخزاعى، ويقال: الأسلمى، أبو يحمى المدنى، مولى ال زيد بن الخطاب، وفليح لقب غلب عليه، واسمه: عبد الملك."],[10948,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٧٥)، تهذيب التهذيب (٨/ ٣٠٣)، الجرح والتعديل (٧ / ت ٤٧٩)، ميزان الاعتدال (٣ / ت ٦٧٨٢)، الكاشف (٢ / ت ٤٥٦٣)، الكامل لابن عدى (٧/ ١٤٥)، تاريخ ابن معين رواية الدورى (٢/ ٤٧٧)."],[10949,"(٣) هو: الفضل بن دلهم الواسطى، ثم البصرى، القصاب."],[10950,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٣٣)، الجرح والتعديل (٧ / ت ٣٥٢)، ميزان الاعتدال (٣ / ت ٦٧٢١)، تهذيب التهذيب (٨/ ٢٧٦)، لسان الميزان (٧/ ٣٣٥)، دائرة معارف الأعلمى (٢٣/ ٢٤٠)، ضعفاء ابن الجوزى (٣/ ٦)، تاريخ أسماء الثقات (١١٢٨)، تراجم الأحبار (٣/ ٢٥٧)، ديوان الضعفاء (ت ٣٣٦٣)، التاريخ الكبير (٧/ ١١٦)، تاريخ ابن معين (٢/ ٤٧٤)، المغنى (٢ / ت ٤٩١٧)."],[10951,"(٤) هو: فضيل بن سليمان النميرى، أبو سليمان البصرى."],[10952,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٥٨)، الجرح والتعديل (٢ / ت ٤٠٩)، الكاشف = قال: وسمعته يقول: فضل أو فضيل بن سليمان النميرى لا يكتب حديثه."],[10953,"٧٠١ - الفرج بن فضالة"],[10954,"(١)"],[10955,"قال: وسئل عن الفرج بن فضالة، فقال: هو ضعيف."],[10956,"٧٠٢ - فطر"],[10957,"(٢)"],[10958,"قال: وسمعت قطبة بن العلاء الغنوى، يقول: تركت فطرًا؛ لأنه روى أحاديث إزراء على عثمان بن عفان، رحمه الله."],[10959,"٧٠٣ - الفضيل (٣) بن ميسرة (٤)"],[10960,"على قال: قال يحيى: قلت للفضيل بن ميسرة أبى معاذ: أحاديث أبى حريز؟، قال: سمعتها فذهب كتابى ثم أخذته بعد ذلك من إنسان."],[10961,"٧٠٤ - فائد أبو الورقاء"],[10962,"(٥)"],[10963,"ضعيف."],[10964,"= (٢ / ت ٤٥٤٩)، تهذيب التهذيب (٨/ ٢٩١)، العبر (١/ ٢٧٧)، ميزان الاعتدال (٣/ ٣٦١)، الكامل لابن عدى (٧/ ١٢٩)، التاريخ الكبير (١٢٣١٧)، دائرة معارف الأعلمى (٢٣/ ٢٤٨)، المغنى (٢ / ت ٤٩٥٩)، تراجم الأحبار (٣/ ٢٥٠)، لسان الميزان (٧/ ٣٣٧)."],[10965,"(١) هو: فرج بن فضالة بن النعمان بن نعيم التنوخى القضاعى، أبو فضالة الحمصي، ويقال: الدمشقى."],[10966,"انظر: تهذيب الكمال (٢٣ / ت ٤٧١٤)، التاريخ الكبير (٧ / ت ٦٠٧)، الجرح والتعديل (٧ / ت ٤٨٣)، الكاشف (٢ / ت ٤٥١٢)، ميزان الاعتدال (٣ / ت ٦٦٩٦)، تهذيب التهذيب (٨/ ٢٦٠)، تراجم الأحبار (٣/ ٢٥١)، البداية والنهاية (١٠/ ١٧١)، تاريخ بغداد (١٢/ ٣٩٣)، المغنى (٢ / ت ٤٨٩٦)، لسان الميزان (٧/ ٣٣٤)، الكامل لابن عدى (٧/ ١٤١)."],[10967,"(٢) هو: فطر بن خليفة القرشى المخزومى، مولاهم، أبو بكر الحناط الكوفى. قلت: قد سبق."],[10968,"(٣) جاء بالمخطوط \"الفضل\"، وهو تصحيف."],[10969,"(٤) هو: فضيل بن ميسرة الأزدى العقيلى، أبو معاذ البصرى."],[10970,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٧١)، تهذيب التهذيب (٨/ ٣٠٠)، الجرح والتعديل (٧ / ت ٤٢٤)، الكاشف (٢/ ت ٤٥٦٠)."],[10971,"(٥) هو: فائد بن عبد الرحمن الكوفى، أبو الورقاء العطار."],[10972,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٠٤)، تهذيب التهذيب (٨/ ٢٥٥)، الجرح والتعديل (٧ / ت ٤٧٥)، ميزان الاعتدال (٣ / ت ٦٦٨٢)، الكاشف (٢ / ت ٤٥٠٤)، التاريخ الكبير (٧ / ت ٥٩٦)، المغنى (٢ / ت ٤٨٨٧)، المجروحين (٢/ ٢١٣)، تاريخ أسماء الثقات (١١٤٠)، لسان الميزان (٧/ ٣٣٤)، الكامل لابن عدى (٧/ ١٣٨)."],[10973,"٧٠٥ - فليح بن سليمان"],[10974,"(١)"],[10975,"وسئل عن فليح بن سليمان فلم يقوّى أمره، وقال مرة: ليس بشئ."],[10976,"٧٠٦ - والفرات بن أبى الفرات"],[10977,"(٢)"],[10978,"بصرى، وليس بشئ."],[10979,"٧٠٧ - فرات بن السائب"],[10980,"(٣)"],[10981,"ليس حديثه بشئ."],[10982,"حرف ق"],[10983,"٧٠٨ - قزعة بن سويد"],[10984,"(٤)"],[10985,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن قزعة بن سويد؟ فقال: ضعيف الحديث."],[10986,"٧٠٩ - قرة بن عبد الرحمن"],[10987,"(٥)"],[10988,"(١) سبق."],[10989,"(٢) انظر: الكامل لابن عدى (٧/ ١٣٢)، الضعفاء والمتروكين (٤١٣)، الجرح والتعديل (٧/ ٨٠)، ميزان الاعتدال (٣/ ٣٤٣)، تاريخ ابن معين رواية الدروى (٢/ ٤٧٢)، التاريخ الكبير (٧/ ١٢٩)، لسان الميزان (٤/ ٤٣٢)، معارف الأعلمى (٢٣/ ١٨٥)، ضعفاء ابن الجوزى (٣/ ٤)، ديوان الضعفاء (ت ٣٣٤٨)، المغنى (٢ / ت ٤٨٩٥)."],[10990,"(٣) هو: فرات بن السائب، أبو سليمان، وقيل: أبو المعلى الجزرى."],[10991,"انظر: الكامل لابن عدى (٧/ ١٣٣)، الجرح والتعديل (٧ / ت ٤٥٥)، أحوال الرجال (٣٢٣)، ديوان الضعفاء (ت ٣٣٤٦)، ميزان الاعتدال (٣/ ٣٤١)، المجروحين (٢/ ٢٠٧)، الضعفاء والمتروكين للدارقطنى (ت ٤٣٤)، الضعفاء الكبير (٣/ ٤٥٨)، لسان الميزان (٤/ ٤٣٠)، الكشف الحثيث (٣٣٤)، التاريخ الصغير (٢/ ١٤٢)، المغنى (٢ / ت ٤٨٩٣)."],[10992,"(٤) قزعة بن سويد بن حجير بن بيان الباهلى، أبو محمد البصرى."],[10993,"انظر: تهذيب الكمال (٢٣ / ت ٤٨٧٦)، تهذيب التهذيب (٨/ ٣٧٧)، الجرح والتعديل (٧ / ت ٧٨٢)، ميزان الاعتدال (٣ / ت ٦٨٩٤)، التاريخ الكبير (٧ / ت ٤٥٤)، الكامل لابن عدى (٧/ ١٧٦)، تاريخ ابن معين رواية الدورى (٢/ ٤٧٧)، سؤالات الآجرى (٣/ ٢٥٧)، تراجم الأحبار (٣/ ٢٦٨)، سير أعلام النبلاء (٨/ ١٥٩)، لسان الميزان (٧/ ٣٤٢)."],[10994,"(٥) هو: قرة بن عبد الرحمن بن حيوئيل بن ناشرة بن عبد بن عامر بن أيم بن الحوث الكتعى بن مالك بن عمرو بن يعفر المعافرى، ويقال: ابن حيويل، أبو محمد المصري، يقال: إنه مدنى الأصل."],[10995,"انظر: تهذيب الكمال (٢٣ / ت ٤٨٧١)، تهذيب التهذيب (٨/ ٣٧٢)، الجرح والتعديل (٧ / ت ٧٥١)، الكاشف (٢ / ت ٤٦٣٩)، ميزان الاعتدال (٣ / ت ٦٨٨٦)، لسان الميزان (٧/ ٣٤٢)، = قال: وسئل عن قرة بن عبد الرحمن، فقال: يقال فيه، وليس به بأس عندى، قال:"],[10996,"وسئل عنه مرة أخرى، فقال: ضعيف."],[10997,"٧١٠ - قطبة بن العلاء بن المنهال الغنوى"],[10998,"(١)"],[10999,"قال أبو حاتم الرازى: قطبة بن العلاء بن المنهال الغنوى، يكتب حديثه ولا يحتج به."],[11000,"٧١١ - وقزعة بن سويد البصرى"],[11001,"(٢)"],[11002,"يكتب حديثه ولا يحتج به."],[11003,"٧١٢ - وقابوس بن أبى ظبيان"],[11004,"(٣)"],[11005,"يكتب حديثه ولا يحتج به."],[11006,"قال: وقال أيد بن حنبل ضر به ابن أبى ليلى بشهادة شهد بها."],[11007,"قال ابن المدينى: كان قابوس بن أبى ظبيان ضعيفًا فى الحديث."],[11008,"٧١٣ - القاسم بن فياض"],[11009,"(٤)"],[11010,"= تراجم الأحبار (٣/ ٢٨١)، المغنى (٢ / ت ٥٠٤٦)، الثقات (٧/ ٣٤٢)، التاريخ الكبير (٧/ ١٨٣)، الكامل لابن عدى (٧/ ١٨٢)."],[11011,"(١) هو: قطة بن العلاء بن المنهال الغنوى الكوفى."],[11012,"انظر: الكامل لابن عدى (٧/ ١٨١)، الضعفاء الكبير (٣/ ٤٨٦)، الجرح والتعديل (٧/ ١٤١)، المغنى (٢ / ت ٥٠٥٣)، الضعفاء الصغير (٣٠٤)، تاريخ أسماء الثقات (ت ١١٦٥)، ضعفاء ابن الجوزى (٣/ ١٨)، المجروحين (٢/ ٢٢٠)، معرفة الثقات (ت ١٥٢٥)، لسان الميزان (٤/ ٤٧٣)، ميزان الاعتدال (٣/ ٣٩٠)، ديوان الضعفاء (ت ٣٤٤٨)، الإكمال (٧/ ١٢٠)، دائرة معارف الأعلمى (٢٤/ ٨٢)، الكامل لابن عدى (٣/ ١٨)."],[11013,"(٢) قلت: قد سبق."],[11014,"(٣) هو: قابوس بن أبى ظبيان الجنبى الكوفى."],[11015,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٧٧)، تهذيب التهذيب (٨/ ٣٠٦)، التاريخ الكبير (٧ / ت ٨٦١)، الجرح والتعديل (٧ / ت ٨٠٨)، الكاشف (٢ / ت ٤٥٦٥)، ميزان الاعتدال (٣ / ت ٦٧٨٨)، لسان الميزان (٧/ ٣٣٧)، تراجم الأحبار (٣/ ٢٧١)، المغنى (٢ / ت ٤٩٧٥)، معرفة الثقات (١٤٩٣)، الكامل لابن عدى (٧/ ١٧٢)."],[11016,"(٤) هو: القاسم بن فياض بن عبد الرحمن بن جُندة، بضم الجيم، الصنعانى الأبناوى."],[11017,"انظر: تهذيب الكمال (٢٣ / ت ٤٨١٣)، تهذيب التهذيب (٨/ ٣٣٠)، ميزان الاعتدال (٣ / ت ٦٨٣٢)، الجرح والتعديل (٧ / ت ٦٧٠)، الكاشف (٢ / ت ٤٥١٩)، التاريخ الكبير = قال ابن معين: القاسم بن فياض، ضعيف، وهو صنعانى، لقيه هشام بن يوسف."],[11018,"٧١٤ - والقاسم بن عبد الله بن عمر"],[11019,"(١)"],[11020,"ليس بشئ. وقال مرة: هو ضعيف."],[11021,"٧١٥ - القاسم بن عبد الرحمن"],[11022,"(٢)"],[11023,"ليس يساوى شيئًا."],[11024,"٧١٦ - قابوس بن أبى ظبيان"],[11025,"(٣)"],[11026,"قال ابن المدينى: كان قابوس بن أبى ظبيان، ضعيفًا فى الحديث."],[11027,"٧١٧ - القاسم بن عوف"],[11028,"(٤)"],[11029,"قال ابن المدينى: قيل ليحيى بن سعيد: نحفظ حديث قتادة: \"إن هذه الحشوش محتضرة\" (٥). قال: لا، قلت: كان شعبة يحدث به عن قتادة، عن النضر بن أنس، عن زيد"],[11030,"= (٧ / ت ٧٢٥)، لسان الميزان (٧/ ٣٣٩)، ضعفاء ابن الجوزى (٧/ ١٦٢)، المغنى (٢ / ت ٥٠٠٦)، الكامل لابن عدى (٧/ ١٥٢)."],[11031,"(١) هو: القاسم بن عبد الله بن عمر بن حفص بن عاصم بن عمر بن الخطاب العدوى العمرى المدنى، أخو عبد الرحمن."],[11032,"انظر: تهذيب الكمال (٢٣ / ت ٤٧٩٨)، تهذيب التهذيب (٨/ ٣٢٠)، الجرح والتعديل (٧ / ت ٦٤٣) الكاشف (٢ / ت ٤٥٨٢)، ميزان الاعتدال (٣ / ت ٦٨١٢)، علل أحمد (٢/ ٣١)، المعرفة ليعقوب (٢/ ١٨٥)، المجروحين (٢/ ٢١٢)، تاريخ ابن معين رواية الدورى (٢/ ٤٨١)، لسان الميزان (٧/ ٣٣٨)، المغنى (٢ / ت ٤٩٩٢)، طبقات ابن سعد (٥/ ٤٢٣)، الكامل لابن عدى (٧/ ١٤٩)."],[11033,"(٢) قال ابن عدى: القاسم بن عبد الرحمن الذى ذكره يحيى بن معين، أى هذا، ليس هو بالمعروف."],[11034,"انظر: الكامل لابن عدى (٧/ ١٥٢)، تاريخ ابن معين رواية الدورى (٢/ ٤٨١)، اللسان (٤/ ٤٦٢)، الجرح والتعديل (٧/ ٦٤٨)، تنقيح المقال (٩٥٧٧)."],[11035,"(٣) قلت: قد سبق."],[11036,"(٤) والقاسم نجن عوف الشيبانى البكرى الكوفى، من بنى مرة بن همام."],[11037,"انظر: تهذيب الكمال (٢٣ / ت ٤٨٠٥)، تهذيب التهذيب (٨/ ٣٢٦)، ميزان الاعتدال (٣ / ت ٦٨٢٨)، الجرح والتعديل (٧ / ت ٦٥٩)، الكاشف (٢ / ت ٤٥٨٧)، التاريخ الكبير (٧ / ت ٧٣٩)."],[11038,"(٥) أخرجه أبو داود \"كتاب الطهارة\"، باب \"ما يقول الرجل إذا دخل الخلاء\"، برقم (٦)، من طريق قتادة، عن النضر بن أنس، عنه به. ="],[11039,"ابن أرقم، وكان ابن أبى عروبة يحدثه، عن القاسم بن عوف [١٠٢/ أ]، عن زيد بن أرقم."],[11040,"قال يحيى: شعبة لو علم أنه عن القاسم بن عوف لم يحمله، قلت: لم؟، قال: إنه تركه وقد رآه."],[11041,"٧١٨ - قيس"],[11042,"(١)"],[11043,"قال السباك: سمعت أبا الوليد يقول: سمعت شعبة، يقول: كنت مع قيس فى بيت"],[11044,"فجعل يحدثنى عن أبى حسين حتى تمنيت أن البيت يقع علىّ وعليه."],[11045,"٧١٩ - القاسم بن عوف الشيبانى"],[11046,"(٢)"],[11047,"قال ابن المدينى: ذكر ليحيى القاسم بن عوف الشيبانى، فقال: قال شعبة: دخلت عليه؟، وحرك يحيى رأسه، فقلت ليحيى: ما شأنه؟ فجعل يجيد، فقلت: ضعّفه فى الحديث؟، فقال: لو لم يكن يضعفه لروى عنه."],[11048,"حرف ك"],[11049,"٧٢٠ - كثير بن زيد"],[11050,"(٣)"],[11051,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن كثير بن زيد، روى عنه عبد الحميد"],[11052,"= وأخرجه أحمد فى المسند (٤/ ٣٦٩، ٣٧٣)، من الطريق السابق."],[11053,"وأخرجه ابن ماجه \"كتاب الطهارة\" باب \"ما يقول الرحل إذا دخل الخلاء\"، برقم (٢٩٦)، من الطريق السابق. وأخرجه من طريق: قتادة عن القاسم بن عوف، عن زيد بن أرقم به. قلت: والحديث مذكور فى مصادر عديدة غير ما ذكرت."],[11054,"(١) هو: قيس بن الربيع الأسدى، أبو محمد الكوفى."],[11055,"انظر: تهذيب الكمال (٢٤ / ت ٤٩٠٣)، تهذيب التهذيب (٨/ ٣٩١)، الكاشف (٢ / ت ٤٦٦٦)، ميزان الاعتدال (٣ / ت ٦٩١١)، التاريخ الكبير (٧ / ت ٧٠٤)، الجرح والتعديل (٧ / ت ٥٥٣)، تاريخ بغداد (١٢/ ٤٥٦)، تراجم الأحبار (٣/ ٢٦٢)، لسان الميزان (٤/ ٤٧٧)، المغنى (٢ / ت ٥٠٦٢)، معرفة الثقات (١٥٣٠)، أعلام النبلاء (٨/ ٤١)، طبقات ابن سعد (٦/ ٦٠)، الكامل لابن عدى (٧/ ١٥٧)."],[11056,"(٢) سبق."],[11057,"(٣) هو: كثير بن زيد الأسلمى، ثم السهمى، مولاهم، أبو محمد المدنى، يقال له: ابن مافنة، وهى أمه."],[11058,"انظر: تهذيب التهذيب (٨/ ٤١٣)، تهذيب الكمال (٢٤ / ت ٤٩٤١)، التاريخ الكبير (١٧ ت ٦٤٣)، الجرح والتعديل (٧ / ت ٨٤١)، الكاشف (٣ / ت ٤٦٩٨)، ميزان الاعتدال (٣ / ت ٦٩٣٨)، تاريخ أسماء الثقات (١١٧٩)، لسان الميزان (٧/ ٣٤٤)، تراجم الأحبار (٣/ ٢٩٣)، الثقات (٧/ ٣٥٤)، المغنى (٢ / ت ٥٠٨٠)، الكامل لابن عدى (٧/ ٢٠٤)."],[11059,"الحنفى؟، قال: ليس بذاك القوى، وكان قال أولا: ليس بشئ."],[11060,"٧٢١ - كثير بن عبد الله بن عمرو بن عوف"],[11061,"(١)"],[11062,"ابن معين قال: كثير بن عبد الله بن عمرو بن عوف لِجدِّه صحبة وكثير ضعيف الحديث."],[11063,"٧٢٢ - وكليب بن وائل"],[11064,"(٢)"],[11065,"ليس بشئ."],[11066,"٧٢٣ - وكثير بن سليمان"],[11067,"(٣)"],[11068,"ضعيف."],[11069,"٧٢٤ - كثير بن شنظير"],[11070,"(٤)"],[11071,"ليس بشئ."],[11072,"(١) هو: كثير بن عبد الله بن عمرو بن عوف بن زيد بن ملحة اليشكرى المزنى المدنى."],[11073,"انظر: تهذيب الكمال (٢٤ / ت ٤٩٤٨)، تهذيب التهذيب (٨/ ٤٢١)، ميزان الاعتدال (٣ / ت ٦٩٤٣)، التاريخ الكبير (٧ / ت ٩٤٥)، الكاشف (٣ / ت ٤٧٠٤)، تراجم الأحبار (٣/ ٣٠٢)، المغنى (٢ / ت ٥٠٨٤)، الثقات (٧/ ٣٥٤)، الجرح والتعديل (٧/ ٧٥٨)، لسان الميزان (٧/ ٣٤٥)."],[11074,"(٢) هو: كليب بن وائل بن هبار التيمى اليشكرى المدنى، ثم الكوفى."],[11075,"انظر: تهذيب الكمال (٢٤ / ت ٤٩٩٤)، التاريخ الكبير (٧ / ت ٩٨٥)، الجرح والتعديل (٧ / ت ٩٤٧)، الكاشف (٣ / ت ٤٧٣٩)."],[11076,"(٣) هو: كثير بن سليم الضبى."],[11077,"انظر: تهذيب الكمال (٢٤ / ت ٤٩٤٣)، تهذيب التهذيب (٨/ ٤١٦)، الجرح والتعديل (٧ / ت ٨٤٦)، الكاشف (٣ / ت ٤٧٠٠)، ميزان الاعتدال (٣ / ت ٦٩٤٠)، التاريخ الكبير (٧ / ت ٩٥١)، الكامل لابن عدى (٧/ ١٩٨)، لسان الميزان (٧/ ٣٤٥)، تاريخ بغداد (١٢/ ٤٨٠)، المغتى (٢ / ت ٥٠٨١)، تاريخ ابن معين (٢/ ٤٩٣)، ضعفاء ابن الجوزى (٣/ ٢٣)، ديوان الضعفاء (ت ٣٤٧٢)، دائرة معارف الأعلمى (٢٤/ ١٧٤)، الضعفاء الكبير (٤/ ٥)، الضعفاء والمتروكين للدارقطنى (٤٤٤)، الكشف الحثيث (٣٤)."],[11078,"(٤) هو: كثير بن شنظي المازنى، ويقال: الأزدى أبو قرة البصرى."],[11079,"انظر: تهذيب الكمال (٢٤/ ت ٤٩٤٥)، تهذيب التهذيب (٨/ ٤١٩)، ميزان الاعتدال (٣ / ت ٦٩٤١)، التاريخ الكبير (٧ / ت ٩٣٥)، الكاشف (٣ / ت ٤٧٠١)، تاريخ ابن معين رواية الدورى (٢/ ٤٩٣)، تاريخ الإسلام (٥/ ٢٩٢)، لسان الميزان (٧/ ٣٤٥)، المجروحين (٢/ ٢٢٢)، تاريخ أسماء الثقات (ت ١١٧٧)، المغنى (٢ / ت ٥٠٨٣)، معارف الأعلمى (٢٤/ ١٧٤)، ضعفاء ابن الجوزى (٣/ ٢٣)، الكامل لابن عدى (٧/ ٢٠٨)."],[11080,"٧٢٥ - وكثير بن مروان"],[11081,"(١)"],[11082,"شامى وليس بشئ."],[11083,"حرف ل"],[11084,"٧٢٦ - لقيط"],[11085,"(٢)"],[11086,"على قال: قلت ليحيى: سفيان، يعنى ابن عيينة، الذى روى عنه عمرو؟، قال: لا"],[11087,"أدرى."],[11088,"٧٢٧ - ليث بن أبى سليمان"],[11089,"(٣)"],[11090,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن ليث بن أبى سليمان قال: ليس حديثه بذاك. صدقة بن الفضل المروزى، قال: ليث أضعف العلمين وحبيب أقواهم."],[11091,"حرف م"],[11092,"٧٢٨ - ميناء مولى عبد الرحمن بن عوف"],[11093,"(٤)"],[11094,"قال: حدثنا عبد الرزاق، عن أبيه، عن ميناء، مولى عبد الرحمن بن عوف، وميناء،"],[11095,"ليس بثقة، وربما قال: ومن ميناء إلا عدو لله."],[11096,"٧٢٩ - مخرمة بن بكير"],[11097,"(٥)"],[11098,"قال: ومخرمة بن بكير."],[11099,"(١) هو: كثير بن مروان الفلسطينى الفهرى، أبو محمد المقدسى."],[11100,"انظر: تاريخ بغداد (١٢/ ٤٨١)، ضعفاء ابن الجوزى (٣/ ٢٤)، المغنى (٢ / ت ٥٠٨٩)، تعجيل المنفعة (٩٠٢)، الذيل على الكاشف رقم (١٢٨٤)، المغنى (٢ / ت ٥٠٩٠)، الجرح والتعديل (٧/ ٨٧٤)، المجروحين (٢/ ٢٢٥)، الضعفاء والمتروكين للدارقطنى (٤٤٧)، ديوان الضعفاء (ت ٣٤٧٦)، معارف الأعلمى (٢٤/ ١٧٥)، ميزان الاعتدال (٣/ ٤٠٩)، لسان الميزان (٤/ ٤٨٣)، الكامل لابن عدى (٧/ ٢٠٧)."],[11101,"(٢) لم أعرفه، والله أعلم."],[11102,"(٣) سبق."],[11103,"(٤) هو: ميناء بن أبى ميناء الزهرى الخراز، مولى عبد الرحمن بن عوف."],[11104,"انظر: تهذيب الكمال (٢٩ / ت ٦٣٤٨)، تهذيب التهذيب (١٠/ ٣٩٧)، الكاشف (٣ / ت ٥٨٦٧)، ميزان الاعتدال (٤ / ت ٨٩٨١)، الجرح والتعديل (٨ / ت ١٨١١)، الكامل لابن عدى (٨/ ٢١٩)، المغنى (٢ / ت ٦٥٧٣)، لسان الميزان (٦/ ١٤٢)."],[11105,"(٥) سبق."],[11106,"٧٣٠ - ومجمع أبو إسماعيل بن مجمع"],[11107,"(١)"],[11108,"ضعيف."],[11109,"٧٣١ - مغيرة بن عبد الرحمن الحرانى"],[11110,"(٢)"],[11111,"صاحب أبى الزناد، ليس بشئ."],[11112,"٧٣٢ - ومسلمة بن محمد"],[11113,"(٣)"],[11114,"ليس حديثه بشئ، يروى عن هشام بن عروة (٤)."],[11115,"٧٣٣ - وموسى بن عبيدة"],[11116,"(٥)"],[11117,"لا يحتج بحديثه."],[11118,"٧٣٤ - ومحمد بن كريب"],[11119,"(٦)"],[11120,"أخو رشدين ليس حديثه بشئ."],[11121,"(١) لم أقف عليه."],[11122,"(٢) هو: المغيرة بن عبد الرحمن بن عبد الله بن خالد بن حزام بن خويلد بن أسد بن عبد العزى بن قصى القرشى الأسدى الحزامى، المدنى، لقبه، قصى، وقيل: إنه من ولد حكيم بن حزام."],[11123,"انظر: تهذيب الكمال (٢٨ / ت ٦١٣٧)، تهذيب التهذيب (١٠/ ٢٦٦)، الجرح والتعديل (٨ / ت ١٠١٤)، الكاشف (٣ / ت ٥٦٩١)، ميزان الاعتدال (٤ / ت ٨٧١٤)."],[11124,"(٣) مسلمة بن محمد الثقفى البصرى."],[11125,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٦١)، تهذيب التهذيب (١/ ١٤٧)، المغنى (٢ / ت ٦٢٤١)، ميزان الاعتدال (٤/ ١١٢)، لسان الميزان (٧/ ٣٨٧)."],[11126,"(٤) روى عنه \"إياكم والزنج، فإنه خلق مشوه\"، قال عنه أبو داود: من حدث بهذا فاتهمه، وقال الأزدى فى الضعفاء: منكر."],[11127,"(٥) هو: موسى بن عبيدة بن نشيط بن عمرو بن الحارث الربذى، أبو عبد العزيز المدنى."],[11128,"قلت: وقد سبق."],[11129,"(٦) هو: محمد بن كريب بن أبى مسلم الهاشمى، مولى ابن عباس."],[11130,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٧٢)، تهذيب التهذيب (٩/ ٤٢٠)، ميزان الاعتدال (٤ / ت ٨١٠٤)، الكاشف (٣ / ت ٥٢٠٩)، الجرح والتعديل (٨ / ت ٣٠٧)، التاريخ الكبير (١/ ت ٦٨٢)، تاريخ ابن معين رواية الدورى (٢/ ٥٣٦)، المعرفة والتاريخ (٣/ ٦٦)، ديوان الضعفاء (٣٩٤٧)، المجروحين (٢/ ٢٦٢)، الضعفاء الكبير (٤/ ١٢٧)، ضعفاء ابن الجوزى (٩٥١٣)، المغنى (٢ / ت ٥٩٣٠)، تاريخ الإسلام (٥/ ٢٩٧)، لسان الميزان (٧/ ٣٧٣)، الكامل لابن عدى (٧/ ٤٩٥)."],[11131,"٧٣٥ - ومعلى بن عرفان"],[11132,"(١)"],[11133,"ليس بشئ، وكان عرافًا فى طريق مكة."],[11134,"٧٣٦ - وموسى بن عثمان"],[11135,"(٢)"],[11136,"يحدث عن الحكم بن عتيبة ليس بشئ."],[11137,"٧٣٧ - ومحمد بن الفرات"],[11138,"(٣)"],[11139,"ليس بشئ."],[11140,"٧٣٨ - ومحمد بن أبان"],[11141,"(٤)"],[11142,"ضعيف."],[11143,"٧٣٩ - ومحمد بن الحسن الهمدانى"],[11144,"(٥)"],[11145,"(١) هو: معلى بن عرفان الأسدى الكوفى."],[11146,"انظر: الكامل لابن عدى (٩٦١٨)، الضعفاء الكبير (٤/ ٢١٣)، الجرح والتعديل (٨/ ٣٣٠)، المغنى (٢ / ت ٦٣٥٨)، تاريخ ابن معين رواية الدورى (٢/ ٥٧٦)، ميزان الاعتدال (٤/ ١٤٩)، لسان الميزان (٦/ ٦٤)."],[11147,"(٢) هو: موسى بن عثمان الحضرمى المؤدب الكوفى."],[11148,"انظر: الجرح والتعديل (٨ / ت ٦٨٧)، الكامل لابن عدى (٦٧١٨)، المغنى (٢ / ت ٦٥١١)، ضعفاء ابن الجوزى (٣/ ١٤٧)، لسان الميزان (٦/ ١٢٥)، ميزان الاعتدال (٤/ ٢١٤)، المعرفة والتاريخ (٣/ ٣٥)."],[11149,"(٣) هو: محمد بن الفرات التميمى، ويقال: الجرمى أبو على الكوفى."],[11150,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٤٠)، تهذيب التهذيب (٩/ ٣٩٦)، ميزان الاعتدال (٤ / ت ٨٠٤٧)، الجرح والتعديل (٨ / ت ٢٧٠)، التاريخ الكبير (١ / ت ٦٥٦)، تاريخ ابن معين رواية الدورى (٢/ ٥٣٣)، الكاشف (ت ٥١٨٨)، ديوان الضعفاء (ت ٣٦٢٦)، الكاشف الحثيث (ت ٧١٥)، المجروحين (١/ ٢٨١)."],[11151,"(٤) هو: محمد بن أبان بن صالح بن عمير، أبو عمر الجعفى."],[11152,"كان يقول بالإرجاء، وكان رئيسا من رؤسائهم، فترك الناس حديثه من أجل ذلك، وكان أصحاب محمد بن الحسن يكثرون عنه، وكان كوفيًا جعفيًا."],[11153,"انظر: تهذيب التهذيب (٩/ ٥)، الكامل لابن عدى (٧/ ٢٩٤)، تعجيل المنفعة (٩٢٢)، الذيل على الكاشف رقم (١٣٠٦)، التاريخ الكبير (١/ ٣٤)، طبقات ابن سعد (٦/ ٢٦٨)، المغنى (٢ / ت ٥٢٢٦)، الجرح والتعديل (٧ / ت ١١١٩)."],[11154,"(٥) هو: محمد بن الحسن بن أبى يزيد الهمدانى ثم المعشارى، أبو الحسن الكوفى، نزيل واسط. ="],[11155,"ليس بثقة."],[11156,"٧٤٠ - ومحمد بن الحسن الأسدى"],[11157,"(١)"],[11158,"قد أدركته [١٠٢/ ب] وليس هو بشئ."],[11159,"٧٤١ - ومطرح بن يزيد"],[11160,"(٢)"],[11161,"كوفى ضعيف، يروى عنه سفيان، وهو مطرح بن يزيد، ويكنى أبا المهلب."],[11162,"٧٤٢ - وموسى بن طريف"],[11163,"(٣)"],[11164,"الذى يحدث عنه الأعمش ضعيف."],[11165,"٧٤٣ - ومحمد بن عون الحراسانى"],[11166,"(٤)"],[11167,"= انظر: تهذيب الكمال (٢٥ / ت ٥١٥٣)، تهذيب التهذيب (٩/ ١٢٠)، التاريخ الكبير (١/ ت ١٥٠)، الجرح والتعديل (٧ / ت ١٢٤٨)، الكاشف (٣ / ت ٤٨٦٨)، ميزان الاعتدال (٣ / ت ٧٣٨٢)، لسان الميزان (٧/ ٣٥٥)، تاريخ بغداد (٢/ ١٧)، تنقيح المقال (١٠٥٣٣)، ضعفاء ابن الجوزى (٣/ ٥٢)، ديوان الضعفاء (ت ٣٦٦٥)، جامع الرواة (٤/ ٩٠)، الكشف الحثيث (٣٦٣)، الضعفاء الكبير (٤/ ٤٨)، الكامل لابن عدى (٧/ ٣٧٢)."],[11168,"(١) هو: محمد بن الحسن بن الزبير الأسدى، أبو عبد الله، ويقال: أبو جعفر، المعروف بالتل الكوفى."],[11169,"انظر: تهذيب الكمال (٢٥ / ت ٥١٤٩)، تهذيب التهذيب (٩/ ١١٧)، التاريخ الكبير (١/ ت ١٥٢)، الجرح والتعديل (٧ / ت ١٢٤٩)، ميزان الاعتدال (٣ / ت ٧٣٧٨)، الكاشف (٣ / ت ٤٨٦٤)، تاريخ الثقات (٤٠٣)، العبر (١/ ٣٣٣)، المجروحين (٢/ ٢٧٧)، تاريخ أسماء الثقات (١٢٦٧)، ضعفاء ابن الجوزى (٥١١٣)، الكامل لابن عدى (٧/ ٣٧٣)."],[11170,"(٢) هو: مطرح بن يزيد الأسدى، الكنانى، أبو المهلب الكوفى، عداده فى الشاميين."],[11171,"انظر: تهذيب الكمال (٢٨ / ت ٥٩٩٩)، التاريخ الكبير (٨ / ت ١٩٩٨)، تهذيب التهذيب (١٠/ ١٧١)، الجرح والتعديل (٨ / ت ١٨٧٠)، الكاشف (٣ / ت ٥٥٧٠)، ميزان الاعتدال (٤ / ت ٨٥٨٠)، تاريخ أسماء الثقات (٧/ ١٤)، ضعفاء ابن الجوزى (٣/ ١٢٤)، المغنى (٢ / ت ٦٢٧٨)، تاريخ ابن معين رواية الدورى (٢/ ٥٦٩)، ابن الجنيد (ت ٥٤٩)، الدارمى (ت ٧٣٠)، ابن محرز (ت ٥٤)، ضعفاء الدارقطنى (ت ٥٣١)، المعرفة والتاريخ (٢/ ٤٣٤)، لسان الميزان (٧/ ٣٨٩)، المجروحين (٣/ ٢٦)."],[11172,"(٣) هو: موسى بن طريف الأسدى."],[11173,"انظر: الكامل لابن عدى (٨/ ٥٣)، الجرح والتعديل (٨ / ت ٦٦٨)، الضعفاء والمتروكين (٣/ ١٤٦)، المغنى (٢ / ت ٦٥٠٢)، التاريخ الكبير (٧/ ٢٨٧)، تاريخ ابن معين رواية الدورى (٣/ ٥٩٣)، الكشف الحثيث (٤٣)، ميزان الاعتدال (٤/ ٤٠٨)، لسان الميزان (٦/ ١٢١)."],[11174,"(٤) هو: محمد بن عون، أبو عبد الله الخراسانى."],[11175,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٢٨)، تهذيب التهذيب (٩/ ٣٨٤)، الجرح والتعديل = ليس بشئ."],[11176,"٧٤٤ - مندل"],[11177,"(١)"],[11178,"قال: وسئل عن مندل، فقال: إنما تركناه لمكان الوديعة، يوفئ إلى أنه استودع فخان أو قيل: وديعة لم يحب أن يقبلها."],[11179,"٧٤٥ - موسى الجهنى"],[11180,"(٢)"],[11181,"على بن المدينى، قال: سألت يحيى بن معين، عن موسى الجهنى؟، فقال: لم يكن بذاك."],[11182,"ابن أبى خيثمة، قال: سألت يحيى بن معين، عن موسى الجهنى؟ فقال: لم يكن بذاك."],[11183,"٧٤٦ - مطر الوراق"],[11184,"(٣)"],[11185,"ابن أبى خيثمة قال: وقال يحيى بن معين: مطر الوراق ضعيف الحديث."],[11186,"٧٤٧ - معاوية بن صالح"],[11187,"(٤)"],[11188,"على قال: سألت يحيى، عن معاية بن صالح، فقال: ما كنا نأخذ من حديثه فى ذلك الزمان ولا حرفًا."],[11189,"= (٨ / ت ٢١٩)، الكاشف (٣ / ت ٥١٧٨)، ميزان الاعتدال (٣ / ت ٨٠٣١)، المعرفة والتاريخ (٣/ ٣٧٨)، لسان الميزان (٧/ ٣٧١)، التاريخ الكبير (١/ ١٩٧)، المجروحين (٢/ ٢٧٢)، المغنى (٢ / ت ٥٨٨٤)، الكامل لابن عدى (٧/ ٤٨٥)."],[11190,"(١) سبق."],[11191,"(٢) هو: موسى بن عبد الله، ويقال: ابن عبد الرحمن الجهنى أبو سلمة، ويقال: أبو عبد الله الكوفى."],[11192,"انظر: تهذيب التهذيب (١٠/ ٣٥٤)، تهذيب الكمال (٢٩ / ت ٦٢٧٦)، الجرح والتعديل (٨ / ت ٦٧٦)، الكاشف (٣ / ت ٥٨٠٦)، تاريخ ابن معين الدورى (٢/ ٥٩٣)."],[11193,"(٣) هو: مطر بن طهمان الوراق، أبو رجاء الخراسانى، السلمى، مولى على، سكن البصرة."],[11194,"قلت: وقد سبق."],[11195,"(٤) هو: معاوية بن صالح بن حدير بن سعيد بن سعد بن فهر الحضرمى، أبو عمرو، وقيل: أبو عبد الرحمن الحمصى، أحد الأعلام، وقاضى الأندلس، وقيل: غير ذلك."],[11196,"انظر: تهذيب الكمال (٢٨ / ت ٦٠٥٨)، تهذيب التهذيب (١٠/ ٢٠٩)، التاريخ الكبير (٧ / ت ١٤٤٣)، الجرح والتعديل (٨ / ت ١٧٥٠)، الكاشف (٣ / ت ٥٦٢١)، ميزان الاعتدال (٤ / ت ٨٦٢٤)، طبقات الحفاظ (٧٧)، تاريخ الإسلام (٦/ ٣٩١)، معرفة الثقات (١٧٤٦)، سير أعلام النبلاء، الأعلام (٧/ ١٥٨)، طبقات ابن سعد (٧/ ٣٣٥)، نسيم الرياض (١/ ٤٤١)، ضعفاء ابن الجوزى (٣/ ١٢٧)، تراجم الأحبار (٣/ ٣٤٦)، الكامل لابن عدى (٨/ ١٤٥)."],[11197,"٧٤٨ - ميمون بن أبى عبد الله"],[11198,"(١)"],[11199,"على قال: سألت يحيى، عن ميمون بن أبى عبد الله الذى روى عنه عوف، عن زيد"],[11200,"ابن أرقم فحمض وجهه، وقال: زعم شعبة أنه كان فسلًا."],[11201,"٧٤٩ - معاذ بن معاذ"],[11202,"(٢)"],[11203,"على قال: سمعت معاذ بن معاذ قال: كتبت عنه عن الزهرى ورغبت عنه، قيل له: لم؟ قال: رأيته يأتى أشعث بن عبد الملك، فإذا قمنا جلس إلى صبيان فأملوها عليه."],[11204,"قال على: فقلت لمعاذ: من هذا يا أبا المثنى؟، فقال: محمد بن أبى حفصة."],[11205,"٧٥٠ - محمد بن أبى حفصة"],[11206,"(٣)"],[11207,"على بن المدينى، قال: قلت ليحيى: حملت عن محمد بن أبى حفصة؟، قال: نعم، كتبت حديثه كله ثم رميت به، قال: وهو نحو صالح بن أبى الأخضر."],[11208,"٧٥١ - محمد بن أبى حميد"],[11209,"(٤)"],[11210,"ابن أبى خيثمة قال: سمعت يحيى بن معين يقول: محمد بن أبى حميد ليس حديثه بشئ."],[11211,"٧٥٢ - مخرمة بن بكير"],[11212,"(٥)"],[11213,"قال: وسمعته يقول: مخرمة بن بكير، يقال: إنه وقع إليه كتاب أبيه فرواه ولم يسمعه."],[11214,"(١) هو: ميمون أبو عبد الله البصرى الكندى، ويقال: القرشى، مولى ابن سمرة عبد الرحمن."],[11215,"انظر: تهذيب الكمال (٢٩ / ت ٦٣٤٠)، تهذيب التهذيب (١٠/ ٣٩٣)، التاريخ الكبير (٧ / ت ٩٤٥٨)، الجرح والتعديل (٨ / ت ١٠٥٧)، ميزان الاعتدال (٤ / ت ٨٩٧١)، الذيل على الكاشف (١٥٥٨)، العقد الثمين (٦٥٦٤)، علل أحمد (١/ ١٦١)، تاريخ ابن معين رواية الدورى (٢/ ٥٩٩)، الكامل لابن عدى (٨/ ١٥٨)."],[11216,"(٢) سبق."],[11217,"(٣) هو: محمد بن أبى حفصة، ميسرة أبو سلمة البصرى."],[11218,"انظر: تهذيب الكمال (٢٥/ ٥١٥٩)، الكاشف (٣ / ت ٤٨٧٣)، ميزان الاعتدال (٣ / ت ٧٤٢٩)، تهذيب التهذيب (٩/ ١٢٣)، تاريخ أسماء الثقات (١٢٠٥)، سير أعلام النبلاء (٧/ ٥٨)، التاريخ الكبير (١/ ٢٢٦)، لسان الميزان (٧/ ٣٥٦)، تراجم الأحبار (٤/ ٧٢)، الجرح والتعديل (٧ / ت ١٣٢٥)، الكامل لابن عدى (٧/ ٥٠٨)."],[11219,"(٤) هو: محمد بن أبى حميد، وكنيته: أبو إبراهيم الزرقى، المدنى، يلقب بحماد. قلت: وقد سبق."],[11220,"(٥) هو: مخرمة بن بكير بن عبد الله بن الأشج مدينى، يكنى أبا المسور. قلت: وقد سبق."],[11221,"٧٥٣ - مسلم بن يسار الجهنى"],[11222,"(١)"],[11223,"قال: وسمعته يقول: مسلم بن بشار الجهنى الذى روى عن عمر، رضي الله عنه، عن النبى - صلى الله عليه وآله وسلم -: \"إن الله مسح ظهر آدم\"، لا يعرف."],[11224,"٧٥٤ - محمد بن عبد الله بن مسلم"],[11225,"(٢)"],[11226,"قال: وسئل عن محمد بن عبد الله بن مسلم ابن أخى شهاب؟، فقال: ليس بذاك"],[11227,"القوى، وقال مرة أخرى: ضعيف."],[11228,"٧٥٥ - مسلم الأعور"],[11229,"(٣)"],[11230,"قال: وسمعته يقول: مسلم الأعور، يقال: إنه اختلط."],[11231,"٧٥٦ - مسعدة بن اليسع"],[11232,"(٤)"],[11233,"قال: وسئل يحيى لم ترك حديث مسعدة بن اليسع؟، فقال: لأنه روى حديثًا أنكروه، روى عن جعفر بن محمد أنه حدَّثه أنه رأى خفاشًا مجنونًا."],[11234,"٧٥٧ - موسى بن دينار"],[11235,"(٥)"],[11236,"على قال: قال يحيى بن سعيد: دخلت على موسى بن دينار أنا وحفص بن غياث"],[11237,"(١) هو: مسلم بن يسار الجهنى."],[11238,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٥١)، تهذيب التهذيب (١٠/ ١٤٢)، ميزان الإعتدال (٤ / ت ٨٥١٤)، الكاشف (٣ / ت ٥٥٢٩)، المغنى (٢ / ت ٦٢٢٩)، لسان الميزان (٧/ ٢٨٦)."],[11239,"(٢) هو: محمد بن عبد الله بن مسلم بن عبيد بن عبد الله بن شهاب بن عبد الله بن الحارث بن زهرة الزهرى، أبو عبد الله المدنى، ابن أخى الزهرى."],[11240,"انظر: تهذيب الكمال (٢٥ / ت ٥٣٧٥)، تهذيب التهذيب (٩/ ٢٧٩)، الجرح والتعديل (٧ / ت ١٦٥٣)، الكاشف (٣ / ت ٥٠٤٩)، ميزان الاعتدال (٣ / ت ٧٧٤٣)، التاريخ الكبير (١ / ت ٣٩٤)."],[11241,"(٣) هو: مسلم بن كيسان الضبى الملائى البراد، أبو عبد الله الكوفى الأعور."],[11242,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٣٩)، التاريخ الكبير (٧ / ت ١١٤٥)، تهذيب التهذيب (١٠/ ١٣٥)، المجروحين (٨١٣)، كشف الأستار (٤٩٥)، تاريخ الإسلام (٥/ ٣٠١)، ضعفاء ابن الجوزى (٣/ ١١٨)، علل أحمد (١/ ١٦٧)، معرفة الثقات (١٨٢٦)، تاريخ ابن معين رواية الدورى (٢٢٢)، تعجيل المنفعة (١٠٣٣)، المغنى (٢ / ت ٦٢٢٠)، لسان الميزان (٧/ ٣٨٦)."],[11243,"(٤) هو: مسعدة بن اليسع بن قيس الباهلى البصرى."],[11244,"انظر: الكامل لابن عدى (٨/ ١٢٧)، الضعفاء والمتروكين (٣/ ١١٦)، الضعفاء الكبير (٤/ ٢٤٥)."],[11245,"(٥) هو: موسى بن دينار المكى."],[11246,"انظر: الضعفاء والمتروكين (٣/ ١٤٥)، الجرح والتعديل (٨/ ١٤٢)، الضعفاء الكبير (٤/ ١٥٦)، المغنى (٢ / ت ٦٤٩١)، ميزان الاعتدال (٤/ ٢٠٤)، لسان الميزان (٦/ ١١٦)، الكامل (٨/ ٦٠)."],[11247,"فجعلت لا أريده على شئ إلّا لقنه، فخرجنا فاتبعنا أبو شيخ، فجعلت أبيِّن له أمره، وجعل لا يقبل (١)."],[11248,"٧٥٨ - محل الضبى"],[11249,"(٢)"],[11250,"ابن أبى خيثمة، قال: سألت يحيى عن محل الضبى، فقال: كان وسطًا لم يكن بذاك."],[11251,"٧٥٩ - معلى بن هلال الكوفى"],[11252,"(٣)"],[11253,"قال أبو حاتم الرازى: معلى بن هلال الكوفى، ذاهب الحديث."],[11254,"٧٦٠ - المثنى بن سعيد"],[11255,"(٤)"],[11256,"وسئل عن المثنى بن سعيد فقال: ليس بالقوى."],[11257,"٧٦١ - ومروان بن سالم"],[11258,"(٥)"],[11259,"(١) بقية هذا القول كما أورده ابن عدى،: قال يحيى: وإذا كان الشيخ إذا لقنته قبل فذاك، وإذا ثبت على شئ واحد، فليس به بأس، قال، على: وقد رأيت أنا أبا شيخ هذا وكان يقال له: جارية بن هرم، وكان رئيسًا فى القدر، وكان ضعيفًا فى الحديث، كتبنا عنه وتركناه."],[11260,"(٢) هو: محل بن محرز الضبى الكوفى الأعور."],[11261,"انظر: تهذيب الكمال (٢٧ / ت ٥٨١١)، تهذيب التهذيب (١٠/ ٦٠)، ميزان الاعتدال (٣/ ت ٧٠٩٦)، الجرح والتعديل (٨ / ت ١٨٨٥)، الكاشف (٣ / ت ٥٤١٠)، التاريخ الكبير (٧ / ت ٢٠٠٤)، طبقات ابن سعد (٦/ ٣٦١)، تاريخ خليفة (٤٢٦)، طبقات خليفة (١٦٨)، عدل أحمد (٢/ ٢٨٦)، المعرفة والتاريخ (٢/ ١٧٥)، الكامل لابن عدى (٨/ ١٩٧)."],[11262,"(٣) هو: معلى بن هلال بن سويد الحضرمى، ويقال: الجعفى، أبو عبد الله الطحان الكوفى."],[11263,"انظر: تهذيب الكمال (٢٨/ ٦١٠٢)، تهذيب التهذيب (١٠/ ٢٤٠)، التاريخ الكبير (٧/ ت ١٧٢٧)، الجرح والتعديل (٨/ ت، ١٥٢٩)، الكاشف (٣ / ت ٥٦٦٠)، ميزان الاعتدال (٤/ ٨٦٧٩)، العلل لأحمد (١/ ١١٧٨)، تاريخ ابن معين رواية الدورى (٢/ ٥٧٦)، ضعفاء ابن الجوزى (٣/ ١٣٢)، المعرفة والتاريخ (٣/ ١٣٧)، ضعفاء النسائى (ت ٥٦٠)، ضعفاء ابن نعيم (ت ٢٤٢)، السابق واللاحق (٢٤٤)، الكشف الحثيث (٧٧٧)، المجروحين (٣/ ١٦)، معرفة الثقات (١٧٦٤)، المغنى (٢/ ت ٦٣٦٣)، لسان الميزان (٧/ ٣٩٤)، الكامل لابن عدى (٨/ ٩٩)."],[11264,"(٤) هو: المثنى بن سعيد الضبعى، أبو سعيد البصرى القسام الذارع القصير."],[11265,"انظر: تهذيب الكمال (٢٧/ ت ٥٧٧٢)، تهذيب التهذيب (١/ ٣٤٠)، الجرح والتعديل (٨/ ت ١٤٩٣)."],[11266,"(٥) هو: مروان بن سالم الغفارى، أبو عبد الله الشامى الجزرى، مولى بنى أمية، سكن قرقيسيا. ="],[11267,"ضعيف الحديث."],[11268,"٧٦٢ - ومروان بن شجاع"],[11269,"(١)"],[11270,"يكتب حديثه ولا يحتج به."],[11271,"٧٦٣ - ومحمد بن أبى حميد"],[11272,"(٢)"],[11273,"ليس بالقوى."],[11274,"٧٦٤ - ومحمد بن مسلم الطائفى"],[11275,"(٣)"],[11276,"يكتب حديثه ولا يحتج به."],[11277,"٧٦٥ - ومسلم بن كيسان الطائفى"],[11278,"(٤)"],[11279,"يكتب حديثه ولا يحتج به."],[11280,"٧٦٦ - ومسلم بن كيسان الملائى الأعور"],[11281,"(٥)"],[11282,"= انظر: تهذيب الكمال (٢٧ / ت ٥٨٧٣)، تهذيب التهذيب (١٠/ ٩٣)، ميزان الاعتدال (٤ / ت ٨٤٢٥)، الكاشف (٣ / ت ٥٤٥٩)، الجرح والتعديل (٨ / ت ١٢٥٥)، التاريخ الكبير (٧ / ت ١٦٠٢)، ضعفاء ابن الجوزى (٣/ ١١٣)، المعرفة والتاريخ (٣/ ٤١، ٥٠)، علل أحمد (٢/ ٢١٠)، ضعفاء أبى نعيم (ت ٢٣٨)، ضعفاء الدارقطنى (٥٢٩)، المجروحين (١٣١٣)، الكشف الحثيث (ت ٧٦١)، كشف الأستار (٥٤٠. ٨٢٠)، الكامل لابن عدى (٨/ ١١٩)، سير أعلام النبلاء (٩/ ٣٥)."],[11283,"(١) هو: مروان بن شجاع الجزرى الحرانى، أبو عبد الله الأموى مولى محمد بن مروان بن الحكم، نزل بغداد، وهو عم الحضير بن شجاع، ويقال له: الخصيفى لكثرة روايته عن خصيف."],[11284,"انظر: تهذيب الكمال (٢٧ / ت ٥٨٧٤)، تهذيب التهذيب (١٠/ ٩٤)، التاريخ الكبير (٧ / ت ١٥٩٧)، الجرح والتعديل (٨ / ت ١٢٤٩)، الكاشف (٣ / ت ٥٤٦٠)."],[11285,"(٢) هو: محمد بن أبى حميد، ويقال: حماد بن أبى حميد، واسم أبى حميد إبراهيم، مدينى يكنى: أبا إبراهيم الزرقى الأنصارى. قلت: وقد سبق."],[11286,"(٣) هو: محمد بن مسلم بن سوس الطائفى، وقيل: سويس، وقيل: سيس، وقيل: سنين، وقيل: شونير الطائفى يعد فى الكيين."],[11287,"انظر: تهذيب الكمال (٢٦ / ت ٦٥٠٤)، تهذيب التهذيب (٩/ ٤٤٤)، التاريخ الكبير (١/ ت ٧٠٠)، الجرح والعديل (٨/ ت ٣٢٢)، الكاشف (٣ / ت ٥٢٣٣)، ميزان الاعتدال (٤ / ت ٨١٧٢)."],[11288,"(٤) هو: مسلم بن كيسان أبو عبد الله الأعور. وقد سبق."],[11289,"(٥) أظنه السابق، وهو: الضبى الملائى، البراد الكوفى، الأعور، والله أعلم."],[11290,"أبو عبد الله الضبى ضعيف الحديث."],[11291,"٧٦٧ - ومسلمة بن على"],[11292,"(١)"],[11293,"ضعيف الحديث."],[11294,"٧٦٨ - وموسى بن أبى كثير، أبو الصباح"],[11295,"(٢)"],[11296,"يكتب حديثه ولا يحتج به."],[11297,"٧٦٩ - ومحمد بن زياد الطحان"],[11298,"(٣)"],[11299,"ذاهب الحديث."],[11300,"٧٧٠ - والمطلب بن زياد"],[11301,"(٤)"],[11302,"(١) هو: مسلمة بن على بن خلف الخشنى، أبو سعيد الدمشقى البلاطى، كان يسكن البلاط، قرية من قرى دمشق."],[11303,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٥٨)، تهذيب التهذيب (١٠/ ١٤٦)، الكاشف (٣ / ت ٥٥٣٥)، ميزان الاعتدال (٤ / ت ٨٥٢٧)، التاريخ الكبير (٧ / ت ١٦٩٢)، السابق واللاحق (١٧٨)، الكشف الحثيث (ت ٧٦٥)، المعرفة والتاريخ (٢/ ١٩١)، ضعفاء النسائى (ت /٥٧٠)، تاريخ ابن معين رواية الدورى (٢/ ٥٦٥)، رواية الدارمى (ت ٧٥٦)، رواية ابن الجنيد (٣٨٥، ٦٧٥)، ضعفاء ابن الجوزى (٣/ ١٢٠)، لسان الميزان (٧/ ٣٨٧)، الكامل لابن عدى (٨/ ١٢)."],[11304,"(٢) هو: موسى بن أبى كثير الأنصارى، مولاهم، ويقال: الهمدانى، أبو الصباح الكوفى، ويقال: الواسطى المعروف بموسى الكبير، واسم أبى كثير الصباح."],[11305,"انظر: تهذيب الكمال (٢٩ / ت ٦٢٩٤)، تهذيب التهذيب (١٠/ ٣٦٧)، التاريخ الكبير (٧ / ت ١٢٥٤)، الجرح والتعديل (٨ / ت ٦٦٩)، الكاشف (٣ / ت ٥٨٢٣)، ضعفاء ابن الجوزى (٣/ ١٤٨)، تاريخ ابن معين رواية الدورى (٢/ ٥٩٥)، المعرفة والتاريخ (٢/ ٦٥٦)، علل أحمد (١/ ١٥٣)، تاريخ أسماء الثقات (١٣٥٣)، طبقات ابن سعد (٦/ ٣٣٩)."],[11306,"(٣) هو: محمد بن زياد الطحان الكوفى اليشكرى، ويقال: الجندى الأعور الفأفاء، المعروف بالميمونى الرقى."],[11307,"انظر: تهذيب التهذيب (٩/ ١٧١)، التاريخ الكبير (١/ ٨٣)، الكامل لابن عدى (٧/ ٢٩٦)، ديوان الضعفاء (٣٧١٨)، تهذيب الكمال (٢٥ / ت ٥٢٢٤)، الكاشف (٣ / ت ٤٩٢٧)، ميزان الاعتدال (٣ / ت ٧٥٤٧)، الأنساب (١٢/ ٥٣٥)، لسان الميزان (٧/ ٣٥٨)، المغنى (٢ / ت"],[11308,"(٤) هو: المطلب بن زياد بن أبى زهير الثقفى، ويقال: القرشى، مولاهم الكوفى."],[11309,"يكتب حديثه ولا يحتج به."],[11310,"٧٧١ - ومنصور بن أبى الأسود"],[11311,"(١)"],[11312,"يكتب حديثه ولا يحتج به."],[11313,"٧٧٢ - ومحمد بن سابق"],[11314,"(٢)"],[11315,"صاحب مالك بن مغول، يكتب حديثه ولا يحتج به."],[11316,"٧٧٣ - ومحمد بن حميد الرازى"],[11317,"(٣)"],[11318,"ضعيف الحديث."],[11319,"٧٧٤ - ومحمد بن حجاج اللخمى"],[11320,"(٤)"],[11321,"= انظر: تهذيب الكمال (٢٨ / ت ٦٠٠٥)، تهذيب التهذيب (١٠/ ١٧٧)، الكاشف (٣ / ت ٥٥٧٦)، ميزان الاعتدال (٤ / ت ٨٥٩١)، لسان الميزان (٧/ ٣٩٠)، البداية والنهاية (١٠/ ١٨٦)، ضعفاء ابن الجوزى (٣/ ١٢٥)، علل أحمد (١/ ٢٤)، تاريخ ابن معين رواية الدورى (٢/ ٥٧٠)، طبقات ابن سعد (٦/ ٣٨٧)، سير أعلام النبلاء (٨/ ٣٣٢)، معرفة الثقات (٨/ ١٦٤٧)، معجم الثقات (١٢١)، الكامل لابن عدى (٨/ ٢٢٥)."],[11322,"(١) هو: منصور بن أبى الأسود الليثي الكوفى، يقال اسم أبيه: حازم."],[11323,"انظر: تهذيب الكمال (٢٨ / ت ٦١٨٩)، تهذيب التهذيب (١٠/ ٣٠٥)، ميزان الاعتدال (٤ / ت ٨٧٧٠) الكاشف (٣ / ت ٥٧٣١)، الجرح والتعديل (٨ / ت ٧٥٤)، التاريخ الكبير (٧ / ت ١٥٠٠)."],[11324,"(٢) هو: محمد بن سابق التميمى، مولاهم، أبو جعفر، ويقال: أبو سعيد البزار الكوفى، أصله من فارس، ثم سكن بغداد."],[11325,"انظر: تهذيب الكمال (٢٥ / ت ٥٢٣٠)، تهذيب التهذيب (٩/ ١٧٤)، التاريخ الكبير (١ / ت ٣١٦)، الجرح والتعديل (٧ / ت ١٥٢٨)، الكاشف (٣ / ت ٤٩٣٣)، ميزان الاعتدال (٣ / ت ٧٥٦٨)."],[11326,"(٣) هو: محمد بن حميد بن حيان التميمى الحافظ، أبو عبد الله الرازى."],[11327,"انظر: تهذيب الكمال (٢٥ / ت ٥١٦٧)، تهذيب التهذيب (١٢٧١٩)، التاريخ الكبير (١ / ت ١٦٧)، الجرح والتعديل (٧ / ت ١٢٧٥)، الكاشف (٣ / ت ٤٨٧٩)، ميزان الاعتدال (٣ / ت ٧٤٥٣)، سير أعلام النبلاء (١/ ٥٠٣)، تاريخ بغداد (٢/ ٢٥٩)، تاريخ أسماء الثقات (١٢٥٤)، الكامل لابن عدى (٧/ ٥٢٩)."],[11328,"(٤) هو: محمد بن الحجاج اللخمى الواسطى، صاحب الهريسة، يكنى: أبا إبراهيم."],[11329,"انظر: الكامل لابن عدى (١٧/ ٣٢٤)، الضعفاء والمتروكين (٣/ ٤٨)، الجرح والتعديل = عن مجالد، كذاب."],[11330,"٧٧٥ - محمد بن سالم"],[11331,"(١)"],[11332,"قال: وسمعت نعيم بن حماد يقول: رأيت ابن المبارك يقول: اطرح حديث محمد بن سالم."],[11333,"٧٧٦ - وميسرة بن عبد ربه"],[11334,"(٢)"],[11335,"قال: وميسرة بن عبد ربه كذاب يفتعل الحديث تسترى."],[11336,"٧٧٧ - والمنكدر بن محمد بن المنكدر"],[11337,"(٣)"],[11338,"رجل صالح يكتب حديثه ولا يحتج به، ولم يكن بالحافظ."],[11339,"٧٧٨ - ويوسف بن محمد بن المنكدر"],[11340,"(٤)"],[11341,"شبيه بأخيه."],[11342,"٧٧٩ - ومحمد بن عبد الله ابن أخى الزهرى"],[11343,"(٥)"],[11344,"يكتب حديثه وليس بالقوى."],[11345,"= (٧/ ٢٣٤)، الضعفاء الكبير (٤/ ٤٤)، الأنساب (١١/ ٢١٤)، المجروحين (٢/ ٢٩٥)، ديوان الضعفاء (٣٦٤٢)، لسان الميزان (٥/ ١١٦، ١١٩)، الكشف الحثيث (٣٥٨)، ميزان الاعتدال (٣/ ٥٠٩)، تاريخ بغداد (٢/ ٢٧٩)، الضعفاء والمتروكين للدارقطنى (٤٩٠)، المغنى (٢ / ت ٥٣٨٥)."],[11346,"(١) هو: محمد بن سالم الهمدانى، أبو سهل الكوفى. وقد سبق."],[11347,"(٢) هو: ميسرة بن عبد ربه التسترى."],[11348,"انظر: الكامل لابن عدى (٨/ ١٧٩)، الضعفاء والمتروكين (٣/ ١٥١)، الجرح والتعديل (٨/ ٢٥٤)، المغنى (٢ / ت ٦٥٥٤)، ميزان الاعتدال (٤/ ٢٣٠)، لسان الميزان (٦/ ١٣٨)، المجروحين (١/ ١٢١)، ديوان الضعفاء (٤٣٢١)."],[11349,"(٣) هو: المنكدر بن محمد بن المنكدر القرشى، التيمى، المدنى. قلت: وقد سبق."],[11350,"(٤) هو: يوسف بن محمد بن المنكدر التيمى."],[11351,"انظر: تهذيب الكمال (٣٢ / ت ٧١٥٣)، تهذيب التهذيب (١١/ ٤٢٢)، الجرح والتعديل (٩ / ت ٩٦٠)، الكاشف (٣/ ٦٥٥٩)، ميزان الاعتدال (٤ / ت ٩٨٨٤)، التاريخ الكبير (٨ / ت ٣٣٩٦)، الكامل لابن عدى (٨/ ٤٨٣)، لسان الميزان (٧/ ٤٤٨)، المجروحين (٣/ ١٣٥)، المغنى (٢ / ت ٧٢٤٩)."],[11352,"(٥) سبق."],[11353,"٧٨٠ - ومطرف (١) الإسكاف (٢)"],[11354,"الذى يحدث عنه عبد الله منكر الحديث، كوفى لا يكتب حديثه."],[11355,"٧٨١ - ومسلم بن خالد الزنجى"],[11356,"(٣)"],[11357,"مولى بنى مخزوم يكتب حديثه ولا يحتج به."],[11358,"٧٨٢ - محمد بن فضاء"],[11359,"(٤)"],[11360,"ابن أبى خيثمة، قال: وسمعت يحيى بن معين، يقول: محمد بن فضاء ليس حديثه"],[11361,"بشئ."],[11362,"(١) كذا بالمخطوط، وهو تصحيف والصواب \"مطر\"."],[11363,"(٢) هو: مطر بن ميمون المحاربى، وهو ابن أبى مطر الإسكاف، أبو خالد."],[11364,"انظر: تهذيب الكمال (٢٨ / ت ٥٩٩٨)، تهذيب التهذيب (١٠/ ١٧٠)، الجرح والتعديل (٨ / ت ١٣١٧)، الكاشف (٣ / ت ٥٥٦٩)، ميزان الاعتدال (٤ / ت ٨٥٩٠)، التاريخ الكبير (٧ / ت ١٧٥٨)، الكامل لابن عدى (٨/ ١٣٤)، تاريخ ابن معين، رواية الدورى (٢/ ٥٦٨)، علل أحمد (١/ ١٢١)، علل ابن المدينى (٥٦)، الكنى للدولابى (١/ ١٧٥)، تاريخ الإسلام (٥/ ١٦٤)، ديوان الضعفاء (ت ٤١٥٠)، معرفة الثقات (١٧٣٦)، طبقات ابن سعد (٧/ ٢٥٤)، تاريخ خليفة (٣٨٩)، سير أعلام النبلاء (٥/ ٤٥٢)."],[11365,"(٣) هو: مسلم بن خالد بن قرقرة، ويقال: ابن جرجرة المخزومى، مولاهم، أبو خالد الزنجى المكى الفقيه."],[11366,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٢٥)، تهذيب التهذيب (١٠/ ١٢٨)، ميزان الاعتدال (٤/ ٨٤٨٥)، الجرح والتعديل (٨ / ت ٨٠٠)، الكاشف (٣ / ت ٥٥٠٦)، الكامل لابن عدى (٦١٨)، تاريخ ابن معين رواية الدورى (٢/ ٥٦١)، الدارمى (٣٦٤)، ابن محرز (٢٩٤)، طبقات خليفة (٢٨٤)، علل أحمد (١/ ٣٠٢)، المعرفة والتاريخ (٣/ ٥١)، تاريخ واسط (٢٤٨)، ضعفاء النسائى (٥٦٩)، طبقات ابن سعد (٥/ ٤٩٩)، طبقات الحفاظ (١٠٩)، المغنى (٢ / ت ٦٢٠٦)، تاريخ أسماء الثقات (١٣٩٤)، تراجم الأحبار (٣/ ٣٩٥)."],[11367,"(٤) هو: محمد بن فضاء بن خالد الأزدى الجهضمى، أبو بحر البصرى، معبر الرؤيا."],[11368,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٤٤)، تهذيب التهذيب (٩/ ٤٠٠)، الكاشف (٣ / ت ٥١٩١)، ميزان الاعتدال (٤ / ت ٨٠٥٤)، الجرح والتعديل (٨ / ت ٢٦١)، التاريخ الكبير (١/ ت ٦٥٩)، تاريخ ابن معين (٢/ ٥٣٣)، لسان الميزان (٧/ ٣٧١)، المشتبه (٥٠٨)، الكامل لابن عدى (٧/ ٣٦٧)، المجروحين (٢/ ٢٧٤)، الضعفاء والمتروكين (١٩١٣)، الضعفاء الكبير (٤/ ١٢٥)."],[11369,"٧٨٣ - موسى بن وردان"],[11370,"(١)"],[11371,"قال: وسمعته يقول: موسى بن وردان قاصّ كان يكون بمصر ضعيف."],[11372,"٧٨٤ - موسى بن فردى"],[11373,"(٢)"],[11374,"قال: وسمعته يقول: موسى بن فردى، كوفى، وما سمعت أحدًا يحدث عنه إلا الأشجعى."],[11375,"٧٨٥ - محمد بن معاوية النيسابورى"],[11376,"(٣)"],[11377,"قال: وسمعته يقول: محمد بن معاوية النيسابورى كذاب."],[11378,"٧٨٦ - محمد بن أبى قيس الدمشقى"],[11379,"(٤)"],[11380,"أبو حاتم الرازى، قال: صُلِبَ محمد بن أبى قيس الدمشقى فى الزندقة."],[11381,"قال: ومنهم من يقول: أبو عبد الرحمن الشامى، ومنهم من يقول: أبو عبد الرحمن"],[11382,"الأزدى."],[11383,"٧٨٧ - ومحمد بن فضيل بن غزوان"],[11384,"(٥)"],[11385,"(١) هو: موسى بن وردان القرشى، العامرى، مولاهم، أبو عمر المصرى القاص، المدنى الأصل."],[11386,"انظر: تهذيب الكمال (٢٩ / ت ٦٣١٢)، التاريخ الكبير (٧ / ت ١٢٦٧)، الجرح والتعديل (٨ / ت ٨٣٣)، الكاشف (٣ / ت ٥٨٣٧)، ميزان الاعتدال (٤ / ت ٨٩٣٩)، تهذيب التهذيب (١٠/ ٣٧٦)، الكامل لابن عدى (٨/ ٦٣)، تاريخ ابن معين، رواية الدورى (٢/ ٥٩٦)، الدارمى (٧٨٥)، ضعفاء ابن الجوزى (٣/ ١٥٠)، لسان الميزان (٧/ ٤٠٥)، شذرات الذهب (١/ ١٥٤)، كشف الأستار (١٤٥٣)، المعرفة والتاريخ (٢/ ٤٥٩)، معرفة الثقات (١٨٢٤)، المجروحين (٢/ ٢٣٩)، تاريخ الإسلام (٥/ ٧)، تاريخ أسماء الثقات (١٣٥٩)."],[11387,"(٢) لم أقف عليه."],[11388,"(٣) هو: محمد بن معاوية بن أعين النيسابورى، أبو على، سكن بغداد، ثم مكة. انظر: تهذيب الكمال (٢٦ / ت ٥٦١٨)، تهذيب التهذيب (٩/ ٤٦٥)، ميزان الاعتدال (٤ / ت ٨١٨٨)، التاريخ الكبير (١/ ت ٧٧٩)، الجرح والتعديل (٨ / ت ٤٤٣)، الوافى بالوفيات (٥/ ٤١)، تاريخ بغداد (٣/ ٢٧٠، ٣٧٠)، المغنى (٢ / ت ٥٩٨٩)، المجروحين (٢/ ٢٩٨)، الكامل لابن عدى (٧/ ٥٣٣)."],[11389,"(٤) لم أقف عليه."],[11390,"(٥) هو: محمد بن فضيل بن غزوان بن جرير الضبى، مولاهم، أبو عبد الرحمن الكوفى."],[11391,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٤٨)، تهذيب التهذيب (٩/ ٤٠٥)، التاريخ الكبير = قال: ومحمد بن فضيل بن غزوان كثير الخطأ."],[11392,"٧٨٨ - محمد بن جابر"],[11393,"(١)"],[11394,"ابن أبى خيثمة، قال: سمعت يحيى يقول: محمد بن جابر ليس حديثه بشئ."],[11395,"٧٨٩ - مرجى بن رجاء"],[11396,"(٢)"],[11397,"قال: وسمعته يقول: مرجّى بن رجاء، ليس حديثه بشئ."],[11398,"٧٩٠ - محمد بن راشد"],[11399,"(٣)"],[11400,"ميمون بن غيلان، حدثنا أبو النضر، قال: كنت أوضى شعبة بباب مسجد الرصافة، فمرّ محمد بن راشد، فقال لى شعبة: سمعت من هذا شيئًا؟ ."],[11401,"قلت: نعم حديث كذا وحديث كذا. قال: أما إنه معتزلى رافضى جسمى."],[11402,"٧٩١ - محمد بن جابر"],[11403,"(٤)"],[11404,"= (١ / ت ٦٥٢)، الجرح والتعديل (٨ / ت ٢٦٣)، الكاشف (٣ / ت ٥١٩٤)، ميزان الإعتدال (٤ / ت ٨٠٦٢)، المغنى (٢ / ت ٥٩١٠)، لسان الميزان (٧/ ٣٧٢)، طبقات ابن سعد (٦/ ٢٧١)."],[11405,"(١) هو: محمد بن جابر بن سيار بن طلق السحيمى، الحنفى، أبو عبد الله اليمامى، أصله كوفى، وكان أعمى."],[11406,"انظر: تهذيب الكمال (٢٤ / ت ٥١١٠)، تهذيب التهذيب (٩/ ٨٨)، الكاشف (٣ / ت ٤٨٣٠)، ميزان الاعتدال (٣ / ت ٧٣٠١)، التاريخ الكبير (١ / ت ١١١)، الوافى بالوفيات (٢/ ٢٨٢)، طبقات ابن سعد (٦/ ١٧٠)، سير أعلام النبلاء (٨/ ٢٣٨)، تراجم الأحبار (٤/ ٣٤)، لسان الميزان (٧/ ٣٥٣)، المغنى (٢ / ت ٥٣٤٩)، المجروحين (٢/ ٢٧٠)، الكامل لابن عدى (٧/ ٣٢٨)."],[11407,"(٢) هو: مرجى بن رجاء اليشكرى، ويقال: العدوى، أبو رجاء البصرى."],[11408,"انظر: تهذيب الكمال (٢٧ / ت ٥٨٥٣)، تهذيب التهذيب (١٠/ ٨٣)، الكاشف (٣ / ت ٥٤٤٥)، ميزان الاعتدال (٤ / ت ٨٤١١)، الجرح والتعديل (٨ / ت ١٨٨٢)، التاريخ الكبير (٨ / ت ٢١٥٤، ٢٢٠٨)، الكامل لابن عدى (٨/ ٢٠٢)، حاشية الإكمال (٣/ ٣٨٥)، المغنى (٢ / ت ٦١٥٦)، لسان الميزان (٨/ ٤١٢)."],[11409,"(٣) هو: محمد بن راشد المكحولى الخزاعى الدمشقى، أبو عبد الله، ويقال: أبو يحيى."],[11410,"انظر: تهذيب الكمال (٢٥ / ت ٥٢٠٨)، تهذيب التهذيب (٩/ ١٥٨)، الجرح والتعديل (٧ / ت ١٣٨٥)، التاريخ الكبير (١ / ت ٢١٢)، تاريخ أسماء الثقات (٨/ ١٢)، الكاشف (٣/ ٤٢)، المغنى (٢ / ت ٥٤٨٩)، الكامل لابن عدى (٧/ ٤١٨)."],[11411,"(٤) سبق."],[11412,"يحيى بن معين قال: كان محمد بن جابر كوفى أعمى، قال: قلت له: فإنما حديثه كذا، لأنه أعمى؟ . قال: لا، ولكن عمى واختلط عليه."],[11413,"٧٩٢ - ومحمد بن عبيد الله"],[11414,"(١)"],[11415,"أضعف من جابر الجعفى."],[11416,"ضعيف الحديث."],[11417,"٧٩٣ - والمنهال بن خليفة"],[11418,"(٢)"],[11419,"ضعيف الحديث."],[11420,"٧٩٤ - محمد بن القاسم"],[11421,"(٣)"],[11422,"وذكر محمد بن القاسم الأسدى فلم يرضه."],[11423,"٧٩٥ - ومحمد بن فضالة"],[11424,"(٤)"],[11425,"قال: ومحمد بن فضالة ليس بشئ."],[11426,"٧٩٦ - ومحمد بن درهم"],[11427,"(٥)"],[11428,"(١) هو: محمد بن عبيد الله بن أبى سليمان العرزمى الفزارى، أبو عبد الرحمن الكوفى."],[11429,"انظر: تهذيب الكمال (٢٦ / ت ٥٤٣٤)، تهذيب التهذيب (٩/ ٣٢٢)، الجرح والتعديل (٨ / ت ٥)، الكاشف (٣ / ت ٥٠٩٩)، التاريخ الكبير (١ / ت ٥١٣)، ضعفاء ابن الجوزى (٣/ ٨٣)، معرفة الثقات (١٦٢٣)، تراجم الأحبار (٤/ ٨٥)، لسان الميزان (٧/ ٣٦٨)، تاريخ الثقات (٤٠٩)، الكامل لابن عدى (٧/ ٢٤٥)."],[11430,"(٢) هو: المنهال بن خليفة العجلى، أبو قدامة الكوفى."],[11431,"انظر: تهذيب الكمال (٢٨ / ت ٦٢٠٩)، التاريخ الكبير (٨ / ت ١٩٦٤)، الجرح والتعديل (٨ / ت ١٦٣٧)، الكاشف (٣ / ت ٥٧٤٦)، تهذيب التهذيب (١٠/ ٣١٨)، تاريخ الإسلام (٦/ ٣٠٧)، لسان الميزان (٧/ ٤٠٠)، تراجم الأحبار (٣/ ٣٠)، تاريخ ابن معين رواية الدورى (٢/ ٥٩٠)، الدارمى (٨٢٠)، تاريخ أسماء الثقات (١٤١١)، الكامل لابن عدى (٨/ ٤٠)."],[11432,"(٣) هو: محمد بن القاسم الأسدى، أبو إبراهيم الكوفى الشامى الأصل، قيل: إن لقبه كاو."],[11433,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٥٠)، تهذيب التهذيب (٩/ ٤٠٧)، الكاشف (٣ / ت ٥١٦٦)، ميزان الاعتدال (٤ / ت ٤٠٦٦)، التاريخ الكبير (١/ ت ٦٧٢)، لسان الميزان (٧/ ٣٧٢)، الكامل لابن عدى (٧/ ٤٩١)."],[11434,"(٤) لم أقف عليه، ولعله محمد بن فخماء بن خالد الجهضمى. وقد سبق."],[11435,"(٥) محمد بن درهم العبسى، مولى بنى هاشم.="],[11436,"الذى يروى عنه شبابة ليس بشئ."],[11437,"٧٩٧ - ومحمد بن ثابت العبدى"],[11438,"(١)"],[11439,"٧٩٨ - ومحمد بن ثابت البنانى"],[11440,"(٢)"],[11441,"ليس بشئ."],[11442,"٧٩٩ - ومهدى بن هلال"],[11443,"(٣)"],[11444,"كذاب."],[11445,"٨٠٠ - ومثنى بن سعيد"],[11446,"(٤)"],[11447,"= انظر: ميزان الاعتدال (٣ / ت ٧٥٠٣)، الكامل لابن عدى (٧/ ٤١٥)، المغنى (٢ / ت ٥٤٨٦)، الجرح والتعديل (٧ / ت ١٣٦٦)، ديوان الضعفاء (٣٦٩٦)، التاريخ الكبير (١/ ٧٧)، المجروحين (٢/ ٢٥٨)، لسان الميزان (١٦٢١٥)، تاريخ بغداد (٥/ ٢٦٨)، دائرة معارف الأعلمى (٢٦/ ٢٦٣)، الضعفاء والمتروكين (٣/ ٥٧)، الضعفاء الكبير (٤/ ٦٢)."],[11448,"(١) هو: محمد بن ثابت العبدى أبو عبد الله البصرى."],[11449,"انظر: تهذيب الكمال (٢٤ / ت ٥١٠٤)، تهذيب التهذيب (٩/ ٨٥)، التاريخ الكبير (١ / ت ١٠٥)، الجرح والتعديل (٧ / ت ١٢٠١)، الكاشف (٣ / ت ٤٨٢٤)، ميزان الاعتدال (٣ / ت ٧٢٩٣)، الكامل لابن عدى (٧/ ٣٠٦)، المجروحين (٢/ ٢٥١)، معرفة الثقات (١٥٧٨)، ضعفاء ابن الجوزى (٣/ ٤٥)، ديوان الضعفاء (٣٦٢٢)، تاريخ أسماء الثقات (١٢٠١)، الإكمال (٧/ ٣٤٨)."],[11450,"(٢) هو: محمد بن ثابت بن أسلم البنانى البصرى."],[11451,"انظر: تهذيب الكمال (٢٤ / ت ٥١٠٠)، تهذيب التهذيب (٩/ ٨٢)، الكاشف (٣ / ت ٤٨٢١)، ميزان الاعتدال (٣ / ت ٧٢٩٤)، التاريخ الكبير (١ / ت ١٠٣)، الجرح والتعديل (٧/ ت ١٢٠٣)."],[11452,"(٣) هو: مهدى بن هلال أبو عبد الله البصرى."],[11453,"انظر: ميزان الاعتدال (٤ / ت ٨٨٢٧)، الضعفاء والمتروكين (٣/ ١٤٣)، الجرح والتعديل (٨/ ٣٣٦)، الضعفاء الكبير (٤/ ٢٢٧)، الكشف الحثيث (٧٨٩)، الكامل لابن عدى (٨/ ٢٢٨)، المغنى (٢ / ت ٦٤٦٧)، لسان الميزان (٦/ ١٠٦)، التاريخ الصغير (٢/ ٢٤٥)."],[11454,"(٤) هو: المثنى بن سعيد الضبعى أبو سعيد البصرى القسام الذارع القصير."],[11455,"انظر: تهذيب الكمال (٢٧٠ / ت ٥٧٧٢)، تهذيب التهذيب (١٠/ ٣٤)، الجرح والتعديل (٨ / ت ١٤٩٣)."],[11456,"٨٠١ - ومحمد بن عثيم"],[11457,"(١)"],[11458,"كذاب."],[11459,"٨٠٢ - ومحمد بن الحارث الحارثى"],[11460,"(٢)"],[11461,"بصرى وليس بشئ."],[11462,"٨٠٣ - ومحمد بن مجيب"],[11463,"(٣)"],[11464,"كان جار عباد بن عوام، وكان كذابًا عدوًا لله."],[11465,"٨٠٤ - وموسى بن دهقان"],[11466,"(٤)"],[11467,"ليس بشئ."],[11468,"قال ابن المدينى: سمعت يحيى بن سعيد ذكر موسى بن الدهقان، فقال: أفسدوه بآخره."],[11469,"(١) هو: محمد بن عثيم بمهملة ومثلثة ومصغرًا، من أهل نجران، يكنى أبا ذر."],[11470,"انظر: تعحيل المنفعة (٩٥٩)، التاريخ الكبير (١/ ٢٠٥)، الجرح والتعديل (٨/ ١٠١)، لسان الميزان (٥/ ٢٨٢)، المغنى (٢ / ت ٥٨١٥)، الإكمال (٦/ ١٣٨)، ضعفاء ابن الجوزى (٣/ ٨٥)، الكامل لابن عدى (٧/ ٤٧٩)."],[11471,"(٢) هو: محمد بن الحارث بن زياد بن الربيع الهاشمى الحارثى أبو عبد الله."],[11472,"انظر: تهذيب الكمال (٢٥ / ت ٥١٣٠)، التاريخ الكبير (١/ ت ١٤٧)، الجرح والتعديل (٧ / ت ١٢٧٠)، الكاشف (٣ / ت ٤٨٥٠)، ميزان الاعتدال (٣ / ت ٧٣٣٥)، تهذيب التهذيب (٩/ ١٠٥)، الكامل لابن عدى (٧/ ٣٧٨)، تاريخ أسماء الثقات (١٢٥٨)، المجروحين (٢/ ٢٩٣)."],[11473,"(٣) هو: محمد بن مجيب الثقفى الكوفى الصائغ."],[11474,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٨١)، تهذيب التهذيب (٩/ ٤٢٨)، الجرح والتعديل (٨ / ت ٤١٥)، ميزان الاعتدال (٤ / ت ٨١١٦)، تصحيفات المحدثين (١٠٧٤)، تاريخ ابن معين (٣/ ٥٣٧)، تبصير المنتبه (٤/ ٢٦١)، المشتبه (٥٧٥)، المغنى (٢ / ت ٥٩٣٩)، تاريخ بغداد (٣/ ٢٩٧)، الكامل لابن عدى (٧/ ٥١١)."],[11475,"(٤) هو: موسى بن دهقان البصرى."],[11476,"انظر: تهذيب الكمال (٢٩ / ت ٦٢٥٢)، التاريخ الكبير (٧ / ت ١١٩٨)، الجرح والتعديل (٨ / ت ٦٣٨)، تهذيب التهذيب (١٠/ ٣٤٤)، تاريخ ابن معين رواية الدورى (٢/ ٥٩٢)، ابن محرز (ت ١٦٨)، أبو زرعة الرازى (٦٥٨)، المجروحين (٢/ ٢٣٩)، الضعفاء الكبير (٤/ ١٥٧)، تاريخ الإسلام (٦/ ٣٠٨)، ديوان الضعفاء (٤٢٧٧)، طبقات ابن سعد (٥/ ٧٧)، لسان الميزان (٧/ ٤٠٢)، الذيل على الكاشف (١٥٤١)، الكامل لابن عدى (٨/ ٥٠)."],[11477,"٨٠٥ - محمد بن الفضل"],[11478,"(١)"],[11479,"قال ابن معين: ومحمد بن الفضل بن عطية ليس بشئ."],[11480,"٨٠٦ - ومحمد بن الفضل الخراسانى"],[11481,"(٢)"],[11482,"ليس بثقة وأبوه ثقة."],[11483,"٨٠٧ - ومحمد بن الحجاج الواسطى"],[11484,"(٣)"],[11485,"ليس بثقة. كان ينزل فصيل الكرخ."],[11486,"٨٠٨ - ومحمد بن الحجاج المصفر"],[11487,"(٤)"],[11488,"ليس بثقة."],[11489,"٨٠٩ - ومحمد بن سعيد بن أبى سعيد"],[11490,"(٥)"],[11491,"ليس حديثه بشئ."],[11492,"٨١٠ - ومعان بن رفاعة"],[11493,"(٦)"],[11494,"(١) هو: محمد بن الفضل بن عطية بن عمر بن خالد العبسى مولاهم، أبو عبد الله الكوفى، ويقال: المروزي، سكن بخارى، خراسانى."],[11495,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٤٦)، تهذيب التهذيب (٩/ ٤٠١)، الكاشف (٣ / ت ٥١٩٢)، تاريخ بغداد (٣/ ١٤٧)، الأنساب (٨/ ٨١)، المغنى (٢ / ت ٥٩٠٣)، المشتبه (٥١٨)، تنقيح المقال (١١٢٣٥)، جامع الرواة (٢/ ١٧٣)، أحوال الرجال (٣٧٢)، المجروحين (٢/ ٢٧٨)، لسان الميزان (٧/ ٣٧)، الكامل لابن عدى (٧/ ٣٢٥)."],[11496,"(٢) انظر الترجمة السابقة."],[11497,"(٣) سبق برقم (٧٧٤)."],[11498,"(٤) هو: محمد بن الحجاج المصفر أبو عبد الله البغدادى."],[11499,"انظر: تاريخ بغداد (٢/ ٢٨٢)، الضعفاء والمتروكين للدارقطنى (٤٥٩)، المجروحين (٢/ ٢٩٦)، ديوان الضعفاء (٣٦٤٣)، الأنساب (٢/ ٢٩٤)، لسان الميزان (٥/ ١١٧)، الضعفاء والمتروكين للنسائى (٥٣٤)، المغنى (٢ / ت ٥٣٨٦)، الكامل لابن عدى (٧/ ٣٢٧)."],[11500,"(٥) لعله محمد بن سعيد بن أبى سعيد المقبرى."],[11501,"انظر: ضعفاء ابن الجوزى (٣/ ٦٤)، ديوان الضعفاء (٣٧٣٤)، دائرة معارف الأعلمى (٢٦/ ٢٧٥)، ميزان الاعتدال (٣/ ٥٦٤)، لسان الميزان (٥/ ١٧٦)، المغنى (٢ / ت ٥٥٦٠)، الكامل لابن عدى (٧/ ٣٢١)، الضعفاء والمتروكين (٣/ ٦٤١)."],[11502,"(٦) هو: معان بن رفاعة السلامى، أبو محمد الدمشقى، ويقال: الحمصى."],[11503,"انظر: تهذيب الكمال (٢٨ / ت ٦٠٤٣)، تهذيب التهذيب (١٠/ ٢٠١)، التاريخ الكبير= ضعيف."],[11504,"٨١١ - ومسلمة الشامى"],[11505,"(١)"],[11506,"ليس بشئ، وهو مسلمة بن على الخشنى."],[11507,"٨١٢ - ومحمد بن عبد الرحمن بن مجبر"],[11508,"(٢)"],[11509,"ليس بشئ."],[11510,"٨١٣ - ومنصور بن دينار"],[11511,"(٣)"],[11512,"ضعيف الحديث، روى عنه وكيع."],[11513,"٨١٤ - محمد بن عبد العزيز بن عمر بن عبد الرحمن بن عوف"],[11514,"(٤)"],[11515,"= (٨ / ت ٢١٩٤)، الجرح والتعديل (٨ / ت ١٩١٩)، الكاشف (٣ / ت ٥٦٠٨)، ميزان الاعتدال (٤/ ١٣٤)، لسان الميزان (٧/ ٣٩١)، المغنى (٢ / ت ٦٣١٠)."],[11516,"(١) هو: محمد بن على بن خلف الخشنى أبو سعيد الدمشقى البلاطى كان يسكن البلاط قرية من قرى دمشق."],[11517,"انظر: تهذيب الكمال (٢٧ / ت ٥٩٥٠٨)، تهذيب التهذيب (١٠/ ١٤٦)، الجرح والتعديل (٨ /ت ١٢٢٢)، الكاشف (٣ / ت ٥٥٣٥)، ميزان الاعتدال (٤ / ت ٨٥٢٧)، المغنى (٢ / ت ٦٢٣٩)، لسان الميزان (٧/ ٣٨٧)."],[11518,"(٢) هو: محمد بن عبد الرحمن بن مجبر بن عبد الرحمن بن عمر بن الخطاب المدينى."],[11519,"انظر: تعجيل المنفعة (٩٥٣)، الجرح والتعديل (٧ / ت ١٧٣٠)، المغنى (٢ / ت ٥٧٣٥)، لسان الميزان (٥/ ٢٤٥)، ضعفاء ابن الجوزى (٣/ ٧٧)، الإكمال (٧/ ٢٠٨)، تراجم الأحبار (٤/ ١١٦)، المشتبه (٥٧١)، الذيل على الكاشف (٣٦٦، ٧٨٤٤)، الكامل لابن عدى (٧/ ٣٩٨)."],[11520,"(٣) هو: منصور بن دينار التميمى الضبى."],[11521,"انظر: تاريخ الإسلام (٦/ ١٣٢)، الكامل لابن عدى (٨/ ١٢٩)، الجرح والتعديل (٨/ ١٧١)، التاريخ الكبير (٧/ ٣٤٧)، ميزان الاعتدال (٤ / ت ٨٧٧٥)، الثقات (٧/ ٤٧٧)، المغنى (٢ / ت ٧/ ٣٩٨)."],[11522,"(٤) هو: محمد بن عبد العزيز بن عمر بن عبد الرحمن بن عوف الزهرى القرشى المدينى."],[11523,"انظر: الضعفاء والمتروكين (٣/ ٧٧)، الجرح والتعديل (٧/ ٨)، الضعفاء الكبير (٤/ ١٠٤)، الكامل لابن عدى (٧/ ٢٧٨)، المجروحين (٢/ ٢٦٣)، التحفة اللطيفة (٣/ ٦٤٧)، تاريخ بغداد (٢/ ٣٤٩)، ميزان الاعتدال (٣/ ٦٢٨)، لسان الميزان (٥/ ٢٥٩)، ديوان الضعفاء (٣٨٤)، جامع الرواة (٢/ ١٣٩)، المغنى (٢/ ت ٥٧٧٠)."],[11524,"قال ابن إسماعيل: هو منكر الحديث وبمشورته جلد مالك."],[11525,"٨١٥ - محمد بن عبيد الله بن أبى رافع"],[11526,"(١)"],[11527,"مولى النبى - صلى الله عليه وآله وسلم -، قال ابن إسماعيل: هو منكر الحديث."],[11528,"٨١٦ - محمد بن عبيد الله العرزمى"],[11529,"(٢)"],[11530,"قال ابن إسماعيل: تركه ابن المبارك ويحيى."],[11531,"٨١٧ - ومحمد بن فرات الكوفى"],[11532,"(٣)"],[11533,"قال ابن إسماعيل: إنه منكر الحديث، وقال: هو أبو على التميمى."],[11534,"٨١٨ - محمد بن كثير"],[11535,"(٤)"],[11536,"أبو يوسف المصيصى، قال ابن إسماعيل: إنّ أحمد ضعفه، وقال: بعث إلى اليمن فأتى بكتاب معمر فأخذه ورواه."],[11537,"٨١٩ - محمد بن المحرم"],[11538,"(٥)"],[11539,"روى عن عطاء والحسن، قال ابن إسماعيل: هو منكر الحديث."],[11540,"٨٢٠ - محمد بن عبد الله بن عبيد الله بن عمير"],[11541,"(٦)"],[11542,"(١) هو: محمد بن عبيد الله بن أبى رافع الهاشمى مولاهم الكوفى."],[11543,"انظر: تهذيب الكمال (٢٦ / ت ٥٤٣٢)، تهذيب التهذيب (٩/ ٣٢١)، ميزان الاعتدال (٣ / ت ٧٩٠٤)، الكاشف (٣ / ت ٥٠٩٧)، الجرح والتعديل (٨ / ت ٦)، المغنى (٢ / ت ٥٧٩٠)، تاريخ أسماء الثقات (٩٥٢)، تاريخ الإسلام (٦/ ١٢٤)، ضعفاء ابن الجوزى (٣/ ٨٣)، الكامل لابن عدى (٧/ ٢٧١)."],[11544,"(٢) و(٣) سبق."],[11545,"(٤) هو: محمد بن كثير بن أبى عطاء الثقفى مولاهم أبو أيوب الصنعانى نزل المصيصة، ويقال: هو من صنعاء دمشق."],[11546,"انظر: تهذيب الكمال (٢٦ / ت ٥٥٧٠)، تهذيب التهذيب (٩/ ٤١٥)، ميزان الاعتدال (٤ / ت ٨١٠٠)، الجرح والتعديل (٨ / ت ٣٠٩)، الكاشف (٣ / ت ٥٢٠٧)، لسان الميزان (٧/ ٣٧٣)، الكامل لابن عدى (٧/ ٥٠٠)."],[11547,"(٥) هو: محمد بن المحرم، ولم ينسب مكى."],[11548,"انظر: الكامل لابن عدى (٧/ ٣٢٢)، لسان الميزان (٥/ ٢١٦)."],[11549,"(٦) سبق."],[11550,"قال السباك، قال عبيد الله، عن يحيى: محمد بن عبد الله بن عبيد بن عمير تُركَ حديثه."],[11551,"حرف \"ن\""],[11552,"\""],[11553,"٨٢١ - ناصح الكوفى"],[11554,"(١)"],[11555,"قال: ناصح الكوفى صاحب سماك ليس بثقة."],[11556,"٨٢٢ - والنضر بن إسماعيل البجلى"],[11557,"(٢)"],[11558,"ليس بشئ."],[11559,"٨٢٣ - ونوح بن دراج"],[11560,"(٣)"],[11561,"ليس بشئ."],[11562,"٨٢٤ - ونهشل"],[11563,"(٤)"],[11564,"(١) هو: ناصح بن عبد الله، ويقال: ابن عبد الرحمن التميمى المحملى، أبو عبد الله الحائك الكوفى. انظر: تهذيب الكمال (٢٩ / ت ٦٣٥٤)، تهذيب التهذيب (٤٠٢٨٠)، التاريخ الكبير (٨ / ت ٢٤٢٥)، الجرح والتعديل (٨ / ت ٢٣٠٣)، الكاشف (٣ / ت ٥٨٧٢)، ميزان الاعتدال (٤ / ت ٨٩٨٨)، المعرفة والتاريخ (٣/ ٤٥)، كشف الأستار (٦٤٩، ٨١١)، تاريخ الإسلام (٦/ ٣٠٩)، ضعفاء ابن الجوزى (٣/ ١٥٥)، تاريخ ابن معين رواية الدورى (٢/ ٦٠١)، الأنساب (١٢/ ١١٩)، لسان الميزان (٧/ ٤٠٧)، الإكمال (٧/ ٣٢٩)، الكامل لابن عدى (٨/ ٣٠٢)."],[11565,"(٢) هو: النضر بن إسماعيل بن حازم البجلى أبو المغيرة القاص الكوفى إمام مسجدها."],[11566,"انظر: تهذيب الكمال (٢٩ / ت ٦٤١٦)، تهذيب التهذيب (١٠/ ٤٣٤)، ميزان الاعتدال (٤ / ت ٩٠٥٧)، التاريخ الكبير (٨ / ت ٢٢٩٨)، الكاشف (٣/ ٥٩٢٥)، الجرح والتعديل (٨ / ت ٢١٧٧)، سؤالات البرقانى للدارقطنى (ت ٥٢٠)، تاريخ ابن معين (٢/ ٦٠٥)، المجروحين (٣/ ٥١)، تاريخ بغداد (١١٣/ ٤٣١)، الإكمال (٧/ ٣٤٣)، لسان الميزان (٧/ ٤١٠)، علل أحمد (٢/ ٧٤)."],[11567,"(٣) هو: نوح بن دراج النخعى مولاهم أبو محمد الكوفى القاضى."],[11568,"انظر: تهذيب الكمال (٣ / ت ٦٤٩٠)، تهذيب التهذيب (١٠/ ٤٨٣)، ميزان الاعتدال (٤ / ت ٩١٣٣)، التاريخ الكبير (٨ / ت ٢٣٨٦)، الجرح والتعديل (٨ / ت ٢٢١٣)، الكامل لابن عدى (٨/ ٢٩٩)، تاريخ ابن معين رواية الدورى (٢/ ٦١١)."],[11569,"(٤) هو.: نهشل بن سعيد بن وردان الوردانى أبو سعيد، ويقال: أبو عبد الله الخراسانى ="],[11570,"ليس بشئ، روى عنه ابن نمير."],[11571,"٨٢٥ - والنضر بن مطرف"],[11572,"(١)"],[11573,"كوفى ضعيف، روى عنه الفزارى."],[11574,"٨٢٦ - والنهاس بن قهم"],[11575,"(٢)"],[11576,"كان قاضيًا، وليس هو بشئ."],[11577,"٨٢٧ - والنعمام بن راشد"],[11578,"(٣)"],[11579,"ضعيف الحديث."],[11580,"= النيسابورى، ويقال: الترمذى، بصرى الأصل."],[11581,"انظر: تهذيب الكمال (٣ / ت ٦٤٨٣)، تهذيب التهذيب (١٠/ ٤٧٩)، ميزان الاعتدال (٤ / ت ٩١٢٣)، الجرح والتعديل (٨ / ت ٢٢٦٧)، التاريخ الكبير (٨ / ت ٢٤٠٠)، الكاشف (٣ / ت ٥٩٨٢)، معرفة الثقات (١٨٦٨)، الأنساب (٥/ ٧٢)، تاريخ ابن معين رواية الدورى (٢/ ٦١٠)، طبقات ابن سعد (٧/ ٣٧٢)، المغنى (٢ / ت ٦٦٧٣)، الكامل لابن عدى (٨/ ٣٢٣)."],[11582,"(١) هو: النضر بن مطرف الكوفى، يكنى أبا لينة. وهو النضر بن طهمان، وابن أبى مريم."],[11583,"انظر: الضعفاء والمتروكين (٥٩٧)، الضعفاء والمتروكين للدارقطنى (٥٤٣)، ميزان الاعتدال (٤/ ٢٦٣)، المغنى (٢ / ت ٦٦٤٦)، الإكمال (٧/ ٢٦١)، الجرح والتعديل (٨ / ت ٢١٨٣)، لسان الميزان (٦/ ١٦٥)، تبصير المنتبه (٤/ ١٢٩٥)، الضعفاء الكبير (٤/ ٢٨٨)."],[11584,"(٢) هو: النهاس بن قهم القيسى أبو الخطاب البصرى."],[11585,"انظر: تهذيب الكمال (٣٠ / ت ٦٤٨٢)، تهذيب التهذيب (١٠/ ٤٧٨)، التاريخ الكبير (٨ / ت ٢٤٧٤)، الجرح والتعديل (٨ / ت ٢٣٤٠)، الكاشف (٣ / ت ٥٩٨١)، ميزان الاعتدال (٤ / ت ٩١٢٤)، المجروحين (٣/ ٥٦)، تاريخ ابن معين رواية الدورى (٣/ ٦١٠)، تاريخ أسماء الثقات (١٤٨٤)، تاريخ الإسلام (٦/ ٣١٠)، الأنساب (١٠/ ٥٢٣)، ديوان الضعفاء (٥٩٨)، لسان الميزان (٧/ ٤١٤)، المغنى (٢ / ت ٦٦٧٢)، علل أحمد (١/ ٩٠)، الكامل لابن عدى (٨/ ٣٢٥)."],[11586,"(٣) هو: النعمان بن راشد الجزرى، أبو إسحاق الرقى، مولى بنى أمية، يقال: إنه أخو إسحاق بن راشد، وقال أبو حاتم: لم يصح ذلك عندى."],[11587,"انظر: تهذيب الكمال (٢٩ / ت ٦٤٤٠)، تهذيب التهذيب (١٠/ ٤٥٢)، الجرح والتعديل (٨ / ت ٢٠٦٠)، الكاشف (٣/ ت ٥٩٤٤)، التاريخ الكبير (٨ / ت ٢٢٤٨)، لسان الميزان (٧/ ٤٢١)، تاريخ أسماء الثقات (١٤٧٦)، تاريخ ابن معين (٢/ ٦٠٨)، المغنى (٢ / ت ٦٦٥١)، علل ابن المدينى (٧٥، ٧٦)، علل أحمد (١/ ١٣٧)، الكامل لابن عدى (٨/ ٢٤٦)."],[11588,"٨٢٨ - ونضر بن ثابت"],[11589,"(١)"],[11590,"ليس بشئ."],[11591,"٨٢٩ - ونصر بن حاجب"],[11592,"(٢)"],[11593,"ليس بشئ."],[11594,"٨٣٠ - ونهشل الخراسانى"],[11595,"(٣)"],[11596,"يروى عن الضحاك، ليس بثقة."],[11597,"٨٣١ - النضر بن شيبان"],[11598,"(٤)"],[11599,"ابن أبى خيثمة، قال: سئل يحيى بن معين عن حديث النضر بن شيبان، روى عن أبى سلمة بن عبد الرحمن، عن أبيه قال: ليس حديثه بشئ."],[11600,"٨٣٢ - ناجية"],[11601,"(٥)"],[11602,"قال: وسمعت يحيى بن معين، قال: حدثنا وكيع قال: قال شعبة: لقيت ناجية الذى"],[11603,"(١) كذا بالمخطوط، وبلسان الميزان أيضًا، وجاء بالكامل: نصر بن باب، وأيضًا بالتعجيل كما فى الكامل، وجاء بميزان الاعتدال نصر بن باب أيضًا فلعل الأولى تصحيف."],[11604,"انظر: ميزان الاعتدال (٤ / ت ٩٠٢٥)، تعجيل المنفعة (١١٠٢)، لسان الميزان (٦/ ١٥٠)، الكامل لابن عدى (٨/ ٢٨٢)."],[11605,"وهو: نصر بن باب الخراسانى المروزى أبو سهل، نزيل بغداد، وكان يسكن مرو."],[11606,"(٢) هو: نصر بن حاجب القرشى الخراسانى، مروزى، كان يسكن مرو."],[11607,"انظر: الكامل لابن عدى (٨/ ٢٨٦)، الجرح والتعديل (٨/ ٤٦٦)، الضعفاء الكبير (٤/ ٣٠١)، الضعفاء والمتروكين (٣/ ١٥٨)."],[11608,"(٣) سبق."],[11609,"(٤) هو: النضر بن شيبان الحُدَّانى البصرى."],[11610,"انظر: المغنى (٢ / ت ٦٦٣٦)، تهذيب الكمال (٢٩ / ت ٦٤٢٢)، تهذيب التهذيب (١٠/ ٤٣٨)، الكاشف (٣ / ت ٥٩٣٢)، ميزان الاعتدال (٤/ ٢٥٨)، لسان الميزان (٧/ ٤١١)، الجرخ والتعديل (٨ / ت ٢١٨٢)."],[11611,"(٥) هو: ناجية بن كعب العنزى أخو سلمى بنت كعب أبو خفاف."],[11612,"انظر: تهذيب الكمال (٢٩ / ت ٦٣٥٢)، تهذيب التهذيب (١٠/ ٤٠٠)، الجرح والتعديل (٨ / ت ٢٢٢٣)، الكاشف (٣ / ت ٥٨٧٠)، ميزان الاعتدال (٤ / ت ٨٩٨٥)، التاريخ الكبير (٨ / ت ٢٣٦٥)."],[11613,"يروى [عنه] (١) أبو إسحاق فرأيته يلعب بالشطرنج فتركته فلم أكتب عنه."],[11614,"٨٣٣ - ناصح البكرى"],[11615,"(٢)"],[11616,"قال: وسمعته يقول: ناصح البكرى ليس حديثه بشئ، وهو ناصح بن العلاء أبو العلاء."],[11617,"٨٣٤ - نوح بن أبى مريم"],[11618,"(٣)"],[11619,"قال أبو حاتم الرازى: نوح بن أبى مريم أبو عصمة، ذاهب الحديث."],[11620,"٨٣٥ - ونضر بن عبد الرحمن الخزاز"],[11621,"(٤)"],[11622,"أبو عمر، ضعيف الحديث."],[11623,"٨٣٦ - وناصح أبو عبد الله المحملى"],[11624,"(٥)"],[11625,"متروك الحديث."],[11626,"(١) ما بين المعقوفتين ساقط من المخطوط وأثبته من الجرح والتعديل."],[11627,"(٢) هو: ناصح بن العلاء أبو العلاء البصرى مولى بنى هاشم."],[11628,"انظر: تهذيب الكمال (٢٩/ ٦٣٥٥)، تهذيب التهذيب (١٠/ ٤٠٣)، الجرح والتعديل (٨/ت ٣٠٤)، ميزان الاعتدال (٤/ت ٨٩٨٩)، ديوان الضعفاء (٤٣٣٩)، الضعفاء الكبير (٨/ ١٢١)، تاريخ ابن معين رواية الدورى (٢/ ٦٠١)، المعرفة والتساريخ (٣/ ٤٥)، ضعفاء الدارقطنى (ت ٥٣٨)، ضعفاء أبى نعيم (٣٥٨)، لسان الميزان (٧/ ٤٠٨)، تاريخ أسماء الثقات (١٤٩٠)، الكامل لابن عدى (٨/ ٣٠٥)، سؤالات الآجرى لأبى داود (٣/ ٣٤٢)."],[11629,"(٣) هو: نوح بن أبى مريم، وقيل: يزيد بن جعونة المروزى، أبو عصمة القرشى، مولاهم، قاضى مرو ويعرف بنوح الجامع."],[11630,"انظر: تهذيب الكمال (٣ / ت ٦٤٩٥)، التاريخ الكبير (٨ / ت ٢٣٣٨)، الجرح والتعديل (٨ / ت ٢٢١٠)، الكاشف (٣ / ت ٥٩٩٢)، ميزان الاعتدال (٤ / ت ٩١٤٣)، تهذيب التهذيب (١٠/ ٤٨٦)، المغنى (٢ / ت ٦٦٨٣)، الأنساب (٣/ ١٧٥)، لسان الميزان (٧/ ٤١٥)، طبقات ابن سعد (٧/ ٣٧١)، علل أحمد (١/ ٢٢٠)، طبقات خليفة (٣٢٣)، شذرات الذهب (١/ ٢٨٣)، الكامل لابن عدى (٨/ ٢٩٢)."],[11631,"(٤) هو: النضر بن عبد الرحمن أبو عمر الخزاز الكوفى اليشكرى."],[11632,"انظر: تهذيب الكمال (٢٩ / ت ٦٤٣٠)، تهذيب التهذيب (١٠/ ٤٤٠١)، الجرح والتعديل (٨ / ت ٢١٨١)، الكاشف (٣ / ت ٥٩٣٥)، التاريخ الكبير (٨ / ت ٢٣٠٠)، تاريخ الإسلام (٦/ ١٣٥)، ضعفاء الدارقطنى (ت ٥٤١)، ديوان الضعفاء (٤٣٧٩)، المجروحين (٣/ ٤٩)، ضعفاء ابن الجوزى (٣/ ١٦٤)، المغنى (٢ / ت ٦٦٤٠)، تاريخ ابن معين رواية الدورى (ت ٢٠٥٦)، الكامل لابن عدى (٨/ ٢٥٧)."],[11633,"(٥) سبق."],[11634,"حرف \"و\""],[11635,"\""],[11636,"٨٣٧ - الوليد بن كثير"],[11637,"(١)"],[11638,"علِى قال: سمعت سفيان بن عيينة يقول: كان الوليد بن كثير أباضيًا، ولكنه كان صدوقًا."],[11639,"٨٣٨ - وزير"],[11640,"(٢)"],[11641,"ابن أبى خيثمة قال: سمعت يحيى بن معين يقول: وزير الذى يحدث بحديث معاوية: \"أن النبى - صلى الله عليه وآله وسلم - أعطاه سهمًا\" (٣)، ليس حديثه بشئ."],[11642,"٨٣٩ - الوازع بن نافع"],[11643,"(٤)"],[11644,"قال: وسمعته يقول: الوازع بن نافع جزرى عقيلى، ليس بثقة."],[11645,"٨٤٠ - وقاء بن إياس"],[11646,"(٥)"],[11647,"(١) هو: الوليد بن كثير المخزومى، مولاهم، أبو محمد المدنى."],[11648,"انظر: تهذيب الكمال (٣/ ت ٦٧٣٣)، تهذيب التهذيب (١١/ ٤٨١)، ميزان الاعتدال (٤/ ت ٩٣٩٧)، الجرح والتعديل (٩ / ت ٦٢)، الكاشف (٣ / ت ٦١٩٢)."],[11649,"(٢) هو: وزير بن عبد الله الجزرى."],[11650,"انظر: الكامل لابن عدى (٨/ ٣٧٥)، الضعفاء الكبير (٤/ ٣٣١)."],[11651,"(٣) أخرجه الخطيب البغدادى فى تاريخه (٣/ ٤٦٦). ذكره الشوكانى فى الفوائد (٤٠٥)، وقال: رواه الخطيب، عن أبى هريرة مرفوعًا، وابن حبان عن جابر مرفوعًا، وهو موضوع، وفى إسناده من ليس بشئ."],[11652,"وقد روى عن أنس مرفوعًا، وذكره ابن القيسرانى فى تذكرة الموضوعات (٢٧٧)، ابن الجوزى فى الموضوعات (٢/ ٢٠)، السيوطى فى اللآلئ (١/ ٢١٩)."],[11653,"انظر: كلام محقق الكامل، دار الكتب العلمية، الموضع السابق."],[11654,"(٤) هو: وازع بن نافع العقيلى الجزرى من أهل الجزيرة."],[11655,"انظر: الكامل لابن عدى (٨/ ٣٨٣)، الضعفاء والمتروكين (٣/ ١٨١)، الضعفاء الكبير (٤/ ٣٣٠)، الجرح والتعديل (٩/ ٣٩)، تاريخ ابن معين (٢/ ٦٢٧)، المغنى (٢ / ت ٦٨١٧)، تاريخ الإسلام (٦/ ٣١٣)، التاريخ الكبير (٤/ ٣٣٠)، ميزان الاعتدال (٤/ ٣٢٧)، المجروحين (٣/ ٨٣)، لسان الميزان (٦/ ٢١٣)."],[11656,"(٥) هو: وقاء بن إياس الأسدى الوالبى، ويقال: الجنبى، أبو يزيد الكوفى."],[11657,"انظر: تهذيب الكمال (٣٠ / ت ٦٦٩٢)، تهذيب التهذيب (١١/ ١٢٢)، الجرح والتعديل (٩ / ت ٢٠٨)، الكاشف (٣ / ت ٦١٥٦)، ميزان الاعتدال (٤ / ت ٩٣٥٤)، تاريخ ابن معين = قال على: سمعت يحيى بن سعيد يقول: ما كان وقاء بن إياس بالذى يعتمد عليه."],[11658,"٨٤١ - الوليد بن القاسم"],[11659,"(١)"],[11660,"قال: وسئل عن الوليد بن القاسم بن الوليد الهمدانى؟، فقال: ضعيف الحديث، وأبو خيثمة يحدث عنه."],[11661,"٨٤٢ - وضاح بن يحيى النهشلى"],[11662,"(٢)"],[11663,"قال أبو حاتم الرازى: وضاح بن يحيى النهشلى، كتبت عنه شيخ وليس بالمتقن."],[11664,"٨٤٣ - واصل بن السائب الرقاشى"],[11665,"(٣)"],[11666,"صاحب أبى سورة ليس بالقوى."],[11667,"٨٤٤ - واصل بن عبد الرحمن"],[11668,"(٤)"],[11669,"= (٦٣٠١٣)، طبقات ابن سعد (٦/ ٣٥٤)، علل أحمد (١/ ١٦٤)، المعرفة والتاريخ (٣/ ١٠٨)، الكنى للدولابى (٢/ ١٦٢)، الإكمال (٧/ ٣٩٦)، توضيح المشتبه (٣/ ١٨٥)، المؤتلف (٤/ ٢٢٨٥)، الكامل لابن عدى (٨/ ٣٧٧)."],[11670,"(١) هو: الوليد بن القاسم بن الوليد الهمدانى، ثم الخبذعى الكوفى."],[11671,"انظر: تهذيب الكمال (٣١/ ٦٧٢٨)، تهذيب التهذيب (١١/ ١٤٥)، ميزان الإعتدال (٤ / ت ٩٣٩٥)، الجرح والتعديل (٩ / ت ٥٨)، الكاشف (٣ / ت ٦١٨٧)، لسان الميزان (٧/ ٤٢٦)، المجروحين (٣/ ٨٠)، سير أعلام النبلاء (٩/ ٤٣٨)، ضعفاء ابن الجوزى (٣/ ١٨٦)، علل أحمد (٢/ ١٧١)، المؤتلف للدارقطنى (٢/ ٩٣٢)، الأنساب (٥/ ٣٨)، الإكمال (٣/ ١٢٥)، المشتبه (١٨٠)، الكامل لابن عدى (٨/ ٣٦٦)."],[11672,"(٢) هو: وضاح بن يحيى النهشلى الأنبارى، سكن الكوفة."],[11673,"انظر: ميزان الاعتدال (٤ / ت ٩٣٥١)، المغنى (٢ / ت ٦٨٤١)، المجروحين (٣/ ٨٥)، ديوان الضعفاء (٤٥٣٤)، ضعفاء ابن الجوزى (٣/ ١٨٣)، الجرح والتعديل (٩ / ت ١٧٤)."],[11674,"(٣) هو: واصل بن السائب الرقاشى، وقيل: الخراسانى، أبو يحيى البصرى."],[11675,"انظر: تهذيب الكمال (٣٠ / ت ٦٦٦٣)، تهذيب التهذيب (١١/ ١٠٤)، الكاشف (٣ / ت ٦١٢٩)، ميزان الاعتدال (٤ / ت ٩٣٢٣)، المجروحين (٢/ ٨٣)، ضعفاء ابن الجوزى (٣/ ١٨١)، تاريخ الإسلام (٦/ ١٤٦)، المعرفة والتاريخ (٣/ ١٤١)، ضعفاء الدارقطنى (٥٥٢)، الكاشف (٣/ ٢٣٢)، الكامل لابن عدى (٨/ ٣٧١)."],[11676,"(٤) هو: واصل بن عبد الرحمن، أبو حرة البصرى، أخو سعيد وليس بالرقاشى."],[11677,"انظر: تهذيب الكمال (٣٠ / ت ٦٦٦٥)، التاريخ الكبير (٨/ت ٢٥٨٥)، الجرح والتعديل (٩/ ت ١٤١)، الكاشف (٣/ ت ٦١٣١)، ميزان الاعتدال (٤/ ت ٩٣٢٤)، لسان الميزان = يكتب حديثه ولا يحتج به."],[11678,"٨٤٥ - الوليد بن أبى يونس"],[11679,"(١)"],[11680,"قال يحيى: الوليد بن أبى يونس، ليس بشئ."],[11681,"٨٤٦ - ورقاء"],[11682,"(٢)"],[11683,"قال: وقال يحيى بن سعيد: ورقاء لا يساوى شيئًا."],[11684,"٨٤٧ - والوليد بن عمرو (٣) ساج"],[11685,"قال: والوليد بن عمرو ضعيف."],[11686,"٨٤٨ - واصل"],[11687,"(٤)"],[11688,"= (٧/ ٤٢٣)، الجمع لابن القيسرانى (٢/ ٥٤٣)، الكنى للدولابى (١/ ١٤٦)، تاريخ ابن معين، رواية الدورى (٢/ ٦٢٧)، المغنى (٢ / ت ٦٨١٨)، طبقات ابن سعد (٧/ ٣٧٥)، تراجم الأحبار (٤/ ١٨٨)، المعرفة والتاريخ (٢/ ٥٣)، طبقات خليفة (٢٢٢)، الكامل لابن عدى (٨/ ٣٧٣)."],[11689,"(١) كذا بالمخطوط، ولم أقف عليه، ولعله تصحيف عن \"الوليد بن أبى عبد الله بن أبى ثور الهمدانى المرهبى الكوفى\" وقد ينسب إلى جده."],[11690,"انظر: تهذيب الكمال (٣١ / ت ٦٧١٣)، تهذيب التهذيب (١١/ ١٣٨)، الجرح والتعديل (٩ / ت ٣٤)، الكاشف (٣ / ت ٦١٧٥)، ميزان الاعتدال (٤ / ت ٩٣٦٢)، التاريخ الكبير (٨ / ت ٢٥١١)، الكامل لابن عدى (٨/ ٣٥٥)، المغنى (٢ / ت ٦٨٦٢)، تاريخ بغداد (١٣/ ٤٣٩)، لسان الميزان (٧/ ٤٢٥)، تاريخ ابن معين (٣/ ٦٣٢)، المجروحين (٣/ ٧٩)."],[11691,"(٢) هو: ورقاء بن عمر بن كليب اليشكرى، ويقال: الشيبانى، أبو بشر الكوفى، نزيل المدائن، يقال: أصله من مرو."],[11692,"انظر: تهذيب الكمال (٣٠ / ت ٦٦٨٤)، تهذيب التهذيب (١١/ ١١٣)، التاريخ الكبير (٨ / ت ٢٦٤٨)، الجرح والتعديل (٩ / ت ٢١٦)، الكاشف (٣ / ت ٦١٤٩)، معجم طبقات الحفاظ (١٨٤)، تراجم الأحبار (٤/ ٢٠٥)، الأنساب (١٣/ ٥١٢)، تاريخ أسماء الثقات (١٥٠٦)، تاريخ بغداد (١٣/ ٤٨٤)، طبقات ابن سعد (٧/ ٣٣٧)، تاريخ ابن معين، رواية الدورى (٢/ ٦٢٨)، الكامل لابن عدى (٨/ ٣٧٨)."],[11693,"(٣) هو: الوليد بن عمرو بن ساج."],[11694,"انظر: الضعفاء والمتروكين (٣/ ١٨٦)، المجروحين (٣/ ٧٩)، الضعفاء الكبير (٤/ ٣٢٠)، الجرح والتعديل (٩/ ١١)، لسان الميزان (٦/ ٢٢٤)، تاريخ ابن معين، رواية الدورى (٢/ ٦٣٣)، أحوال الرجال (٢٥)، ميزان الاعتدال (٤/ ٣٤٢)، ضعفاء ابن الجوزى (٣/ ١٨٦)، المغنى (٢ / ت ٦٨٧٥)، الكامل لابن عدى (٨/ ٣٥٣)."],[11695,"(٤) هو: واصل بن أبى جميل الشامى، أبو بكر السلامانى."],[11696,"انظر: تهذيب الكمال (٣٠/ ت ٧٧٠١)، تهذيب التهذيب (١١/ ١٠٢)، التاريخ الكبير (٨ / ت (٢٥٩٦)."],[11697,"قال السباك الجرجانى: قال عبد الله بن سعيد: يقال: إن واصل، منكر الحديث، وهو الذى يروى عنه الأوزاعى [.....] (١)."],[11698,"حرف \"هـ\""],[11699,"ـ\""],[11700,"٨٤٩ - الهيثم بن بدر"],[11701,"(٢)"],[11702,"قال على: سألت جريرًا عن الهيثم بن بدر الذى روى عنه مغيرة؟ فقال: كان صبيًا وكان على خراج الرى."],[11703,"٨٥٠ - هارون بن معروف بن وهب"],[11704,"(٣)"],[11705,"ابن أبى خيثمة قال: حدث هارون بن معروف بن وهب، عن محمد بن أبى يحيى فقال يحيى: لم يسمع ابن وهب من محمد بن يحيى، ولو كان أدركه أدرك هشام بن عروة."],[11706,"٨٥١ - الهيثم بن حميد"],[11707,"(٤)"],[11708,"قال: وأخبرنا أبو محمد التيمى قال: وأخبرنا أبو مسهر، حدثنا الهيثم بن حميد، وكان صاحب كتب لم يكن من أهل الإثبات ولا من أهل الحفظ، وقد كنت أمسك عن الحديث عنه استضعفته."],[11709,"٨٥٢ - هشام بن سليمان"],[11710,"(٥)"],[11711,"(١) ما بين المعقوفين غير ظاهر بالمخطوط، وأظنه باقى قول البخارى: \"أحاديث مرسلة\"، والله أعلم."],[11712,"(٢) هو: الهيثم بن بدر الضبى."],[11713,"انظر: الكامل لابن عدى (٨/ ٤٠١)، الضعفاء الكبير (٤/ ٣٥٠)، المعرفة والتاريخ (٣/ ٢٣٧)، الجرح والتعديل (٩/ ٣٢٦)، ديوان الضعفاء (٤٤٩٩)، الثقات (٥٧٦)، لسان الميزان (٤/ ٢٠٦)، المغنى (٢/ ت (٦٧٩٣)."],[11714,"(٣) لم أقف عليه."],[11715,"(٤) لم أقف عليه."],[11716,"(٥) هو: هشام بن سلمان المجاشعى، يكنى: أبا يحيى."],[11717,"انظر: الكامل لابن عدى (٨/ ٤٠٧)، المغنى (٢ / ت ٦٧٥١)، المجروحين (٣/ ٨٩)، الجرح = قال: حدثنا موسى بن إسماعيل، حدثنا هشام بن سلمان المجاشعى، قال أبو سلمة: وكان ضعيفًا."],[11718,"٨٥٣ - هشام مولى عثمان"],[11719,"(١)"],[11720,"قال: وقال يحيى: هشام مولى عثمان ليس حديثه بشئ."],[11721,"٨٥٤ - الهيثم بن جماز"],[11722,"(*) (٢)"],[11723,"قال أبو حاتم الرازى: الهيثم بن جماز ضعيف الحديث."],[11724,"٨٥٥ - وهلال بن زيد"],[11725,"(٣)"],[11726,"أبو عقال (٤)، سمع من أنس، ليس بالقوى."],[11727,"= والتعديل (٩/ ٦٢)، الضعفاء والمتروكين (٣/ ١٧٥)، ميزان الاعتدال (٤/ ٢٩٩)، ضعفاء ابن الجوزى (٣/ ١٧٥)."],[11728,"(١) هو: هشام بن زياد بن أبى يزيد القرشى، أبو المقدام بن أبى هشام المدنى، مولى عثمان."],[11729,"انظر: تهذيب الكمال (٣٠ / ت ٦٥٧٥)، تهذيب التهذيب (١١/ ٣٨)، ميزان الاعتدال (٤ / ت ٩٢٢٣)، الجرح والتعديل (٩ / ت ٢٣٨)، التاريخ الكبير (٨ / ت ٢٧٠٢)، تاريخ ابن معين (٢/ ٦١٦)، الضعفاء الكبير (٤/ ٣٣٩)، المعرفة والتاريخ (٣/ ٥٥)، ضعفاء الدارقطنى (٥٦٢)، الكنى للدولابى (٢/ ١٢٧)، المجروحين (٣/ ٨٨)، لسان الميزان (٧/ ٤١٨)، المغنى (٢ /ت ٦٧٤٧)، معرفة الثقات (١٩٠٩)، الكامل لابن عدى (٨/ ٤٠٣)."],[11730,"(*) جاء بالمخطوط: \"حماد\" بالإهمال، ولم أقف عليه عند أبى حاتم ولا فى تاريخ ابن معين فغلب على ظنى أنه تصحيف عما أثبت، فالله أعلم."],[11731,"(٢) هو: الهيثم بن جماز البكار البصرى الحنفى."],[11732,"انظر: الجرح والتعديل (٩ / ت ٣٣٠)، الضعفاء والمتروكين (١٧٨/ ٣)، الضعفاء الكبير (٤/ ٣٥٥)، المجروحين (٩١/ ٣)، المغنى (٢ /ت ٦٧٩٤)، ميزان الاعتدال (٤/ ٣١٩)، لسان الميزان (٦/ ٢٠٤)، الإكمال (٢/ ٥٥٠)، الأنساب (٢/ ٢٨٦، ٣/ ٣١٧)، الضعفاء والمتروكين للدارقطنى (٥٦٤)، تاريخ ابن معين (٢/ ٦٢٦)."],[11733,"(٣) هو: هلال بن زيد بن حسن بن أسامة بن زيد بن حارثة الكلبى، أبو عقال الدمشقى، مولى النبى - صلى الله عليه وآله وسلم -."],[11734,"انظر: تهذيب الكمال (٣/ ١٤٥٢)، تهذيب التهذيب (١١/ ٧٩)، خلاصة تهذيب الكمال (٣/ ١١٨)، التاريخ الكبير (٨/ ٢٠٥)، الضعفاء الكبير (٤/ ٣٤٥)، ديوان الضعفاء (٤٤٨٩)، المغنى (٢ / ت ٦٧٧٧)، الكشف الحثيث (٨/ ٨)، تاريخ ابن معين، رواية الدورى (٢/ ٦٢٣)، الكامل لابن عدى (٨/ ٤٢٢)، لسان الميزان (٧/ ٤٢١)، المجروحين (٣/ ٨٦)."],[11735,"(٤) جاء بالمخطوط: \"أبو عفان\"، وهو تصحيف."],[11736,"٨٥٦ - هشام بن سعد"],[11737,"(١)"],[11738,"قال يحيى بن معين: هشام بن سعد فيه الضعف، وهو صاحب محمد بن كعب القرظى."],[11739,"٨٥٧ - وهياج بن بسطام"],[11740,"(٢)"],[11741,"قال: وهياج بن بسطام ليس بشئ. وهياج بن بسطام هروى ضعيف."],[11742,"٨٥٨ - هارون بن سعد"],[11743,"(٣)"],[11744,"قال: وكان هارون بن سعد من الخريبة (٤)، ممن يعلموا فى التشيع، روى عنه"],[11745,"المسعودى."],[11746,"(١) هو: هشام بن سعد المدنى، أبو عباد، ويقال: أبو سعد القرشى مولاهم."],[11747,"انظر: تهذيب الكمال (٣٠/ ٢٠٤)، تهذيب التهذيب (١١/ ٣٩)، الجرح والتعديل (٩ /ت ٢٤١)، الكاشف (٣ /ت ٦٠٤٦)، ميزان الاعتدال (٤ /ت ٩٢٢٤)، تاريخ ابن معين، رواية الدورى (٢/ ٦١٧)، علل أحمد (٢/ ٤٥)، تاريخ خليفة (٤٢٩)، العرفة والتاريخ (٢/ ١٧٣)، تذكرة الحفاظ (١/ ٢٠٢)، المغنى (٢ /ت ٦٧٤٨)، لسان الميزان (٧/ ٤١٨)، تراجم الأحبار (٤/ ١٦١)، ضعفاء ابن الجوزى (٣/ ١٧٤)، تاريخ الإسلام (٦/ ٣١١)، الأنساب (١١/ ٢٣٦)."],[11748,"(٢) هو: هياج بن بسطام التميمى البرجمى الحنظلى، أبو خالد الخراسانى الهروى."],[11749,"انظر: تهذيب الكمال (٣٠ /ت ٦٦٣٧)، تهذيب التهذيب (١١/ ٨٨)، الجرح والتعديل (٩ /ت ٤٧٤)، التاريخ الكبير (٨ /ت ٢٧٦٦)، المعرفة والتاريخ (٣/ ٣٧)، تاريخ ابن معين، رواية الدورى (٢/ ٦٢٥)، المجروحين (٣/ ٩٦)، ديوان الضعفاء (٤٤٩٨)، ضعفاء ابن الجوزى (٣/ ١٧٨)، الضعفاء الكبير (٦١٣)، المغنى (٢ /ت ٦٧٩٠)، تاريخ بغداد (١٤/ ٨٠)، لسان الميزان (٧/ ٤٢٢)، الكامل لابن عدى (٨/ ٤٤٧)."],[11750,"(٣) جاء بالمخطوط \"سعيد\" وما أثبت من المصادر التالية: وهو: هارون بن سعد العجلى الكوفى، يكنى: أبا محمد."],[11751,"انظر: تهذيب الكمال (٣٠ /ت ٦٥١٢)، تهذيب التهذيب (٦/ ١١)، الكامل لابن عدى (٨/ ٤٣٩)، ضعفاء ابن الجوزى (٣/ ١٧٠)، المجروحين (٣/ ٩٤)، لسان الميزان (٧/ ٤١٥)، تاريخ ابن معين، رواية الدورى (٢/ ٦١٣)، رواية الدارمى (ت ٨٥٤)، تاريخ أسماء الثقات (١٥٢٠)، علل أحمد (٢/ ٣٠)، الكاشف (٣ /ت ٦٠٠٧)، ميزان الاعتدال (٤ /ت ٩١٥٩)، التاريخ الكبير (٨ /ت ٢٧٨٧)، الجرح والتعديل (٩ /ت ٣٧٤)."],[11752,"(٤) هم إحدى فرق غلاة الشيعة، يرون جواز إتيان النساء فى أدبارهن، انظر: هامش الكامل لابن عدى، الموضع السابق."],[11753,"٨٥٩ - والهيثم بن عدى"],[11754,"(١)"],[11755,"كوفى، ليس بثقة، وكان يكذب، قال: وحدثنى بعض أصحابنا، قال: كانت جارية الهيثم، تقول: كان مولاى يقوم عامة الليل يصلى، فإذا أصبح جلس يكذب."],[11756,"٨٦٠ - وهشام أبو المقدام"],[11757,"(٢)"],[11758,"ليس بثقة، وهو هشام بن زياد، أخو الوليد بن أبى هاشم، وهو هشام بن زياد، أخو"],[11759,"الوليد بن أبى هاشم (٣)، وهو مولى عثمان."],[11760,"٨٦١ - والهذيل بن بلال"],[11761,"(٤)"],[11762,"كان ينزل المدائن وليس بشئ."],[11763,"٨٦٢ - هشام بن حجير"],[11764,"(٥)"],[11765,"قال ابن المدينى: قرأت على يحيى: حدثنا عن هشام بن حجير، فقال يحيى: خليق أن أدعه، قلت: أضرب على حديثه؟ قال: إن شئت، فضربت عليه."],[11766,"حرف \"ى\""],[11767,"\""],[11768,"٨٦٣ - يزيد بن عياض بن جعدبة"],[11769,"(٦)"],[11770,"(١) هو: الهيثم بن عدى الطائى، أبو عبد الرحمن المنبجى، ثم الكوفى، من أهل منبج، وأمه من سبى منبج."],[11771,"انظر: ميزان الاعتدال (٤ /ت ٩٣١١)، الضعفاء والمتروكين (٣/ ١٧٩)، المجروحين (٣/ ٩٢)، الجرح والتعديل (٩/ ٨٥)، الكامل لابن عدى (٨/ ٤٠٠)."],[11772,"(٢) سبق."],[11773,"(٣) كذا بالمخطوط مكرر، ولعله سهو من الناسخ."],[11774,"(٤) هو: هذيل بن بلال الفزارى، أبو البهلول المدائنى."],[11775,"انظر تعجيل المنفعة (١١٣٣)، التاريخ الكبير (٨/ ٤٥)، المجروحين (٣/ ٩٥)، تاريخ بغداد (١٤/ ٧٦)، ضعفاء ابن الجوزى (٣/ ١٧٣)، تاريخ ابن معين (٣/ ٦١٥)، المغنى (٢ / ت ٦٧٣٨)، لسان الميزان (٦/ ١٩٢)، الجرح والتعديل (٩/ ٤٧٧)، تاريخ ابن معين (٣/ ٦١٥)، الكامل لابن عدى (٨/ ٤٣٢)."],[11776,"(٥) سبق."],[11777,"(٦) هو: يزيد بن عياض بن جعدبة الليثى، أبو الحكم المدنى، نزل البصرة."],[11778,"انظر: تهذيب الكمال (٣٢ / ت ٧٠٣٥)، تهذيب التهذيب (١١/ ٣٥٢)، التاريخ الكبير (٨ / ت = قال: يزيد بن عياض بن جعدبة ضعيف."],[11779,"٨٦٤ - ويونس بن الحارث الطائفى"],[11780,"(١)"],[11781,"ضعيف."],[11782,"٨٦٥ - ويعقوب بن الوليد"],[11783,"(٢)"],[11784,"كان بخضرة الرصافة ولم يكن بشئ."],[11785,"٨٦٦ - ويحيى بن كاسب"],[11786,"(٣)"],[11787,"ليس بشئ."],[11788,"٨٦٧ - يوسف السمتى"],[11789,"(٤)"],[11790,"= ٣٢٩٦)، الكاشف (٣ / ت ٦٤٥٣)، نسيم الرياض (٣/ ١٠٥)، التاريخ لابن معين (٣/ ٦٧٥)، الضعفاء الكبير (٤/ ٣٨٧)، المغنى (٢ / ت ٧١٣٤)، ضعفاء ابن الجوزى (٣/ ٢١١)، تاريخ بغداد (١٤/ ٣٢٩)، ديوان الضعفاء (٤٧٤٤)، الجرح والتعديل (٩ / ت ١١٩٢)، لسان الميزان (٧/ ٤٤٣)، الكامل لابن عدى (٩/ ١٤٠)."],[11791,"(١) هو: يونس بن الحارث الثقفى الطائفى، نزيل الكوفة."],[11792,"انظر، تهذيب الكمال (٣٢ / ت ٧١٧٤)، تهذيب التهذيب (١١/ ٤٣٧)، الجرح والتعديل (٩ / ت ١٠٠١)، الكاشف (٣ / ت ٦٥٧٨)، ميزان الاعتدال (٤/ ت ٩٩٠٣)، لسان الميزان (٧/ ٤٤٨)، الثقات (٩/ ٢٨٨)، ضعفاء ابن الجوزى (٢/ ٢٢٣)، الكامل لابن عدى (٨/ ٥٢٠)."],[11793,"(٢) هو: يعقوب بن الوليد بن عبد الله بن أبى هلال الأزدى، أبو يوسف، وقيل: أبو هلال المدنى، سكن بغداد."],[11794,"انظر: تهذيب الكمال (٣٢ / ت ٧١٠٦)، تهذيب التهذيب (١١/ ٣٩٨)، الكاشف (٣/ ت ٦٥١٥)، ميزان الاعتدال (٤ / ت ٩٨٢٩)، الجرح والتعديل (٩ / ت ٩٠٣)، لسان الميزان (٧/ ٤٤٦)، المجروحين (٣/ ١٣٧)، الضعفاء الكبير (٤/ ٤٤٨)، المغنى (٢/ ت ٧٢٠٥)، تاريخ ابن معين (٣/ ٦٨١)، تاريخ بغداد (١٤/ ٢٦٥)، ضعفاء ابن الجوزى (٣/ ٢١٧، الكامل لابن عدى (٨/ ٤٧٠)."],[11795,"(٣) كذا بالمخطوط، ولم أقف له على ترجمة وغلبة الظن عندى أنه مصحف عن غير هذا الاسم، ولعله عن \"يعقوب بن حميد بن كاسب\"."],[11796,"انظر: أعلام النبلاء (١١/ ١٥٨)، طبقات الحفاظ (٢٦٢)، الضعفاء الكبير (٤/ ٤٤٦)، الثقات (٧/ ٦٤٢)، ضعفاء ابن الجوزى (٣/ ٢١٥)، المغنى (٢ / ت ٧١٨٧)، تهذيب التهذيب (١١/ ٣٨٣)، الكامل لابن عدى (٨/ ٤٧٦)."],[11797,"(٤) هو: يوسف بن خالد بن عمير السمتى، أبو خالد البصرى، مولى صخر بن سهل الليثى. ="],[11798,"قال: وكان يوسف السمتى يكذب."],[11799,"٨٦٨ - ويحيى بن سلمة بن كهيل"],[11800,"(١)"],[11801,"ليس بشئ."],[11802,"٨٦٩ - ويحيى بن عبيد الله"],[11803,"(٢)"],[11804,"ليس بشئ."],[11805,"٨٧٠ - وياسين بن معاذ"],[11806,"(٣)"],[11807,"ضعيف."],[11808,"٨٧١ - ويونس بن خباب"],[11809,"(٤)"],[11810,"= انظر: تهذيب الكمال (٣٢ /ت ٧١٣٤)، تهذيب التهذيب (١١/ ٤١١)، الجرح والتعديل (٩ /ت ٩٢٥)، التاريخ الكبير (٨ /ت ٣٤٢٦)، الكاشف (٣ /ت ٦٥٤٣)، ميزان الاعتدال (٤ /ت ٩٨٦٣)، الأنساب (٧/ ٢١١)، تاريخ الثقات (٤٨٦)، تاريخ ابن معين (٣/ ٦٨٤)، ضعفاء ابن الجوزى (٣/ ٢١٩)، المجروحين (٣/ ١٣١)، لسان الميزان (٧/ ٤٤٧)، الكامل لابن عدى (٨/ ٤٩٠)."],[11811,"(١) هو: يحيى بن سلمة بن كهيل الحضرمى، أبو جعفر الكوفى."],[11812,"انظر: تهذيب الكمال (٣١ /ت ٦٨٣٨)، تهذيب التهذيب (١١/ ٢٢٤)، ميزان الاعتدال (٤ /ت ٩٥٢٧)، الجرح والتعديل (٩ /ت ٦٣٦)، الكاشف (٣ /ت ٦٢٨٢)، التاريخ الكبير (٨ /ت ٢٩٨٩)، المغنى (٢ /ت ٦٩٧٧)، المجروحين (٣/ ١١٢)، معرفة الثقات (١٩٧٩)، ضعفاء ابن الجوزى (٣/ ١٩٦)، الثقات (٧/ ٥٩٥)، ديوان الضعفاء (٣٦٣٧)، الضعفاء الكبير (٤/ ٤٠٥)، الكامل لابن عدى (٩/ ٢٠)."],[11813,"(٢) هو: يحيى بن عبيد الله بن عبد الله بن موهب التيمى المدنى."],[11814,"انظر: تهذيب الكمال (٣١ /ت ٦٨٧٦)، التاريخ الكبير (٨ /ت ٣٠٥٦)، الجرح والتعديل (٩ / ت ٦٩٢)، الكاشف (٣ / ت ٦٣١١)، ميزان الاعتدال (٤ /ت ٩٥٨١)، تهذيب التهذيب (١١/ ٢٥٢)، تاريخ ابن معين (٢/ ٦٥٠)، الضعفاء الكبير (٤/ ٤١٥)، المغنى (٢ /ت ٧٠١٣)، المجروحين (٣/ ١٢١)، لسان الميزان (٧/ ٤٣٥)، الكامل لابن عدى (٣١٩٩)، ضعفاء ابن الجوزى (٣/ ١٩٩)."],[11815,"(٣) هو: ياسين بن معاذ، أبو خلف الزيات الكوفى."],[11816,"انظر: الكامل لابن عدى (٨/ ٥٣٣)، الضعفاء والمتروكين (٣/ ١٩٠)، الضعفاء الكبير (٤/ ٤٦٤)، الجرح والتعديل (٩/ ٣١٢)، المجروحين (٣/ ١٤٢)، المغنى (٢ /ت ٦٩١٧)، الإكمال (٤/ ٦)، أحوال الرجال (٢٦٤)، دائرة معارف الأعلمى (٣٠/ ٧٦)."],[11817,"(٤) هو: يونس بن خباب الأسيدى، مولاهم أبو حمزة، ويقال: أبو الجهم الكوفى. ="],[11818,"رجل سوء [كان يشتم عثمان بن عفان]، قال ابن المدينى: سمعت يحيى بن سعيد"],[11819,"يقول: ما تعجبنى الرواية عن يونس بن خباب."],[11820,"٨٧٢ - ويزيد بن سنان أبو فروة"],[11821,"(١)"],[11822,"يروى عن الزهرى، ليس حديثه بشئ."],[11823,"٨٧٣ - ويحيى بن سليم"],[11824,"(٢)"],[11825,"شيخ ضعيف، كوفى يروى عنه وكيع."],[11826,"٨٧٤ - ويمان بن المغيرة"],[11827,"(٣)"],[11828,"ليس حديثه بشئ."],[11829,"= انظر: تهذيب الكمال (٣٢ / ت ٧١٧٤)، الجرح والتعديل (٩ / ت ١٠٠١)، الكاشف (٣ /ت ٦٥٧٨)، ميزان الاعتدال (٤ /ت ٩٩٠٣)، ضعفاء ابن الجوزى (٣/ ٢٢٤)، لسان الميزان (٧/ ٤٤٩)، الكامل لابن عدى (٨/ ٥١٥)."],[11830,"(١) بالمخطوط \"أبو قرة\"، وهو: يزيد بن سنان بن يزيد التميمى الجزرى، أبو فروة الرهاوى."],[11831,"انظر: تهذيب الكمال (٣٢ /ت ٧٠٠١)، تهذيب التهذيب (١١/ ٣٣٥)، التاريخ الكبير (٨ /ت ٣٢٢٨)، الجرح والتعديل (٩/ ت ١١٢٠)، الكاشف (٣ /ت ٦٤٢١)، ميزان الاعتدال (٤ /ت ٩٧٠٥)، تاريخ ابن معين (٣/ ٦٧٢)، تاريخ الإسلام (٦/ ٣١٦)، ضعفاء ابن الجوزى (٣/ ٢٠٩)، ديوان الضعفاء (٦٥٠)، المغنى (٢ /ت ٧١١٠)، المجروحين (٣/ ١٠٦)، الكامل لابن عدى (٩/ ١٥٢)."],[11832,"(٢) هو: يحيى بن سليم القرشى الطائفى، أبو محمد، ويقال: أبو زكريا المكى الحذاء الخراز."],[11833,"انظر: تهذيب الكمال (٣١ /ت ٦٨٤١)، تهذيب التهذيب (١١/ ٢٢٦)، الجرح والتعديل (٩/ ت ٦٤٧)، ميزان الاعتدال (٤ /ت ٩٥٣٨)، الثقات (٧/ ٦١٥)، ديوان الضعفاء (٦٣٣)، معرفة الثقات (١٩٨٠)، ضعفاء ابن الجوزى (٣/ ١٩٦)، تاريخ أسماء الثقات (١٥٩١)، تراجم الأحبار (٤/ ٢٨١)، المغنى (٢ /ت ٦٩٨٦)، الضعفاء الكبير (٤/ ٤٠٦)، الكامل لابن عدى (٩/ ٦٢)."],[11834,"(٣) هو: يمان بن المغيرة العنبرى، ويقال: العبرى، ويقال: التيمى، أبو حذيفة البصرى."],[11835,"انظر: تهذيب الكمال (٣٢ /ت ٧١٢٥)، تهذيب التهذيب (١١/ ٤٠٦)، التاريخ الكبير (٨ / ت ٦٥٣٥)، ميزان الاعتدال (٤ /ت ٩٨٥١)، المجروحين (٣/ ١٤٣)، ضعفاء ابن الجوزى (٣/ ٢١٨)، الأنساب (١٠/ ٨٧)، المغنى (٢/ ٧٢٢٣)، لسان الميزان (٧/ ٤٤٧)، تاريخ ابن معين (٣/ ٦٨٤)، الكامل لابن عدى (٨/ ٥٢٨)."],[11836,"٨٧٥ - ويوسف بن عطية الصفار"],[11837,"(١)"],[11838,"ليس بشئ."],[11839,"٨٧٦ - ويزيد بن جعدبة"],[11840,"(٢)"],[11841,"ليس بشئ، وأحسبه الذى ذكره فى أول هذا الحرف."],[11842,"٨٧٧ - ويزيد بن درهم"],[11843,"(٣)"],[11844,"بصرى، وليس بشئ."],[11845,"٨٧٨ - ويزيد بن عطاء"],[11846,"(٤)"],[11847,"ضعيف."],[11848,"٨٧٩ - ويحيى بن عمرو بن مالك النكرى"],[11849,"(٥)"],[11850,"(١) هو: يوسف بن عطة بن ثابت الصفار الأنصارى السعدى، مولاهم، أبو سهل البصرى الجفرى."],[11851,"انظر: تهذيب الكمال (٣٢ /ت ٧١٤٥)، تهذيب التهذيب (١١/ ٤١٨)، الجرح والتعديل (٩ /ت ٩٥٠)، ميزان الاعتدال (٤ /ت ٩٨٧٧)، المغنى (٢ /ت ٧٢٤٤)، معرفة الثقات (٢٠٦٠)، ضعفاء ابن الجوزى (٣/ ٢٢١)، لسان الميزان (٧/ ٤٤٧)، الذيل على الكاشف (١٧١٣)، الكافل لابن عدى (٨/ ٤٨٠)."],[11852,"(٢) هو: يزيد بن عياض بن يزيد بن جعدبة. وقد سبق."],[11853,"(٣) هو: يزيد بن درهم، أبو العلاء."],[11854,"انظر: ميزان الاعتدال (٤/ ٤٢١)، الضعفاء الكبير (٤/ ٣٨٦)، ديوان الضعفاء (٤٧١٩)، دائرة معارف الأعلمى (١٢٧٣٠)، تاريخ ابن معين (٣/ ٦٦٩)، الجرح والتعديل (٩/ ١٩٦)، المغنى (٢ /ت ٧٠٩٦)، الكامل لابن عدى (٩/ ١٦٨)، الضعفاء والمتروكين (٣/ ٢٠٨)."],[11855,"(٤) هو: يزيد بن عطاء بن عبد الرحمن اليشكرى، مولاهم، ويقال: الكندى، ويقال: السلمى، أبو خالد الواسطى البزار، أعتقه أبو عوانة، هو مولاه من فوق."],[11856,"انظر: تهذيب الكمال (٣٢ /ت ٧٠٣٠)، تهذيب التهذيب (١١/ ٣٥٠)، التاريخ الكبير (٨ /ت ٣٢٩٤)، الكاشف (٣ /ت ٦٤٤٩)، ميزان الاعتدال (٤ /ت ٩٧٣١)، ضعفاء ابن الجوزى (٣/ ٣١١)، العبر (١/ ٣٦٩)، معرفة الثقات (٢٠٢٧)، الأنساب (٥١١)، المجروحين (٣/ ١٠٣)، المغنى (٢ /ت ٣١٢٧)، لسان الميزان (٧/ ٤٤٢)، الكامل لابن عدى (٩/ ١٥٩)."],[11857,"(٥) هو: يحيى بن عمرو بن مالك النكرى البصرى."],[11858,"انظر: تهذيب الكمال (٣١ /ت ٦٨٩٢)، الجرح والتعديل (٩ /ت ٧٣٢)، الكاشف (٣ /ت = ضعيف."],[11859,"٨٨٠ - ويحيى بن راشد"],[11860,"(١)"],[11861,"ليس بشئ، وكان يروى عن الجريرى."],[11862,"٨٨١ - ويزيد بن يوسف"],[11863,"(٢)"],[11864,"شامى، وليس بثقة."],[11865,"٨٨٢ - ويزيد بن زريع الرملى"],[11866,"(٣)"],[11867,"ضعيف."],[11868,"٨٨٣ - ابن السكن"],[11869,"(٤)"],[11870,"كان ابن السكن فى الحرم، وكان يقول: سمعت الشعبى ولم يكن شيئًا."],[11871,"٨٨٤ - يحيى بن عطاء بن عجلان"],[11872,"(٥)"],[11873,"الذى يروى عنه إسماعيل بن عياش، لم يكن بشئ."],[11874,"= ٦٣٢٦)، تهذيب التهذيب (١١/ ٢٥٩)، تاريخ ابن معين (٣/ ٦٥١)، ضعفاء ابن الجوزى (٣/ ٢٠١)، المجروحين (٣/ ١١٤)، الأنساب (١٣/ ١٧٥)، الإكمال (١/ ٤٥٢)، الضعفاء الكبير (٤/ ٤٢٠)، المغنى (٢/ ت ٧٠٢٤)، الكامل لابن عدى (٩/ ٣٧)."],[11875,"(١) هو: يحيى بن راشد المازنى، أبو سعيد البصرى البراء."],[11876,"انظر: تهذيب التهذيب (١١/ ٢٠٧)، تهذيب الكمال (٣١ / ت ٦٨٢٣)، الجرح والتعديل (٩ / ت ٦٠٣)، الكاشف (٣ /ت ٦٢٧٠)، ميزان الاعتدال (٤/ ت ٩٤٩٩)، لسان الميزان (٧/ ٤٣١)، تاريخ ابن معين (٣/ ٦٤٢)، الثقات (٥/ ٥٢٤)، ضعفاء ابن الجوزى (٣/ ١٩٤)، الكامل لابن عدى (٩/ ٤٧)."],[11877,"(٢) هو: يزيد بن يوسف الرحبى، أبو يوسف الصنعانى الدمشقى، صاحب الأوزاعى."],[11878,"انظر: تهذيب الكمال (٣٢/ ت ٧٠٦٥)، ميزان الاعتدال (٤ /ت ٩٧٧٠)، الجرح والتعديل (٩ / ت ١٢٦١)، الكاشف (٣/ ت ٦٤٧٨)، ضعفاء ابن الجوزى (٣/ ٢١٣)، تاريخ ابن معين (٣/ ٦٧٩)، المغنى (٢ /ت ٧١٥٦)، الأنساب (٨/ ٣٣٤)، المجروحين (٣/ ١٠٦)، الضعفاء الكبير (٤/ ٣٩٠)، لسان الميزان (٧/ ٤٤٤)، الكامل لابن عدى (٩/ ١٥٠)."],[11879,"(٣) كذا بالمخطوط، وهو تصحيف عن يزيد بن بزيع الرملى. وقد سبق."],[11880,"(٤) سبق، وهو يحيى بن السكن."],[11881,"(٥) لم أقف له على ترجمة."],[11882,"٨٨٥ - يوسف بن مهران"],[11883,"(١)"],[11884,"وسئل صدقة بن الفضل المروزى، عن يوسف بن مهران، فقال: هو شيخ."],[11885,"٨٨٦ - يحيى بن عبيد الله"],[11886,"(٢)"],[11887,"قال السباك، عن عبيد الله، عن يحيى: إنه ترك حديث يحيى بن عبيد الله، وهو ابن موهب."],[11888,"٨٨٧ - يحيى الأفريقى"],[11889,"(٣)"],[11890,"على بن المدينى قال: رأيت يحيى ضعف يحيى الأفريقى."],[11891,"٨٨٨ - يحيى بن عبد الله"],[11892,"(٤)"],[11893,"ابن أبى خيثمة قال: سمعت يحيى بن معين يقول: يحيى بن عبد الله يروى عن أبيه، عن أبى هريرة، ليس بشئ."],[11894,"٨٨٩ - يوسف بن أبى ذرة"],[11895,"(٥)"],[11896,"روى عنه أنس بن عياض، قال: لا شئ."],[11897,"٨٩٠ - يزيد بن أبى زياد"],[11898,"(٦)"],[11899,"قال: وسئل عن يزيد بن أبى زياد، فقال: ليس بذاك."],[11900,"٨٩١ - يزيد بن إبراهيم"],[11901,"(٧)"],[11902,"(١) هو: يوسف بن مهران البصرى."],[11903,"انظر: تهذيب الكمال (٣٢/ ت ٧١٥٨)، الجرح والتعديل (٩/ ت ٩٦٢)، ميزان الاعتدال (٤ /ت ٩٨٨٨)، تهذيب التهذيب (١١/ ٤٢٤)."],[11904,"(٢) سبق."],[11905,"(٣) هو: يحيى بن عطاء الجفرى الأفريقى."],[11906,"انظر: ميزان الاعتدال (٤/ ٩٥٣٣)، المغنى (٦٩٨٥)."],[11907,"(٤) سبق."],[11908,"(٥) هو: يوسف بن أبى درة الأنصارى."],[11909,"انظر: تعجيل المنفعة (١٢٠٨)، ميزان الاعتدال (٤/ ت ٩٨٦٥)، لسان الميزان (٦/ ٣٢٠)، دائرة معارف الأعلمى (٣٠/ ٢١٠)، ديوان الضعفاء (٤٨٠٥)، مجمع الزوائد (١٠/ ٢٠٥)، المغنى (٢ / ت ٧٢٣٥)."],[11910,"(٦) سبق."],[11911,"(٧) هو: يزيد بن إبراهيم التسترى، أبو سعيد البصرى التميمى، مولاهم. ="],[11912,"على قال: قال يحيى: يزيد بن إبراهيم، عن قتادة، ليس بذاك."],[11913,"٨٩٢ - يعلى أبو أمية بن يعلى"],[11914,"(١)"],[11915,"ابن أبى خيثمة قال: سمعت يحيى يقول: يعلى أبو أمية بن يعلى ليس حديثه بشئ، وقال مرة أخرى: ضعيف."],[11916,"٨٩٣ - يوسف بن خالد السمتى"],[11917,"(٢)"],[11918,"كذاب."],[11919,"٨٩٤ - يزيد بن عطاء"],[11920,"(٣)"],[11921,"قال: وسمعته يقول: يزيد بن عطاء ضعيف الحديث، وهو مولى أبى عوانة."],[11922,"وقال مرة أخرى: ليس بشئ."],[11923,"٨٩٥ - يحيى بن أبى أنيسة"],[11924,"(٤)"],[11925,"قال: وسمعته يقول: يحيى بن أبى أنيسة ضعيف، وهو أخو زيد بن أبى أنيسة."],[11926,"٨٩٦ - يحيى الجابر"],[11927,"(٥)"],[11928,"=انظر: تهذيب الكمال (٣٢ /ت ٦٩٥٩)، تهذيب التهذيب (١١/ ٣١١)، التاريخ الكبير (٨ /ت ٣١٥٩)، الجرح والتعديل (٩ /ت ١٠٥٧)، الكاشف (٣ /ت ٦٣٨٤)، معرفة الثقات (٢٠٠٣)، تاريخ الثقات (٤٧٧)، المغنى (٢ /ت ٧٠٨٣)، الثقات (٧/ ٦٣١)، تاريخ أسماء الثقات (١٥٧١)، لسان الميزان (٧/ ٤٣٩)، الكامل لابن عدى (٩/ ١٧١)."],[11929,"(١) لم أقف له على ترجمة."],[11930,"(٢) و(٣) سبق."],[11931,"(٤) هو: يحيى بن أبى أنيسة، واسمه: زيد، ويقال: أسامة الغنوى، مولاهم أبو زيد الجزرى."],[11932,"انظر: تهذيب الكمال (٣١ /ت ٦٧٨٩)، الجرح والتعديل (٩ /ت ٥٥٠)، الكاشف (٣ /ت ٦٢٣٨)، ميزان الاعتدال (٤ /ت ٩٤٦٣)، تهذيب التهذيب (١١/ ١٨٣)، تاريخ الإسلام (٦/ ١٤٧)، الجرح والتعديل (٩/ ٥٥٠)، المجروحين (٣/ ١١٠)، تاريخ ابن معين، رواية الدورى (٢/ ٦٤٠)، ديوان الضعفاء (٤٦٠٢)، الأنساب (٦/ ٢٠٥)، تراجم الأحبار (٤/ ٣٠٣)."],[11933,"(٥) هو: يحيى بن عبد الله بن الحارث الجابر، ويقال: المجبر التيمى البكرى، مولاهم أبو الحارث الكوفى، كان يجبر الأعضاء."],[11934,"انظر: تهذيب الكمال (٣١ /ت ٦٨٥٩)، الجرح والتعديل (٩ /ت ٦٦٧)، الكاشف (٣ /ت = قال: وسمعته يقول: يحيى الجابر لا شئ."],[11935,"٨٩٧ - يحيى الشحام"],[11936,"(١)"],[11937,"قال: وذكر يحيى الشحام، فقال: نعرف وننكر."],[11938,"٨٩٨ - يحيى بن مسلم"],[11939,"(٢)"],[11940,"قال: وسمعته يقول: يحيى بن مسلم، ليس حديثه بشئ، روى عنه عبد الله بن داود، وروى عن زيد بن وهب."],[11941,"على قال: سألت [..........] (٣)."],[11942,"٨٩٩ - يحيى بن عيسى"],[11943,"(٤)"],[11944,"قال: وسمعته يقول: يحيى بن عيسى الرملى، ليس حديثه بشئ."],[11945,"٩٠٠ - يحيى البكاء"],[11946,"(٥)"],[11947,"= ٦٢٩٨)، ميزان الاعتدال (٤ / ت ٩٥٥٩)، تهذيب التهذيب (١١/ ٢٣٧)، تاريخ ابن معين (٢/ ٦٥٠)، تاريخ الإسلام (٥/ ٣١٢)، سؤالات البرقانى (٥٢٨)، التاريخ الكبير (٨/ ٢٨٦)، المغنى (٢ / ت ٧٠٠١)."],[11948,"(١) لم أقف له على ترجمة."],[11949,"(٢) هو: يحيى بن مسلم الهمدانى، أبو الضحاك الكوفى."],[11950,"انظر: تهذيب الكمال (٣١ / ت ٦٩٢٢)، تهذيب التهذيب (١١/ ٢٧٩)، التاريخ الكبير (٨ / ت ٣١٠٣)، ميزان الاعتدال (٤ / ت ٩٦٣٢)، الجرح والتعديل (٩ / ت ٧٧٦)."],[11951,"(٣) ما بين المعقوفين غير ظاهر بالمخطوط، وأظنه باقى أقوال ابن معين فيه \"يحيى بن مسلم الكوفى ضعيف\" والله أعلم."],[11952,"(٤) هو: يحيى بن عيسى الرملى الخزاز، وهو ابن عيسى بن عبد الرحمن، أبو زكريا كوفى الأصل، سكن الرملة، كان يختلف إلى العراق."],[11953,"انظر: تهذيب الكمال (٣١ /ت ٦٨٩٦)، تهذيب التهذيب (١١/ ٢٦٣)، التاريخ الكبير (٨ / ت ٣٠٦٣)، الجرح والتعديل (٩ / ت ٧٣٩)، الكاشف (٣ / ت ٦٣٣١)، الإكمال (٥/ ١١٢)، تراجم الأحبار (٤/ ٣١٣)، معرفة الثقات (١٩٩١)، تاريخ أسماء الثقات (١٦١١)، تاريخ الإسلام (٦/ ١٥١)، تبصير المنتبه (٤/ ١٤٨٦)، الثقات (٧/ ٦٠٩)، الكامل لابن عدى (٩/ ٦٠)."],[11954,"(٥) هو: يحيى بن مسلم، ويقال: ابن سليم، ويقال: ابن أبى خليد الأزدى، أبو سليم، ويقال: أبو السلم، ويقال: أبو مسلم، ويقال: أبو الحكم البصرى المعروف بيحيى البكاء، مولى القاسم بن ="],[11955,"قال: وسمعته يقول: يحيى البكاء ليس بذاك."],[11956,"قال: حدثنا عبيد الله بن عمر قال: لم يكن يحيى بن سعيد يرضى يحيى البكاء."],[11957,"٩٠١ - يزيد الرشك"],[11958,"(١)"],[11959,"قال: وسئل عن يزيد الرشك، فقال: ضعيف، قال: وحدثنا يحيى بن معين قال: كان ابن علية يضعف يزيد الرشك."],[11960,"* * *"],[11961,"= الفضل الحدانى."],[11962,"انظر: تهذيب الكمال (٣١ /ت ٦٩٢٠)، التاريخ الكبير (٨ / ت ٢٩٣٦)، الجرح والتعديل (٩ / ت ٧٧٥)، الكاشف (٣ /ت ٦٣٥٣)، ديوان الضعفاء (٦٣٦)، الأنساب (٢/ ٢٨٧)، المغنى (٢ /ت ٧٠٥٣)، المجروحين (٣/ ١٠٩)، سير أعلام النبلاء (٥/ ٣٥٠)، ضعفاء ابن الجوزى (٣/ ٢٠٣)، الكامل لابن عدى (٩/ ١٣)."],[11963,"(١) سبق."],[11964,"١٧ - باب الكنى والألقاب"],[11965,"٩٠٢ - أبو المغيرة القواس"],[11966,"(١)"],[11967,"على بن المدينى قال: قال يحيى: كان التيمى سيئ الرأى فى عبد الله بن شقيق، قال: قلت له: فأبو المغيرة القوّاس؟ قال: كان شرًا عنده منه."],[11968,"قال يحيى: ولم أر أحدًا عرف أبا المغيرة غيره."],[11969,"٩٠٣ - أبو شهاب الحناط"],[11970,"(٢)"],[11971,"على قال: سمعت يحيى يقول: لم يكن أبو شهاب الحناط بالحافظ، ولم يرض يحيى أمره (٣)."],[11972,"٩٠٤ - أبو واقد الليثى"],[11973,"(٤)"],[11974,"على قال: سمعت عبد الرحمن قال: أخبرنى وهيب قال: قدم علينا أبو واقد الليثى يعد (٥) صالح بن محمد بن زائدة، قال: فسمعته يحدث قال: فلو شئت أن أكتب عندكم، قال: فتركه."],[11975,"(١) انظر: ميزان الاعتدال (٤/ ت ١٠٦٣٠)، الثقات لابن حبان (٥/ ٥٦٥)، الكنى والأسماء (٢/ ١٢٤)، الجرح والتعديل (٩/ ٤٣٤)، تفسير الطبرى (١١/ ١٣٠٢٥، ٢٦)، المغنى (٢/ ت ٧٧٥٠)."],[11976,"(٢) هو: عبد ربه بن نافع، وهو ثقة من رجال الصحيحين، الكوفى، ثم المدائنى، توفى سنة اثنتين وسبعين ومائة، وقيل: إحدى وسبعين، وهو أبو شهاب الأصغر."],[11977,"انظر: الطبقات الكبرى (٦/ ٣٩١)، المعرفة والتاريخ للفسوى (٢/ ١٧٠)، تهذيب التهذيب (٦/ ١٢٨)، تاريخ بغداد (١١/ ١٢٨)، العبر (١/ ٢٦٠)، سير أعلام النبلاء (٨/ ٢٢٦)، ميزان الاعتدال (٢/ ت ٤٨٠٠)، الجرح والتعديل (٦/ ت ٢١٧)، الكاشف (٢/ ت ٣١٦٦)، التاريخ الكبير (٦/ ت ١٧٧٣)."],[11978,"(٣) هذ! موقف يحيى بن سعيد القطان منه، وآخرون على غير موقفه."],[11979,"(٤) هو: صالح بن محمد بن زائدة المدنى، أبو واقد الليثى الصغير."],[11980,"انظر: تهذيب الكمال (١٣ / ت ٢٨٣٥)، تهذيب التهذيب (٤/ ٤٠١)، التاريخ الكبير (٤/ ت ٢٨٦٢)، الجرح والتعديل (٤ / ت ١٨١٠)، الكاشف (٢ / ت ٢٣٧٨)، ميزان الاعتدال (٢ / ت ٣٨٢٤)."],[11981,"(٥) هذه الكلمة لا أدرى لما وجدت هنا: فلعلها سهو من الناسخ، والله أعلم."],[11982,"٩٠٥ - ابن أبى المهدى سعيد بن سنان الحمصى"],[11983,"(١)"],[11984,"محمد بن نصر قال: قال محمد بن يوسف: سألت أحمد بن حنبل، عن ابن أبى المهدى سعيد بن سنان الحمصى؟، فقال: أحاديثه منكرات، كلها يروى لابن عمر أشياء لم يروها أحد من أصحابه."],[11985,"٩٠٦ - أبو هلال الراسبى"],[11986,"(٢)"],[11987,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن أبى هلال الراسبى؟، فقال: ليس بصاحب كتاب وهو ضعيف الحديث."],[11988,"٩٠٧ - ابن أبى حرملة"],[11989,"(٣)"],[11990,"ابن المدينى قال: قلت ليحيى: ما رأيت ابن أبى حرملة، لو شئت أن ألقنه أشياء، فقلت: كان يلقن، قال: نعم."],[11991,"٩٠٨ - أبو واقد"],[11992,"(٤)"],[11993,"قال ابن أبى خيثمة: وسئل يحيى بن معين، عن واقد الذى روى عنه وهب؟، فقال: ضعيف، قال: وسئل عن حديث وهب (٥)، قال: حدتنى أبو واقد قال: حدثنى أبو أروى، قال: ضعيف."],[11994,"٩٠٩ - ابن أنيس بن أبى يحيى"],[11995,"(٦)"],[11996,"(١) هو: سعيد بن سنان، أبو مهدى الحنفى، ويقال: الكندى الحمصى."],[11997,"انظر: تهذيب الكمال (١٠ / ت ٢٢٩٥)، تهذيب التهذيب (٤/ ٤٦)، الجرح والتعديل (٤ / ت ١١٤)، الكاشف (١ /ت ١٩٢٥)، ميزان الاعتدال (٢ /ت ٣٢٠٨)، التاريخ الكبير (٣ /ت ١٥٩٨)، تاريخ بغداد (٦٥١٩)، تاريخ الإسلام (٦/ ١٨٢)، المغنى (١ /ت ٢٤١٠)، ديوان الضعفاء (١٦١٨)، تاريخ ابن معين (٢/ ٢٠١)، الكامل لابن عدى (٤/ ٣٩٩)."],[11998,"(٢) سبق."],[11999,"(٣) هو: محمد بن أبى حرملة القرشى، أبو عبد الله المدنى، مولى عبد الرحمن بن أبى سفيان بن حويطب."],[12000,"انظر: تهذيب الكمال (٢٥ /ت ٥١٣٩)، التاريخ الكبير (١ /ت ١٢٩)، الجرح والتعديل (٧ /ت ١٣٢٢)، الكاشف (٣ /ت ٤٨٥٦)."],[12001,"(٤) سبق، وهو صالح بن محمد بن زائدة المدنى."],[12002,"(٥) كذا بالمخطوط، وهو تصحيف، والصواب، والله أعلم، وهيب بن خالد."],[12003,"(٦) هو: حاتم بن أنيس بن أبى يحيى. ="],[12004,"قال: وسمعته يقول: ابن أنيس بن أبى يحيى لا يكتب حديثه."],[12005,"٩١٠ - أبو حمزة"],[12006,"(١)"],[12007,"قال: وسئل عن أبى حمزة الذى روى عنه إبراهيم، قال: اسمه ميمون، كوفى، ضعيف الحديث، وهو الذى حدث عنه حماد بن سلمة، وقد حدَّث عنه منصور بن المعتمر، قال: حدثنا أبى، حدثنا جرير، عن منصور، عن أبى حمزة، عن سعيد بن المسيب، فسئل يحيى بن معين، عن حديث منصور عن أبى حمزة؟، قال: قال أبو حمزة: ميمون القصاب: ليس بشئ."],[12008,"٩١١ - أبو الغيث"],[12009,"(٢)"],[12010,"قال: وسمعت يحيى بن معين يقول: أبو الغيث الذى يروى عنه ثور بن زيد ليس بثقة (٣)."],[12011,"٩١٢ - أبو الجمل"],[12012,"(٤)"],[12013,"قال: حدثنا أيوب بن محمد أبو الجمل، سئل يحيى بن معين، عن أبى الجمل، فقال: اسمه أيوب لا شئ."],[12014,"٩١٣ - أبو الوداك"],[12015,"(٥)"],[12016,"= انظر: الجرح والتعديل (٣ / ت ١١٦٢)، ديوان الضعفاء (٨٠٢)، دائرة معارف الأعلمى (١٥/ ١٨٩)، لسان الميزان (٢/ ١٤٥)، ميزان الاعتدال (١/ ٤٢٨)، المغنى (١ / ت ١٢١٠)."],[12017,"(١) هو: ميمون أبو حمزة الأعور القصاب الكوفى الراعى."],[12018,"انظر: تهذيب الكمال (٢٩ / ت ٦٣٤٦)، تهذيب التهذيب (١٠/ ٣٩٥)، التاريخ الكبير (٧ / ت ١٤٧٧)، الجرح والتعديل (٨ / ت ١٠٦١)، الكاشف (٣ / ت ٥٨٦٦)، ميزان الاعتدال (٤ / ت ٨٩٦٩)."],[12019,"(٢) هو: سالم أبو الغيث المدنى، مولى ابن مطيع."],[12020,"انظر: تهذيب الكمال (١٠/ ت ٢١٦٣)، تهذيب التهذيب (٣/ ٤٤٥)، الجرح والتعديل (٤ / ت ٨١٨)، التاريخ الكبير (٤ / ت ٢١٣٤)."],[12021,"(٣) لم أقف على قول ابن معين هذا، وجاء الجرح والتعديل وتهذيب التهذيب، قال: إنه ثقة."],[12022,"(٤) هو: أيوب بن محمد، يكنى: أبا سهل يمامى، لقبه: أبو الجمل."],[12023,"انظر: الكامل لابن عدى (٢/ ١٨)، الجرح والتعديل (٢/ ٢٥٧)، المغنى (٢ / ت ٧٣٨٢)، الضعفاء والمتروكين (١/ ١٣٣)، ميزان الاعتدال (٤/ ٧٣٥)، الكنى والأسماء (١/ ١٣٨)."],[12024,"(٥) هو: جبر بن نوف الهمدانى البكالى، أبو الوداك الكوفى. ="],[12025,"قال: وسمعته يقول: أبو الوداك ثقة ما له ولأبى هارون (١)."],[12026,"٩١٤ - أبو هارون العبدى"],[12027,"(٢)"],[12028,"قال: وسمعت أحمد بن حنبل، يقول: لا يكتب حديث أبى هارون العبدى، قال: وقال يحيى: أبو هارون بصرى، اسمه: عمارة بن جوين."],[12029,"٩١٥ - أبو الغصن"],[12030,"(٣)"],[12031,"قال: وسمعته وسئل عن أبى الغصن؟، فقال: ضعيف."],[12032,"٩١٦ - أبو الأعشى العبيدى"],[12033,"(٤)"],[12034,"قال: وسئل عن أبى الأعشى العبيدى، عن أبى الأحوص؟، فقال: ضعيف لا يعرف."],[12035,"٩١٧ - أبو حمزة"],[12036,"(٥)"],[12037,"قال: وسئل عن أبى حمزة الذى روى عن سعيد بن المسيب، وروى عنه منصور بن"],[12038,"المعتمر؟ فقال: ميمون القصاب أبو حمزة، ليس بشئ."],[12039,"على قال: قلت ليحيى: قال لكم أبو حمزة فى سماعه نحو مما قال ميمون المرائى؟ (٦)،"],[12040,"= انظر: تهذيب الكمال (٤ / ت ٨٩٥)، تهذيب التهذيب (٢/ ٦٠)، التاريخ الكبير (٢/ ٢٤٣)، الجرح والتعديل (٥٣٢/ ١/١)، الكاشف (١/ ١٧٩)."],[12041,"(١) يقصد أنه خير من أبى هارون."],[12042,"(٢) هو: عمارة بن جوين، أبو هارون العبدى البصرى."],[12043,"انظر: تهذيب الكمال (٢١/ ت ٤١٧٨)، تهذيب التهذيب (٧/ ٤١٣)، التاريخ الكبير (٦ /ت ٣١٠٧)، الجرح والتعديل (٦ /ت ٢٠٠٥)، الكاشف (٢ / ت ٤٠٦٢)."],[12044,"(٣) هو: ثابت بن قيس الغفارى، مولاهم، أبو الغصن المدنى، مات سنة (١٦٨)."],[12045,"انظر: تهذيب الكمال (٤ /ت ٨٢٩)، تهذيب التهذيب (٢/ ١٣)، التاريخ الكبير (٢/ ١/ ١٦٧)، الجرح والتعديل (٤٥٦/ ١/١)، المجروحين (١/ ٢٠٦)، الكاشف (١/ ١٧٢)، ميزان الاعتدال (١/ ٣٦٦)، الوافى بالوفيات (١٠/ ٤٦٢)، ضعفاء ابن الجوزى (١/ ١٥٩)، الثقات (٤/ ٩٠)، الكامل لابن عدى (٢/ ٢٩٢)."],[12046,"(٤) لم أقف له على ترجمة."],[12047,"(٥) سبق."],[12048,"(٦) هو: ميمون بن موسى المرائى البصرى، ويقال: إنه ابن ميمون بن عبد الرحمن بن صفوان بن قدامة."],[12049,"انظر: تهذيب الكمال (٢٩ /ت ٦٣٣٩)، تهذيب التهذيب (١٠/ ٣٩٢)، ميزان اعتدال (٤ / ت ="],[12050,"قال: نعم، وشر من ذاك، قلت: كيف؟، قال: قال منه ما سمعت، ومنه ما حفظه بعضنا عن بعض، ومنه ما لم نسمع حدثنا به أصحابنا."],[12051,"قال: فقيل ليحيى بن سعيد فى سعيد أخى أبى حمزة: أن عبد الرحمن كان يقول: كنت أتيت شيخ بالبصرة، فقال يحيى: إيش أقول كأنه يضعفه، قال: وسمعته يقول: أبو حمزة الثمالى (١)، ليس حديثه بشئ."],[12052,"٩١٨ - أبو حمزة الثمالى"],[12053,"(٢)"],[12054,"الحسين قال: حدثنا الحميدى، حدثنا سفيان، حدثنا أبو حمزة الثمالى."],[12055,"قال الحميدى: أبو حمزة فيه ضعف، وكان وكيع إذا حدث عنه قال: حدثنا ثابت بن أبى صفية."],[12056,"٩١٩ - أبو ظلال"],[12057,"(٣)"],[12058,"ابن أبى خيثمة قال: سئل يحيى بن معين، عن أبى ظلال ما اسمه؟، فقال: هلال، وسئل عنه فقال: لا شئ."],[12059,"٩٢٠ - أبو دراس"],[12060,"(٤)"],[12061,"قال: وسمعته يقول: أبو دارس صاحب الجوز ضعيف الحديث."],[12062,"٩٢١ - أبو خلف موسى بن خلف"],[12063,"(٥)"],[12064,"= ٨٩٦٦)، الجرح والتعديل (٨ / ت ١٠٦٥)، الكاشف (٣ / ت ٥٦٢)، التاريخ الكبير (٤ / ت ٨٩٦٦)."],[12065,"(١) أبو حمزة الثمالى، هو: ثابت بن أبى صفية، واسم أبيه: دينار، وقيل: سعد الأزدى الكوفى مولى المهلب."],[12066,"أما أبو حمزة القصاب فهو: ميمون أبو حمزة الأعور القصاب الكوفى الراعى."],[12067,"(٢) انظر السابق."],[12068,"(٣) هو: هلال بن أبى هلال، ويقال: ابن أبى مالك، واسم أبيه: ميمون، ويقال: يزيد، ويقال: زيد أبو ظلال القسملى البصرى الأعمى."],[12069,"انظر: تهذيب الكمال (٣٠/ ت ٦٦٣٢)، تهذيب التهذيب (١١/ ٨٤)، الجرح والتعديل (٩ / ت ٢٨٦)، الكاشف (٣ / ت ٦١٠٩)، التاريخ الكبير (٨ / ت ٢٧٢٣)."],[12070,"(٤) هر: أبو دِراسٍ، أو أبو دارسٍ، روى عنه عبد الصمد، ضعفه ابن معين."],[12071,"انظر: ميزان الاعتدال (٤ / ت ١٠١٧١)، المغنى (٢ / ت ٧٤٥٠)."],[12072,"(٥) هو: موسى بن خلف العمى، أبو خلف البصرى العابد.="],[12073,"قال: وسمعته يقول: وسئل عن أبى خلف موسى بن خلف؟ قال: روى عنه عفان"],[12074,"ضعيف."],[12075,"٩٢٢ - أبو معاذ"],[12076,"(١)"],[12077,"قال: وسمعت أحمد بن حنبل يقول: أبو معاذ الذى روى عنه الثورى عن الحسن"],[12078,"اسمه: سليمان بن أرقم وليس بشئ."],[12079,"٩٢٣ - عليلة بن بدر"],[12080,"(٢)"],[12081,"قال ابن أبى خيثمة: وسمعت يحيى بن معين يقول: عليلة بن بدر ليس حديثه بشئ، وهو الربيع بن بدر."],[12082,"٩٢٤ - أبو الربيع السمان"],[12083,"(٣)"],[12084,"=انظر: تهذيب الكمال (٢٩ /ت ٦٢٥٠)، تهذيب التهذيب (١٠/ ٣٤١)، التاريخ الكبير (٧ /ت ١١٩٧)، الجرح والتعديل (٨ /ت ٦٣٤)، الكاشف (٣/ ١٨٣)، ميزان الاعتدال (٤ /ت ٨٨٥٨)، تاريخ أسماء الثقات (١٣٥٧)، تاريخ بغداد (١٣/ ٤٩)، الأنساب (٣٨١/ ٩)، المغنى (٢ /ت ٦٤٨٦)، علل أحمد (٢/ ٣٣٤)، ضعفاء ابن الجوزى (٣/ ١٤٥)، الكامل لابن عدى (٨/ ٦١)."],[12085,"(١) هو: سليمان بن أرقم، أبو معاذ البصرى، مولى الأنصار، وقيل: مولى قريش، وقيل: مولى قريظة أو النضير."],[12086,"انظر: تهذيب الكمال (١١ / ت ٢٤٩١)، تهذيب التهذيب (٤/ ١٦٨)، الجرح والتعديل (٤ / ت ٤٥٠)، ميزان الاعتدال (٢ / ت ٣٤٢٧)، الكاشف (١/ ٢٠٨٩)، التاريخ الكبير (٤ / ت ١٧٥٦)، تاريخ ابن معين، رواية الدورى (٢/ ٢٢٨)، علل أحمد (١/ ٢٣٦، ٣٩٨)، الكامل لابن عدى (٤/ ٢٢٨)."],[12087,"(٢) الربيع بن بدر بن عمرو بن جرار التيمى السعدى الأعرجى، ويقال: العرجى، أبو العلاء البصرى المعروف بعليلة، وهو لقب."],[12088,"انظر: تهذيب الكمال (٩ / ت ١٨٥٤)، تهذيب التهذيب (٣/ ٢٣٩)، الجرح والتعديل (٣ / ت ٢٠٥٧)، الكاشف (١/ ٣٠٣)، تاريخ بغداد (٤١٥١٨)، التاريخ الكبير (٣ / ت ٩٥٧)، المغنى (١ / ت ٢٠٨٧)، المجروحين (١/ ٢٩٧)، ميزان الاعتدال (٢/ ٢٧٣٠)، ضعفاء النسائى (٢٠٠)، أحوال الرجال (١٢٧)، الكامل لابن عدى (٤/ ٢٩)."],[12089,"(٣) هو: أشعث بن سعيد البصرى، أبو الربيع السمان."],[12090,"انظر: تهذيب الكمال (٣ /ت ٥٢٣)، تهذيب التهذيب (١/ ٣٥١)، الجرح والتعديل (٢/ ٢٧٢)، = قال: وسمعته يقول: أبو الربيع السمان، ليس حديثه بشئ ضعيف."],[12091,"٩٢٥ - أبو حفص"],[12092,"(١)"],[12093,"قال: وسمعته يقول: أبو حفص، ليس حديثه بشئ."],[12094,"٩٢٦ - أبو بكر بن أبى الأسود"],[12095,"(٢)"],[12096,"قال: وكان سيئ الرأى فى أبى بكر ابن أبى الأسود بن أخت عبد الرحمن بن مهدى، وهو عبد الله بن محمد (٣) بن حميد بن أسود بن أبى الأسود."],[12097,"٩٢٧ - أبو عبد الله محمد بن كثير"],[12098,"(٤)"],[12099,"قال: ولا تكتبوا عن أبى عبد الله محمد بن كثير أخى سليمان بن كثير العبدى."],[12100,"٩٢٨ - ابن عائشة"],[12101,"(٥)"],[12102,"قال: وسمعته، وقال له إنسان: إن ابن عائشة، فسر: لعن الله من غير منار الأرض،"],[12103,"= تاريخ ابن معين (٢/ ٤٠)، المجروحين (١/ ١٧٣)، ميزان الاعتدال (١/ ٢٣٦)، الضعفاء والمتروكين للدارقطنى (١١٣)، التاريخ الكبير (١/ ٤٣٠)، المغنى (١ / ت ٧٥٥)."],[12104,"(١) لم أستطع الوقوف عليه ولا تحديده."],[12105,"(٢) هو: عبد الله بن محمد بن أبى الأسود، حميد بن الأسود البصرى الحافظ، أبو بكر القاضى بهمدان، ابن أخت عبد الرحمن بن مهدى."],[12106,"انظر: تهذيب الكمال (١٦ / ت ٣٥٢٩)، تهذيب التهذيب (٦/ ٦)، ميزان الاعتدال (٢ / ت ٤٥٥٩)، تاريخ بغداد (٦٢/ ١)، التاريخ الكبير (٥ / ت ٥٩٤)، طبقات الحفاظ (٢١٥)، تذكرة الحفاظ (٢/ ٤٩٣)، المعجم المشتمل (١٥٩)، الجرح والتعديل (٥ / ت ٧٣٣)، سير أعلام النبلاء (١٠/ ٦٤٨)، الكاشف (٢/ ١٢٥)."],[12107,"(٣) جاء بالمخطوط \"يحيى\"، وهو تصحيف."],[12108,"(٤) هو: محمد بن كثير العبدى، أبو عبد الله البصرى، توفى سنة ثلاث وعشرين ومائتين، وكان تقيًا فاضلًا، قال ابن حجر: لم يصب من ضعفه."],[12109,"انظر: تهذيب الكمال (٢٦ / ت ٣٣٤)، التاريخ الكبير (١ / ت ٦٨٥)، الجرح والتعديل (٨ / ت ٣١١)، الكاشف (٣ / ت ٥٢٠٨)، ميزان الاعتدال (٤ / ت ٨٠٩٩)."],[12110,"(٥) هو: عبيد الله بن محمد بن حفص بن عمر بن موسى بن عبيد الله بن معمر التيمى، أبو عبد الرحمن البصرى، المعروف بالعيشى، والعائشى، وبابن عائشة؛ لأنه من ولد عائشة بنت طلحة."],[12111,"انظر: تهذيب الكمال (١٩/ ت ٣٦٧٨)، تهذيب التهذيب (٧/ ٤٥)، الكاشف (٢ / ت ٣٦٣٣)، التاريخ الكبير (٥ / ت ١٢٩٢)، الجرح والتعديل (٥ / ت ١٥٨٣)."],[12112,"أنهم العلماء يفسدهم السلطان فيتغيرون، فقال: قبحه الله قد كنت أرى أنه يحسن شيئًا، منار الأرض حدودها. على قال: قال يحيى: كان شعبة ينكر أن ظبيان سمع سلمان."],[12113,"٩٢٩ - أبو صادق"],[12114,"(١)"],[12115,"ابن أبى خيثمة قال: حدثنا خالد بن خداش، حدثنا أبو بكر بن شعيب، عن أبيه قال: رأيت أبا صادق صلى فى قطيفة."],[12116,"قال: فقال له رجل: ما يقول فى عثمان؟ قال: إنى لأشنوه."],[12117,"٩٣٠ - أبو حمزة القصاب"],[12118,"(٢)"],[12119,"قال: وسمعت يحيى بن معين يقول: أبو حمزة القصاب لا يكتب حديثه وهو ميمون الأعور."],[12120,"٩٣١ - أبو العلاء"],[12121,"(٣)"],[12122,"قال: وسئل عن حديث يزيد بن هارون، قال: أخبرنا أصبع بن زيد، عن أبى العلاء،"],[12123,"عن أبى أمامة، قال: لبس عمر ثوبًا جيدًا فكتب على أبى العلاء بخطه ليس بشئ."],[12124,"٩٣٢ - أبو الزاهرية"],[12125,"(٤)"],[12126,"قال: وسئل عن أبى الزاهرية روى عنه أصبع بن زيد فقال: لا شئ."],[12127,"٩٣٣ - أبو عبد الله البكرى"],[12128,"(٥)"],[12129,"قال: وسئل عن أبى عبد الله البكرى، روى عنه هشيم بن بشير؟، فقال: لا ندرى"],[12130,"(١) هو: أبو صادق الأزدى الكوفى من أزد شنوءة، وقيل: اسمه مسلم بن يزيد، وقيل: عبد الله بن ناجد."],[12131,"انظر: تهذيب الكمال (٣٣ /ت ٧٤٣٣)، تهذيب التهذيب (١٢/ ١٣٠)."],[12132,"(٢) سبق."],[12133,"(٣) لم أستطع تحديده، والله أعلم."],[12134,"(٤) هو: حدير بن كريب الحضرمى، ويقال: العميرى أبو الزاهرية الحمصى، توفى سنة (١٢٩)."],[12135,"انظر: تهذيب الكمال (٥/ ١١٤٤)، طبقات ابن سعد (٧/ ٤٥٠)، التاريخ الكبير (٣ /ت ٣٤٠)، الجرح والتعديل (٣ /ت ١٣١٣)، الكاشف (١/ ٢١٠)، تهذيب التهذيب (٢/ ٢١٨)."],[12136,"(٥) هو: أبو عبد الله البكرى عن سعيد المقبرى، وعنه هشيم، لا شئ غمز ابن حبان."],[12137,"انظر: ميزان الاعتدال (٤ /ت ١٠٣٧٠)، الضعفاء والمتروكين (٣/ ٢٣٤)، معرفة الرجال (١/ ١١٩، ٢/ ٣٧٣)، المجروحين (٣/ ١٤٨)، المغنى (٢ /ت ٧٥٧٩)."],[12138,"من أبو عبد الله."],[12139,"٩٣٤ - أبو جناب الكلبى"],[12140,"(١)"],[12141,"قال: وسمعته يقول: أبو جناب الكلبى ضعيف الحديث."],[12142,"٩٣٥ - ابن ثوبان"],[12143,"(٢)"],[12144,"قال: وسئل عن ابن ثوبان روى عنه الوليد بن مسلم؟، فقال: لا شئ."],[12145,"٩٣٦ - أبو سفيان السروجى"],[12146,"(٣)"],[12147,"قال: وقال أبو سفيان السروجى عبد الرحيم بن مطرف ابن عم وكيع يكره الحديث،"],[12148,"عن أبى عبدالله العدوى."],[12149,"٩٣٧ - أبو معاذ"],[12150,"(٤)"],[12151,"قال: وسمعت أحمد بن حنبل يقول: أبو معاذ الذى روى عنه سفيان الثورى، عن"],[12152,"الحسن اسمه سليمان بن أرقم ليس بشئ."],[12153,"٩٣٨ - أبو مالك النخعى"],[12154,"(٥)"],[12155,"(١) هو: يحيى بن أبى حية، أبو جناب الكلبى الكوفى، واسم أبى حية حيى."],[12156,"انظر: نهذيب التهذيب (١١/ ٢٠١)، تهذيب الكمال (٣١ /ت ٦٨١٧)، التاريخ الكبير (٨ /ت ٢٩٥٤)، الجرح والتعديل (٩ / ت ٣٢٢)، الكاشف (٣ / ت ٦٢٦٤)، ميزان الاعتدال (٤ / ت ٩٤٩١)، تاريخ ابن معين (٣/ ٦٤٢)، طبقات ابن سعد (٦/ ٣٦)، معرفة الثقات (١٩٧٣)، ضعفاء ابن الجوزى (٣/ ١٩٣)، تاريخ الثقات (٤٧١)، المغنى (٢ / ت ٦٩٥٤)، المجروحين (٣/ ١١١)، الكامل لابن عدى (٩/ ٥٠)."],[12157,"(٢) هو: عبد الرحمن بن ثابت بن ثوبان العنسى، أبو عبد الله الدمشقى الزاهد."],[12158,"انظر: تهذيب الكمال (١٧/ ت ٣٧٧٥)، تهذيب التهذيب (٦/ ١٥٠)، الكاشف (٢ / ت ٣١٩٦)، ميزان الاعتدال (٢ /ت ٤٨٢٨)، الجرح والتعديل (٥/ ت ١٠٣١)، التاريخ الكبير (٥ / ت ٨٥٦)، سير أعلام النبلاء (٧/ ٣١٣)، الثقات (٩٢/ ٧)، الكامل لابن عدى (٥/ ٤٦٠)."],[12159,"(٣) هو: عبد الرحيم بن مطرف بن أنيس بن قدامة بن عبد الرحمن الرؤاسى، أبو سفيان الكوفى، ثم السروجى ابن عم وكيع."],[12160,"انظر: تهذيب الكمال (١٨ / ت ٣٤٠٩)، تهذيب التهذيب (٦/ ٣٠٧)، الجرح والتعديل (٥ / ت ١١٦١)، الكاشف (٢ / ت ٣٤٠٣)."],[12161,"(٤) سبق."],[12162,"(٥) هو: أبو مالك النخعى الواسطى، اسمه: عبد الملك بن الحسين، ويقال: عبادة بن الحسين ="],[12163,"قال: وسمعت يحيى يقول: أبو مالك النخعى ليس حديثه بشئ."],[12164,"وأبو مالك النخعى: ضعيف الحديث."],[12165,"٩٣٩ - أبو عقيل"],[12166,"(١)"],[12167,"قال: وسمعته يقول: أبو عقيل صاحب بهية ليس حديثه بشئ."],[12168,"٩٤٠ - أبو قيس الدمشقى"],[12169,"(٢)"],[12170,"قال: وسمعته يقول: أبو قيس الدمشقى، ليس بشئ، روى عنه أبو معاوية."],[12171,"٩٤١ - ابن أبى لبيبة"],[12172,"(٣)"],[12173,"= ويعرف بابن ذر."],[12174,"انظر: تهذيب الكمال (٣٤ / ت ٧٥٩٩)، تهذيب التهذيب (١٢/ ٢١٩)، الجرح والتعديل (٥/ ٣٤٧)، لسان الميزان (٧/ ٢٩١)، الكامل لابن عدى (٦/ ٥٢٧)، ميزان الاعتدال (٢/ ٦٥٣)، المجروحين (٢/ ١٣٤)."],[12175,"(١) هو: يحيى بن المتوكل العمرى، أبو عقيل المدنى، ويقال: الكوفى الحذاء الضرير، صاحب بهية، مولى العمريين."],[12176,"انظر: تهذيب الكمال (٣١ / ت ٦٩٠٨)، التاريخ الكبير (٨ / ت ٣١٠٧)، الجرح والتعديل (٩ /ت ٧٨٨)، الكاشف (٣ /ت ٦٣٤٢)، ميزان الاعتدال (٤ / ت ٩٦١٤)، ضعفاء ابن الجوزى (٣/ ٢٠٢)، المجروحين (٣/ ١١٦)، الأنساب (٩٥/ ٤)، تاريخ بغداد (١٤/ ١٠٨)، المغنى (٢ / ت ٧٠٣٨)، الإكمال (٢٣٤/ ٦)، الكامل لابن عدى (٩/ ٣٩)."],[12177,"(٢) هو: محمد بن سعيد بن حسان بن قيس الأسدى المصلوب، ويقال: محمد بن سعيد بن عبد العزيز، ويقال: ابن اْبى عتبة، ويقال: ابن أبى قيس، ويقال ابن أبى حسان، ويقال: ابن الطبرى، ويقال: غير ذلك فى نسبه: أبو عبد الرحمن، ويقال: أبو عبد الله، ويقال: أبو قيس الشامى الدمشقى، ويقال: الأزدى."],[12178,"قال ابن حجر: قيل: إنهم قلبوا اسمه على مائة وجه ليخفى، كذبوه، وقال أحمد بن صالح: وضع أربعة آلاف حديث، وقتل على الزندقة وصلب."],[12179,"انظر: تهذيب الكمال (٢٥ / ت ٥٢٤١)، تهذيب التهذيب (٩/ ١٨٤)، الجرح والتعدبل (٧ /ت ١٤٣٦)، الكاشف (٣ / ت ٤٩٤٣)، ميزان الاعتدال (٣ / ت ٧٥٩٢)."],[12180,"(٣) هو: محمد بن عبد الرحمن بن لبيبة يقال: ابن أبى لبيبة، ويقال: إن لبيبة أمه، وأبا لبيبة أبوه، واسمه: وردان."],[12181,"انظر: تهذيب التهذيب (٩/ ٣٠١)، تهذيب الكمال (٢٥ / ت ٥٤٠٥)، التاريخ الكبير (١ /ت ٤٥٢)، الجرح والتعديل (٧ /ت ١٧٢٨)، الكاشف (٣ /ت ٥٠٧٢)، ميزان الاعتدال = قال: وسمعته يقول: ابن أبى لبيبة الذى يروى عنه، وكيع ليس بشئ."],[12182,"قال: وابن أبى لبيبة ليس حديثه بشئ."],[12183,"٩٤٢ - أبو أيوب الأفريقى"],[12184,"(١)"],[12185,"قال أبو حاتم الرازى: أبو أيوب الأفريقى، يقال له: عبد الله بن على، روى عنه ابن أبى زائدة، ليس بالمتين."],[12186,"٩٤٣ - أبو شيبة"],[12187,"(٢)"],[12188,"قال: وأبو شيبة إبراهيم بن عثمان جد أبى بكر بن أبى شيبة ضعيف الحديث."],[12189,"٩٤٤ - أبو بكر الداهرى"],[12190,"(٣)"],[12191,"قال: وأبو بكر الداهرى عبد الله بن حكيم ضعيف الحديث."],[12192,"٩٤٥ - وأبو إسرائيل الملائى"],[12193,"(٤)"],[12194,"حسن الحديث لا يحتج به، فى حديثه أوهام."],[12195,"٩٤٦ - وأبو بكر بن عبد الله بن أبى مريم الغسانى"],[12196,"(٥)"],[12197,"ضعيف الحديث وقّاع."],[12198,"= (٣ / ت ١٨٢٩)."],[12199,"(١) سبق."],[12200,"(٢) هو: إبراهيم بن عثمان بن خواستى، أبو شيبة العبسى، مولاهم الكوفى، قاضى واسط."],[12201,"انظر: تهذيب الكمال (٢ / ت ٢١٢)، تهذيب التهذيب (١/ ١٤٤)، تاريخ بغداد (٦/ ١١٣)، التاريخ الكبير (١/ ٣١٠)، الجرح رالتعديل (٢/ ١١٥)، المجروحين (١/ ١٤٠١)، طبقات ابن سعد (٦/ ٣٨٤)."],[12202,"(٣) هو: عبد الله بن حكيم، أبو بكر الداهرى الضبى البصرى."],[12203,"انظر: الكامل لابن عدى (٥/ ٢٢٦)، الضعفاء والمترركين (٢/ ١١٩)، الجرح والتعديل (٥/ ٤١)، المجروحين (٢/ ٢١)."],[12204,"(٤) سبق."],[12205,"(٥) هو: أبو بكر بن عبد الله بن أبى مريم الغسانى الشامى، وقد ينسب إلى جده، قيل: اسمه بكير، وقيل: عبد السلام، وقيل: بكر، وقيل: عمرو، وقيل: عامر."],[12206,"انظر: تهذيب الكمال (٣٣ / ت ٧٢٤١)، تهذيب التهذيب (١٢/ ٢٨)، المغنى (٢ / ت ٧٣٤١)، ميزان الاعتدال (ت ١٠٠٠٦)."],[12207,"٩٤٧ - وأبو فرة الجزرى الزهاوى"],[12208,"(١)"],[12209,"يكتب حديثه ولا يحتج به."],[12210,"٩٤٨ - وأبو مالك الجنبى"],[12211,"(٢)"],[12212,"عمرو بن هاشم لين الحديث."],[12213,"٩٤٩ - والأجلح يحيى بن عبد الله بن حجية الكندى"],[12214,"(٣)"],[12215,"يكتب حديثه، ولا يحتج به."],[12216,"٩٥٠ - أبو عاتكة البصرى"],[12217,"(٤)"],[12218,"صاحب أنس، ضعيفى الحديث."],[12219,"٩٥١ - وأبو سمعان"],[12220,"(٥)"],[12221,"ضعيف الحديث."],[12222,"٩٥٢ - أبو قتادة الحرانى"],[12223,"(٦)"],[12224,"وقيل لأبى حاتم: ما تقول فى أبى قتادة الحرانى، وفيما روى أنه دفع إليه حديث أبى"],[12225,"(١) سبق."],[12226,"(٢) هو: عمرو بن هاشم، أبو مالك الجنبىُّ الكوفى."],[12227,"انظر: تهذيب الكمال (٢٢ /ت ٤٤٦٢)، تهذيب التهذيب (٨/ ١١١)، التاريخ الكبير (٦ /ت ٢٧٠٢)، الجرح والتعديل (٦ /ت ١٤٧٨)، الكاشف (٢ /ت ٤٣٠٥)، لسان الميزان (٧/ ٣٢٧)، طبقات ابن سعد (٦/ ٣٩٢)، ضعفاء ابن الجوزى (٢٣٢/ ٢)، الكامل لابن عدى (٦ /ت ١٣٠٥)."],[12228,"(٣) هو: أجلح بن عبد الله بن حجية، ويقال: معاوية الكندى أبو حجية، ويقال: اسمه يحيى الأجلح لقب."],[12229,"انظر: تهذيب الكمال (٢ /ت ٢٨٢)، تهذيب التهذيب (١/ ١٨٩)، المجروحين (١/ ٩٧٥)، الجرح والتعديل (٢/ ٣٤٦)، تاريخ ابن معين (٢/ ١٩)، طبقات ابن سعد (٦/ ٣٥٠)، ميزان الاعتدال (١/ ٧٨)."],[12230,"(٤) هو: أبو عاتكة، اسمه: طريف بن سلمان، ويقال: سلمان بن طريف، الكوفى."],[12231,"انظر: تهذيب الكمال (٣٤ /ت ٧٤٥٨)، تهذيب التهذيب (١٢/ ١٤١)، ميزان الاعتدال (٧/ ٤٧١)، لسان الميزان (٢/ ٣٣٥، ٤/ ٥٤٢)."],[12232,"(٥) لم أقف له على ترجمة."],[12233,"(٦) هو: عبد الله بن واقد، أبو قتادة الحرانى، مولى بنى حماد، ويقال: مولى بنى تميم، توفى سنة (٢٠٧). قلت: وقد سبق."],[12234,"نعيم، عن مسعر، فقرأه حتى بلغ موضع شك فيه أبو نعيم، فقال: ما هذا؟، فقال أبو حاتم: ذهب حديثه."],[12235,"٩٥٣ - وأبو حمزة الثمالى"],[12236,"(١)"],[12237,"قال: وأبو حمزة الثمالى، ثابت بن أبى صفية، يكتب حديثه ولا يحتج به."],[12238,"قال: وأبو حمزة الثمالى ليس بشئ."],[12239,"٩٥٤ - وأبو الأسباط الحارثى"],[12240,"(٢)"],[12241,"صاحب يحيى بن أبى كثير الذى يحدث [عنه] (٣)، حاتم بن إسماعيل ضعيف"],[12242,"الحديث."],[12243,"٩٥٥ - وأبو آدم سليمان بن زيد"],[12244,"(٤)"],[12245,"مولى عبد الله بن أبى أوفى ليس بالقوى."],[12246,"٩٥٦ - وغندر بن محمد بن جعفر"],[12247,"(٥)"],[12248,"ثقة فى شعبة، ويكتب حديثه عن غيره، ولا يحتج به."],[12249,"٩٥٧ - عمر بن قيس"],[12250,"(٦)"],[12251,"قال: حدثنى يونس بن حبيب العجلى الأصبهانى، حدثنا أبو داود الطيالسى قال: كنا عند عمر بن قيس سندل بمكة، فحدثنا، عن عطاء، عن ابن عباس، عن أسامة قال: قال النبى - صلى الله عليه وآله وسلم -: \"لا ربا إلَّا فى نسيئة\"."],[12252,"(١) سبق."],[12253,"(٢) هو: بشر بن رافع الحارثى، أبو الأسباط النحرانى، إمامها ومفتيها."],[12254,"انظر: تهذيب الكمال (٤ /ت ٦٨٧)، تهذيب التهذيب (١/ ٤٤٨)، التاريخ الكبير (٢/ ١/ ٧٤)، الجرح والتعديل (٢ / ت ١٣٥٩)، المجروحين (١/ ١٨٨)، الكاشف (١/ ١٥٥)، ميزان الاعتدال (١/ ٣١٧)، الكشف الحثيث (١٦٨)، الأنساب (١٣/ ٤١)، المغنى (١/ ت ٩٠٠)."],[12255,"(٣) ما بين المعقوفين ساقط من المخطوط، وأثبته من بعض المصادر السابقة."],[12256,"(٤) هو: سليمان بن زيد المحاربى، ويقال: الأزدى، أبو آدم الكوفى. وقد سبق."],[12257,"(٥) هو: محمد بن جعفر الهذلى، مولاهم، أبو عبد الله البصرى، المعروف بغندر صاحب الكرابيسى. قلت: وقد سبق، وهو ثقة."],[12258,"(٦) سبق برقم (٦٨٦)."],[12259,"قال أبو داود: فقلت أنا: حدثنا فلان عن أبى الجوزاء: أن ابن عباس رجع عن الصرف، فقال: انظروا إلى هذا أحدثه عمن جعلتى جُعل بين الركن والمقام مراعه، وتحدثنى عن أبى الجوزاء، وأبى اللوز، وأبى الفستق (١)."],[12260,"٩٥٨ - وأبو عرنة موسى بن محمد بن مسكر"],[12261,"(٢)"],[12262,"ضعيف الحديث، كان قاضى المدينة."],[12263,"٩٥٩ - أبو بكر بن نافع"],[12264,"(٣)"],[12265,"قال يحيى بن معين: أبو بكر بن نافع ليس بشئ."],[12266,"٩٦٠ - وأبو بكر بن أبى سبرة"],[12267,"(٤)"],[12268,"الذى يقال له: السبرى، ليس حديثه بشئ، وهو مدينى مات ببغداد."],[12269,"٩٦١ - ابن كاسب"],[12270,"(٥)"],[12271,"ليس بشئ."],[12272,"٩٦٢ - وأبو البخترى"],[12273,"(٦)"],[12274,"كان خبيثا، وكان يحدث عن هشام بن عروة، عن أبيه، عن عائشة، وعن ثور بن زيد، عن خالد بن معدان، عن معاذ، وعن جعفر بن محمد، عن أبيه، عن على قالوا: قال رسول الله - صلى الله عليه وآله وسلم - فى الخمير يقترض قال: \"لا بأس\"."],[12275,"وقال مرة: أبو البخترى يضع الحديث، يعنى القاضى، وقال مرة: كان يأخذ ثلاثًا فيتذاكر عامة الليل يضع الحديث."],[12276,"(١) لم أقف على هذا الكلام، وإن كان عمر بن قيس قد أورد له العلماء كثيرًا من هذا القبيل."],[12277,"(٢) لم أقف له على ترجمة."],[12278,"(٣) هو: أبو بكر بن نافع العدوى المدنى، مولى ابن عمر. وقد سبق."],[12279,"(٤) هو: أبو بكر بن عبد الله بن محمد بن أبى سبرة بن أبى رهم بن عبد العزى بن أبى قيس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤى القرشى العامرى المدنى، قيل: اسمه عبد الله، وقيل: محمد. انظر: تهذيب الكمال (٣٣ /ت ٧٢٤٠)، تهذيب التهذيب (١٢/ ٢٧)."],[12280,"(٥) سبق."],[12281,"(٦) هو: وهب بن وهب بن كثير بن عبد الله بن زمعة بن الأسود بن المطلب بن أسد بن عبد العزى بن قصى القاضى، أبو البخترى القرشى المدنى، كان جوادًا ممدحًا لكنه متهم فى الحديث."],[12282,"وقد سبق."],[12283,"٩٦٣ - ابن زبالة"],[12284,"(١)"],[12285,"قال: وابن زبالة المدينى ليس بثقة، كان يسرق الحديث."],[12286,"٩٦٤ - وأبو جابر البياضى"],[12287,"(٢)"],[12288,"كذاب."],[12289,"قال ابن المدينى: قال ليحيى: سألت مالك بن أنس، عن أبى جابر البياضى، فقال: لم يكن يرضاه."],[12290,"٩٦٥ - ابن أبى خيثم بن عراك بن مالك"],[12291,"(٣)"],[12292,"قال ابن معين: وكان ابن أبى خيثم بن عراك بن مالك يصيح به الناس ياذا كلامين،"],[12293,"وكان لا يكتب عنه."],[12294,"٩٦٦ - وأبو أويس"],[12295,"(٤)"],[12296,"صدوق وليس بحجة."],[12297,"٩٦٧ - وأبو الحويرث"],[12298,"(٥)"],[12299,"ليس يحتج بحديثه."],[12300,"(١) هو: محمد بن الحسن بن زبالة، ويقال: لجده، أبو الحسن، مخزومى مدنى."],[12301,"انظر: تهذيب الكمال (٢٥ / ت ٥١٤٨)، تهذيب التهذيب (٩/ ١١٥)، التاريخ الكبير (١ / ت ١٥٤)، الجرح والتعديل (٧/ ت ١٢٥٤)، الكاشف (٣/ ت ٤٨٦٣)، ميزان الاعتدال (٣/ ت ٧٣٨٠)."],[12302,"(٢) سبق."],[12303,"(٣) لم أقف له على ترجمة، وهو بهذه الصورة بالمخطوط."],[12304,"(٤) هو: عبد الله بن عبد الله بن أبى عامر القرشى التيمى، أبو أويس الأصبحى المدينى."],[12305,"انظر: الكامل لابن عدى (٥/ ٣٠٠)، الضعفاء والمتروكين (٢/ ١٢٩)، المغنى (١ / ت ٣٢٣٠)، تهذيب التهذيب (٥/ ٢٨٠)، تهذيب الكمال (١٥/ ت ٣٣٦١)، التاريخ الكبير (٥ / ت ٣٧٧)، الجرح والتعديل (٥ / ت ٤٢٣)، ميزان الاعتدال (٢ / ت ٤٤٠٢)، الكاشف (٢ / ت ٢٨٣٢)، الإكمال (١/ ١١٤)، التحفة اللطيفة (٢/ ٣٣٩)."],[12306,"(٥) هو: عبد الرحمن بن معاوية بن الحويرث الأنصارى الزرقى، أبو الحويرث المدنى."],[12307,"انظر: تهذيب الكمال (١٧ / ت ٣٩٦٢)، تهذيب التهذيب (٦/ ٢٧٢)، الكاشف (٢ / ت ٣٣٥٨)، ميزان الاعتدال (٢ / ت ٤٩٧٩)، الجرح والتعديل (٥ / ت ١٣٥٢)، التاريخ الكبير (٥ / ت ١١٠٧)، لسان الميزان (٧/ ٨٧، ٢٨٤)، الكامل لابن عدى (٥/ ٥٠١)."],[12308,"٩٦٨ - والبكائى"],[12309,"(١)"],[12310,"ليس بشئ، وقد كتبت عنه المغازى."],[12311,"٩٦٩ - وأبو الحفص العبدى"],[12312,"(٢)"],[12313,"ليس بشئ."],[12314,"٩٧٠ - والكلبى"],[12315,"(٣)"],[12316,"ليس بشئ."],[12317,"٩٧١ - وأبو مريم الكوفى"],[12318,"(٤)"],[12319,"ليس بشئ. وأبو مريم، اسمه: عبد الغفار بن القاسم، وليس بشئ."],[12320,"٩٧٢ - وأبو مخنف"],[12321,"(٥)"],[12322,"(١) هو: زياد بن عبد الله بن الطفيل البكائى العامرى، أبو محمد، ويقال: أبو يزيد الكوفى."],[12323,"انظر: تهذيب الكمال (٩ /ت ٢٠٥٣)، تهذيب التهذيب (٣٧٥/ ٣)، الجرح والتعديل (٣ /ت ٢٤٢٥)، الكاشف (١/ ٣٣٢)، التاريخ الكبير (٣ / ت ١٢١٨)، طبقات ابن سعد (٣٩٦/ ٦)، الكامل لابن عدى (٤/ ١٣٦)، وفيات الأعيان (٢/ ٣٣٨)، ديوان الضعفاء (١٥٠٢)، المعرفة والتاريخ (١/ ٤٤٤)، ضعفاء النسائى (ت ٢٢٦)، المجروحين (١/ ٣٠٦)، تاريخ ابن معين، رواية الدورى (٢/ ١٧٩)، سير أعلام النبلاء (٥١٩)، الأنساب (١/ ٢٧٠)."],[12324,"(٢) هو: عمر بن حفص بن ذكوان العبدى، ويقال: عمر بن أبى خليفة."],[12325,"انظر: الضعفاء والمتروكين (٢/ ٤٠٦)، الضعفاء الكبير (٣/ ١٥٥)، المجروحين (٢/ ٨٤)، المغنى (٢ / ت ٤٤٣٦)، ميزان الاعتدال (٣/ ١٨٩)، الكشف الحثيث (٣١٤)، أحوال الرجال (١٤٣)، الكامل لابن عدى (٦/ ٩٨)."],[12326,"(٣) هو: أبو النضر محمد بن السائب بن بشر الكلبى الفسر العلامة الأخبارى، وكان رأسًا فى الأنساب إلَّا أنه شيعى، متروك الحديث. قلت: وقد سبق."],[12327,"(٤) هو: عبد الغفار بن القاسم بن قيس الأنصارى، أبو مريم الكوفى، مشهور بكنيته، وهو ابن عم يحيى بن سعيد الأنصارى."],[12328,"انظر: تعجيل المنفعة (٦٦٦)، الذيل على الكاشف (٩٤٢)، التاريخ الكبير (٦/ ١٢٢)، الجرح والتعديل (٦/ ٢٨٤)، لسان الميزان (٤/ ٤٢)، المغنى (٢ / ت ٣٧٦٨)، تراجم الأحبار (٢/ ٥٢١)، الكامل لابن عدى (٧/ ١٨)."],[12329,"(٥) هو: لوط بن يحيى. أبو مخنف، أخبارى، تألف لا يوثق به."],[12330,"انظر: ميزان الاعتدال (٣ / ت ٦٩٩٢)، المغنى (٢ / ت ٧٧٢٠)، الكنى (١/ ١٥٥)، ريحانة = ليس بشئ."],[12331,"٩٧٣ - والوقاصى"],[12332,"(١)"],[12333,"ليس بشئ، وهو عثمان بن عبد الرحمن."],[12334,"٩٧٤ - وابن أبى روق"],[12335,"(٢)"],[12336,"قد رأيته وليس بثقة."],[12337,"٩٧٥ - ابن هارون بن عنترة"],[12338,"(٣)"],[12339,"كذاب، وهارون بن عنترة كنيته: أبو عمرو."],[12340,"٩٧٦ - وأبو سفيان السعدى"],[12341,"(٤)"],[12342,"= الأدب (٧/ ٢٥٨)، طبقات ابن سعد (٦/ ٣٥، ٤٧)، تنقيح المقال (٣/ ٤٣)، دائرة المعارف الإسلامية (١/ ٣٩٨)."],[12343,"(١) هو: عثمان بن عبد الرحمن بن عمر بن سعد بن أبى وقاص الزهرى الوقاصى، أبو عمرو المدنى، ويقال له: المالكى نسبه إلى جده أبى وقاص مالك."],[12344,"انظر: تهذيب الكمال (١٩/ ت ٣٨٣٧)، التاريخ الكبير (٦/ ت ٢٢٧٠)، الجرح والتعديل (٦/ ت ٨٦٥)، تهذيب التهذيب (٧/ ١٣٣)، لسان الميزان (٧/ ٣٠٢)، سير أعلام النبلاء (٩/ ٤٢٨)، تاريخ الدورى (٢/ ٣٩٤)، المعرفة والتاريخ (٣/ ٣٦)، المغنى (٢/ ت ٤٠٣٨)، أنساب القرشيين (٢٩٧)، ضعفاء الدارقطنى (٣٩٨)، الكامل لابن عدى (٦/ ٢٧١)، تاريخ ابن معين، رواية الدورى (٢/ ٣٩٤)."],[12345,"(٢) ابن أبى روق."],[12346,"انظر: ميزان الاعتدال (٤/ ت ١٠٧٨٦)، تاريخ ابن معين (٢/ ٧٣٣)، المغنى (٢ / ت ٧٨٤٨)."],[12347,"(٣) هو: عبد الملك بن هارون بن عنترة بن عبد الرحمن الشيبانى."],[12348,"انظر: تاريخ ابن معين (٢/ ٣٧٦)، المجروحين (٢/ ١٣٣)، الجرح والتعديل (٥/ ٣٧٤)، الكشف الحثيث (٤٦٢)، الكامل لابن عدى (٦/ ٥٢٩)، المغنى (٢ / ت ٣٨٥١)، ميزان الاعتدال (٢/ ٦٦٦)، الضعفاء الكبير (٣/ ٣٨)، لسان الميزان (٤/ ٧١)، التاريخ الكبير (٥/ ٤٣٦)، العلل للدارقطنى (١/ ١١٣)."],[12349,"(٤) هو: طريف بن شهاب، وقيل: ابن سعد، وقيل: ابن سفيان، أبو سفيان السعدى الأشل، ويقال: الأعسم، وقال فيه البخارى: العطاردى."],[12350,"انظر: تهذيب الكمال (١٣ / ت ٢٩٦١)، تهذيب التهذيب (٥/ ١١)، التاريخ الكبير (٤ / ت ٣١٣٤)، الجرح والتعديل (٤/ ت ٢١٦٥)، الكاشف (٢ / ت ٢٤٨٤)، ميزان الاعتدال (٢/ ت ٣٩٨٥)، الكامل لابن عدى (٥/ ١٨٥)، الأنساب (٨/ ٤٧٦)، المجروحين (١/ ٣٨١)، المغنى (١/ ت ٢٩٣٨)."],[12351,"اسمه طريف وهو ضعيف، روى عنه شريك، وأبو معاوية ومروان الفزارى."],[12352,"٩٧٧ - وأبو يحيي القتات"],[12353,"(١)"],[12354,"ضعيف."],[12355,"٩٧٨ - وأبو هانى مولى الشعبى"],[12356,"(٢)"],[12357,"ضعيف."],[12358,"٩٧٩ - والوصافى"],[12359,"(٣)"],[12360,"ليس حديثه بشئ."],[12361,"٩٨٠ - محمد بن طلحة"],[12362,"(٤)"],[12363,"[قال] (٥) أبو كامل: محمد بن طلحة ليس بشئ."],[12364,"٩٨١ - وأبو كامل (٦) محمد بن طلحة"],[12365,"ليس بشئ."],[12366,"(١) هو: عبد الرحمن بن دينار، وقيل: اسمه: زاذان، وقيل: اسمه: دينار، أبو يحيى القتات."],[12367,"انظر: ميزان الاعتدال (٢ / ت ٤٨٥٩)، لسان الميزان (٧/ ٢٧٩)، الجرح والتعديل (٥ / ت ١٠٩٨)، الأنساب (١٠/ ٣٣٥)، التاريخ الكبير (٥/ ٢٧٩)، المجروحين (٢/ ٥٣)، الضعفاء الكبير (٢/ ٣٢٩)، ضعفاء ابن الجوزى (٢/ ٩٣)، المغنى (١/ ت ٣٥٦١)."],[12368,"(٢) انظر: ميزان الاعتدال (٤ / ت ١٠٦٨٩)، المغنى (٢ / ت ٧٧٨٧)."],[12369,"(٣) هو: عبيد الله بن الوليد الوصافى، أبو إسماعيل الكوفى، قال البخارى: هو من ولد الوصاف ابن عامر العجلى."],[12370,"انظر: تهذيب الكمال (١٩ / ت ٣٦٩٤)، تهذيب التهذيب (٧/ ٥٥)، الجرح والتعديل (٥ / ت ١٥٩٠)، الكاشف (٢/ ٣٦٤٩)، ميزان الاعتدال (٣ / ت ٥٤٠٥)، التاريخ الكبير (٥ / ت ١٢٩٨)."],[12371,"(٤) هو: محمد بن طلحة بن مصرف اليامى الكوفى الهمدانى، يكنى: أبا عبد الله."],[12372,"انظر: تهذيب الكمال (٢٥ / ت ٥٣١٢)، تهذيب التهذيب (٩/ ٢٣٧)، التاريخ الكبير (١ / ت ٣٥٥)، الجرح والتعديل (٧ / ت ١٥٨٢)، الكاشف (٣ / ت ٤٩٩٧)، ميزان الاعتدال (٣ / ت ٧٧١٦)، طبقات ابن سعد (٦/ ٢٦١)، سير أعلام النبلاء (٧/ ٣٣٨)، معرفة الثقات (٦١١٠)، تاريخ الثقات (٤٠٦)، لسان الميزان (٧/ ٣٦٢)، الكامل لابن عدى (٧/ ٤٧٤)."],[12373,"(٥) ما بين المعقوفين ساقط من المخطوط."],[12374,"(٦) كذا بالمخطوط. وهو الذى قبله."],[12375,"٩٨٢ - وأبو بردة"],[12376,"(١)"],[12377,"الذى يحدث عنه محمد بن الصلت، أو قال: يحدث محمد بن الصلت ليس حديثه بشئ، وليس هو من ولد أبى موسى."],[12378,"وأبو بردة الذى يروى عنه أحمد بن يونس، ضعيف."],[12379,"وأبو بردة الذى يروى عنه القواريرى، ضعيف."],[12380,"٩٨٣ - وأبو يحيى التيمى"],[12381,"(٢)"],[12382,"اسمه إسماعيل بن إبراهيم، وهو كوفى، يروى عنه أبو الجارود زياد بن المنذر، وليس بثقة."],[12383,"٩٨٤ - وأبو الجارود زياد بن المنذر"],[12384,"(٣)"],[12385,"كذاب خبيث، يروى عنه الفزارى (٤)."],[12386,"٩٨٥ - وأبو داود النخعى"],[12387,"(٥)"],[12388,"(١) هو: عمرو بن يزيد التميمى، أبو بردة الكوفى."],[12389,"انظر: تهذيب الكمال (٢٢ / ت ٤٤٧٦)، تهذيب التهذيب (٨/ ١١٩)، ميزان الاعتدال (٣ / ت ٦٤٧٧)، لسان الميزان (٧/ ٣٢٨)، المغنى (٢ / ت ٤٧٣٠)، تاريخ ابن معين، رواية الدورى (٢/ ٤٥٦)، المعرفة والتاريخ (١/ ٢٥١)، الكامل لابن عدى (٦/ ٢٣٩)، الكاشف (٢ / ت ٤٣١٨)، الجرح والتعديل (٦/ ٢٦٩)."],[12390,"(٢) هو: إسماعيل بن إبراهيم، أبو يحيى التيمى الكوفى الأحول."],[12391,"انظر: تهذيب الكمال (٣ / ت ٤٢٢)، تهذيب التهذيب (١/ ٢٨١)، تاريخ ابن معين (٢/ ٣١)، الجرح والتعديل (٢/ ١٥٥)، التاريخ الكبير (١/ ٣٤٢)، الضعفاء الصغير (٢٥٢)، ديوان الضعفاء (١٩)، المجروحين (١/ ١٢٢)، الكاشف (١/ ١٢٠)، ضعفاء ابن الجوزى (١/ ١٠٨)، المغنى (١/ ت ٦٢١)."],[12392,"(٣) هو: زياد بن المنذر الهمدانى، ويقال: النهدى، ويقال: الثقفى، أبو الجارود الأعمى الكوفى."],[12393,"انظر: تهذيب الكمال (٩/ ت ٢٠٧٠)، تهذيب التهذيب (٣/ ٣٨٦)، الجرح والتعديل (٣ / ت ٢٤٦٢)، الكاشف (١/ ٣٣٤)، الكامل لابن عدى (٤/ ١٣٢)."],[12394,"(٤) جاء بالمخطوط \"القوارى\"، وهو تصحيف، واسمه: مروان بن معاوية الفزارى، وبقية قول ابن معين: بحديث أبى جعفر: \"أن النبى - صلى الله عليه وآله وسلم -، أمر عليًا أن يلثم الحيطان\"."],[12395,"(٥) هو: سليمان بن عمرو، أبو داود النخعى."],[12396,"انظر: التاريخ الكبير (٤/ ٢٨)، المجروحين (١/ ٣٣٣)، الضعفاء والمتروكين للدارقطنى= اسمه: سليمان بن عمرو، كان رجل سوء كذابًا."],[12397,"٩٨٦ - وأبو الفيض سالم"],[12398,"(١)"],[12399,"ليس حديثه بشئ، روى عنه ابن إدريس."],[12400,"٩٨٧ - وأبو قيس"],[12401,"(٢)"],[12402,"الذى روى عنه أبو معاوية، ليس حديثه بشئ."],[12403,"٩٨٨ - وأبو سعد البقال"],[12404,"(٣)"],[12405,"هو سعيد بن المرزبان، حبان بن على (٤) ليس حديثه بشئ."],[12406,"٩٨٩ - وأبو عقيل"],[12407,"(٥)"],[12408,"اسمه: يحيى بن المتوكل، ليس حديثه بشئ."],[12409,"٩٩٠ - وأبو بكر الهذلى"],[12410,"(٦)"],[12411,"ليس بشئ."],[12412,"٩٩١ - وأبو أمية بن يعلى"],[12413,"(٧)"],[12414,"= (٩٨/ ٢٥٦)، تنقيح المقال (٥٢٤)، الضعفاء الصغير (١٤٤)، المغنى (١ /ت ٢٦١٠)."],[12415,"(١) هو: سالم بن عبد الأعلى، وقيل: ابن عبد الرحمن، وقيل: ابن غيلان."],[12416,"انظر: الكامل لابن عدى (٤/ ٣٧١)، الجرح والتعديل (٤/ ١٨٦)، الكشف الحثيث (٣٠٤)، الضعفاء الكبير (٢/ ٥٢)، تاريخ ابن معين (٢/ ١٨٦)، الضعفاء والمتروكين للدارقطنى (٢٥٩)، ضعفاء ابن الجوزى (١/ ٣٠٧)، ديوان الضعفاء (١٥٤٦)، ميزان الاعتدال (٢/ ١١٢)، المغنى (١ /ت ٢٣٠٤)."],[12417,"(٢) هو: أبو قيس الدمشقى محمد بن سعيد بن حسان بن قيس الأسدى المصلوب. وقد تقدم."],[12418,"(٣) هو: سعيد بن المرزبان العبسى، أبو سعد البقال الكوفى الأعور، مولى حذيفة."],[12419,"انظر: تهذيب الكمال (١١ /ت ٢٣٥)، تهذيب التهذيب (٤/ ٧٩)، الجرح والتعديل (٤ /ت ٢٦٤)، الكاشف (١ /ت ١٩٧٤)، ميزان الاعتدال (٢ /ت ٣٢٧١)."],[12420,"(٤) كذا بالمخطوط، ولعل ذلك من سهو الناسخ."],[12421,"(٥) سبق برقم (٩٣٩)."],[12422,"(٦) سبق."],[12423,"(٧) هو: إسماعيل بن يعلى، أبو أمية الثقفى البصرى."],[12424,"انظر: الكامل لابن عدى (١/ ٥١١)، الضعفاء والمتروكين للدارقطنى (٧٨)، الضعفاء = ليس بشئ."],[12425,"٩٩٢ - وأبو جزى"],[12426,"(١)"],[12427,"ليس بشئ، وهو نصر بن راشد."],[12428,"٩٩٣ - مولى أبى عوانة"],[12429,"(٢)"],[12430,"ليس بشئ."],[12431,"٩٩٤ - وأبو سهل محمد بن عمرو الأنصارى"],[12432,"(٣)"],[12433,"ضعيف."],[12434,"٩٩٥ - وأبو هرمز"],[12435,"(٤)"],[12436,"الذى يروى عن أنس بن مالك ضعيف."],[12437,"٩٩٦ - المزنى"],[12438,"(٥)"],[12439,"ليس بشئ."],[12440,"٩٩٧ - وأبو عامر الخزاز"],[12441,"(٦)"],[12442,"= والمتروكين (٣٩)، المغنى (١ / ت ٧٣٧)، التاريخ الكبير (١/ ١/ ٣٧٧)، لسان الميزان (١/ ٢٥٤)، ديوان الضعفاء (٢٣)، المجروحين (١/ ١٢٤)، الجرح والتعديل (٢/ ٢٠٣)."],[12443,"(١) هو: نصر بن طريف، أبو جزى القصاب الباهلى البصرى، وليس هو نصر بن طريف كما يقول المصنف. قلت: وقد سبق."],[12444,"(٢) لم أقف عليه."],[12445,"(٣) هو محمد بن عمرو الأنصارى، يقال اسم جده عبيد، وقيل عبد الله بن حنظلة بن رافع الأنصارى الواقفى، أبو سهل البصرى."],[12446,"انظر: تهذيب الكمال (٢٦ / ت ٥٥١٧)، تهذيب التهذيب (٩ لم ٣٧٨)، التاريخ الكبير (١ / ت ٥٩٤)، ميزان الاعتدال (٣ / ت ٨٠١٧)، المغنى (٢ / ت ٥٨٨٢)، لسان الميزان (٧/ ٣٧٠)، ضعفاء ابن الجوزى (٣/ ٨٨)."],[12447,"(٤) انظر: ميزان الاعتدال (٤ / ت ١٠٦٩١)، الجرح والتعديل (٩/ ٤٥٦)، المصنوع للهروى (٢٧٠)، المغنى (٢ / ت ٧٧٨٩)."],[12448,"(٥) لم أقف عليه."],[12449,"(٦) هو: صالح بن رستم المزنى مولاهم أبو عامر الخزاز البصرى."],[12450,"انظر: تهذيب الكمال (١٣/ ٢٨١٢)، تهذيب التهذيب (٤/ ٣٩١)، التاريخ الكبير= ضعيف."],[12451,"٩٩٨ - وأبو عبيدة الناجى"],[12452,"(١)"],[12453,"ضعيف."],[12454,"٩٩٩ - وأبو سفيان الصواف"],[12455,"(٢)"],[12456,"كان كذابًا، وكان يقال له ابن رواحة."],[12457,"١٠٠٠ - وأبو حتروش سلمة بن هزال"],[12458,"(٣)"],[12459,"بصرى، وليس بشئ."],[12460,"١٠٠١ - وأبو بحر البكراوى"],[12461,"(٤)"],[12462,"ضعيف الحديث."],[12463,"= (٤ /ت ٢٨٠٧)، الجرح والتعديل (٤ / ت ١٧٦٤)، الكاشف (٢ / ت ٢٣٥٧)، ميزان الاعتدال (٢ / ت ٣٧٩١)، طبقات خليفة (٢٢٢)، المعرفة والتاريخ (٣/ ٣٨١)، تاريخ الإسلام (٦/ ٢٠٢)، التاريخ الكبير (٤/ ٢٨٠)، الكامل لابن عدى (٥/ ١١١)."],[12464,"(١) هو: بكر بن الًا سود، ويقال: ابن أبى الأسود أبو عبيدة الناجى."],[12465,"انظر: ميزان الاعتدال (١/ ١٢٧١)، ديوان الضعفاء (٤٩٩٢)، الكنى والأسماء (٢/ ٧٤)، أحوال الرجال (١٧٩)، تبصير المنتبه (١/ ١١٧)، المغنى (٢ / ت ٧٥٩٧)."],[12466,"(٢) هو: عبيد الله بن سفيان، أبو سفيان، ويعرف بابن رواحة."],[12467,"انظر: ميزان الاعتدال (٣ /ت ٥٣٦٦)، لسان الميزان (٤/ ١٠٤)، الجرح والتعديل (٥ /ت ٥١١٢)، الكامل لابن عدى (٥/ ٥٣٥)، المجروحين (٢/ ٦٦)، التاريخ الكبير (٥/ ٣٨١)، ثقات (٥/ ٧٠)، حاشية الإكمال (٦/ ١٩٩)، المغنى (٢ / ت ٩٣٢٨)."],[12468,"(٣) هو: شملة بن هزال، أبو حتروش البصرى."],[12469,"انظر: ميزان الاعتدال (٢ / ت ٣٧٤٧)، لسان الميزان (٣/ ١٥٣)، الجرح والتعديل (٤ / ت ١٦٨٤)، التاريخ لابن معين (٢/ ٢٢٧)، ضعفاء ابن الجوزى (٢/ ٤٣)، الكامل لابن عدى (٥/ ٦٧)، الضعفاء الكبير (٢/ ١٩٤)، المغنى (٢ / ت ٣٠٠)."],[12470,"(٤) هو: عبد الرحمن بن عثمان بن أمية بن عبد الرحمن بن أبى بكرة الثقفى، أبو بحر البكراوى البصرى."],[12471,"انظر: تهذيب الكمال (١٧ / ت ٣٨٩٧)، تهذيب التهذيب (٦/ ٢٢٦)، التاريخ الكبير (٥ /ت ١٠٥٤)، الجرح والتعديل (٦ / ت ١٢٥٢)، الكاشف (٢ / ت ٣٣٠١)، ميزان الاعتدال (٢ / ت ٤٩١٨)، الضعفاء والمتروكين (٢/ ٩٧)، الضعفاء الكبير (٢/ ٣٣٥)، الكامل لابن عدى (٥/ ٤٨٣)."],[12472,"١٠٠٢ - وأبو هارون العبدى"],[12473,"(١)"],[12474,"ليس بثقة. قال ابن المدينى: قيل لابن عون ما تقول فى أبى هارون العبدى؟، قال:"],[12475,"تركه عندنا شعبة."],[12476,"١٠٠٣ - أبو المتوكل الناجى"],[12477,"(٢)"],[12478,"١٠٠٤ - وأبو الصديق الناجى"],[12479,"(٣)"],[12480,"ليس حديثهما بشئ."],[12481,"فى حديثه ضعف."],[12482,"١٠٠٥ - وأبو قدامة"],[12483,"(٤)"],[12484,"فى حديثه ضعف."],[12485,"١٠٠٦ - أبو سفيان"],[12486,"(٥)"],[12487,"قال: وحديث أبى سفيان عن جابر إنما هى صحيفة."],[12488,"١٠٠٧ - وأبو هدبة"],[12489,"(٦)"],[12490,"(١) سبق."],[12491,"(٢) هو: على بن داود، ويقال: دؤاد، أبو المتوكل الناجى الساجى البصرى."],[12492,"انظر: تهذيب الكمال (٢٠ / ت ٤٠٦٦)، تهذيب التهذيب (٧/ ٣١٨)، التاريخ الكبير (٦/ ت ٢٣٨٤)، الجرح والتعديل (٦/ ت ١٠١٤)، الكاشف (٢/ ت ٣٩٦٨)."],[12493,"(٣) هو: بكر بن عمرو، وقيل: ابن قيس، أبو الصديق الناجى."],[12494,"انظر: تهذيب الكمال (٤/ ت ٧٥١)، طبقات ابن سعد (٧/ ٢٢٦)، تهذيب التهذيب (١/ ٤٨٦)، التاريخ الكبير (٢/ ١/ ٩٣)، الجرح والتعديل (١/ ١/ ٣٩)، الكاشف (١/ ٦٢)."],[12495,"(٤) هو: الحارث بن عبيد، أبو قدامة الإيادى البصرى المؤذن."],[12496,"انظر: تهذيب الكمال (٥ / ت ١٠٢٩)، تهذيب التهذيب (٢/ ١٤٩)، الجرح والتعديل (٣ / ت ٣٧١)، ميزان الاعتدال (١/ ٤٣٨)، الكاشف (١/ ١٩٥)."],[12497,"(٥) هو: طلحة بن نافع القرشى مولاهم، أبو سفيان الواسطى، ويقال: المكى الإسكاف."],[12498,"انظر: تهذيب الكمال (١٣ / ت ٢٩٨٣)، تهذيب التهذيب (٥/ ٢٦)، التاريخ الكبير (٤/ ت ٣٠٧٩)، الجرح والتعديل (٤/ ت ٢٠٨٦)، الكاشف (٢/ ٢٥٠١)، ميزان الاعتدال (٢/ ت ٤٠١٢)، الكامل لابن عدى (٥/ ١٨٠)."],[12499,"(٦) هو: إبراهيم بن هدبة، أبو هدبة البصرى الفارسى، حدث ببغداد وغيرها بالأباطيل."],[12500,"انظر: ميزان الاعتدال (١ / ت ٢٤٢)، الضعفاء والمتروكين للدارقطنى (١٢)، الكامل لابن عدى (١/ ٣٤١)، المغنى (١/ ت ١٩٩)، لسان الميزان (١/ ١١٩)، تاريخ بغداد (٦/ ٢٠٠)، الجرح= وأبو هدبة قدم فاجتمع عليه الخلق، فقالوا له: أخرج رجلك."],[12501,"قال العباس: قيل ليحيى: لم قالوا له ذلك؟، قال: كانوا يخافون -أن تكون- رجله رجل حمار فيكون شيطانًا."],[12502,"١٠٠٨ - وأبو السرى"],[12503,"(١)"],[12504,"اسمه ثابت، كان ابن إدريس لا يرضاه، وكان يحيى بن سعيد لا يروى عنه."],[12505,"١٠٠٩ - أبو سعد الصغانى"],[12506,"(٢)"],[12507,"ليس بشئ."],[12508,"١٠١٠ - وأبو علقمة"],[12509,"(٣)"],[12510,"ليس بشئ، كان يكون فى المسجد الجامع لا يفارقه، وليس هو أبا علقمة الفروى."],[12511,"١٠١١ - وأبو الجنيد الضرير"],[12512,"(٤)"],[12513,"ليس بثقة."],[12514,"١٠١٢ - وأبو يوسف المدينى"],[12515,"(٥)"],[12516,"شيخ كان يحدث عن هشام بن عروة، ليس بثقة."],[12517,"١٠١٣ - والحبطى"],[12518,"(٦)"],[12519,"= والتعديل (٢/ ٤٧١)، المجروحين (١/ ١١٤)، تاريخ أصبهان (١/ ١٧٠)."],[12520,"(١) هو: ثابت بن يزيد الأودى. قلت: سبق."],[12521,"(٢) هو: محمد بن مُيَسَّر الجعفى، أبو سعد الصاغانى البلخى، الضرير، نزيل بغداد، وهو محمد بن أبى زكريا، وكان جهميًا، وكان شيطانًا من الشياطين."],[12522,"انظر: تهذيب الكمال (٢٦ / ت ٥٦٤٨)، تهذيب التهذيب (٩/ ٤٨٣)، الجرح والتعديل (٨ / ت ٤٤٩)، التاريخ الكبير (١ / ت ٧٠٧٨)، الأنساب (٨/ ٦٩)، المعرفة والتاريخ (٣/ ٣٩)، المجروحين (٢/ ١٧١)، ضعغاء ابن الجوزى (٣/ ١٠٣)، تاريخ ابن معين رواية الدورى (٢/ ٥٤١)، طبقات ابن سعد (٧/ ٣٧٧)، تاريخ بغداد (٣/ ٣٨١)، المغنى (٢ / ت ٦٠٣٠)، الكامل لابن عدى (٧/ ٤٦٠)."],[12523,"(٣) انظر: ميزان الاعتدال (٤/ ١٠٤٣٤)، المغنى (٢ / ت ٧٦٢٦)."],[12524,"(٤) هو: خالد بن الحسين أبو الجنيد الضرير."],[12525,"انظر: ميزان الاعتدال (٤/ ١٠٠٧٦)، (١/ ٦٢٩)، (١/ ٥٣٤)، الكامل لابن عدى (٣/ ٤٧٣)، المغنى (١ / ت ١٨٣٨)."],[12526,"(٥) انظر: الجرح والتعديل (٩ / ت ٢٣٣٦)، الكنى والأسماء (٢/ ١٦٠)، ميزان الاعتدال (٤ / ت ١٠٧٥٢)، تاريخ ابن معين (٢/ ٧٣٢)."],[12527,"(٦) هو: حفص بن عمر الحبطى الرملى أبو عمر. ="],[12528,"الذى كان جار الشهبى ليس بشئ."],[12529,"١٠١٤ - أبو الأشهب الكوفى"],[12530,"(١)"],[12531,"ضعيف الحديث، روى عنه يزيد بن هارون، ومحمد بن سالم الواسطى."],[12532,"١٠١٥ - وأبو فروة الجزرى"],[12533,"(٢)"],[12534,"اسمه يزيد بن سنان، وقد روى عنه الكوفيون، وليس بثقة."],[12535,"١٠١٦ - وأبو بكر الداهرى"],[12536,"(٣)"],[12537,"الذى يحدث عنه عمرو بن عون الواسطى ليس حديثه بشئ."],[12538,"١٠١٧ - والأفريقى عبد الرحمن بن يزيد بن أنعم"],[12539,"(٤)"],[12540,"فيه ضعف. قال: وهو أحب إلى من أبى بكر بن أبى مريم الغسانى."],[12541,"١٠١٨ - وأبو الغطريف الجزرى"],[12542,"(٥)"],[12543,"ليس حديثه بشئ."],[12544,"١٠١٩ - وأبو همدان"],[12545,"(٦)"],[12546,"كذاب، ومنزله هيت."],[12547,"= انظر: ميزان الاعتدال (١ /ت ٢١٣٣)، الكامل لابن عدى (٣/ ٢٨٥)، دائرة معارف الأعلمى (١٦/ ٢٩٩)، الإكمال (١٥٤/ ٧)، المجروحين (١/ ٢٥٩)، المغنى (١ / ت ١٦٢٨)."],[12548,"(١) هو: جعفر بن الحارث الواسطى أبو الأشهب."],[12549,"انظر: تهذيب التهذيب (٢/ ٨٨)، الجرح والتعديل (٢ / ت ١٩٤١)، المجروحين (١/ ٢١٢)، ميزان الاعتدال (١/ ١٤٩٥)، الكامل لابن عدى (٢/ ٣٦٧)، الثقات (٦/ ١٣٩)، الضعفاء والمتروكين (١/ ٢٩)، التاريخ الكبير (٢/ ١٨٩)."],[12550,"(٢) سبق."],[12551,"(٣) سبق، وهو: عبد الله بن حكيم، متروك."],[12552,"(٤) و(٥) سبق."],[12553,"(٦) هو: قاسم بن بهرام قاضى هيت."],[12554,"انظر: ميزان الاعتدال (٣/ ٣٨٠، ٤/ ٥٨٣، ٤/ ٧٤٢)، الضعفاء والمتروكين (٣/ ٢٤٢)، ريحانة الأدب (٧/ ٣٠٥)، تنقيح المقال (٣/ ٣٨)، المغنى (٢ / ت ٧٧٩٦)."],[12555,"١٠٢٠ - الواقدى"],[12556,"(١)"],[12557,"قال: والواقدى ليس بشئ."],[12558,"١٠٢١ - وأبو آدم"],[12559,"(٢)"],[12560,"ليس بثقة."],[12561,"١٠٢٢ - أبو جابر البياضى"],[12562,"(٣)"],[12563,"قال ابن إسماعيل: عن أبى الأسود، عن يحيى قال: سألت مالكًا عن أبى جابر البياضى، فقال: لم يكن يرضاه وهو محمد بن عبد الرحمن."],[12564,"١٠٢٣ - أبو عمارة"],[12565,"(٤)"],[12566,"صاحب الزعفران ليس بشئ."],[12567,"١٠٢٤ - أبو الفيض"],[12568,"(٥)"],[12569,"قال ابن المدينى: قال يحيى: سمعته يقول: حدثنا أبو الفيض، وكان ممن رمى بيت الله بالمنجنيق."],[12570,"١٠٢٥ - أبو الزبير"],[12571,"(٦)"],[12572,"قال صدقة: سمعت ابن عيينة يقول: حدثنا أيوب قال: حدثنا أبو الزبير وهو مكى تركه شعبة أصلًا."],[12573,"١٠٢٦ - أبو طالب"],[12574,"(٧)"],[12575,"قال ابن المدينى: قال يحيى: كان أبو طالب قد تغير، وكان يرمى بالقدر، ثم قال يحيى: بلغنى أنه تغير."],[12576,"١٠٢٧ - أبو حمزة"],[12577,"(٨)"],[12578,"قال: وقلت لحيى: قال لكم أبو حمزة فى سماعه نحوًا مما قال ميمون المرائى؟"],[12579,"(١) إلى (٦) سبق."],[12580,"(٧) هو: يحيى بن يعقوب أبو طالب القاص."],[12581,"انظر: ميزان الاعتدال (٤ /ت ٩٦٥٦)، ديوان الضعفاء (٤٧٠١)، الضعفاء (٤٣٦/ ٤)، المغنى (٢/ ت ٧٠٧٢)."],[12582,"(٨) أبو حمزة سبق كثيرًا."],[12583,"قال: نعم وأشد من ذلك. قلت: كيف؟ قال: فيه ما سمعته، ومنه ما حفظه بعضنا"],[12584,"عن بعض، ومنه ما لم نسمع حدثنا به أصحابنا."],[12585,"١٠٢٨ - أبو داود الأعمى"],[12586,"(١)"],[12587,"ابن حنبل: حدثنا يزيد، أخبرنا همام قال: دخل أبو داود الأعمى على قتادة، قال:"],[12588,"فقال له بعض القوم: إن هذا يزعم أنه لقى ثمانية عشر بدريًا."],[12589,"قال: فقال: هذا كان سائلًا قبل الجارف لا يعرض فى شئ من هذا، فوالله ما حدثنا الحسن عن بدرى واحد مشافهة، ولا سعيد بن المسيب إلا عن سعد بن مالك."],[12590,"* * *"],[12591,"(١) هو: نفيع بن الحارث أبو داود الأعمى الهمدانى الدارمى، ويقال: السبيعى الكوفى القاص، ويفال: اسمه نافع. وقد سبق."],[12592,"١٨ - باب فيه ذكر من رموه، بأنه من أهل البدع وأصحاب الأهواء"],[12593,"١٠٢٩ - ابن أبى نجيح"],[12594,"(١)"],[12595,"حدثنى أبو على، عن العباس، عن يحيى بن معين قال: كان ابن أبى نجيح ثقة، وكان يرمى بالقدر، قال الكرابيسى: هو ممن يقول بالقدر."],[12596,"قال على بن المدينى: قال يحيى بن سعيد: كان ابن أبى نجيح معتزليًا، قال: وكان من رؤوس الدعاة. قال الشافعى: حدثنا ابن علية فال: قدمت مكة فغلبتنا المعتزلة على ابن أبى نجيح."],[12597,"١٠٣٠ - سيف بن سليمان"],[12598,"(٢)"],[12599,"١٠٣١ - وزكريا بن إسحاق"],[12600,"(٣)"],[12601,"قال يحيى: سيف بن سليمان وزكريا بن إسحاق قدريان."],[12602,"١٠٣٢ - إبراهيم بن أبى يحيى"],[12603,"(٤)"],[12604,"قال: وكان إبراهيم بن أبى يحيى رافضيًا قدريًا."],[12605,"١٠٣٣ - ابن إسحاق"],[12606,"(٥)"],[12607,"قال العباس: قال رجل ليحيى: يصح أن ابن إسحاق كان يرى القدر؟، قال: نعم كان يرى القدر."],[12608,"١٠٣٤ - عبد الحميد بن جعفر"],[12609,"(٦)"],[12610,"(١) سبق."],[12611,"(٢) هو: سيف بن سليمان، ويقال: ابن أبى سليمان المخزومى مولاهم أبى سليمان المكى."],[12612,"انظر: تهذيب الكمال (١٢ /ت ٢٦٧٤)."],[12613,"(٣) هو: زكريا بن إسحاق المكى، ثقة رمى بالقدر. انظر: تهذيب الكمال (٩ /ت ١٩٩٠)."],[12614,"(٤) هو: إبراهيم بن محمد بن أبى يحيى الأسلمى، تركه جماعة وضعفه آخرون للرفض والقدر، واسمه سمعان أبو إسحاق المدنى. انظر: تهذيب الكمال (٢ /ت ٢٣٦)."],[12615,"(٥) هو: محمد بن إسحاق بن يسار، ويقال: كوثان المدنى أبو بكر، ويقال: أبو عبد الله المطلبى نزيل العراق، صدوق يدلس، رمى بالتشيع والقدر. انظر: تهذيب الكمال (٢٤ /ت ٥٠٥٧)."],[12616,"(٦) هو: عبد الحميد بن جعفر بن عبد الله بن الحكم بن رافع بن سنان الأنصارى الأوسى أبو="],[12617,"قال: وعبد الحميد بن جعفر ثقة، وكان يُرمى بالقدر."],[12618,"١٠٣٥ - عائذ بن حبيب"],[12619,"(١)"],[12620,"قال: وعائذ بن حبيب قد سمعت منه، وكان يقال: إنه زيدى، وكان مسجده ومسجد عبيد الله بن موسى واحدًا، وكان عبيد الله لا يحدث [حتى] (٢) يقوم عائذ."],[12621,"١٠٣٦ - وأبو الصباح"],[12622,"(٣)"],[12623,"مرجئ روى عنه سفيان، ومسعر، وهشيم، وهو ثقة."],[12624,"١٠٣٧ - هشام الدستوائى"],[12625,"(٤)"],[12626,"كان ممن يرى القدر ولا يدعو إليه، وكان لا يطفئ سراجه بالليل، فقالت له امرأته: إن هذا السراج يضر بنا، فقال لها: ويحك إنك إذا طفئتيه ذكرت ظلمة القبر فلم أتقار."],[12627,"١٠٣٨ - عمران القطان"],[12628,"(٥)"],[12629,"قال: وكان عمران القطان يرى رأى الخوارج ولم يكن داعية."],[12630,"١٠٣٩ - عوف"],[12631,"(٦)"],[12632,"قال: وكان عوف قدريًا."],[12633,"١٠٤٠ - عباد بن منصور"],[12634,"(٧)"],[12635,"وكان عباد بن منصور قدريًا."],[12636,"= الفضل، ويقال: أبو حفص، ويقال: إن رافع بن سنان جده لأمه، صدوق رمى بالقدر وربما وهم."],[12637,"انظر: تهذيب الكمال (١٦ /ت ٣٧٠٩)."],[12638,"(١) هو: عائذ بن حبيب بن الملاح العبسى ويقال: القرشى مولاهم أبو أحمد، ويقال: أبو هشام الكوفى بياع الهروى، صدوق رمى بالتشيع، قال الذهبى: شيعى جلد."],[12639,"انظر: تهذيب الكمال (١٤ /ت ٣٠٧٠)."],[12640,"(٢) ما بين المعقوفين ساقط من المخطوط."],[12641,"(٣) لم أقف عليه."],[12642,"(٤) و(٥) سبق."],[12643,"(٦) هو: عوف بن أبى جميلة الأعرابى العبدى البصرى."],[12644,"(٧) سبق."],[12645,"١٠٤١ - قرط بن حريث"],[12646,"(١)"],[12647,"قد كتبت عنه، وليس به بأس، ولكنه كان قدريًا أتيناه إلى منزله فقال لنا: نزهوا الله عن هذه المعاصى دعانا إلى القدر، فخرجت وكان مولى لباهلة وكان يقوم لرجل من المحدثين حديثه - يعنى يخرج منه اللحن."],[12648,"١٠٤٢ - الفضل الرقاشى"],[12649,"(٢)"],[12650,"كان رجل سوء قدرى."],[12651,"١٠٤٣ - والحسن بن ذكوان"],[12652,"(٣)"],[12653,"قدرى، وكان يحيى بن سعيد القطان يروى عنه، وروى عنه الخفاف وابن المبارك."],[12654,"١٠٤٤ - ثور بن يزيد"],[12655,"(٤)"],[12656,"وكان أزهر الحرازى، وأسد بن وداعة، وجماعة يجلسون فيشتمون على بن أبى طالب رضي الله عنه، وكان ثور بن يزيد يكون فى ناحية لا يشتمه فيجرون رجله."],[12657,"١٠٤٥ - يحيى بن حمزة"],[12658,"(٥)"],[12659,"كان قاضى دمشق، وكان يرمى بالقدر."],[12660,"١٠٤٦ - العلاء [بن] الحارث"],[12661,"(٦)"],[12662,"قال العباس: وقيل ليحيى العلاء الحارث فى حديثه شئ؟"],[12663,"قال: لا، ولكنه كان يرى القدر، ومات فى ولاية أبى العباس، إلى هاهنا عن يحيى بن سعيد."],[12664,"(١) سبق. وجاء بالمخطوط: \"وكان عباد وسلام وأبان وقرط بن حريث\"، وضبب المصنف عليهم عدا \"قرط حريث\"."],[12665,"(٢) و(٣) سبق."],[12666,"(٤) هو: ثور بن زيد الديلى، ثقة."],[12667,"(٥) هو: يحيى بن حمزة بن واقد الحضرمى، أبو عبد الرحمن الدمشقى القاضى، من أهل بيت لهيا."],[12668,"انظر: تهذيب الكمال (٣١ / ت ٦٨١٦)."],[12669,"(٦) هو: العلاء بن الحارث بن عبد الوارث الحضرمى، ويقال: أبو محمد الدمشقى، صدوق فقيه لكن رمى بالقدر وقد اختلط. انظر: تهذيب الكمال (٢٢/ ت ٤٥٦٠)."],[12670,"١٠٤٧ - سعد بن إبرهيم"],[12671,"(١)"],[12672,"قال محمد بن إدريس الشافعى: سمعت مالك بن أنس يقول: قدم غيلان المدينة فتكلم هو وربيعة، وحضرهما سعد بن إبراهيم، والصلت بن زيد حليف قريش، فلما تفرقوا قبل سعد بن إبراهيم مقالة غيلان وصوبها، وقبل الصلت مقالة ربيعة."],[12673,"قال المخرمى: قلت لأحمد بن حنبل: مالك لا تروى عن سعد؟ فقال: سعد خير من مالك، سعد لا يسئل عنه."],[12674,"١٠٤٨ - عبد الله بن أبى لبيد الثقفى"],[12675,"(٢)"],[12676,"قال الحميد: قال ابن عيينة: عبد الله بن أبى لبيد الثقفى، هو عبد الله بن عباد من أهل المدينة، وكان يرى القدر."],[12677,"١٠٤٩ - ابن أبى ذئب"],[12678,"(٣)"],[12679,"وقال محمد بن إدريس: سمعت مالك بن أنس يقول: لو برئ ابن أبى ذئب من القدر ما كان على ظهر الأرض أحد خيرًا منه."],[12680,"قال داود الأصفهانى فى كتابه: على الكرابيسى فى إكفار المتأولين ومن قال بالقدر."],[12681,"١٠٥٠ - شريك بن عبد الله بن أبى نمر"],[12682,"(٤)"],[12683,"١٠٥١ - وهمام بن يحيى"],[12684,"(٥)"],[12685,"١٠٥٢ - والحسن بن واصل"],[12686,"(٦)"],[12687,"١٠٥٣ - وهارون الأعور"],[12688,"(٧)"],[12689,"١٠٥٤ - وعمر الأبح"],[12690,"(٨)"],[12691,"١٠٥٥ - وروح بن عطاء بن أبى ميمونة وابنه"],[12692,"(٩)"],[12693,"(١) هو: سعد بن إبراهيم بن عبد الرحمن بن عوف الزهرى، أبو إسحاق، ويقال: أبو إبراهيم، أمه أم كلثوم بنت سعد، وكان قاضى المدينة، والقاسم بن محمد حى."],[12694,"انظر: تهذيب الكمال (١٠ / ت ٢١٩٩)."],[12695,"(٢) إلى (٧): سبق."],[12696,"(٨) هو: عمر بن سعيد الأبح، منكر الحديث. انظر: الكامل لابن عدى (٦/ ٩٦)."],[12697,"(٩) سبق."],[12698,"١٠٥٦ - وصالح الناجى"],[12699,"(١)"],[12700,"١٠٥٧ - والأشعث بن سعيد السمان"],[12701,"(٢)"],[12702,"١٠٥٨ - وعنبسة بن سعيد القطان"],[12703,"(٣)"],[12704,"١٠٥٩ - وطلق"],[12705,"(٤)"],[12706,"١٠٦٠ - وعمرو بن مرة"],[12707,"(٥)"],[12708,"١٠٦١ - ومسعر بن كدام"],[12709,"(٦)"],[12710,"١٠٦٢ - ومهدى بن هلال"],[12711,"(٧)"],[12712,"١٠٦٣ - وعبد الرحمن بن إسحاق"],[12713,"(٨)"],[12714,"١٠٦٤ - والمنهال بن السراح"],[12715,"(٩)"],[12716,"١٠٦٥ - وعطاء بن سيار"],[12717,"(١٠)"],[12718,"١٠٦٦ - وإبراهيم بن نافع"],[12719,"(١١)"],[12720,"١٠٦٧ - وأبو هلال الراسبى"],[12721,"(١٢)"],[12722,"١٠٦٨ - ومحمد بن سليم"],[12723,"(١٣)"],[12724,"١٠٦٩ - وعثمان بن مقسم اليزنى"],[12725,"(١٤)"],[12726,"١٠٧٠ - أبو الأسود الديلى"],[12727,"(١٥)"],[12728,"وقال يعقوب بن شيبة، عن إبراهيم بن المنذر الحزامى، قال: حدثنا أبو ضمرة، عن"],[12729,"عبد الله بن عثمان: أول من تكلم فى القدر، أبو الأسود الديلى."],[12730,"١٠٧١ - محمد بن إسحاق"],[12731,"(١٦)"],[12732,"١٠٧٢ - وعمرو بن دينار"],[12733,"(١٧)"],[12734,"قال العلاء: عن يحيى بن معين، عن محمد بن إسحاق، وعمرو بين دينار قدريان."],[12735,"١٠٧٣ - محمد بن إسحاق"],[12736,"(١٨)"],[12737,"قال الدورى: قيل ليحيى: يصح أن محمد بن إسحاق كان يرى القدر؟، قال: نعم."],[12738,"(١) إلى (١٨): سبق."],[12739,"١٠٧٤ - زكريا بن إسحاق"],[12740,"(١)"],[12741,"قال العباس: قال يحيى: زكريا بن إسحاق كان يرى القدر."],[12742,"١٠٧٥ - وهب بن منبه"],[12743,"(٢)"],[12744,"قال أحمد بن حنبل: كان وهب بن منبه متهم بشئ من القدر."],[12745,"١٠٧٦ - الحسن"],[12746,"(٣)"],[12747,"قال. أيوب: ما أعيانى الحسن فى شئ ما أعيانى فى القدر حتى خوفته بالسلطان."],[12748,"١٠٧٧ - قتادة"],[12749,"(٤)"],[12750,"قال يعقوب بن شيبة، عن على بن أبى هاشم، عن شعبة قال: قال قتادة: الأشياء كلها بقدر ما خلا المعاصى."],[12751,"١٠٧٨ - عبادة بن صهيب"],[12752,"(٥)"],[12753,"قال الدورى: قال يحيى: كان عباد بن صهيب يرى القدر لم أكتب عنه شيئًا."],[12754,"١٠٧٩ - ابن يعمر"],[12755,"(٦)"],[12756,"وروى خلف بن أيوب البلخى، عن محمد بن أبان، عن علقمة بن يزيد، عن عبد الله ابن بريدة أنه قال: فى حديث جرى فيه ذكر ابن يعمر: وكان ابن يعمر اعترض فى شئ من القدر."],[12757,"١٠٨٠ - ابن أبى عروبة"],[12758,"(٧)"],[12759,"قال ابن عيينة: قدم علينا ابن أبى عروبة، فخطب بالقدر، فقيل له: فقال: هذا رأى"],[12760,"ورأى صاحبى، ورأى صاحب صاحبى."],[12761,"١٠٨١ - أبان بن يزيد العطار"],[12762,"(٨)"],[12763,"قال الدورى: قال يحيى: كان أبان بن يزيد العطار يرمى بشئ من القدر."],[12764,"١٠٨٢ - عبد الواحد بن زيد"],[12765,"(٩)"],[12766,"قال الدورى: قال يحيى: عبد الواحد بن زيد ليس بشئ. قيل للعباس: ما أنكر عليه؟ قال: كان قدريًا داعية ليس لشئ غير ذلك."],[12767,"(١) إلى (٩): سبق."],[12768,"١٠٨٣ - الأسود بن شيبان"],[12769,"(١)"],[12770,"قال المخرمى: قال يحيى بن معين: كان الأسود بن شيبان عابدًا، وكان يرى القدر."],[12771,"١٠٨٤ - عمران القصير"],[12772,"(٢)"],[12773,"قال ابن المدينى: قال يحيى بن سعيد: كان عمران القصير يرى القدر."],[12774,"١٠٨٥ - عبد الوارث"],[12775,"(٣)"],[12776,"فال المخرمى: وسمعت القواريرى يقول: كان عبد الوراث يرى الحديث فى القدر تم يقول: ما أرويه إلا ردًا له."],[12777,"١٠٨٦ - سفيان بن حبيب"],[12778,"(٤)"],[12779,"قال المخرمى: سمعت القواريرى يقول: كان سفيان بن حبيب يرى القدر."],[12780,"١٠٨٧ - أبو عبيدة الناجى"],[12781,"(٥)"],[12782,"قال العلاء عن يحيى بن معين: كان أبو عبيدة الناجى اسمه بكر بن الأسود وكان قدريًا."],[12783,"١٠٨٨ - غندر"],[12784,"(٦)"],[12785,"قال المخرمى: وسمعت القواريرى يقول: كان غندر يرى القدر."],[12786,"١٠٨٩ - عامر بن رباح"],[12787,"(٧)"],[12788,"قال ابن المدينى: سمعت يحيى بن سعيد يقول: كان عامر بن رباح صاحب عربية وكان ثبتًا فأفسدوه بالقدر."],[12789,"١٠٩٠ - عطاء بن أبى ميمونة"],[12790,"(٨)"],[12791,"قال العلاء: سمعت أحمد بن حنبل يقول: مات عطاء بن أبى ميمونة سنة الطاعون وكان يتهم بالقدر."],[12792,"(١) سبق."],[12793,"(٢) هو: عمران بن مسلم المنقرى أبو بكر البصرى القصير."],[12794,"انظر: تهذيب الكمال (٢٢ / ت ٤٥٠٢)، تهذيب التهذيب (٨/ ١٣٧)، الكاشف (٢ /ت ٤٣٣٩)، ميزان الاعتدال (٣ /ت ٦٣١٣)، التاريخ الكبير (٦ /ت ٢٨٤٠)."],[12795,"(٣) إلى (٨) سبق."],[12796,"١٠٩١ - الفضل بن يحيى الرقاشى"],[12797,"(١)"],[12798,"قال العباس: قال يحيى: الفضل بن يحيى الرقاشى، يروى عنه حماد بن زيد، وهو من القدرية من رؤسائهم. قال: والفضل بن يزيد الرقاشى يرى القدر، أدرك عمر."],[12799,"١٠٩٢ - سلام بن مسكين"],[12800,"(٢)"],[12801,"قال العباس: قال يحيى: سلام بن مسكين يرمى بشئ من القدر."],[12802,"١٠٩٣ - العباس بن الفضل الأنصارى"],[12803,"(٣)"],[12804,"قال المخرمى: قال إبراهيم الهروى: كان العباس بن الفضل الأنصارى يرى القدر."],[12805,"١٠٩٤ - مكحول"],[12806,"(٤)"],[12807,"١٠٩٥ - والحسن"],[12808,"(٥)"],[12809,"قال يعقوب بن شيبة: قال أبو مسهر: حدثنا هقل بن زياد قال: سمعت الأوزاعى يقول: لا نعلم أحدًا انتسب إلى القدر غير مكحول والحسن ولم يصح ذلك عندنا."],[12810,"١٠٩٦ - ثور بن يزيد الأرخبى"],[12811,"(٦)"],[12812,"قال ابن المدينى عن ابن شداد: سمعت وكيعًا يقول: كان ثور بن يزيد الأرخبى يرى القدر. قال: وسألت يحيى بن معين، عن ثور فقال: كان يرى القدر."],[12813,"١٠٩٧ - قتادة"],[12814,"(٧)"],[12815,"١٠٩٨ - والدستوائى"],[12816,"(٨)"],[12817,"١٠٩٩ - وسعيد"],[12818,"(٩)"],[12819,"١١٠٠ - والحسن"],[12820,"(١٠)"],[12821,"١١٠١ - وثور بن يزيد"],[12822,"(١١)"],[12823,"١١٠٢ - وعثمان بن عطاء"],[12824,"(١٢)"],[12825,"(١) إلى (٥) سبق."],[12826,"(٦) هو: ثور بن يزيد بن زياد الكلاعى، ويقال: الرحبى أبو خالد الحمصى، ثقة ثبت إلا أنه يرى القدر. انظر: تهذيب الكمال (٤ /ت ٨٦٢)."],[12827,"(٧) إلى (١٢) سبق."],[12828,"قال مكى بن إبراهيم البلخى: كلهم قدريون."],[12829,"١١٠٣ - أبو داود مسلم بن عمرو النخعى"],[12830,"(١)"],[12831,"قال العباس: قال يحيى: أبو داود مسلم بن عمرو النخعى، كان قدريًا."],[12832,"١١٠٤ - سعد بن عبيدة"],[12833,"(٢)"],[12834,"وروى ابن إسماعيل قال: كان سعد بن عبيدة يرى رأى الخوارج."],[12835,"١١٠٥ - صالح بن إبراهيم الباهلى الدهان"],[12836,"(٣)"],[12837,"وقال: قال موسى بن إسماعيل: إن صالح بن إبراهيم الباهلى الدهان، كنيته أبو نوح"],[12838,"ويقال: إنه من الأباضية. وقال غيره: كنيته أبو الأزهر."],[12839,"١١٠٦ - عمر بن أبى زائدة"],[12840,"(٤)"],[12841,"قال ابن المدينى: قال يحيى: كان عمر بن أبى زائدة يرى القدر."],[12842,"١١٠٧ - أبو الشعثاء"],[12843,"(٥)"],[12844,"قال: وقال يحيى: قال عبد ربه بن راشد: كان أبو الشعثاء يختلف إلى جارة لنا أباضية."],[12845,"١١٠٨ - عمرو بن عبيد"],[12846,"(٦)"],[12847,"قال الكرابيسى: ومن القدرية عمرو بن عبيد، قال: وقد روى عنه الثورى، وابن عيينة، وهشيم، وابن علية، والناس. قال: وقال ابن عيينة: لم تر عينى مثله، وقد رأى التابعين."],[12848,"قال: ومنهم الحسن، وقتادة، وسعيد بن أبى عروبة، وهشام الدستوائى، وعوف، وزكريا بن إسحاق، وشبل، وإبراهيم بن نافع، والماجشونى."],[12849,"١١٠٩ - جابر بن زيد"],[12850,"(٧)"],[12851,"١١١٠ - وصدقة بن يسار"],[12852,"(٨)"],[12853,"(١) إلى (٥) سبق."],[12854,"(٦) هو: عمرو بن عبيد بن باب، ويقال: ابن كيسان التميمى، مولاهم أبو عثمان البصرى."],[12855,"قال ابن حجر: معتزلى مشهور وكان داعية لبدعته، اتهمه جماعة مع أنه كان عابدًا. تهذيب الكمال (٢٢ / ت ٤٤٠٦)."],[12856,"(٧) و(٨) سبق."],[12857,"١١١١ - وعمران بن حطان"],[12858,"(١)"],[12859,"قال: وكان جابر بن زيد أباضيًا وكذلك صدقة بن بشار، وكذلك عمران بن حطان، قال: وروى عنه ابن سيرين."],[12860,"١١١٢ - إبراهيم بن أبى يحيى"],[12861,"(٢)"],[12862,"قال: وكان إبراهيم بن أبى يحيى سبعيًا قدرئا، وكان قبل ذلك أباضيًا."],[12863,"١١١٣ - ثور"],[12864,"(٣)"],[12865,"قال: ورأى خارجة سفيان الثورى يجئ من عند ثور، فقال له: من أين جئت؟"],[12866,"قال: سلمت على هذا القدرى، فلما مات جعل يحدث عنه، فقال لخارجة: حدثنى ذاك القدرى."],[12867,"١١١٤ - ابن أبى عروبة"],[12868,"(٤)"],[12869,"١١١٥ - هشام الدستوائى"],[12870,"(٥)"],[12871,"قال المكى: وكان ابن أبى عروبة، قيل له هشام الدستوائى فقال: كان قدريًا."],[12872,"١١١٦ - قتادة"],[12873,"(٦)"],[12874,"١١١٧ - ابن أبى رواد"],[12875,"(٧)"],[12876,"١١١٨ - عمر بن أبى ذر"],[12877,"(٨)"],[12878,"قال ابن المدينى: قلت ليحيى بن سعيد: إن عبد الرحمن يقول: اترك كل من كان رأسًا فى البدعة يدعو إليها. فقال: كيف يصنع بقتادة؟ وكيف يصنع بابن أبى رواد؟ وعمر بن أبى ذر وعد من هؤلاء، ثم قال: إن ترك هذا الضرب ترك ناسًا كثيرا."],[12879,"١١١٩ - عدى بن ثابت"],[12880,"(٩)"],[12881,"قال الخشنى: ومن السبعة عدى بن ثابت رأس فيهم."],[12882,"١١٢٠ - وعطية العوفى"],[12883,"(١٠)"],[12884,"١١٢١ - وسماك بن حرب"],[12885,"(١١)"],[12886,"(١) إلى (١١) سبق."],[12887,"١١٢٢ - ومنذر الثورى"],[12888,"(١)"],[12889,"١١٢٣ - والربيع بن المنذر"],[12890,"(٢)"],[12891,"١١٢٤ - ومنهال بن عمرو"],[12892,"(٣)"],[12893,"١١٢٥ - ومنصور بن المعتمر"],[12894,"(٤)"],[12895,"قال: ومن المتقدمين:"],[12896,"١١٢٦ - جابر الجعفى"],[12897,"(٥)"],[12898,"١١٢٧ - وصعصعة بن صولجان"],[12899,"(٦)"],[12900,"١١٢٨ - ورشيد الهجرى"],[12901,"(٧)"],[12902,"١١٢٩ - والحارث"],[12903,"(٨)"],[12904,"١١٣٠ - وثعلبة الحمانى"],[12905,"(٩)"],[12906,"١١٣١ - وعلى بن زيد"],[12907,"(١٠)"],[12908,"١١٣٢ - وعمار بن أبى عمار"],[12909,"(١١)"],[12910,"١١٣٣ - وعبد الله بن محمد بن عقيل"],[12911,"(١٢)"],[12912,"١١٣٤ - أبى هارون العبدى"],[12913,"(١٣)"],[12914,"قال ابن المدينى: قال يحيى: قال شعبة: كنت أتلقى الركبان أيام الخوارج أسأل عن أبى هارون العبدى، فلما قدم رأيته، فرأيت عنده كتابًا فيه أشياء منكرة فى على، فقلت: ما فى هذا الكتاب؟ قال: هذا الكتاب حق."],[12915,"١١٣٥ - يحيى بن الخزاز"],[12916,"(١٤)"],[12917,"قال ابن المدينى: قال يحيى: أخبرنى شعبة، عن الحكم، قال: كان يحيى بن الخزاز يغلو فى حب على رضوان الله عليه. قال الكسرابيسى: ومن المرجئة:"],[12918,"(١) إلى (٦) سبق."],[12919,"(٧) هو: رشيد الهجرى. عن أبيه، قال الجوزجانى: كذاب غير ثقة، وقال النسائى: ليس بالقوى، قال البخارى: يتكلمون فيه، انظر: ميزان الاعتدال (٢/ ٥١)."],[12920,"(٨) إلى (١٤) سبق."],[12921,"١١٣٦ - مسعر بن كدام"],[12922,"(١)"],[12923,"ويروى عنه ابن عيينة وزعم أنه أفضل الناس."],[12924,"١١٣٧ - وعمر بن ذر"],[12925,"(٢)"],[12926,"١١٣٨ - ومالك بن مغول"],[12927,"(٣)"],[12928,"١١٣٩ - وإبراهيم التيمى"],[12929,"(٤)"],[12930,"١١٤٠ - وعمرو بن مرة"],[12931,"(٥)"],[12932,"١١٤١ - والحسين بن محمد بن على"],[12933,"(٦)"],[12934,"١١٤٢ - ومحارب بن دثار"],[12935,"(٧)"],[12936,"١١٤٣ - وسعيد بن عبد الرحمن بن أبزى"],[12937,"(٨)"],[12938,"١١٤٤ - وطلق بن حبيب"],[12939,"(٩)"],[12940,"١١٤٥ - علقمة بن مرثد"],[12941,"(١٠)"],[12942,"وقال صدقة بن الفضل: علقمة بن مرثد ثقة، لولا شئ من الإرجاء."],[12943,"١١٤٦ - التيمى"],[12944,"(١١)"],[12945,"وقال أبو نعيم: مررت بجوار التيمى فلم أعرض له، وكان مرجئًا."],[12946,"١١٤٧ - نعيم بن أبى حكيم"],[12947,"(١٢)"],[12948,"قال: وكان نعيم بن أبى حكيم مرجئًا لم ير سفيان أن يروى عنه."],[12949,"١١٤٨ - يونس"],[12950,"(١٣)"],[12951,"يحيى بن معين، قال: كان يونس يتبع السلطان وكان مرجئًا."],[12952,"قال العباس: أحسبه يعنى يونس بن بكير."],[12953,"١١٤٩ - عدى بن ثابت"],[12954,"(١٤)"],[12955,"قال: وكان عدى بن ثابت ليس بثقة ولا مأمون، وكان يفرط فى التشييع. قال أبو حاتم الرازى: ومن المرجئة:"],[12956,"(١) إلى (١٤) سبق."],[12957,"١١٥٠ - خارجة بن مصعب"],[12958,"(١)"],[12959,"١١٥١ - وسلم بن سالم"],[12960,"(٢)"],[12961,"١١٥٢ - وعمر بن قيس الناصر"],[12962,"(٣)"],[12963,"١١٥٣ - وعبد الحميد الحمانى"],[12964,"(٤)"],[12965,"١١٥٤ - وعبد الكريم أبو أمية"],[12966,"(٥)"],[12967,"١١٥٥ - ويحيى بن زكريا بن أبى زائدة"],[12968,"(٦)"],[12969,"١١٥٦ - وأبو بكر النهشلى"],[12970,"(٧)"],[12971,"١١٥٧ - وعمرو بن مرة الجملى"],[12972,"(٨)"],[12973,"١١٥٨ - وسالم الأفطس"],[12974,"(٩)"],[12975,"١١٥٩ - وعباد بن العوام"],[12976,"(١٠)"],[12977,"١١٦٠ - وسعيد بن سالم القداح"],[12978,"(١١)"],[12979,"١١٦١ - ومسلمة بن علقمة المازنى"],[12980,"(١٢)"],[12981,"١١٦٢ - وأبو الصباح موسى بن كثير"],[12982,"(١٣)"],[12983,"١١٦٣ - وعثمان بن غياث الراسبى"],[12984,"(١٤)"],[12985,"١١٦٤ - وعبد العزيز بن أبى رواد"],[12986,"(١٥)"],[12987,"١١٦٥ - وعبد المجيد بن عبد العزيز"],[12988,"(١٦)"],[12989,"١١٦٦ - ويزيد بن عبد الرحمن، أبو خالد الدالانى، مولى بنى أسد"],[12990,"(١٧)"],[12991,"١١٦٧ - وعبد الله بن داود الخريبى"],[12992,"(١٨)"],[12993,"(١) إلى (١٦) سبق."],[12994,"(١٧) هو: يزيد بن عبد الرحمن الدالانى، أبو خالد الأسدى، وكان ينزل فى بنى ديلان، ويقال: واسطى. قال ابن معين: ليس به بأس. وقال أبو حاتم: صدوق ثقة."],[12995,"انظر: الجرح والتعديل (٨/ ١١٦٨)."],[12996,"(١٨) سبق."],[12997,"١١٦٨ - وعلى بن الحسن بن شقيق"],[12998,"(١)"],[12999,"لا بأس به إن سلم من ذلك."],[13000,"١١٦٩ - وأيوب بن عائد"],[13001,"(٢)"],[13002,"١١٧٠ - وسالم بن عمرو أبو المنذر البجلى"],[13003,"(٣)"],[13004,"١١٧١ - والفرات بن خالد الرازى"],[13005,"(٤)"],[13006,"١١٧٢ - والصلت بن بهرام التيمى الكوفى أبو هاشم"],[13007,"(٥)"],[13008,"١١٧٣ - والنضر بن محمد أبو عبد الله المروزى"],[13009,"(٦)"],[13010,"١١٧٤ - وحماد بن قيراط"],[13011,"(٧)"],[13012,"١١٧٥ - وعمرو بن غياث"],[13013,"(٨)"],[13014,"١١٧٦ - وعلى بن الجعد"],[13015,"(٩)"],[13016,"كان مائلًا إلى أصحاب الرأى."],[13017,"١١٧٨ (*) - وأبو عاصم النبيل"],[13018,"(١٠)"],[13019,"كان مولعًا بالرأى."],[13020,"١١٧٩ - وإسحاق بن يوسف الأزرق"],[13021,"(١١)"],[13022,"كان يميل إلى الرأى."],[13023,"(١) هو: على بن الحسن بن شقيق بن دينار بن مشعب العبدى، مولاهم أبو عبد الرحمن المروزى، توفى سنة (٢١١)، وقيل: (٢١٢)، وقيل: (٢١٣)، ثقة حافظ."],[13024,"انظر: تهذيب الكمال (٢٠ / ت ٤٠٤٢)."],[13025,"(٢) إلى (٤) سبق."],[13026,"(٥) هو: الصلت بن بهرام الكوفى التيمى أبو هاشم. قال ابن عيينة: كان أصدق أهل الكوفة. قال أبو حاتم: ليس له عيب إلا الإرجاء."],[13027,"انظر: الجرح والتعديل (٤/ ت ٢٠١٠)، تهذيب التهذيب (٤/ ٤٣٢)."],[13028,"(٦) سبق."],[13029,"(٧) هو: حماد بن قيراط النيسابورى. عن عبيد الله بن عمر، وعنه محمد بن يزيد بن محمش، قال ابن حبان: لا تجوز الرواية عنه، يجئ بالطامات. انظر: ميزان الاعتدال (١/ ت ٢٢٦٦)."],[13030,"(٨) إلى (١١) سبق."],[13031,"(*) قال مُعِدُّ الكتاب للشاملة: كذا الترقيم بالمطبوع، سقط ١١٧٧"],[13032,"١١٨٠ - وأبو معاوية الفرير"],[13033,"(١)"],[13034,"يرى الإرجاء."],[13035,"١١٨١ - وشبابة بن سوار"],[13036,"(٢)"],[13037,"١١٨٢ - ومسلم النحات"],[13038,"(٣)"],[13039,"١١٨٣ - ومحمد بن عبد الله الأنصارى"],[13040,"(٤)"],[13041,"يميل إلى الرأى."],[13042,"١١٨٤ - وحماد بن أبى سليمان"],[13043,"(٥)"],[13044,"يرى الإرجاء."],[13045,"١١٨٥ - وعافية القاضى"],[13046,"(٦)"],[13047,"١١٨٦ - وأبو بردة"],[13048,"(٧)"],[13049,"الذى يحدث عنه محمد بن الصلت وليس من ولد أبى موسى."],[13050,"١١٨٧ - وخلاد بن يحيى"],[13051,"(٨)"],[13052,"١١٨٨ - وجعفر بن عبد الله النيسابورى"],[13053,"(٩)"],[13054,"(١) و(٢) سبق."],[13055,"(٣) هو: مسلم بن صاعد النحات، أرسل عن على رضي الله عنه. وعنه مروان بن معاوية، وأبو معاوية الضرير. قال ابن معين: ثقة. انظر: الجرح والتعديل (٨/ت ٨١٧)."],[13056,"(٤) سبق."],[13057,"(٥) هو: حماد بن أبى سليمان الأشعرى، مولاهم أبو إسماعيل، فقيه صدوق، له أوهام رُمى بالإرجاء. انظرت تهذيب الكمال (٧ /ت ١٤٨٣)، تهذيب التهذيب (١٦١٣)."],[13058,"(٦) هو: عافية بن يزيد بن قيس بن عافية القاضى الأودى الكوفى."],[13059,"انظر: تهذيب الكمال (١٤ /ت ٣٠٣٣)، تهذيب التهذيب (٦٠١٥)، ميزان الاعتدال (٢ /ت ٤٠٧٤)."],[13060,"(٧) سبق."],[13061,"(٨) هو: خلاد بن يحيى بن صفوان السلمى أبو محمد الكوفى، سكن مكة. قال ابن حجر: صدوق رمى بالإرجاء وهو من كبار شيوخ البخارى."],[13062,"(٩) سبق."],[13063,"١١٨٩ - وأبو سعد الصغانى"],[13064,"(١)"],[13065,"١١٩٠ - وقيس بن مسلم"],[13066,"(٢)"],[13067,"كان يبجل ذلك."],[13068,"١١٩١ - وعمر بن المرماح"],[13069,"(٣)"],[13070,"١١٩٢ - ومسعر بن كدام"],[13071,"(٤)"],[13072,"١١٩٣ - وإبراهيم بن طهمان"],[13073,"(٥)"],[13074,"١١٩٤ - وعلقمة بن مرثد"],[13075,"(٦)"],[13076,"١١٩٥ - وعاصم بن كليب"],[13077,"(٧)"],[13078,"١١٩٦ - وجواب بن عبيد الله"],[13079,"(٨)"],[13080,"١١٩٧ - وشعيب بن إسحاق"],[13081,"(٩)"],[13082,"الذى يحدث عن سعيد بن أبى عروبة من أصحاب أبى حنيفة."],[13083,"(١) سبق."],[13084,"(٢) هو: قيس بن مسلم الجُدرى العدوانى، أبو عمرو الكوفى، من بنى قيس علان. قال ابن حجر: ثقة رُمى بالإرجاء."],[13085,"انظر: تهذيب التهذيب (٨/ ٤٠٣)، تهذيب الكمال (٢٤/ ت ٤٩٢١)."],[13086,"(٣) هو: عمر بن ميمون بن بحر بن سعد بن الرماح البلخى، أبو على قاضى بلخ، انظر: تهذيب التهذيب (٧/ ٤٩٨)."],[13087,"(٤) إلى (٧) سبق."],[13088,"(٨) هو: جواب بن عبيد الله التيمى، تيم الرباب، الكوفى، قال ابن نمير: ضعيف الحديث قد رآه الثورى فلم يحمل عنه، قال أبو خالد الأحمر: كان يقص ويذهب مذهب الإرجاء، قال ابن حبان: كان مرجئًا، قال ابن حجر: صدوق رمى بالإرجاء."],[13089,"انظر: تهذيب الكمال (٥/ ٩٨٢)، تهذيب التهذيب (٢/ ١٢١)."],[13090,"(٩) هو: شعيب بن إسحاق بن عبد الرحمن بن عبد الله بن راشد الدمشقى الأموى، مولى رملة بنت عثمان أصله من البصرة."],[13091,"انظر: تهذيب الكمال (١٢/ ت ٢٧٤٢)، تهذيب التهذيب (٤/ ٣٤٧)، الجرح والتعديل (٤ / ت ١٤٩٨)."],[13092,"قال: أبو حاتم: ومن القدرية."],[13093,"١١٩٨ - مهدى بن هلال"],[13094,"(١)"],[13095,"١١٩٩ - وسعيد بن بشير"],[13096,"(٢)"],[13097,"وروى عنه هشيم."],[13098,"١٢٠٠ - وعبد الرزاق"],[13099,"(٣)"],[13100,"١٢٠١ - وابن عيينة"],[13101,"(٤)"],[13102,"١٢٠٢ - وبقية"],[13103,"(٥)"],[13104,"١٢٠٣ - والوليد بن مسلم"],[13105,"(٦)"],[13106,"١٢٠٤ - ووكيع"],[13107,"(٧)"],[13108,"١٢٠٥ - وأبو وكيع"],[13109,"(٨)"],[13110,"١٢٠٦ - وحمزة بن يحيى"],[13111,"(٩)"],[13112,"١٢٠٧ - وكهمس"],[13113,"(١٠)"],[13114,"١٢٠٨ - والمنهال"],[13115,"(١١)"],[13116,"١٢٠٩ - ويحيى بن بسطام بن حريث"],[13117,"(١٢)"],[13118,"١٢١٠ - وأبو حمزة العطار إسحاق بن الربيع"],[13119,"(١٣)"],[13120,"فيما أحسب."],[13121,"١٢١١ - وبكر بن اليشرود الصنعانى"],[13122,"(١٤)"],[13123,"١٢١٢ - وقحطبة بن عدانة البصرى"],[13124,"(١٥)"],[13125,"١٢١٣ - ويحيى بن حمزة"],[13126,"(١٦)"],[13127,"١٢١٤ - ويزيد بن واقد"],[13128,"(١٧)"],[13129,"(١) إلى (١٤) سبق."],[13130,"(١٥) كذا بالمخطوط ولم أقف عليه."],[13131,"(١٦) و(١٧) سبق."],[13132,"١٢١٥ - وبرد بن سنان"],[13133,"(١)"],[13134,"١٢١٦ - محمد بن راشد"],[13135,"(٢)"],[13136,"١٢١٧ - محمد بن دينار"],[13137,"(٣)"],[13138,"١٢١٨ - صدقة بن عبد الله السمين"],[13139,"(٤)"],[13140,"١٢١٩ - عبد الوارث"],[13141,"(٥)"],[13142,"١٢٢٠ - وهمام بن يحيى"],[13143,"(٦)"],[13144,"قال: كانا واقعين فى القدر. قال أبو حاتم: وممن كان يذهب إلى الأهواء."],[13145,"١٢٢١ - أبو عبد الله الجدلى"],[13146,"(٧)"],[13147,"كان من أصحاب المختار."],[13148,"١٢٢٢ - وأبو حسان الأعرج"],[13149,"(٨)"],[13150,"صاحب ابن عباس، كان يرى رأى الخوارج."],[13151,"١٢٢٣ - ومحمد بن سعيد الدمشقى"],[13152,"(٩)"],[13153,"صلب فى الزندقة."],[13154,"١٢٢٤ - وصدقة بن بشار"],[13155,"(١٠)"],[13156,"من الخوارج من الجزيرة، وكان ثقة."],[13157,"١٢٢٥ - وبشر بن عمارة"],[13158,"(١١)"],[13159,"يتهم بالتجهم."],[13160,"(١) هو: برد بن سنان الشامى، أبو العلاء الدمشقى، مولى قريش، قال ابن حجر: صدوق رُمى بالقدر. انظر: تهذيب الكمال (٤ / ت ٦٥٥)، تهذيب التهذيب (١/ ٤٢٨)."],[13161,"(٢) و(٣) سبق."],[13162,"(٤) جاء بالمخطوط: \"السمتى\"، وهو تصحيف، وهو: صدقة بن عبد الله السَّمين أبو معاوية، ويقال: أو محمد الدمشقى."],[13163,"انظر: تهذيب الكمال (١٣ / ت ٢٨٦٣)، تهذيب التهذيب (٤/ ٤١٥)، الجرح والتعديل (٤/ ١٨٨٩)."],[13164,"(٥) إلى (١١) سبق."],[13165,"١٢٢٦ - ومحمد بن يعلى السلمى الكوفى"],[13166,"(١)"],[13167,"كان جهميًّا."],[13168,"١٢٢٧ - وإسماعيل بن علية"],[13169,"(٢)"],[13170,"تكلم بشئ من كلام الجهمية، يزعمون أن أبيه حمله على ذلك ثم تاب ورجع."],[13171,"١٢٢٨ - وعلى بن الجعد"],[13172,"(٣)"],[13173,"يتهم بالتجهم. قال أبو حاتم: وممن كان يتشيع."],[13174,"١٢٢٩ - أحمد بن الفضل الكوفى"],[13175,"(٤)"],[13176,"وكان من رؤوسائهم."],[13177,"١٢٣٠ - والحارث بن حصيرة"],[13178,"(٥)"],[13179,"وهو من العُتق."],[13180,"١٢٣١ - والأجلح"],[13181,"١٢٣٢ - وعبد الملك بن أعين"],[13182,"(٦)"],[13183,"من العُتق."],[13184,"١٢٣٣ - وعلى بن هاشم بن البريد"],[13185,"(٧)"],[13186,"١٢٣٤ - وجعفر بن سليمان الضبعى"],[13187,"(٨)"],[13188,"١٢٣٥ - والعلاء بن صالح"],[13189,"(٩)"],[13190,"من العتق."],[13191,"١٢٣٦ - وهارون بن سعد"],[13192,"(١٠)"],[13193,"كان كثير التشييع."],[13194,"١٢٣٧ - وموسى بن طريف"],[13195,"(١١)"],[13196,"(١) إلى (٣) سبق."],[13197,"(٤) لم أقف عليه."],[13198,"(٥) إلى (١١) سبق."],[13199,"١٢٣٨ - وعبد الملك بن بكير الغنوى"],[13200,"(١)"],[13201,"من العتق."],[13202,"١٢٣٩ - ومحمد بن راشد صاحب مكحول"],[13203,"(٢)"],[13204,"رافضى."],[13205,"١٢٤٠ - وإبراهيم بن الحكم بن ظهير"],[13206,"(٣)"],[13207,"كان يترفض."],[13208,"١٢٤١ - وفطر بن خليفة"],[13209,"(٤)"],[13210,"١٢٤٢ - وخالد بن طهمان"],[13211,"(٥)"],[13212,"١٢٤٣ - وعبد الله بن الأجلح"],[13213,"(٦)"],[13214,"١٢٤٤ - وسليمان بن معاذ"],[13215,"(٧)"],[13216,"١٢٤٥ - وعلى بن زيد"],[13217,"(٨)"],[13218,"١٢٤٦ - وسعادة الحمانى"],[13219,"(*)"],[13220,"١٢٤٧ - وعلى بن ثابت الدهان الكوفى"],[13221,"(٩)"],[13222,"١٢٤٨ - وأبان بن تغلب"],[13223,"(* *)"],[13224,"١٢٤٩ - ويزيد بن أبى زياد"],[13225,"(١٠)"],[13226,"١٢٥٠ - والعلاء بن العباس"],[13227,"(١١)"],[13228,"(١) إلى (٦) سبق."],[13229,"(٧) هو: سليمان بن قرن بن معاذ التيمى الضبى، أبو داود النحوى، ومنهم من ينسبه إلى جده."],[13230,"انظر: تهذيب الكمال (١٢/ ت ٢٥٥٥)."],[13231,"(٨) سبق."],[13232,"(*) أظنه: سعاد بن سليمان الجعفى، ويقال: التميمى، ويقال: اليشكرى الكاهلى، الكوفى."],[13233,"(٩) سبق."],[13234,"(* *) هو: أبان بن تغلب الربعى، أبو سعد الكوفى، قال ابن حجر: ثقة تكلم فيه للتشيع."],[13235,"انظر: تهذيب الكمال (٢ / ت ١٣٥)، تهذيب التهذيب (١/ ٩٣)."],[13236,"(١٠) و(١١) سبق."],[13237,"١٢٥١ - ومنصور بن أبى الأسود"],[13238,"(١)"],[13239,"١٢٥٢ - ومخول بن إبراهيم بن راشد"],[13240,"(٢)"],[13241,"١٢٥٣ - وإسماعيل بن أبان الوراق"],[13242,"(٣)"],[13243,"١٢٥٤ - وسالم بن أبى العلاء المرادى"],[13244,"(٤)"],[13245,"١٢٥٥ - وعلى بن غراب"],[13246,"(٥)"],[13247,"١٢٥٦ - ومحمد بن فضيل"],[13248,"(٦)"],[13249,"١٢٥٧ - وعبد الرزاق بن همام"],[13250,"(٧)"],[13251,"١٢٥٨ - وأبو الجويرية"],[13252,"(٨)"],[13253,"مطرف قال: مات أبو الجويرية بالمدينة، وكان مرجئًا مبتدعًا، فلم يصل عليه مالك ولا أحد ممن كان معه."],[13254,"١٢٥٩ - ثوير"],[13255,"(٩)"],[13256,"شبابة عن يونس بن أبى إسحاق قال: كان ثوير رافضيًا."],[13257,"* * *"],[13258,"(١) إلى (٤) سبق."],[13259,"(٥) هو: على بن غراب الفزارى، أبو الحسن، ويقال: أبو الوليد الكوفى القاضى، ويقال: هو على ابن عبد العزيز، وعلى بن أبى الوليد، قال أبو حاتم: كان مروان بن معاوية، قال باسمه."],[13260,"فقال: على بن عبد العزيز، وزعم الفلكى: أن غرابًا لقب وأن اسمه عبد العزيز."],[13261,"انظر: تهذيب الكمال (٢١/ ت ٤١٢٠)."],[13262,"(٦) إلى (٩) سبق."],[13263,"١٩ - باب ذكر المدلسين، وما قيل فى التدليس"],[13264,"قال الكرابيسى: كان من المشهورين بالتدليس بالكوفة: أبو إسحاق، والحكم، ومغيرة، والأعمش والثورى."],[13265,"وبالبصرة: قتادة، وبغيرهما: هشيم وابن عيينة وإسحاق."],[13266,"قال أبو حاتم الرازى: الزهرى أحب إلىَّ من الأعمش، وكلاهما يحتج بحديثه فيما لم يدلسا."],[13267,"قال: وسليمان التيمى يدلس أحيانًا، ومبارك بن فضالة: يدلس."],[13268,"قال: وكان قتادة يدلس."],[13269,"قال: وأحسب حميد الطويل كان يدلس، عن أنس بعض ما سمعه من ثابت وغيره."],[13270,"قال: وكان ابن أبى نجيح، وححاج بن أرطأة، وحميد الطويل يدلسون، قال: وكان ابن أبى نجيح يدلس عن مجاهد."],[13271,"محمد بن نصر قال: سمعت أحمد بن عاصم يقول: سمعت يزيد بن هارون يقول: دلس أبو هريرة، ودلس ابن عمر."],[13272,"قلت له: ما كان يدلس ابن عمر؟ قال: حيث قال لأبى هريرة: لقد فرطنا فى قراريط، ثم قال ابن عمر بعد ذلك، قال رسول الله - صلى الله عليه وآله وسلم -. قال أبو حاتم: وكان يحيى بن أبى كثير يدلس، وكان الأعمش والثورى وأبو إسحاق السبيعى يدلسون."],[13273,"محمد بن نصر قال: سمعت أحمد بن عاصم يقول: قال يزيد بن هارون هشيم رأس المدلسين."],[13274,"على بن المدينى قال: سمعت عبد الرحمن يقول: قال شبية: حدثنى رجل عن سفيان، عن منصور، عن إبراهيم بكذا ثم قال: ما سرنى أنى قلت. قال منصور: وأن الدنيا كلها لى، يعنى التدليس."],[13275,"محمد بن نصر قال: سمعت أحمد بن عاصم، يقول: سمعت سنان الخفاف يحدث على بن المدينى قال: قال رجل لشريك، يا أبا عبد الله ما ترى فى التدليس؟، قال: وما التدليس؟، قال: إن الرجل يسمع من الأعمش، ثم سمع منك عن الأعمش حديثًا فيقول: الأعمش ويرسله، قال: أليس يوهم صاحبه أنه سمعه من الأعمش؟، قال: نعم، قال: هيهات دون ذلك جزاء الحلاقيم."],[13276,"ابن أبى خيثمة، قال: حدثنا أحمد بن محمد الصفار قال: سمعت يزيد بن زريع وسئل عن التدليس؟ فقال: التدليس كذب."],[13277,"أبو حاتم الرازى قال: سمعت أبا نعيم، يقول: سمعت شعبة يقول: لأن أزنى أحب إلى من أن أدلس (١)."],[13278,"تم الكتاب والحمد لله رب العالمين"],[13279,"وصلواته على سيدنا محمد النبى وآله أجمعين"],[13280,"وهو حسبنا ونعم الوكيل (٢)"],[13281,"(١) سبق أن ذكر المصنف هذا القول فى ترجمة شعبة، وعند ذلك عد قول شعبة هذا مأخذًا عليه، وإن كان شعبة ذكره كناية عن شدة بغضه للتدليس وليس غير ذلك، ثم نراه الآن يورده هنا ليؤكد نفس المعنى، المراد من كراهية التدليس."],[13282,"(٢) بهذا القول ينتهى الكتاب، ولكن يوجد بعد هذه العبارة كلام آخر ليس من الكتاب ويبدو أنه من كلام الناسخ."]])